--
-- Name: admin_dms_einfuegen_menu(); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.admin_dms_einfuegen_menu() RETURNS void
    LANGUAGE plpgsql
    AS $$

DECLARE
	p_lfd_nr INT;
	p_menu_id INT;
	p_verweis_typ INT;

	BEGIN
		 p_verweis_typ:= (SELECT verweis_typ FROM sv_menu_item WHERE name = '&Integration');

		IF (p_verweis_typ = 0) THEN

			p_menu_id := (SELECT menu_id FROM sv_menu_item WHERE name = '&Integration');
			p_lfd_nr := (SELECT MAX(lfd_nr) FROM sv_menu_item WHERE name = '&Integration');

			p_lfd_nr := p_lfd_nr - 1;

			UPDATE sv_menu_item SET lfd_nr = lfd_nr + 1 WHERE lfd_nr > 21;

			INSERT INTO sv_menu_item (menu_id, name, lfd_nr, verweis_typ, verweis_id) VALUES (p_menu_id, '&DMS-Konfiguration', p_lfd_nr, 0, 18);

		END IF;

	END;
$$;


