-- Name: bzgrdb(); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.bzgrdb() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
BEGIN
 PERFORM cob.bzgrdi(OLD);
 RETURN OLD; END; $$;


--
-- Name: bzgr; Type: TABLE; Schema: cob; Owner: -
--

CREATE TABLE cob.bzgr (
    db_einfuegemarke character varying(6),
    bzgr_id integer NOT NULL,
    bzgr_jahr smallint,
    bzgr_kpumkey character varying(20),
    bzgr_varnr integer
);


--
-- Name: bzgrdi(cob.bzgr); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.bzgrdi(cob.bzgr) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM cob.bzgr_empf bzgr_empf WHERE old_row.bzgr_id = bzgr_empf.bzgr_bzgr_id;
IF EXISTS(SELECT * FROM cob.umks umks WHERE old_row.bzgr_kpumkey = umks.umks_kpumkey AND old_row.bzgr_jahr = umks.umks_jahr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "umks" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.umks_e umks_e WHERE old_row.bzgr_kpumkey = umks_e.kpumkey AND old_row.bzgr_jahr = umks_e.jahr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "umks_e" verwendet!';
END IF;
 RETURN old_row; END; $_$;


