--
-- Name: db_sachbearbeiterdi(cob.db_sachbearbeiter); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.db_sachbearbeiterdi(cob.db_sachbearbeiter) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM cob.r_db_sachbearbeiter_attribut r_db_sachbearbeiter_attribut WHERE old_row.sachbearbeiter_id = r_db_sachbearbeiter_attribut.db_sachbearbeiter_join_id;
IF EXISTS(SELECT * FROM cob.rev_ereignis rev_ereignis WHERE old_row.login = rev_ereignis.login) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "rev_ereignis" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.rev_queryprot_exp rev_queryprot_exp WHERE old_row.login = rev_queryprot_exp.login) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "rev_queryprot_exp" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.rev_queryprot_sel rev_queryprot_sel WHERE old_row.login = rev_queryprot_sel.login) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "rev_queryprot_sel" verwendet!';
END IF;
DELETE FROM cob.sv_appcontext sv_appcontext WHERE old_row.sachbearbeiter_id = sv_appcontext.eigentuemer;
 RETURN old_row; END; $_$;


