--
-- Name: delete_dokumente(); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.delete_dokumente() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$

DECLARE
    r_dokumente_anzahl INT;

  BEGIN

    r_dokumente_anzahl := (SELECT COUNT(*) FROM cob.r_dokumente WHERE dokumente_join_id = OLD.dokumente_join_id);

    IF r_dokumente_anzahl < 1 THEN
	--Dokument loeschen:
			DELETE FROM cob.dokumente WHERE dokumente_serial = OLD.dokumente_join_id;
    END IF;

    --Rueckgabewerte
    RETURN OLD;

  END;
$$;


