--
-- Name: evaldi(cob.eval); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.evaldi(cob.eval) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM cob.eval_kpum_zuord eval_kpum_zuord WHERE old_row.eval_key = eval_kpum_zuord.eval_key;
DELETE FROM cob.l100 l100 WHERE old_row.eval_key = l100.l100_evalkey;
DELETE FROM cob.l110 l110 WHERE old_row.eval_key = l110.l110_evalkey;
DELETE FROM cob.l200 l200 WHERE old_row.eval_key = l200.l200_evalkey;
DELETE FROM cob.l210 l210 WHERE old_row.eval_key = l210.l210_evalkey;
DELETE FROM cob.l220 l220 WHERE old_row.eval_key = l220.l220_evalkey;
DELETE FROM cob.lcr100 lcr100 WHERE old_row.eval_key = lcr100.evalkey;
DELETE FROM cob.lcr110 lcr110 WHERE old_row.eval_key = lcr110.evalkey;
DELETE FROM cob.lcr1x7 lcr1x7 WHERE old_row.eval_key = lcr1x7.evalkey;
DELETE FROM cob.lcr200 lcr200 WHERE old_row.eval_key = lcr200.evalkey;
DELETE FROM cob.lcr204_b lcr204_b WHERE old_row.eval_key = lcr204_b.evalkey;
DELETE FROM cob.lcr204_h lcr204_h WHERE old_row.eval_key = lcr204_h.evalkey;
DELETE FROM cob.lcr210 lcr210 WHERE old_row.eval_key = lcr210.evalkey;
DELETE FROM cob.lcr210_exp lcr210_exp WHERE old_row.eval_key = lcr210_exp.evalkey;
DELETE FROM cob.lcr214 lcr214 WHERE old_row.eval_key = lcr214.evalkey;
DELETE FROM cob.lcr220 lcr220 WHERE old_row.eval_key = lcr220.lcr220_evalkey;
DELETE FROM cob.lcr240 lcr240 WHERE old_row.eval_key = lcr240.evalkey;
DELETE FROM cob.lcr326 lcr326 WHERE old_row.eval_key = lcr326.evalkey;
DELETE FROM cob.lcr326_exp lcr326_exp WHERE old_row.eval_key = lcr326_exp.evalkey;
DELETE FROM cob.lcr433 lcr433 WHERE old_row.eval_key = lcr433.evalkey;
 RETURN old_row; END; $_$;


