--
-- Name: exists_role(character varying); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.exists_role(rolle character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$   DECLARE          abfrage TEXT;   BEGIN          IF NOT EXISTS (SELECT * FROM pg_roles WHERE rolname = rolle) THEN           abfrage := 'CREATE ROLE ' || rolle || ' WITH LOGIN NOSUPERUSER NOINHERIT NOCREATEDB NOCREATEROLE NOREPLICATION VALID UNTIL ''infinity'';';           EXECUTE abfrage;          END IF;           abfrage := 'GRANT USAGE ON SCHEMA ' || current_schema || ' TO ' || rolle || ';';           EXECUTE abfrage;          END;   $$;


--
-- Name: f_dependency_lister(integer, oid, oid); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.f_dependency_lister(ebin integer, refobj oid, refclass oid, OUT ebene integer, OUT poid oid, OUT pclass oid, OUT objekttype text, OUT dpschema text, OUT dpoid oid, OUT dpname text, OUT dpclname text, OUT intern boolean, OUT droptext text) RETURNS SETOF record
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
 abfrage text;
 nspalte text;
 sspalte text;
 dpclass oid;		--pg_class.oid der System-Tabelle in der das abhaengige Objekt verzeichnet ist
 reltyp pg_class.relkind%type;
 trigrelname text;	--Name der Tabelle zu der der Trigger gehoert
 colnum INT;
 colname text;
 oidbuf oid;		--Zum Zwischenspeichern der pg_namespace.oid
 dpoid2 oid;
 soid oid;
 viewrelname text;
 dparray text[];
 vgarray text[];
BEGIN
 dparray := ARRAY[''];

FOR ebene, dpoid, dpclname, intern IN SELECT ebin, objid, ( SELECT relname FROM pg_class pc WHERE pc.oid = classid ), (CASE WHEN deptype = 'i' THEN true ELSE false END) FROM pg_depend WHERE refobjid = refobj AND refclassid = refclass LOOP
	--RAISE NOTICE '% % % % %', ebene, dpschema, dpoid, dpclname, intern;
	nspalte := 'unbekannt';
	dpschema := NULL;
	sspalte := NULL;
	abfrage := 'SELECT oid FROM pg_class WHERE relname = ''' || dpclname || ''';';
	EXECUTE abfrage INTO dpclass;
	IF dpclname = 'pg_trigger' THEN
		objekttype := 'TRIGGER';
		nspalte := 'tgname';
	ELSIF dpclname = 'pg_class' THEN
		abfrage := 'SELECT relkind FROM pg_class WHERE oid = ' || dpoid;
		EXECUTE abfrage INTO reltyp;
		IF reltyp = 'i' THEN
			objekttype := 'INDEX';
			sspalte := 'relnamespace';
			nspalte := 'relname';
		ELSIF reltyp = 'v' THEN
			objekttype := 'VIEW';
			sspalte := 'relnamespace';
			nspalte := 'relname';
		ELSIF reltyp = 'r' THEN
			objekttype := 'TABLE';
			sspalte := 'relnamespace';
			nspalte := 'relname';
		ELSIF reltyp = 'S' OR reltyp = 's' THEN
			objekttype := 'SEQUENCE';
			sspalte := 'relnamespace';
			nspalte := 'relname';
		ELSIF reltyp = 'c' THEN
			objekttype := 'COMPOSITE TYPE';
			nspalte := 'IGNORE';
		ELSIF reltyp = 't' THEN
			objekttype := 'TOAST TABLE';
			nspalte := 'IGNORE';
		ELSIF reltyp = 'f' THEN
			objekttype := 'FOREIGN TABLE';
			nspalte := 'IGNORE';
		ELSE
			RAISE WARNING 'pg_class.relkind % unbekannt!', reltyp;
		END IF;
	ELSIF dpclname = 'pg_type' THEN
		objekttype := 'TYPE';
		sspalte := 'typnamespace';
		nspalte := 'typname';
	ELSIF dpclname = 'pg_proc' THEN
		objekttype := 'FUNCTION';
		sspalte := 'pronamespace';
		nspalte := 'proname';
	ELSIF dpclname = 'pg_rewrite' THEN
		objekttype := 'VIEW';
		nspalte := 'ev_class';
	ELSIF dpclname = 'pg_attrdef' THEN
		objekttype := 'DEFAULT';
		--nspalte := 'adsrc';  --auskommentiert, weil zu PostgreSQL 12 die Spalte adsrc weggefallen ist
	ELSIF dpclname = 'pg_constraint' THEN
		objekttype := 'CONSTRAINT';
		nspalte := 'conname';
	END IF;
	IF nspalte NOT IN ('unbekannt', 'IGNORE') THEN
		IF nspalte = 'ev_class' THEN
			abfrage := 'SELECT oid FROM pg_class WHERE relname = ''pg_class''';
			EXECUTE abfrage INTO dpclass;
			FOR dpoid2 IN SELECT DISTINCT ev_class FROM pg_rewrite WHERE oid = dpoid LOOP
				SELECT relname, relnamespace FROM pg_class INTO viewrelname, soid WHERE oid = dpoid2;
				SELECT nspname FROM pg_namespace INTO dpschema WHERE oid = soid;
				IF dpoid2 <> refobj THEN
					--RAISE NOTICE '% %', dpoid2, viewrelname;
					dpoid := dpoid2;
					dpname := viewrelname;
					dpclname := 'pg_class';
					IF dpschema IS NOT NULL THEN
						droptext := 'DROP ' || objekttype || ' IF EXISTS ' || quote_ident(dpschema) || '.' || quote_ident(dpname) || ';';
					ELSE
						droptext := 'DROP ' || objekttype || ' IF EXISTS ' || quote_ident(dpname) || ';';
					END IF;
					vgarray := ARRAY[dpoid2::text || '|' || dpclass::text];
					IF NOT (vgarray <@ dparray) THEN
						poid := refobj;
						pclass := refclass;
						RETURN NEXT;
						dparray := array_append(dparray, dpoid2::text || '|' || dpclass::text );
						RETURN QUERY SELECT * FROM f_dependency_lister( (ebene + 1), dpoid2, dpclass );
					END IF;
				END IF;
			END LOOP;
			CONTINUE;
		ELSIF nspalte <> 'proname' AND nspalte <> 'conname' THEN
			IF sspalte IS NOT NULL THEN
				abfrage := 'SELECT ' || sspalte || ',' || nspalte || ' FROM ' || dpclname || ' WHERE oid = ' || dpoid;
				EXECUTE abfrage INTO soid, dpname;
			ELSE
				abfrage := 'SELECT ' || nspalte || ' FROM ' || dpclname || ' WHERE oid = ' || dpoid;
				EXECUTE abfrage INTO dpname;
			END IF;
		ELSIF nspalte = 'proname' THEN
			abfrage := 'SELECT ' || sspalte || ',' || nspalte || ' FROM ' || dpclname || ' WHERE oid = ' || dpoid;
			EXECUTE abfrage INTO soid, dpname;
			dpname := regprocedure(dpoid);
		END IF;
		SELECT nspname FROM pg_namespace INTO dpschema WHERE oid = soid;
		droptext := 'DROP ' || objekttype || ' ' || dpschema || '.' || dpname;
		IF dpclname = 'pg_trigger' THEN
			SELECT tgrelid FROM pg_trigger INTO oidbuf WHERE oid = dpoid;
			SELECT relnamespace, relname FROM pg_class c INTO soid, trigrelname WHERE c.oid = oidbuf;
			SELECT nspname FROM pg_namespace INTO dpschema WHERE oid = soid;
			droptext := 'DROP ' || objekttype || ' ' || dpschema || '.' || dpname || ' ON ' || dpschema || '.' || trigrelname;
		END IF;
		IF dpclname = 'pg_attrdef' THEN
			SELECT adrelid, adnum FROM pg_attrdef INTO oidbuf, colnum WHERE oid = dpoid;
			SELECT relnamespace, relname FROM pg_class c INTO soid, trigrelname WHERE c.oid = oidbuf;
			SELECT nspname FROM pg_namespace INTO dpschema WHERE oid = soid;
			SELECT attname INTO colname FROM pg_attribute WHERE attrelid = oidbuf AND attnum = colnum AND NOT attisdropped;
			droptext := 'ALTER TABLE ' || dpschema || '.' || trigrelname || ' ALTER COLUMN ' || colname || ' DROP DEFAULT';
		END IF;
		IF dpclname = 'pg_constraint' THEN
			--Noch nicht ausgewertet
		END IF;
		droptext := droptext || ';';

		vgarray := ARRAY[dpoid::text || '|' || dpclass::text];
		IF refobj <> dpoid AND NOT (vgarray <@ dparray) THEN
			poid := refobj;
			pclass := refclass;
			RETURN NEXT;
			dparray := array_append(dparray, dpoid::text || '|' || dpclass::text );
		END IF;
		RETURN QUERY SELECT * FROM f_dependency_lister( (ebene + 1), dpoid, dpclass );
	ELSIF nspalte = 'unbekannt' THEN
		RAISE INFO 'System-Tabelle % nicht (komplett) beruecksichtigt!', dpclname;
	ELSE
		IF objekttype <> 'TOAST TABLE' THEN
			RAISE INFO '% wird ignoriert', objekttype;
		END IF;
	END IF;
END LOOP;

END;
$$;


--
-- Name: FUNCTION f_dependency_lister(ebin integer, refobj oid, refclass oid, OUT ebene integer, OUT poid oid, OUT pclass oid, OUT objekttype text, OUT dpschema text, OUT dpoid oid, OUT dpname text, OUT dpclname text, OUT intern boolean, OUT droptext text); Type: COMMENT; Schema: cob; Owner: -
--

COMMENT ON FUNCTION cob.f_dependency_lister(ebin integer, refobj oid, refclass oid, OUT ebene integer, OUT poid oid, OUT pclass oid, OUT objekttype text, OUT dpschema text, OUT dpoid oid, OUT dpname text, OUT dpclname text, OUT intern boolean, OUT droptext text) IS 'f_dependency_lister 1.11 (10.03.2020)';


--
-- Name: f_dump_drop_nuidx(integer, integer, text[]); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.f_dump_drop_nuidx(izahl integer, szahl integer, ausnahmen text[]) RETURNS character
    LANGUAGE plpgsql
    AS $$
DECLARE
	fver text;
	abfrage text;
	tab_name text;
	ignr BOOLEAN;
	indexliste pg_indexes%rowtype;
	indexcreate pg_indexes.indexdef%type;
	idrop pg_indexes.indexname%type;
	idroparr text[];
	icr integer;
	idropstring text;
	rp pg_class.relpages%type;
	rn pg_class.relname%type;
BEGIN

fver := '1.2';
RAISE NOTICE 'f_dump_drop_nuidx(int,int,text[]) % (05.11.2015)', fver;
SELECT tablename INTO tab_name FROM pg_tables WHERE schemaname = current_schema() AND tablename = '_idx_sicherung';
IF tab_name IS NULL THEN
	abfrage := 'CREATE TABLE _idx_sicherung AS SELECT indexdef FROM pg_indexes WHERE 1=0';
	RAISE NOTICE '%', abfrage;
	EXECUTE abfrage;
ELSE
	RAISE NOTICE 'Tabelle _idx_sicherung existiert bereits.';
END IF;

FOR rn, rp IN SELECT relname, relpages FROM pg_class WHERE relkind = 'r' AND ( relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname = current_schema()) ) AND ( relname IN (SELECT tablename FROM pg_indexes WHERE schemaname = current_schema() AND indexdef LIKE 'CREATE INDEX%' GROUP BY tablename HAVING count(tablename) >= izahl ) ) AND relpages >= szahl ORDER BY relpages DESC LOOP

	indexcreate := NULL;
	idrop := NULL;
	idroparr := NULL;
	icr := 0;
	ignr := false;

	FOR i IN 1..array_upper(ausnahmen, 1) LOOP
		IF rn = ausnahmen[i] THEN
			ignr := true;
			RAISE NOTICE 'Tabelle % wird ignoriert', rn;
			EXIT;
		ELSE
			ignr := false;
		END IF;
	END LOOP;

	IF ignr = false THEN
		RAISE NOTICE 'Anweisungen zum Erstellen der NON-Unique-Indexe fuer Tabelle % werden in Tabelle _idx_sicherung gesichert', rn;

		FOR indexliste IN SELECT * FROM pg_indexes WHERE schemaname = current_schema() AND tablename = rn AND indexdef LIKE 'CREATE INDEX%' LOOP
			icr := icr+1;
			indexcreate := indexliste.indexdef;
			abfrage := 'INSERT INTO _idx_sicherung VALUES(' || quote_literal(indexcreate) || ');';
			RAISE NOTICE '%', abfrage;
			EXECUTE abfrage;
			idrop := indexliste.indexname;
			idroparr[icr] := idrop::text;
		END LOOP;

		--Loeschen von NON-UNIQUE Indices
		RAISE NOTICE 'Die % NON-Unique-Indexe fuer Tabelle % werden nun geloescht', array_upper(idroparr, 1)::text, rn;
		FOR i IN 1..array_upper(idroparr, 1) LOOP
			idropstring := 'DROP INDEX ' || idroparr[i]::text;
			RAISE NOTICE '%', idropstring;
			EXECUTE idropstring;
		END LOOP;

	END IF;

END LOOP;

RETURN 'Erfolgreich beendet';
END;
$$;


--
-- Name: FUNCTION f_dump_drop_nuidx(izahl integer, szahl integer, ausnahmen text[]); Type: COMMENT; Schema: cob; Owner: -
--

COMMENT ON FUNCTION cob.f_dump_drop_nuidx(izahl integer, szahl integer, ausnahmen text[]) IS 'f_dump_drop_nuidx(int,int,text[]) v1.2';


--
-- Name: f_dump_drop_single_table_nuidx(text, text[]); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.f_dump_drop_single_table_nuidx(name_tab text, ausnahmen text[]) RETURNS character
    LANGUAGE plpgsql
    AS $$  DECLARE     ignr BOOLEAN;     abfrage text;     name_seq text;     indexliste pg_indexes%rowtype;     indexcreate pg_indexes.indexdef%type;     idrop pg_indexes.indexname%type;     idroparr text[];     icr integer;     idropstring text;  BEGIN  ignr := false;  icr := 0;  indexcreate := NULL;  idrop := NULL;  idroparr := NULL;  abfrage := 'CREATE TABLE ' || name_tab || '_idx_backup AS SELECT indexdef FROM pg_indexes WHERE 1=0';  RAISE NOTICE '%', abfrage;  EXECUTE abfrage;     FOR indexliste IN SELECT * FROM pg_indexes WHERE schemaname = current_schema() AND tablename = name_tab AND indexdef LIKE 'CREATE INDEX%' LOOP     FOR i IN 1..array_upper(ausnahmen, 1) LOOP     IF indexliste.indexname = ausnahmen[i] THEN     ignr := true;     RAISE NOTICE 'Index % wird ignoriert.', indexliste.indexname;     EXIT;     ELSE     ignr := false;     END IF;     END LOOP;     IF ignr = false THEN     icr := icr +1;     indexcreate := indexliste.indexdef;     abfrage := 'INSERT INTO '|| name_tab || '_idx_backup VALUES(' || quote_literal(indexcreate) || ');';     EXECUTE abfrage;     idrop := indexliste.indexname;     idroparr[icr] := idrop::text;     END IF;     END LOOP;     IF icr = 0 THEN     RAISE NOTICE 'Kein NON-Unique Index in % ', name_tab;     END IF;     IF icr > 0 THEN     RAISE NOTICE '% NON-Unique-Index(e) fuer Tabelle % wird/werden geloescht', array_upper(idroparr, 1)::text, name_tab;     FOR i IN 1..array_upper(idroparr, 1) LOOP     idropstring := 'DROP INDEX ' || idroparr[i]::text;     RAISE NOTICE '%', idropstring;     EXECUTE idropstring;     END LOOP;     END IF;  RETURN 'Erfolgreich beendet';  END;  $$;


--
-- Name: f_dumpe_tabellen(text); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.f_dumpe_tabellen(in_copy_path text) RETURNS character
    LANGUAGE plpgsql
    AS $_$
DECLARE
 --global
  f_oid oid;
  c_txt text;
  dump_mode_string text;
  dump_mode text;
  cfg_mode_string text;
  read_cfg boolean;
  write_cfg boolean;
  ifx_mode boolean;
  ifx_mode_string text;
  copy_path text; --Ausgabepfad auf dem Server
  ifx_copy_path text; --Ausgabepfad auf dem Server
  schema_oid oid; --OID des aktuellen Schemas
  sql_query text; --Enthaelt String von dynamisch generierten SQL-Abfragen
  ifx_unload_sql_query text; --Unload-Anweisungen fuer Informix
  conf_loaded boolean;
  valid_copy_path boolean;
  can_write boolean;
  dump_activated boolean;

 --Spalten
  col_fname text; --Spaltenname
  col_ord_p int; --Nummer der Spalte in der Tabelle
  col_max_row_count integer; --Nummer der Spalte mit den meisten Werten
  cols_exc_arr text[]; --Array der auszulassenden Spalten
  cols_exc_text text; --Text ''
  cols_ord_comb integer []; --Array aller Spalten, nach denen sortiert wird
  cols_ord integer[]; --Array der Spalten, nach denen sortiert wird - Ohne Serials
  cols_ord_p integer; --Pointer auf cols_ord
  cols_ord_ser integer[]; --Array der Serial-Spalten, nach denen sortiert wird
  cols_ord_ser_p integer; --Pointer auf cols_ord_ser
  cols_ord_text text; --String fuer die 'ORDER BY'-Spalten
  cols_sel_arr text[]; --Array mit den selektierten Spalten
  cols_sel_arr_copy text[]; --Anhand von cols_exc_arr gefilterte Kopie von cols_sel_arr
  cols_sel_text text; --SELECT-String
  col_dv_type text; --Fuer Test auf Typ der Spalte = Serial

 --Indices
  idx_name text; --Index-Name
  idx_cols pg_index.indkey%type; --Array der Spalten, auf denen der Index liegt
  idx_oid pg_class.oid%type; --Spalten-OID
  idx_rec pg_index%rowtype;
  pk_name information_schema.table_constraints.table_name%type; --Eine der Spalten, auf denen der Index liegt
  row_counter integer; --Zaehler fuer Datensaetze
  row_max_count integer; --Die bislang hoechste Anzahl an Werten in einer Spalte

 --Tabellen
  tab_name pg_tables.tablename%type; --Tabellenname
  tab_oid pg_class.oid%type; --Tabellen-OID
  tab_state integer; -- 1 = Tabelle wird gedumpt
  tab_has_ord_info boolean; --wahr wenn geeignete Spalten zum Sortieren gefunden worden sind
  tab_rec pg_tables%rowtype;
  tab_row_check text; --Fuer die Pruefung, ob bereits ein Datensatz fuer eine Tabelle existiert

 --Foreign Key Constraints
  automap_fk boolean;
  all_fk_arr text[]; --Alle Foreign Key Mappings zu einer Tabelle. 1 Element = 1 Mapping
  all_fk_text text; --Inhalt von/fuer _customize_dumping.foreign_key_replacement
  fkarr int2[]; --Foreign Key Spalten
  rfkarr int2[]; --Liste der referenzierten Spalten
  fkname name; --Name des Foreign Key Constraints
  fkcol text; --Name der Foreign Key Spalte
  rfktaboid oid; --OID der referenzierten Tabelle
  rfktab text; --Name der referenzierten Tabelle
  rfkcol text; --Name der referenzierten Spalte
  rfkaltcols text;
  rfkaltcolarr text[]; --Liste mit Namen von Spalten, die alternativ ausgelesen werden
  rfkaltcol name; --Name der Spalte, die statt fkcol ausgelesen wird
  fkalias text; --Alias fuer referenzierte Tabelle
  fkac int; --Alias Pointer - fuer die Erstellung von fkalias
  fkcolalias text; --Spalten-Alias
  tabstring text;
  fkcoltype text;

BEGIN
 SET log_min_messages TO notice;
 conf_loaded := false;
 valid_copy_path := false;
	RAISE NOTICE 'f_dumpe_tabellen() v1.27 (07.09.2015)';
	SELECT pg_namespace.oid INTO schema_oid FROM pg_namespace WHERE pg_namespace.nspname = current_schema()::name;
	SELECT p.oid INTO f_oid FROM pg_catalog.pg_proc p LEFT JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = current_schema() AND p.oid::regprocedure::text = 'f_dumpe_tabellen(text)';
	SELECT obj_description(f_oid, 'pg_proc') INTO c_txt;

	--IFX-Modus
		--ON: Es wird eine SQL-Datei mit Unload-Anweisungen fuer Informix generiert.
	IF SUBSTRING( c_txt FROM E'.*(IFX-Modus:.*?)\\s+.*') IS NOT NULL THEN
		ifx_mode_string := SUBSTRING( c_txt FROM E'.*(IFX-Modus:.*?)\\s+.*');
	ELSIF SUBSTRING( c_txt FROM E'.*(IFX-Modus:.*?)\\s*?') IS NOT NULL THEN
		ifx_mode_string := SUBSTRING( c_txt FROM E'.*(IFX-Modus:.*?)\\s*?');
	END IF;
	ifx_mode_string := SUBSTRING( ifx_mode_string FROM E'IFX-Modus:(.*)');
	ifx_mode_string := UPPER(ifx_mode_string);
	IF ifx_mode_string = 'ON' THEN
		RAISE NOTICE 'Generiere eine SQL-Datei mit Unload-Anweisungen fuer Informix.';
		ifx_mode := true;
		CREATE TEMP TABLE _ifx_unload ( sql_zeile text );
	ELSIF ifx_mode_string = 'OFF' THEN
		ifx_mode := false;
	ELSE
		RAISE NOTICE 'Der im Kommentar zur Funktion angegebene IFX-Modus (%) ist unbekannt!', ifx_mode_string;
		ifx_mode := false;
		RAISE NOTICE 'IFX-Modus wird daher auf % gesetzt!', ifx_mode;
	END IF;

	--CFG-Modus
	IF SUBSTRING( c_txt FROM E'.*(CFG-Modus:.*?)\\s+.*') IS NOT NULL THEN
		cfg_mode_string := SUBSTRING( c_txt FROM E'.*(CFG-Modus:.*?)\\s+.*');
	ELSIF SUBSTRING( c_txt FROM E'.*(CFG-Modus:.*?)\\s*?') IS NOT NULL THEN
		cfg_mode_string := SUBSTRING( c_txt FROM E'.*(CFG-Modus:.*?)\\s*?');
	END IF;
	cfg_mode_string := SUBSTRING( cfg_mode_string FROM E'CFG-Modus:(.*)');
	cfg_mode_string := UPPER(cfg_mode_string);
	IF cfg_mode_string IN ('R', 'RW') THEN
		RAISE NOTICE 'Es wird versucht die Sicherung (_customize_dumping) der Konfiguration zu laden.';
		read_cfg := true;
	ELSIF cfg_mode_string IN ('W', 'RW') THEN
		RAISE NOTICE 'Die Konfiguration wird nach dem Lauf in Datei ''_customize_dumping'' gesichert.';
		write_cfg := true;
	ELSE
		RAISE NOTICE 'Der im Kommentar zur Funktion angegebene CFG-Modus (%) ist unbekannt!', cfg_mode_string;
		RAISE NOTICE 'Die Konfiguration wird weder geladen noch anschliessend gesichert.';
	END IF;

	RAISE NOTICE 'Werte Tabellen in Schema % in Datenbank % aus.', current_schema()::text, current_database()::text;

	--DUMP-Modus
	IF SUBSTRING( c_txt FROM E'.*(DUMP-Modus:.*?)\\s+.*') IS NOT NULL THEN
		dump_mode_string := SUBSTRING( c_txt FROM E'.*(DUMP-Modus:.*?)\\s+.*');
	ELSIF SUBSTRING( c_txt FROM E'.*(DUMP-Modus:.*?)\\s*?') IS NOT NULL THEN
		dump_mode_string := SUBSTRING( c_txt FROM E'.*(DUMP-Modus:.*?)\\s*?');
	END IF;
	dump_mode := SUBSTRING( dump_mode_string FROM E'DUMP-Modus:(.*)');
	dump_mode := UPPER(dump_mode);
	IF dump_mode = 'ALL' THEN
		RAISE NOTICE 'Alle Tabellen werden gedumpt.';
	ELSIF dump_mode = 'NONE' THEN
		RAISE NOTICE 'Es wird keine Tabelle gedumpt.';
	ELSIF dump_mode = 'STATE' THEN
		RAISE NOTICE 'Tabelle wird gedumpt, wenn _customize_dumping.table_state  = 1.';
	ELSIF dump_mode = 'STATELOADED' THEN
		RAISE NOTICE 'Tabelle wird gedumpt, wenn _customize_dumping.table_state  = 1 und diese Daten enthaelt.';
	ELSIF dump_mode IS NULL THEN
		dump_mode := 'NONE';
		RAISE NOTICE 'Parameter DUMP-Modus konnte nicht gefunden werden! DUMP-Modus wird daher auf % gesetzt!', dump_mode;
	ELSE
		RAISE NOTICE 'Der im Kommentar zur Funktion angegebene DUMP-Modus (%) ist unbekannt!', dump_mode;
		dump_mode := 'NONE';
		RAISE NOTICE 'DUMP-Modus wird daher auf % gesetzt!', dump_mode;
	END IF;

	--Konfigurationstabelle anlegen, wenn sie nicht bereits existiert
	SELECT tablename INTO tab_name FROM pg_tables WHERE schemaname = current_schema() AND tablename = '_customize_dumping';
	IF tab_name IS NULL THEN
		CREATE TABLE _customize_dumping
		(
			tabname text,
			order_by_cols text,
			selected_cols text,
			excluded_cols text,
			where_condition text,
			foreign_key_replacement text,
			table_state integer
		)
		WITH (
			OIDS=TRUE
		);
		INSERT INTO _customize_dumping (tabname) VALUES ( '#SELECTION-MODE#' );
		INSERT INTO _customize_dumping (tabname, selected_cols) VALUES ( '#COPY-PATH#', '<- Insert absolute path to an already existing folder on the server! The tables will be copied as csv files into this folder. Make sure that postgres has the necessary permissions on this folder!' );
		INSERT INTO _customize_dumping (tabname, order_by_cols, selected_cols) VALUES ( '#FK_MAP_DEFAULT#', 'uniquename, defaulttext', '<- Insert list of column names to automatically look for in the referenced table (in order to replace a foreign key that is an integer) - #NODEF#  if you want to disable this feature.');
		RAISE NOTICE 'Tabelle _customize_dumping wurde neu angelegt.';
	ELSE
		RAISE NOTICE 'Tabelle _customize_dumping existiert bereits.';
		UPDATE _customize_dumping SET order_by_cols = NULL WHERE TRIM(order_by_cols) = '';
		UPDATE _customize_dumping SET selected_cols = NULL WHERE TRIM(selected_cols) = '';
		UPDATE _customize_dumping SET excluded_cols = NULL WHERE TRIM(excluded_cols) = '';
		UPDATE _customize_dumping SET where_condition = NULL WHERE TRIM(where_condition) = '';
		UPDATE _customize_dumping SET foreign_key_replacement = NULL WHERE TRIM(foreign_key_replacement) = '';
		UPDATE _customize_dumping SET table_state = 0 WHERE table_state IS NULL OR table_state NOT IN (0,1);
	END IF;

	--Ausgabepfad analysieren
	copy_path := TRIM(in_copy_path);
	IF TRIM(copy_path) = '' OR ( copy_path !~ E'\\\\{1,2}' AND copy_path !~ '/' ) THEN
		RAISE NOTICE '''%'' ist kein formal gueltiger Ausgabepfad!', copy_path;
		RAISE NOTICE 'Lese Parameter #COPY-PATH# aus Tabelle _customize_dumping';
		SELECT order_by_cols INTO copy_path FROM _customize_dumping WHERE tabname = '#COPY-PATH#';
	END IF;

	IF copy_path IS NULL OR TRIM(copy_path) = '' OR ( copy_path !~ E'\\\\{1,2}' AND copy_path !~ '/' ) THEN
		RAISE NOTICE 'Auch keinen formal gueltigen Ausgabepfad in Tabelle ''_customize_dumping'' gefunden!';
		read_cfg := false;
		write_cfg := false;
	ELSE
		--Bereinigen des Ausgabepfades
		copy_path := TRIM(copy_path);
		--Ersetze Backslashes mit einem Slash
		copy_path := regexp_replace ( copy_path, E'\\\\{1,2}', '/', 'g' );
		--Setze einen abschliessenden Slash wenn dieser fehlt
		IF copy_path !~ '.*/$' THEN
			copy_path := copy_path || '/';
		END IF;
		valid_copy_path := true;
	END IF;

	BEGIN
		CREATE TEMPORARY TABLE _customize_dumping_load AS SELECT * FROM _customize_dumping WHERE 1=0;
	EXCEPTION
		WHEN SQLSTATE '42P07' THEN
			TRUNCATE _customize_dumping_load;
			RAISE NOTICE 'Temporaere Tabelle _customize_dumping_load wurde geleert.';
		WHEN OTHERS THEN
			RAISE NOTICE '%', SQLSTATE;
			RAISE NOTICE '%', SQLERRM;
			RAISE EXCEPTION 'Temporaere Tabelle _customize_dumping_load konnte nicht angelegt werden!';
	END;

	IF read_cfg THEN
		BEGIN
			sql_query := 'COPY _customize_dumping_load FROM ''' || copy_path || '_customize_dumping'' WITH DELIMITER ''|'' NULL AS '''' CSV HEADER;';
			EXECUTE sql_query;
			conf_loaded := true;
			RAISE NOTICE 'Sicherung der Konfiguration eingeladen.';
			RAISE NOTICE '   %', sql_query;
		EXCEPTION
			WHEN SQLSTATE '58P01' THEN
				RAISE NOTICE 'Keine Sicherung von _customize_dumping gefunden.';
				conf_loaded := false;
			WHEN SQLSTATE '22P04' THEN
				RAISE NOTICE 'Das Format der Konfigurationssicherung entspricht nicht dem von COPY erwarteten Datei-Format! Beschaedigt?';
				conf_loaded := false;
			WHEN OTHERS THEN
				RAISE NOTICE '%', SQLSTATE;
				RAISE NOTICE 'Unbehandelte Ausnahme beim Laden der Konfigurationssicherung!';
				conf_loaded := false;
		END;

		IF conf_loaded THEN
			UPDATE _customize_dumping cus SET order_by_cols = ( SELECT order_by_cols FROM _customize_dumping_load cl WHERE cl.tabname = cus.tabname ) WHERE EXISTS ( SELECT order_by_cols FROM _customize_dumping_load cl2 WHERE cl2.tabname = cus.tabname AND cl2.order_by_cols IS NOT NULL AND TRIM(cl2.order_by_cols) <> '') AND ( cus.order_by_cols IS NULL OR TRIM(cus.order_by_cols) = '' );
			UPDATE _customize_dumping cus SET selected_cols = ( SELECT selected_cols FROM _customize_dumping_load cl WHERE cl.tabname = cus.tabname ) WHERE EXISTS ( SELECT selected_cols FROM _customize_dumping_load cl2 WHERE cl2.tabname = cus.tabname AND cl2.selected_cols IS NOT NULL AND TRIM(cl2.selected_cols) <> '') AND ( cus.selected_cols IS NULL OR TRIM(cus.selected_cols) = '' );
			UPDATE _customize_dumping cus SET excluded_cols = ( SELECT excluded_cols FROM _customize_dumping_load cl WHERE cl.tabname = cus.tabname ) WHERE EXISTS ( SELECT excluded_cols FROM _customize_dumping_load cl2 WHERE cl2.tabname = cus.tabname AND cl2.excluded_cols IS NOT NULL AND TRIM(cl2.excluded_cols) <> '') AND ( cus.excluded_cols IS NULL OR TRIM(cus.excluded_cols) = '' );
			UPDATE _customize_dumping cus SET foreign_key_replacement = ( SELECT foreign_key_replacement FROM _customize_dumping_load cl WHERE cl.tabname = cus.tabname ) WHERE EXISTS ( SELECT foreign_key_replacement FROM _customize_dumping_load cl2 WHERE cl2.tabname = cus.tabname AND cl2.foreign_key_replacement IS NOT NULL AND TRIM(cl2.foreign_key_replacement) <> '') AND ( cus.foreign_key_replacement IS NULL OR TRIM(cus.foreign_key_replacement) = '' );

			BEGIN
				INSERT INTO _customize_dumping (SELECT * FROM _customize_dumping_load cl WHERE NOT EXISTS ( SELECT tabname FROM _customize_dumping cus WHERE cus.tabname = cl.tabname ) );
			EXCEPTION
				WHEN OTHERS THEN
					RAISE NOTICE 'Beim Einfuegen von Zeilen aus _customize_dumping_load kam es zu Fehlern!';
			END;
		ELSE
			RAISE NOTICE 'Fehlgeschlagene COPY-Anweisung:';
			RAISE NOTICE '   %', sql_query;
		END IF;
	END IF;

	SELECT order_by_cols INTO rfkaltcols FROM _customize_dumping WHERE tabname = '#FK_MAP_DEFAULT#';
	IF rfkaltcols IS NOT NULL AND TRIM(rfkaltcols) <> '' AND TRIM(rfkaltcols) <> '#NODEF#' THEN
		rfkaltcols := regexp_replace ( rfkaltcols, E'\\\s+', '', 'g' );
		rfkaltcolarr := regexp_split_to_array ( rfkaltcols, ',' );
		RAISE NOTICE 'Looking for the following column names in order to create foreign key mappings automatically:';
		FOR i IN array_lower(rfkaltcolarr, 1)..array_upper(rfkaltcolarr, 1) LOOP
			RAISE NOTICE '  %', rfkaltcolarr[i];
		END LOOP;
		automap_fk := true;
	ELSE
		UPDATE _customize_dumping SET order_by_cols = '#NODEF#' WHERE tabname = '#FK_MAP_DEFAULT#';
--		RAISE NOTICE 'Foreign Key Mappings werden nicht automatisch generiert.';
		automap_fk := false;
	END IF;

	--Spalten order_by_cols und selected_cols in _customize_dumping fuellen wenn leer
	FOR tab_rec IN SELECT * FROM pg_tables WHERE schemaname = current_schema() AND tablename <> '_customize_dumping' AND tablename <> '_customize_dumping_load' ORDER BY tablename LOOP
		tab_name := tab_rec.tablename;
		SELECT tabname INTO tab_row_check FROM _customize_dumping WHERE tabname = tab_name;
		IF tab_row_check IS NULL THEN
			INSERT INTO _customize_dumping (tabname, table_state) VALUES (tab_name, 1);
		END IF;
		SELECT oid INTO tab_oid FROM pg_class WHERE relname = tab_name AND relnamespace = schema_oid;

		--Werte zuruecksetzen
		tab_has_ord_info := false;
		cols_sel_arr := ARRAY['----'];
		row_max_count := 0;
		cols_ord := ARRAY[-1];
		cols_ord_p := 1;
		cols_ord_ser := ARRAY[-1];
		cols_ord_ser_p := 1;
		cols_ord_comb := ARRAY[-1];
		col_max_row_count := NULL;
		dump_activated := false;

		--Spalte selected_cols fuellen, wenn leer
		SELECT selected_cols INTO cols_sel_text FROM _customize_dumping WHERE tabname = tab_name;
		IF cols_sel_text IS NULL OR TRIM(cols_sel_text) = '' THEN
			cols_sel_text := '';
			FOR col_fname IN SELECT column_name FROM information_schema.columns WHERE table_catalog = current_database() AND table_schema = current_schema() AND table_name = tab_name ORDER BY ordinal_position LOOP
				cols_sel_arr := array_append( cols_sel_arr, col_fname::text );
			END LOOP;

			FOR i IN array_lower(cols_sel_arr, 1)+1..array_upper(cols_sel_arr, 1) LOOP
				IF i < array_upper(cols_sel_arr, 1) THEN
					cols_sel_text := cols_sel_text || cols_sel_arr[i] || ', ';
				ELSE
					cols_sel_text := cols_sel_text || cols_sel_arr[i];
				END IF;
			END LOOP;
			UPDATE _customize_dumping SET selected_cols = cols_sel_text WHERE tabname = tab_name;
			RAISE NOTICE '%: selected_cols wurde aktualisiert!', tab_name;
		END IF;

		--Spalte order_by_cols fuellen, wenn leer
		SELECT order_by_cols INTO cols_ord_text FROM _customize_dumping WHERE tabname = tab_name;
		IF cols_ord_text IS NULL OR TRIM(cols_ord_text) = '' THEN

			RAISE NOTICE '%: order_by_cols wird aktualisiert!', tab_name;

			--Unique Indices
			FOR idx_rec IN SELECT * FROM pg_index WHERE indrelid = tab_oid AND indisunique LOOP
				idx_oid := idx_rec.indexrelid;
				idx_cols := idx_rec.indkey;

				SELECT relname INTO idx_name FROM pg_class WHERE oid = idx_oid;

				IF NOT idx_cols::int[] <@ cols_ord_comb THEN
					SELECT column_name INTO pk_name FROM information_schema.key_column_usage WHERE table_schema = current_schema() AND table_name = tab_name AND constraint_name = idx_name;
					IF pk_name IS NULL THEN
						RAISE NOTICE E'   unique index: % (OID: %)', idx_name, idx_oid;
					ELSE
						RAISE NOTICE E'   PK: % (OID: %)', idx_name, idx_oid;
					END IF;
					tab_has_ord_info := true;
					FOR i IN 0..array_upper(idx_cols, 1) LOOP
						SELECT attname INTO col_fname FROM pg_attribute WHERE attrelid = tab_oid AND NOT attisdropped AND attnum = idx_cols[i];
						IF ARRAY[idx_cols[i]::int] <@ cols_ord_comb THEN
							RAISE NOTICE E'      Spalte % (%) bereits beruecksichtigt (idx[]:%  / ord[]:%) (pidx: % / pord: %)!', col_fname, idx_cols[i], array_to_string(idx_cols, '/'), array_to_string(cols_ord, '/'), i, cols_ord_p;
						ELSE
							SELECT pg_get_expr(adbin, adrelid) INTO col_dv_type FROM pg_attrdef WHERE adrelid = tab_oid AND adnum = idx_cols[i];
							IF col_dv_type IS NULL OR col_dv_type NOT LIKE 'nextval(%' THEN
								RAISE NOTICE E'      %: %', idx_cols[i], col_fname;
								cols_ord[cols_ord_p] := idx_cols[i];
								cols_ord_p := cols_ord_p + 1;
							ELSE
								RAISE NOTICE E'      %: % (serial)', idx_cols[i], col_fname;
								cols_ord_ser[cols_ord_ser_p] := idx_cols[i];
								cols_ord_ser_p := cols_ord_ser_p + 1;
							END IF;
							cols_ord_comb := cols_ord_comb || idx_cols[i]::int;
						END IF;
					END LOOP;
				ELSE
					RAISE NOTICE E'      Alle Spalten bereits beruecksichtigt!';
				END IF;
			END LOOP;

			IF tab_has_ord_info = false AND tab_name <> '_customize_dumping' THEN
				RAISE NOTICE '   Keine Unique Indices gefunden!';
				FOR col_ord_p IN SELECT ordinal_position FROM information_schema.columns WHERE table_schema = current_schema() AND table_name = tab_name AND is_nullable = 'NO' LOOP
					cols_ord := cols_ord || col_ord_p;
					tab_has_ord_info := true;
				END LOOP;
			ELSE
				IF cols_ord_ser <> ARRAY[-1] THEN
					cols_ord := cols_ord || cols_ord_ser;
				END IF;
			END IF;

			IF tab_has_ord_info = false AND tab_name <> '_customize_dumping' THEN
				RAISE NOTICE '   ... ebenfalls keine NOT NULL Constraints!';

				FOR col_fname, col_ord_p IN SELECT column_name, ordinal_position FROM information_schema.columns WHERE table_schema = current_schema() AND table_name = tab_name LOOP
					sql_query := 'SELECT COUNT(' || col_fname || ') FROM ' || tab_name || ';';
					EXECUTE sql_query INTO row_counter;
					IF row_counter > row_max_count THEN
						col_max_row_count := col_ord_p;
						row_max_count := row_counter;
						RAISE NOTICE '% (%): %', col_fname, col_ord_p, row_max_count;
					END IF;
				END LOOP;
				cols_ord := cols_ord || col_max_row_count;
				tab_has_ord_info := true;
				IF col_max_row_count IS NULL THEN
					RAISE NOTICE '   ... ebenfalls keine Datensaetze -> erste Spalte ausgewaehlt!';
					cols_ord := cols_ord || 1;
				END IF;
			END IF;

			--RAISE NOTICE '%', array_to_string(cols_ord, '/');
			cols_ord_text := '';
			FOR i IN array_lower(cols_ord, 1)..array_upper(cols_ord, 1) LOOP
				IF cols_ord[i] <> -1 THEN
					SELECT attname INTO col_fname FROM pg_attribute WHERE attrelid = tab_oid AND attnum = cols_ord[i] AND NOT attisdropped;
					IF i < array_upper(cols_ord, 1) THEN
						cols_ord_text := cols_ord_text || col_fname || ', ';
					ELSE
						cols_ord_text := cols_ord_text || col_fname;
					END IF;
				END IF;
			END LOOP;

			IF TRIM(cols_ord_text) <> '' THEN
				UPDATE _customize_dumping SET order_by_cols = cols_ord_text WHERE tabname = tab_name;
				RAISE NOTICE '%: order_by_cols wurde aktualisiert!', tab_name;
			END IF;
		END IF;

		--Automatische Generierung von Foreign Key Mappings, wenn Feature (#FK_MAP_DEFAULT#) aktiviert und bislang kein Mapping zu dieser Tabelle existiert
		IF automap_fk THEN
			SELECT foreign_key_replacement INTO all_fk_text FROM _customize_dumping WHERE tabname = tab_name;
			IF all_fk_text IS NULL OR TRIM(all_fk_text) = '' THEN
				all_fk_text := '';
				FOR fkname, fkarr, rfktaboid, rfkarr IN SELECT conname, conkey, confrelid, confkey FROM pg_constraint WHERE conrelid = tab_oid AND contype = 'f' LOOP
					SELECT relname INTO rfktab FROM pg_class WHERE oid = rfktaboid;
					FOR i IN array_lower(rfkarr, 1)..array_upper(rfkarr, 1) LOOP
						IF i > 1 THEN
							RAISE EXCEPTION 'Keine 1:1 Beziehung?';
						END IF;
						SELECT attname INTO fkcol FROM pg_attribute WHERE attrelid = tab_oid AND NOT attisdropped AND attnum = fkarr[i];
						SELECT attname INTO rfkcol FROM pg_attribute WHERE attrelid = rfktaboid AND NOT attisdropped AND attnum = rfkarr[i];
						FOR i IN array_lower(rfkaltcolarr, 1)..array_upper(rfkaltcolarr, 1) LOOP
							SELECT attname INTO rfkaltcol FROM pg_attribute WHERE attrelid = rfktaboid AND NOT attisdropped AND attname = rfkaltcolarr[i];
							IF rfkaltcol IS NOT NULL THEN
								EXIT;
							END IF;
						END LOOP;
						SELECT data_type::text INTO fkcoltype FROM information_schema.columns WHERE table_schema = current_schema() AND table_name = tab_name AND column_name = rfkcol;

						IF fkcoltype NOT IN ('smallint', 'integer', 'bigint') THEN
							RAISE NOTICE 'Foreign Key ist kein Integer';
						ELSE
							IF rfkcol <> rfkaltcol THEN
								IF all_fk_text <> '' THEN
									all_fk_text := all_fk_text || '|#|';
								END IF;
								fkcolalias := rfktab;
								all_fk_text := all_fk_text || fkcol || ',' || rfktab || ',' || rfkcol || ',' || rfkaltcol || ',' || fkcolalias;
							END IF;
						END IF;
						IF all_fk_text IS NULL THEN
							RAISE EXCEPTION 'NULL in Foreign Key Mapping (Constraint: %)!', fkname;
						END IF;
					END LOOP;
				END LOOP;
				IF all_fk_text <> '' THEN
					UPDATE _customize_dumping SET foreign_key_replacement = all_fk_text WHERE tabname = tab_name;
					RAISE NOTICE '% - Foreign Key Mapping erstellt: %', tab_name, all_fk_text;
				ELSE
					--RAISE NOTICE '%: Es wurde kein Foreign Key Mapping erstellt.', tab_name;
				END IF;
			ELSE
				--RAISE NOTICE '%: Foreign Key Mapping bereits vorhanden.', tab_name;
			END IF;
		END IF;
	END LOOP;

	IF NOT valid_copy_path THEN
		RETURN 'Ausgabepfad ungueltig, Es werden keine Tabellen gedumpt!';
		can_write := false;
	ELSE
		can_write := true;
	END IF;

	IF can_write THEN
		BEGIN
			sql_query := 'COPY ( SELECT ''' ||  'DB: ' || current_database() || ' Schema: ' || current_schema() || ''') TO ''' || copy_path || '#source#''';
			EXECUTE sql_query;
		EXCEPTION
			WHEN SQLSTATE '42602' THEN
				RAISE NOTICE 'Ausgabepfad ''%'' nicht gefunden!', copy_path;
				can_write := false;
			WHEN OTHERS THEN
				RAISE NOTICE 'Unbekannter Fehler beim Schreiben der Datei ''#source#'' (SQLSTATE): %)!', SQLSTATE;
				can_write := false;
				RAISE NOTICE 'Anweisung: %', sql_query;
		END;
	END IF;

	--_customize_dumping sichern, falls sie nicht am Anfang geladen worden ist
	IF write_cfg AND can_write THEN
		sql_query := E'COPY ( SELECT * FROM _customize_dumping ORDER BY tabname ) TO ''' || copy_path || '_customize_dumping'' WITH DELIMITER ''|'' NULL AS '''' CSV HEADER;';
		EXECUTE sql_query;
	END IF;

	--Dump-Algorithmus
	IF can_write THEN
		IF dump_mode = 'ALL' THEN
			RAISE NOTICE 'Dumpe alle Tabellen nach%.', copy_path;
		ELSIF dump_mode = 'NONE' THEN
			RAISE NOTICE 'Es wird keine Tabelle gedumpt.';
		ELSIF dump_mode = 'STATE' THEN
			RAISE NOTICE 'Dumpe alle Tabellen, deren table_state = 1 ist nach ''%''.', copy_path;
		ELSIF dump_mode = 'STATELOADED' THEN
			RAISE NOTICE 'Dumpe alle Tabellen, die nicht leer sind und bei denen table_state = 1 ist nach ''%''.', copy_path;
		ELSE
			RAISE EXCEPTION 'Unbekannter dump_mode (%)!', dump_mode;
		END IF;
	ELSE
		RAISE WARNING 'Tabellen werden nicht gedumpt, da keine Ausgabe moeglich ist!';
	END IF;
	FOR tab_rec IN SELECT * FROM pg_tables WHERE schemaname = current_schema() AND tablename <> '_customize_dumping' AND tablename <> '_customize_dumping_load' ORDER BY tablename LOOP

		tab_name := tab_rec.tablename;

		--Tabelle ueberspringen, wenn table_state <> 1
		SELECT table_state INTO tab_state FROM _customize_dumping WHERE tabname = tab_name;
		IF tab_state <> 1 AND dump_mode IN ('STATE', 'STATELOADED') THEN
			RAISE NOTICE '% wird aufgrund _customize_dumping.table_state ignoriert!', tab_name;
			CONTINUE;
		ELSIF dump_mode <> 'NONE' THEN
			dump_activated := true;
		END IF;

		IF dump_mode = 'STATELOADED' THEN
			--Datensaetze zaehlen und wenn keine vorhanden sind zur naechsten Tabellen springen
			sql_query := 'SELECT COUNT(*) FROM ' || tab_name;
			EXECUTE sql_query INTO row_counter;
			IF row_counter = 0 THEN
				RAISE NOTICE '% enthaelt keine Daten.', tab_name;
				dump_activated := false;
			END IF;
		END IF;

		--Werte zuruecksetzen
		cols_sel_text := '';
		cols_sel_arr := ARRAY['----'];
		cols_sel_arr_copy := ARRAY['----'];
		cols_exc_arr := ARRAY['----'];
		fkac := 1;
		fkalias := '';

		RAISE NOTICE '%', tab_name;

		--Array aufbauen fuer die Spalten, die ignoriert werden sollen (aus Spalte excluded_cols)
		SELECT excluded_cols INTO cols_exc_text FROM _customize_dumping WHERE tabname = tab_name;
		IF cols_exc_text IS NOT NULL AND TRIM(cols_exc_text) <> '' THEN
			cols_exc_text := regexp_replace ( cols_exc_text, E'\\\s+', '', 'g' );
			cols_exc_arr := regexp_split_to_array ( cols_exc_text, ',' );
		ELSIF TRIM(cols_exc_text) = '' THEN
			UPDATE _customize_dumping SET excluded_cols = NULL WHERE tabname = tab_name;
		END IF;

		--Array fuer die Zuordnung eines Foreign Keys zu einem Text-Schluessel aufbauen
		SELECT foreign_key_replacement INTO all_fk_text FROM _customize_dumping WHERE tabname = tab_name;
		IF all_fk_text IS NOT NULL AND TRIM(all_fk_text) <> '' THEN
			all_fk_text := regexp_replace ( all_fk_text, E'\\\s+', '', 'g' );
			all_fk_arr := regexp_split_to_array ( all_fk_text, E'\\|#\\|' );
		ELSIF TRIM(all_fk_text) = '' THEN
			UPDATE _customize_dumping SET foreign_key_replacement = NULL WHERE tabname = tab_name;
		END IF;

		--Neues SELECT-Array aufbauen (in excluded_cols aufgefuehrte Spalten NICHT uebernehmen)
		SELECT selected_cols INTO cols_sel_text FROM _customize_dumping WHERE tabname = tab_name;
		cols_sel_text := regexp_replace ( cols_sel_text, E'\\\s+', '', 'g' );
		cols_sel_arr := regexp_split_to_array ( cols_sel_text, ',' );
		IF cols_exc_arr <> ARRAY['----'] THEN
			RAISE NOTICE E'   Es werden Spalten anhand von _customize_dumping.excluded_cols gefiltert';
			FOR i IN array_lower(cols_sel_arr, 1)..array_upper(cols_sel_arr, 1) LOOP
				FOR j IN 1..array_upper(cols_exc_arr, 1) LOOP
					IF cols_sel_arr[i] = cols_exc_arr[j] THEN
						RAISE NOTICE E'   Spalte ''%'' wird ausgelassen!', cols_exc_arr[j];
						cols_sel_arr[i] := '-';
						EXIT;
					END IF;
				END LOOP;
				IF cols_sel_arr[i] <> '-' AND cols_sel_arr[i] <> '----' THEN
					cols_sel_arr_copy := cols_sel_arr_copy || cols_sel_arr[i];
				END IF;
			END LOOP;
		ELSE
			cols_sel_arr_copy := cols_sel_arr;
			RAISE NOTICE E'   Alle in _customize_dumping.selected_cols angegebenen Spalten werden gedumpt.';
		END IF;
		cols_sel_text := '';
		cols_sel_arr := cols_sel_arr_copy;

		--Foreign Key Spalten ersetzen
		IF all_fk_arr IS NOT NULL THEN
			FOR i IN array_lower(all_fk_arr, 1)..array_upper(all_fk_arr, 1) LOOP
				fkcol := SUBSTRING(all_fk_arr[i] FROM  '^([^,]*?),.*$');
				rfktab := SUBSTRING(all_fk_arr[i] FROM  '^[^,]*?,([^,]*?),.*$');
				rfkcol := SUBSTRING(all_fk_arr[i] FROM  '^[^,]*?,[^,]*?,([^,]*?),.*$');
				rfkaltcol := SUBSTRING(all_fk_arr[i] FROM  '^[^,]*?,[^,]*?,[^,]*?,([^,]*?),.*$');
				fkcolalias := SUBSTRING(all_fk_arr[i] FROM  '^[^,]*?,[^,]*?,[^,]*?,[^,]*?,([^,]*?)$');
				FOR j IN array_lower(cols_sel_arr, 1)..array_upper(cols_sel_arr, 1) LOOP
					IF cols_sel_arr[j] = fkcol THEN
						fkac := fkac + 1;
						fkalias := 'tab' || fkac::text;
						cols_sel_arr[j] := '( SELECT DISTINCT ' || rfkaltcol || ' FROM ' || rfktab || ' ' || fkalias || ' WHERE ' || fkalias || '.' || rfkcol || ' = tab1.' || fkcol || ' ) AS ' || fkcolalias;
					END IF;
				END LOOP;
			END LOOP;
		END IF;

		--Endgueltige SELECT-Anweisung generieren
		--RAISE NOTICE '%', array_to_string(cols_sel_arr, '/');
		FOR i IN array_lower(cols_sel_arr, 1)..array_upper(cols_sel_arr, 1) LOOP
			IF cols_sel_arr[i] <> '----' THEN
				cols_sel_text := cols_sel_text || cols_sel_arr[i];
				IF i < array_upper(cols_sel_arr, 1) THEN
					cols_sel_text := cols_sel_text || ', ';
				END IF;
			END IF;
		END LOOP;

		IF TRIM(cols_sel_text) <> '' THEN
			IF fkac > 1 THEN
				tabstring := ' tab1';
			ELSE
				tabstring := '';
			END IF;

			IF ifx_mode THEN
				ifx_unload_sql_query := E'UNLOAD TO ' || quote_literal( tab_name || '.unl') || ' DELIMITER ''|'' SELECT ' || cols_sel_text || ' FROM ' || tab_name || tabstring || ' WHERE 1=1';
			END IF;
			sql_query := E'   COPY (SELECT ' || cols_sel_text || ' FROM ' || tab_name || tabstring;

			--Entlade-Anweisung abschliessen - Sortierung einfuegen falls definiert
			SELECT order_by_cols INTO cols_ord_text FROM _customize_dumping WHERE tabname = tab_name;
			IF cols_ord_text IS NOT NULL AND TRIM(cols_ord_text) <> '' THEN
				IF ifx_mode THEN
					ifx_unload_sql_query := ifx_unload_sql_query || E' ORDER BY ' || cols_ord_text || ';';
				END IF;
				sql_query := sql_query || E' ORDER BY ' || cols_ord_text || ') TO ' || quote_literal(  copy_path || tab_name || '.csv') || ' WITH DELIMITER ''|'' NULL AS '''' CSV HEADER;';
			ELSE
				RAISE NOTICE '%: Keine Sortierung!', tab_name;
				IF ifx_mode THEN
					ifx_unload_sql_query := ifx_unload_sql_query || ';';
				END IF;
				sql_query := sql_query || E') TO ' || quote_literal(  copy_path || tab_name || '.csv') || ' WITH DELIMITER ''|'' NULL AS '''' CSV HEADER;';
			END IF;

			IF ifx_mode THEN
				INSERT INTO _ifx_unload VALUES (ifx_unload_sql_query);
			END IF;

			RAISE NOTICE '%', sql_query;
			IF can_write AND dump_activated THEN
				EXECUTE sql_query;
			END IF;
		ELSE
			RAISE NOTICE E'   Alle Spalten gefiltert? Keine Spalte im SELECT-String!';
			CONTINUE;
		END IF;

	END LOOP;

	IF ifx_mode THEN
		sql_query := E'COPY ( SELECT sql_zeile FROM _ifx_unload ORDER BY sql_zeile ) TO ' || quote_literal(  copy_path || '_ifx_unload.sql') || ';';
		RAISE NOTICE '%', sql_query;
		IF can_write THEN
			EXECUTE sql_query;
		END IF;
		DROP TABLE _ifx_unload;
	END IF;

	IF can_write THEN
		RETURN 'Erfolgreich beendet';
	ELSE
		RETURN 'Es konnten keine Dateien geschrieben werden!';
	END IF;

	RESET log_min_messages;
END;
$_$;


--
-- Name: FUNCTION f_dumpe_tabellen(in_copy_path text); Type: COMMENT; Schema: cob; Owner: -
--

COMMENT ON FUNCTION cob.f_dumpe_tabellen(in_copy_path text) IS 'f_dumpe_tabellen(text) v1.27 CFG-Modus:W IFX-Modus:OFF DUMP-Modus:STATE';


--
-- Name: f_error_noright(character varying, character varying); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.f_error_noright(character varying, character varying) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
BEGIN
  RAISE EXCEPTION 'Keine Berechtigung für % in der Tabelle %', $1, $2;
  RETURN FALSE;
END;
$_$;


--
-- Name: f_error_on_rm_integration(); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.f_error_on_rm_integration() RETURNS character
    LANGUAGE plpgsql
    AS $$
DECLARE
 int_status text;
 schema_oid oid;
 syswert INT;
BEGIN
	int_status := 'Nein';
	syswert := -1;

	RAISE NOTICE 'f_error_on_rm_integration() 1.6 (14.1.2015)';
	SELECT pg_namespace.oid INTO schema_oid FROM pg_namespace WHERE pg_namespace.nspname = current_schema()::name;

	SELECT * INTO int_status FROM f_rm_integrationsstatus();
	IF int_status ~ 'Ja' THEN
		RAISE WARNING 'Eine aktive Integration wurde festgestellt (%)!', int_status;
		SELECT COUNT(*) FROM sys WHERE msnr = 'check_auf_ressourcen_integration' INTO syswert;
		IF syswert <> 1 THEN
			RAISE WARNING 'Systemschalter check_auf_ressourcen_integration nicht gefunden!';
		ELSE
			SELECT COUNT(*) FROM sys WHERE msnr = 'check_auf_ressourcen_integration' AND txt = '1' INTO syswert;
			IF syswert = 0 THEN
				RAISE WARNING 'Trotz externen Zugriffs auf Integrationstabellen wurde nicht abgebrochen, weil Sysschalter check_auf_ressourcen_integration nicht auf 1 steht';
				RETURN 'Trotz externen Zugriffs auf Integrationstabellen wurde nicht abgebrochen, weil Sysschalter check_auf_ressourcen_integration nicht auf 1 steht';
			END IF;
		END IF;
		RAISE EXCEPTION 'Aktive Ressourcen-Integration in einer oder beiden anderen Ressourcen-Datenbanken festgestellt. Ausgabe von ''SELECT f_rm_integrationsstatus()'' fuer Details pruefen';
	END IF;

	RETURN 'Keine Ressourcen-Integration gefunden.';
END;
$$;


--
-- Name: FUNCTION f_error_on_rm_integration(); Type: COMMENT; Schema: cob; Owner: -
--

COMMENT ON FUNCTION cob.f_error_on_rm_integration() IS 'f_error_on_rm_integration() 1.6 (14.01.2015)';


--
-- Name: f_get_rechte(); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.f_get_rechte(OUT benutzer text, OUT schem text, OUT tabelle text, OUT grant_komp text, OUT grant_redu text, OUT rev_komp text, OUT rev_redu text) RETURNS SETOF record
    LANGUAGE plpgsql IMMUTABLE
    AS $$

DECLARE
	role_count int;
	role_switch_limit int;
	switch_mode_string text;
	pg_version_num int;
	relschema text;
	relname text;
	aclist aclitem[];
	relgrantee text;
	privstring text;
	rellist information_schema.role_table_grants%rowtype;
	relprivtype information_schema.role_table_grants.privilege_type%type;
	relgrantable information_schema.role_table_grants.is_grantable%type;

	f_oid oid;
	c_txt text;

	-- Die SQL-Befehle zum Setzen der Rechte / Rueckgabewert der Funktion:
	grant_line1 text;
	grant_line2 text;
	grant_zahl int;
	grantable_line1 text;
	grantable_line2 text;
	grantable_zahl int;
	revoke_line1 text;
	revoke_line2 text;
	-- Test, ob neue Tabelle beginnt
	old_schema text;
	old_name text;
	old_grantee text;
	last_char text;
	last_char_string text;

	mtable_view BOOLEAN;

	ifx_mode boolean;
	ifx_mode_string text;
BEGIN

grant_line1 :='GRANT';
grant_line2 :='GRANT';
grant_zahl := 0;
grantable_line1 :='GRANT';
grantable_line2 :='GRANT';
grantable_zahl := 0;
revoke_line1 := '';
revoke_line2 := '';
old_schema := '';
old_name := '';
old_grantee := '';

RAISE NOTICE 'f_get_rechte() v1.18 (10.7.2013)';

SELECT p.oid INTO f_oid FROM pg_catalog.pg_proc p INNER JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = current_schema() AND p.oid::regprocedure::text = 'f_get_rechte()';
SELECT obj_description(f_oid, 'pg_proc') INTO c_txt;

IF SUBSTRING( c_txt FROM E'.*(SWITCH-LIMIT:.*?)\\s+.*') IS NOT NULL THEN
	switch_mode_string := SUBSTRING( c_txt FROM E'.*(SWITCH-LIMIT:.*?)\\s+.*');
ELSIF SUBSTRING( c_txt FROM E'.*(SWITCH-LIMIT:.*?)\\s*?') IS NOT NULL THEN
	switch_mode_string := SUBSTRING( c_txt FROM E'.*(SWITCH-LIMIT:.*?)\\s*?');
END IF;
role_switch_limit := (SUBSTRING( switch_mode_string FROM E'SWITCH-LIMIT:(.*)'))::int;

--IFX-Modus
	--ON: Nur SELECT-Recht auf 'multi-table views'
IF SUBSTRING( c_txt FROM E'.*(IFX-Modus:.*?)\\s+.*') IS NOT NULL THEN
	ifx_mode_string := SUBSTRING( c_txt FROM E'.*(IFX-Modus:.*?)\\s+.*');
ELSIF SUBSTRING( c_txt FROM E'.*(IFX-Modus:.*?)\\s*?') IS NOT NULL THEN
	ifx_mode_string := SUBSTRING( c_txt FROM E'.*(IFX-Modus:.*?)\\s*?');
END IF;
ifx_mode_string := SUBSTRING( ifx_mode_string FROM E'IFX-Modus:(.*)');
ifx_mode_string := UPPER(ifx_mode_string);
IF ifx_mode_string = 'ON' THEN
	RAISE NOTICE 'Filtere Rechte auf ''multi-table views''.';
	ifx_mode := true;
ELSIF ifx_mode_string = 'OFF' THEN
	ifx_mode := false;
ELSE
	RAISE NOTICE 'Der im Kommentar zur Funktion angegebene IFX-Modus (%) ist unbekannt!', ifx_mode_string;
	ifx_mode := false;
	RAISE NOTICE 'IFX-Modus wird daher auf % gesetzt!', ifx_mode;
END IF;

--LAST-CHAR:; - wenn jede SQL-Anweisung mit einem Semikolon abschliessen soll - z.B. um SQL-Skripte zu erstellen
IF SUBSTRING( c_txt FROM E'.*(LAST-CHAR:.*?)\\s+.*') IS NOT NULL THEN
	last_char_string := SUBSTRING( c_txt FROM E'.*(LAST-CHAR:.*?)\\s+.*');
ELSIF SUBSTRING( c_txt FROM E'.*(LAST-CHAR:.*?)\\s*?') IS NOT NULL THEN
	last_char_string := SUBSTRING( c_txt FROM E'.*(LAST-CHAR:.*?)\\s*?');
END IF;
last_char := SUBSTRING( last_char_string FROM E'LAST-CHAR:(.*)');
IF last_char IS NULL THEN
	RAISE NOTICE 'LAST-CHAR ist NULL!';
	last_char := '';
ELSIF TRIM(last_char) = '' THEN
--	RAISE NOTICE 'LAST-CHAR nicht gesetzt.';
	last_char := '';
END IF;

pg_version_num := current_setting('server_version_num');
IF pg_version_num >= 80400 THEN
--	RAISE NOTICE 'Server Version >=8.4';
END IF;

SELECT COUNT(rolname) INTO role_count FROM pg_roles;

IF role_count < role_switch_limit THEN
	RAISE NOTICE 'Es existieren % Rollen/Benutzer. Auslesen der Rechte erfolgt ueber das information_schema. (Switch-Limit = %).', role_count, role_switch_limit;

	FOR rellist IN SELECT * FROM information_schema.role_table_grants WHERE table_schema !~* 'information_schema' AND table_schema !~* '^pg_' AND table_name <> '_sv_connstr' ORDER BY table_schema, table_name, grantee, privilege_type LOOP
		relgrantee := rellist.grantee;
		relschema := rellist.table_schema;
		relname := rellist.table_name;
		relprivtype := rellist.privilege_type;
		relgrantable := rellist.is_grantable;

		--Nur SELECT-Rechte auf Views vergeben, die auf mehrere Tabellen zugreifen
		--IF EXISTS ( SELECT table_name FROM information_schema.views WHERE table_schema = current_schema AND table_name = relname AND SUBSTRING( UPPER(view_definition) FROM E'%#"FROM%(WHERE|GROUP BY|JOIN)#"%' FOR '#') ~ ',') THEN
		IF ifx_mode AND relname IN ( 'anteil_sum', 'bedarf_view', 'beleg_anz', 'db_spaltplaus_view', 'db_tabplaus_view', 'esum_nb08', 'esum_nb0810', 'esum_nb081012', 'esum_nb09', 'esum_nb10', 'esum_nb12', 'esum_nb14', 'esum_nb21', 'esum_pers', 'fachbereich_proj', 'fakt_bib', 'fakt_pers', 'fakt_stud', 'fgr_view', 'hs_view', 'hsfgr_view', 'hsstb_view', 'k_institut', 'kosten_stelle', 'pbz_sum', 'pgd_bau', 'pko_pbz', 'projekt', 'rnakfa_view', 'rp_bestand', 'rp_bewgeb', 'rp_bewnut', 'rp_bwert', 'rp_bwert1', 'rp_bwert2', 'rp_bwert3', 'rp_bwert4', 'rp_bwert5', 'rp_peranz', 'rp_umleg', 'rp_umleg0', 'stamm_view', 'stb_view', 'titel' ) THEN
			mtable_view := true;
		ELSE
			mtable_view := false;
		END IF;

		IF (relschema::text <> old_schema OR relname::text <> old_name OR relgrantee::text <> old_grantee)
		AND (old_schema <> '' AND old_name <> '' AND old_grantee <> '')
		AND (grant_zahl >= 1 OR grantable_zahl >= 1) THEN

			revoke_line1 := 'REVOKE ALL PRIVILEGES ON ' || old_schema || '.' || old_name || ' FROM ' || old_grantee || last_char;
			revoke_line2 := 'REVOKE ALL PRIVILEGES ON ' || old_name || ' FROM ' || old_grantee || last_char;

			IF grant_zahl >= 1 THEN
				grant_line1 := substring(grant_line1 FROM 1 FOR ((length(grant_line1))-1) );
				grant_line1 := grant_line1 || ' ON ' || old_schema || '.' || old_name || ' TO ' || old_grantee || last_char;
				grant_line2 := substring(grant_line2 FROM 1 FOR ((length(grant_line2))-1) );
				grant_line2 := grant_line2 || ' ON ' || old_name || ' TO ' || old_grantee || last_char;

				IF ( pg_version_num >= 80400 AND grant_zahl = 7 ) OR ( pg_version_num < 80400 AND grant_zahl = 6 ) THEN
					IF mtable_view THEN
						grant_line2 := 'GRANT SELECT ON ' || old_name || ' TO ' || old_grantee || last_char;
					ELSE
						grant_line2 := 'GRANT ALL ON ' || old_name || ' TO ' || old_grantee || last_char;
					END IF;
				END IF;

				SELECT INTO benutzer, schem, tabelle, grant_komp, grant_redu, rev_komp, rev_redu old_grantee, old_schema, old_name, grant_line1, grant_line2, revoke_line1, revoke_line2;
				RETURN NEXT;

			END IF;

			grant_zahl := 0;
			grant_line1 :='GRANT';
			grant_line2 :='GRANT';

			IF grantable_zahl >= 1 THEN
				grantable_line1 := substring(grantable_line1 FROM 1 FOR ((length(grantable_line1))-1) );
				grantable_line1 := grantable_line1 || ' ON ' || old_schema || '.' || old_name || ' TO ' || old_grantee || ' WITH GRANT OPTION' || last_char;
				grantable_line2 := substring(grantable_line2 FROM 1 FOR ((length(grantable_line2))-1) );
				grantable_line2 := grantable_line2 || ' ON ' || old_name || ' TO ' || old_grantee || ' WITH GRANT OPTION' || last_char;

				IF ( pg_version_num >= 80400 AND grantable_zahl = 7 ) OR ( pg_version_num < 80400 AND grantable_zahl = 6 ) THEN
					grantable_line2 := 'GRANT ALL ON ' || old_name || ' TO ' || old_grantee || ' WITH GRANT OPTION' || last_char;
				END IF;

				SELECT INTO benutzer, schem, tabelle, grant_komp, grant_redu, rev_komp, rev_redu old_grantee, old_schema, old_name, grantable_line1, grantable_line2, revoke_line1, revoke_line2;
				RETURN NEXT;

			END IF;

			grantable_zahl := 0;
			grantable_line1 :='GRANT';
			grantable_line2 :='GRANT';
		END IF;

		IF(relprivtype::text = 'SELECT')THEN
			IF relgrantable = 'NO' THEN
				grant_line1 := grant_line1 || ' SELECT,';
				grant_line2 := grant_line2 || ' SELECT,';
				grant_zahl := grant_zahl + 1;
			ELSE
				grantable_line1 := grantable_line1 || ' SELECT,';
				grantable_line2 := grantable_line2 || ' SELECT,';
				grantable_zahl := grantable_zahl + 1;
			END IF;

		ELSIF( mtable_view = false ) THEN

			IF(relprivtype::text = 'UPDATE')THEN
				IF relgrantable = 'NO' THEN
					grant_line1 := grant_line1 || ' UPDATE,';
					grant_line2 := grant_line2 || ' UPDATE,';
					grant_zahl := grant_zahl + 1;
				ELSE
					grantable_line1 := grantable_line1 || ' UPDATE,';
					grantable_line2 := grantable_line2 || ' UPDATE,';
					grantable_zahl := grantable_zahl + 1;
				END IF;

			ELSIF(relprivtype::text = 'INSERT')THEN
				IF relgrantable = 'NO' THEN
					grant_line1 := grant_line1 || ' INSERT,';
					grant_line2 := grant_line2 || ' INSERT,';
					grant_zahl := grant_zahl + 1;
				ELSE
					grantable_line1 := grantable_line1 || ' INSERT,';
					grantable_line2 := grantable_line2 || ' INSERT,';
					grantable_zahl := grantable_zahl + 1;
				END IF;

			ELSIF(relprivtype::text = 'DELETE')THEN
				IF relgrantable = 'NO' THEN
					grant_line1 := grant_line1 || ' DELETE,';
					grant_line2 := grant_line2 || ' DELETE,';
					grant_zahl := grant_zahl + 1;
				ELSE
					grantable_line1 := grantable_line1 || ' DELETE,';
					grantable_line2 := grantable_line2 || ' DELETE,';
					grantable_zahl := grantable_zahl + 1;
				END IF;

			ELSIF(relprivtype::text = 'REFERENCES')THEN
				IF relgrantable = 'NO' THEN
					grant_line1 := grant_line1 || ' REFERENCES,';
					grant_zahl := grant_zahl + 1;
				ELSE
					grantable_line1 := grantable_line1 || ' REFERENCES,';
					grantable_zahl := grantable_zahl + 1;
				END IF;

			ELSIF(relprivtype::text = 'TRIGGER')THEN
				IF relgrantable = 'NO' THEN
					grant_line1 := grant_line1 || ' TRIGGER,';
					grant_zahl := grant_zahl + 1;
				ELSE
					grantable_line1 := grantable_line1 || ' TRIGGER,';
					grantable_zahl := grantable_zahl + 1;
				END IF;

			ELSIF(relprivtype::text = 'TRUNCATE')THEN
				IF relgrantable = 'NO' THEN
					grant_line1 := grant_line1 || ' TRUNCATE,';
					grant_zahl := grant_zahl + 1;
				ELSE
					grantable_line1 := grantable_line1 || ' TRUNCATE,';
					grantable_zahl := grantable_zahl + 1;
				END IF;
			ELSE
				RAISE EXCEPTION 'Unbekanntes Privileg: % (Tabelle: %.% )', relprivtype::text, relschema, relname;
			END IF;
		END IF;

		old_schema := relschema::text;
		old_name := relname::text;
		old_grantee := relgrantee::text;

	END LOOP;

ELSE
	RAISE NOTICE 'Wechsele zum Auslesen auf pg_catalog, da % Rollen/Benutzer existieren (Switch-Limit: % ).', role_count, role_switch_limit;

	FOR relschema, relname, aclist IN SELECT sp.nspname, c.relname, c.relacl FROM pg_class c JOIN pg_namespace sp ON ( c.relkind = 'r' OR c.relkind = 'v' ) AND c.relnamespace = sp.oid AND sp.nspname !~* '^pg_' AND sp.nspname <> 'information_schema' AND c.relname <> '_sv_connstr' ORDER BY sp.nspname, c.relname LOOP

		IF aclist IS NOT NULL THEN
			FOR i IN array_lower(aclist, 1)..array_upper(aclist, 1) LOOP
				relgrantee := SUBSTRING( aclist[i]::text FROM '(.*)=.*');
				IF TRIM(relgrantee) = '' THEN
					relgrantee := 'public';
				END IF;
				privstring := SUBSTRING( aclist[i]::text FROM '.*=(.*)/.*');

				--Nur SELECT-Rechte auf Views vergeben, die auf mehrere Tabellen zugreifen
				--IF EXISTS ( SELECT table_name FROM information_schema.views WHERE table_schema = current_schema AND table_name = relname AND SUBSTRING( UPPER(view_definition) FROM E'%#"FROM%(WHERE|GROUP BY|JOIN)#"%' FOR '#') ~ ',') THEN
				IF ifx_mode AND relname IN ( 'anteil_sum', 'bedarf_view', 'beleg_anz', 'db_spaltplaus_view', 'db_tabplaus_view', 'esum_nb08', 'esum_nb0810', 'esum_nb081012', 'esum_nb09', 'esum_nb10', 'esum_nb12', 'esum_nb14', 'esum_nb21', 'esum_pers', 'fachbereich_proj', 'fakt_bib', 'fakt_pers', 'fakt_stud', 'fgr_view', 'hs_view', 'hsfgr_view', 'hsstb_view', 'k_institut', 'kosten_stelle', 'pbz_sum', 'pgd_bau', 'pko_pbz', 'projekt', 'rnakfa_view', 'rp_bestand', 'rp_bewgeb', 'rp_bewnut', 'rp_bwert', 'rp_bwert1', 'rp_bwert2', 'rp_bwert3', 'rp_bwert4', 'rp_bwert5', 'rp_peranz', 'rp_umleg', 'rp_umleg0', 'stamm_view', 'stb_view', 'titel' ) THEN
					mtable_view := true;
				ELSE
					mtable_view := false;
				END IF;

				IF( mtable_view = false ) THEN

					IF privstring ~ '.*d.*' THEN
						IF privstring !~ E'.*d\\*.*' THEN
							grant_line1 := grant_line1 || ' DELETE,';
							grant_line2 := grant_line2 || ' DELETE,';
							grant_zahl := grant_zahl + 1;
						ELSE
							grantable_line1 := grantable_line1 || ' DELETE,';
							grantable_line2 := grantable_line2 || ' DELETE,';
							grantable_zahl := grantable_zahl + 1;
						END IF;
					END IF;

					IF privstring ~ '.*a.*' THEN
						IF privstring !~ E'.*a\\*.*' THEN
							grant_line1 := grant_line1 || ' INSERT,';
							grant_line2 := grant_line2 || ' INSERT,';
							grant_zahl := grant_zahl + 1;
						ELSE
							grantable_line1 := grantable_line1 || ' INSERT,';
							grantable_line2 := grantable_line2 || ' INSERT,';
							grantable_zahl := grantable_zahl + 1;
						END IF;
					END IF;

					IF privstring ~ '.*x.*' THEN
						IF privstring !~ E'.*x\\*.*' THEN
							grant_line1 := grant_line1 || ' REFERENCES,';
							grant_zahl := grant_zahl + 1;
						ELSE
							grantable_line1 := grantable_line1 || ' REFERENCES,';
							grantable_zahl := grantable_zahl + 1;
						END IF;
					END IF;
				END IF;

				IF privstring ~ '.*r.*' THEN
					IF privstring !~ E'.*r\\*.*' THEN
						grant_line1 := grant_line1 || ' SELECT,';
						grant_line2 := grant_line2 || ' SELECT,';
						grant_zahl := grant_zahl + 1;
					ELSE
						grantable_line1 := grantable_line1 || ' SELECT,';
						grantable_line2 := grantable_line2 || ' SELECT,';
						grantable_zahl := grantable_zahl + 1;
					END IF;
				END IF;

				IF( mtable_view = false ) THEN

					IF privstring ~ '.*t.*' THEN
						IF privstring !~ E'.*t\\*.*' THEN
							grant_line1 := grant_line1 || ' TRIGGER,';
							grant_zahl := grant_zahl + 1;
						ELSE
							grantable_line1 := grantable_line1 || ' TRIGGER,';
							grantable_zahl := grantable_zahl + 1;
						END IF;
					END IF;

					IF privstring ~ '.*D.*' THEN
						IF privstring !~ E'.*D\\*.*' THEN
							grant_line1 := grant_line1 || ' TRUNCATE,';
							grant_zahl := grant_zahl + 1;
						ELSE
							grantable_line1 := grantable_line1 || ' TRUNCATE,';
							grantable_zahl := grantable_zahl + 1;
						END IF;
					END IF;

					IF privstring ~ '.*w.*' THEN
						IF privstring !~ E'.*w\\*.*' THEN
							grant_line1 := grant_line1 || ' UPDATE,';
							grant_line2 := grant_line2 || ' UPDATE,';
							grant_zahl := grant_zahl + 1;
						ELSE
							grantable_line1 := grantable_line1 || ' UPDATE,';
							grantable_line2 := grantable_line2 || ' UPDATE,';
							grantable_zahl := grantable_zahl + 1;
						END IF;
					END IF;

				END IF;

				revoke_line1 := 'REVOKE ALL PRIVILEGES ON ' || relschema || '.' || relname || ' FROM ' || relgrantee || last_char;
				revoke_line2 := 'REVOKE ALL PRIVILEGES ON ' || relname || ' FROM ' || relgrantee || last_char;

				IF grant_zahl >= 1 THEN
					grant_line1 := substring(grant_line1 FROM 1 FOR ((length(grant_line1))-1) );
					grant_line1 := grant_line1 || ' ON ' || relschema || '.' || relname || ' TO ' || relgrantee || last_char;
					grant_line2 := substring(grant_line2 FROM 1 FOR ((length(grant_line2))-1) );
					grant_line2 := grant_line2 || ' ON ' || relname || ' TO ' || relgrantee || last_char;

					IF ( pg_version_num >= 80400 AND grant_zahl = 7 ) OR ( pg_version_num < 80400 AND grant_zahl = 6 ) THEN
						IF mtable_view THEN
							grant_line2 := 'GRANT SELECT ON ' || relname || ' TO ' || relgrantee || last_char;
						ELSE
							grant_line2 := 'GRANT ALL ON ' || relname || ' TO ' || relgrantee || last_char;
						END IF;
					END IF;

					SELECT INTO benutzer, schem, tabelle, grant_komp, grant_redu, rev_komp, rev_redu relgrantee, relschema, relname, grant_line1, grant_line2, revoke_line1, revoke_line2;
					RETURN NEXT;
				END IF;

				grant_zahl := 0;
				grant_line1 :='GRANT';
				grant_line2 :='GRANT';

				IF grantable_zahl >= 1 THEN
					grantable_line1 := substring(grantable_line1 FROM 1 FOR ((length(grantable_line1))-1) );
					grantable_line1 := grantable_line1 || ' ON ' || relschema || '.' || relname || ' TO ' || relgrantee || ' WITH GRANT OPTION' || last_char;
					grantable_line2 := substring(grantable_line2 FROM 1 FOR ((length(grantable_line2))-1) );
					grantable_line2 := grantable_line2 || ' ON ' || relname || ' TO ' || relgrantee || ' WITH GRANT OPTION' || last_char;

					IF ( pg_version_num >= 80400 AND grantable_zahl = 7 ) OR ( pg_version_num < 80400 AND grantable_zahl = 6 ) THEN
						grantable_line2 := 'GRANT ALL ON ' || relname || ' TO ' || relgrantee || ' WITH GRANT OPTION' || last_char;
					END IF;

					SELECT INTO benutzer, schem, tabelle, grant_komp, grant_redu, rev_komp, rev_redu relgrantee, relschema, relname, grantable_line1, grantable_line2, revoke_line1, revoke_line2;
					RETURN NEXT;

				END IF;

				grantable_zahl := 0;
				grantable_line1 :='GRANT';
				grantable_line2 :='GRANT';

			END LOOP;

		END IF;

	END LOOP;

END IF;

END;
$$;


--
-- Name: FUNCTION f_get_rechte(OUT benutzer text, OUT schem text, OUT tabelle text, OUT grant_komp text, OUT grant_redu text, OUT rev_komp text, OUT rev_redu text); Type: COMMENT; Schema: cob; Owner: -
--

COMMENT ON FUNCTION cob.f_get_rechte(OUT benutzer text, OUT schem text, OUT tabelle text, OUT grant_komp text, OUT grant_redu text, OUT rev_komp text, OUT rev_redu text) IS 'f_get_rechte() v1.18 SWITCH-LIMIT:10 LAST-CHAR: IFX-Modus:OFF';


--
-- Name: f_initialisiere_lock_version(); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.f_initialisiere_lock_version() RETURNS character
    LANGUAGE plpgsql
    AS $$
DECLARE
 tabname text;
 abfrage text;

BEGIN

	FOR tabname IN SELECT t.table_name FROM information_schema.tables t INNER JOIN information_schema.columns c ON (c.table_name = t.table_name and c.table_schema = t.table_schema) WHERE c.column_name = 'lock_version' AND t.table_schema = current_schema AND t.table_type = 'BASE TABLE' ORDER BY t.table_schema, t.table_name LOOP

		abfrage := 'UPDATE ' || quote_ident(tabname) || ' SET lock_version = 0 WHERE lock_version IS NULL;';

		IF abfrage IS NOT NULL THEN
			RAISE NOTICE '%', abfrage;
			EXECUTE abfrage;
		ELSE
			RAISE WARNING 'abfrage IS NULL';
		END IF;

	END LOOP;

	RETURN 'Erfolgreich beendet';
END;
$$;


--
-- Name: f_initialisiere_obj_guid(); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.f_initialisiere_obj_guid() RETURNS character
    LANGUAGE plpgsql
    AS $$
DECLARE
 tabname text;
 abfrage text;

BEGIN

	FOR tabname IN SELECT t.table_name FROM information_schema.tables t INNER JOIN information_schema.columns c ON (c.table_name = t.table_name and c.table_schema = t.table_schema) WHERE c.column_name = 'obj_guid' AND t.table_schema = current_schema AND t.table_type = 'BASE TABLE' ORDER BY t.table_schema, t.table_name LOOP

		abfrage := 'UPDATE ' || quote_ident(tabname) || ' SET obj_guid = (md5(random()::text || clock_timestamp()::text)::uuid) WHERE obj_guid = ''0'' OR obj_guid IS NULL;';

		IF abfrage IS NOT NULL THEN
			RAISE NOTICE '%', abfrage;
			EXECUTE abfrage;
		ELSE
			RAISE WARNING 'abfrage IS NULL';
		END IF;

	END LOOP;

	RETURN 'Erfolgreich beendet';
END;
$$;


--
-- Name: f_konsistenz(); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.f_konsistenz() RETURNS character
    LANGUAGE plpgsql
    AS $_$
DECLARE
schema_oid oid;

fver text;
cver text;

--Variablen fuer die Konfiguration:
fsv_mode_string text;
fsv_mode text;
trim_mode text;
trim_mode_string text;
idxdrop_mode_string text;
idxdrop_mode text;
selection_mode text;
selection_mode_string text;
null_mode_string text;
null_mode text;
sim_mode boolean;
sim_mode_string text;
debug_mode boolean;
debug_mode_string text;

ftext text;
wschema name;
f_oid oid;
c_txt text;


tab_oid pg_class.oid%type;
pk_exists boolean; --wahr wenn eine eindeutige Zuordnung von temporaerer zu Original-Tabelle moeglich ist
name_tab pg_tables.tablename%type;
name_sp pg_attribute.attname%type;
rec_tab pg_tables%rowtype;
rec_sp pg_attribute%rowtype;
typ_sp pg_attribute.atttypid%type;
mod_sp pg_attribute.atttypmod%type;
num_sp pg_attribute.attnum%type;

abfrage text;
a1 text;
ausgabe text;
zaehler_update int;
tt1 text;
tt2 text;
dtabname text;

indexliste pg_indexes%rowtype;
indexcreate pg_indexes.indexdef%type;
indexcreatearr text[];
idrop pg_indexes.indexname%type;
idroparr text[];
icr int;
idropstring text;

uindexliste pg_indexes%rowtype;
uindexcreate pg_indexes.indexdef%type;
uindexcreatearr text[];
uidrop pg_indexes.indexname%type;
uidroparr text[];
uicr int;
uidropstring text;

ds_counter int;
skip_tab text[];
skip_sp text[];
sql_arr text[];
tdirty boolean;
dtc int;
simst text;

luidx int;
uidxtxt text;
uidxcols text[];
c_name_sp text;		--Eine Kopie von name_sp oder ein durch FSV- und/oder NULL-Modus angepasstes SELECT auf die Spalte eines Unique Index
c_uidxcols text[];		--Array von c_name_sp

spart text;
wpart text;
wstr text;

temprows int;
changes int;

col_dv_type text; --Fuer Test auf Typ der Spalte = Serial

charcolarr text[];
skiptt boolean;

--Indices
idx_name text; --Index-Name
idx_cols pg_index.indkey%type; --Array der Spalten, auf denen der Index liegt
idx_oid pg_class.oid%type; --Spalten-OID
idx_rec pg_index%rowtype;
pk_name information_schema.table_constraints.table_name%type; --Eine der Spalten, auf denen der Index liegt

ic int; --Anzahl Indexe
nc int; --Anzahl NULLs

BEGIN
skip_tab := ARRAY['dau', 'dauanf', 'druck' , 'fb', 'huel', 'ins', 'ins2', 'ins3', 'tit', 'ut'];
skip_sp := ARRAY['dr', 'dr2', 'fb', 'ins', 'ins2', 'ins3', 'tit', 'ut'];
dtc := 0;

	fver := '1.32';
	RAISE NOTICE 'f_konsistenz() % (04.12.2020)', fver;
	--Pruefung, ob bei Aufruf der Funktion ein PostgreSQL-Schema angegeben worden ist:
	ftext := TRIM( SUBSTRING( LOWER(current_query()) FROM E'.*select\\s*(.*?)f_konsistenz\\(\\)'));
	IF ftext IS NOT NULL THEN
		ftext := regexp_replace( ftext, E'\\.$', '');
		ftext := regexp_replace( ftext, E'\\*$', '');
		ftext := TRIM(ftext);
		IF ftext ~ E'\\s*' THEN
			ftext := regexp_replace( ftext, E'.*?\\s*?(\\S*?)$', E'\\1');
		END IF;
		SELECT pg_namespace.oid INTO schema_oid FROM pg_namespace WHERE pg_namespace.nspname = ftext::name;
		IF schema_oid IS NULL THEN
			IF ftext <> '' THEN
				RAISE WARNING 'Schema ''%'' nicht gefunden! Weiche auf das aktuelle Schema % aus!', ftext, current_schema();
			END IF;
			wschema := current_schema()::name;
		ELSIF ftext <> '' THEN
			wschema := ftext::name;
			--RAISE NOTICE 'Angegebenes Schema % gefunden.', ftext;
		ELSE
			wschema := current_schema()::name;
		END IF;
	END IF;
	IF wschema::text <> current_schema THEN
		RAISE NOTICE 'Ausfuehrung auf Tabellen in Schema % in Datenbank % und nicht im aktuellen Schema %!', wschema::text, current_database()::text, current_schema()::text;
	ELSE
		RAISE NOTICE 'Im Schema % von Datenbank %.', wschema::text, current_database()::text;
	END IF;
	SELECT pg_namespace.oid INTO schema_oid FROM pg_namespace WHERE pg_namespace.nspname = wschema::name;

	SELECT p.oid INTO f_oid FROM pg_catalog.pg_proc p LEFT JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = wschema AND p.oid::regprocedure::text LIKE E'%f\\_konsistenz()';
	IF f_oid IS NULL THEN
		RAISE WARNING 'OID der Funktion f_konsistenz() nicht gefunden!';
		RETURN 'Funktion f_konsistenz() abgebrochen!';
	END IF;
	SELECT obj_description(f_oid, 'pg_proc') INTO c_txt;

	cver := TRIM(SUBSTRING( c_txt FROM LOWER(E'f_konsistenz\\(\\)\\s+.*?(\\d*?\\.\\d*?)\\s+.*')));
	IF cver IS NULL THEN
		RAISE WARNING 'Keine Versionsangabe im Kommentar gefunden. Abbruch!';
		RETURN 'Funktion f_konsistenz() abgebrochen!';
	ELSIF cver <> fver THEN
		RAISE WARNING 'Version in Funktion (%) weicht von Version im Kommentar (%) zur Funktion ab!', fver, cver;
	END IF;

	--FSV-Modus: ON - bei Tabellen in skip_tab werden die Spalten in skip_sp bei NULL/leerem String <> ' ' auf ' ' gesetzt.
	IF SUBSTRING( c_txt FROM E'.*(FSV-Modus:.*?)\\s+.*') IS NOT NULL THEN
		fsv_mode_string := SUBSTRING( c_txt FROM E'.*(FSV-Modus:.*?)\\s+.*');
	ELSIF SUBSTRING( c_txt FROM E'.*(FSV-Modus:.*?)\\s*?') IS NOT NULL THEN
		fsv_mode_string := SUBSTRING( c_txt FROM E'.*(FSV-Modus:.*?)\\s*?');
	END IF;
	fsv_mode := SUBSTRING( fsv_mode_string FROM E'FSV-Modus:(.*)');
	fsv_mode := UPPER(fsv_mode);
	IF fsv_mode = 'ON' THEN
		RAISE NOTICE 'FSV-spezifische Spalten werden gesondert behandelt - '' '' als Default fuer nicht gesetzte Werte!';
	ELSIF fsv_mode = 'OFF' THEN
		RAISE NOTICE 'FSV-spezifische Spalten werden nicht gesondert behandelt! (DEFAULT)';
	ELSIF fsv_mode IS NULL THEN
		fsv_mode := 'OFF';
		RAISE NOTICE 'Parameter FSV-Modus konnte nicht gefunden werden! FSV-Modus wird daher auf % gesetzt! (DEFAULT)', fsv_mode;
	ELSE
		RAISE NOTICE 'Der im Kommentar zur Funktion angegebene FSV-Modus (%) ist unbekannt!', fsv_mode;
		fsv_mode := 'OFF';
		RAISE NOTICE 'FSV-Modus wird daher auf % gesetzt! (DEFAULT)', fsv_mode;
	END IF;

	--NULL-Modus: 'ON' oder 'OFF' - CHAR-Spalten auf NULL setzen, wenn diese nur Leerzeichen enthalten
	IF SUBSTRING( c_txt FROM E'.*(NULL-Modus:.*?)\\s+.*') IS NOT NULL THEN
		null_mode_string := SUBSTRING( c_txt FROM E'.*(NULL-Modus:.*?)\\s+.*');
	ELSIF SUBSTRING( c_txt FROM E'.*(NULL-Modus:.*?)\\s*?') IS NOT NULL THEN
		null_mode_string := SUBSTRING( c_txt FROM E'.*(NULL-Modus:.*?)\\s*?');
	END IF;
	null_mode := SUBSTRING( null_mode_string FROM E'NULL-Modus:(.*)');
	null_mode := UPPER(null_mode);
	IF null_mode = 'ON' THEN
		RAISE NOTICE 'CHAR-Spalten werden auf NULL gesetzt, wenn diese nur Leerzeichen enthalten!';
	ELSIF null_mode = 'OFF' THEN
		RAISE NOTICE 'CHAR-Spalten werden nicht auf NULL gesetzt, auch wenn diese nur Leerzeichen enthalten. (DEFAULT)';
	ELSIF null_mode IS NULL THEN
		null_mode := 'OFF';
		RAISE NOTICE 'Parameter NULL-Modus konnte nicht gefunden werden! Setze NULL-Modus auf %! (DEFAULT)', null_mode;
	ELSE
		RAISE NOTICE 'Der im Kommentar zur Funktion angegebene NULL-Modus (%) ist unbekannt!', null_mode;
		null_mode := 'OFF';
		RAISE NOTICE 'Setze NULL-Modus auf %! (DEFAULT)', null_mode;
	END IF;

	--IDXDROP-Modus: 'IDX', 'OLDIDX', 'UIDX' oder 'OFF'
	IF SUBSTRING( c_txt FROM E'.*(IDXDROP-Modus:.*?)\\s+.*') IS NOT NULL THEN
		idxdrop_mode_string := SUBSTRING( c_txt FROM E'.*(IDXDROP-Modus:.*?)\\s+.*');
	ELSIF SUBSTRING( c_txt FROM E'.*(IDXDROP-Modus:.*?)\\s*?') IS NOT NULL THEN
		idxdrop_mode_string := SUBSTRING( c_txt FROM E'.*(IDXDROP-Modus:.*?)\\s*?');
	END IF;
	idxdrop_mode := SUBSTRING( idxdrop_mode_string FROM E'IDXDROP-Modus:(.*)');
	idxdrop_mode := UPPER(idxdrop_mode);
	IF idxdrop_mode = 'IDX' THEN
		RAISE NOTICE 'Nur Indices, die nicht UNIQUE sind, werden ggf. fuer die Dauer des UPDATEs entfernt. (DEFAULT)';
	ELSIF idxdrop_mode = 'OLDIDX' THEN
		RAISE NOTICE 'Alle Indices, die nicht UNIQUE sind, werden fuer die Dauer des UPDATEs entfernt.';
	ELSIF idxdrop_mode = 'UIDX' THEN
		RAISE NOTICE 'UNIQUE Indices werden ggf. ebenfalls entfernt, nachdem die UPDATEs durchgefuehrt worden sind und anschliessend wieder neu angelegt!';
	ELSIF idxdrop_mode = 'OFF' THEN
		RAISE NOTICE 'Es werden keine Indices gedroppt und neu angelegt!';
	ELSIF idxdrop_mode IS NULL THEN
		idxdrop_mode := 'IDX';
		RAISE NOTICE 'Parameter IDXDROP-Modus konnte nicht gefunden werden! Setze IDXDROP-Modus auf %! (DEFAULT)', idxdrop_mode;
	ELSE
		RAISE NOTICE 'Der im Kommentar zur Funktion angegebene IDXDROP-Modus (%) ist unbekannt!', idxdrop_mode;
		idxdrop_mode := 'IDX';
		RAISE NOTICE 'Setze IDXDROP-Modus auf %! (DEFAULT)', idxdrop_mode;
	END IF;

	--SELECTION-Modus: 'ALLCHARCOLS', 'OLDALLCHARCOLS' oder 'TEMPTABLE'
	IF SUBSTRING( c_txt FROM E'.*(SELECTION-Modus:.*?)\\s+.*') IS NOT NULL THEN
		selection_mode_string := SUBSTRING( c_txt FROM E'.*(SELECTION-Modus:.*?)\\s+.*');
	ELSIF SUBSTRING( c_txt FROM E'.*(SELECTION-Modus:.*?)\\s*?') IS NOT NULL THEN
		selection_mode_string := SUBSTRING( c_txt FROM E'.*(SELECTION-Modus:.*?)\\s*?');
	END IF;
	selection_mode := SUBSTRING( selection_mode_string FROM E'SELECTION-Modus:(.*)');
	selection_mode := UPPER(selection_mode);
	IF selection_mode = 'ALLCHARCOLS' THEN
		RAISE NOTICE 'Die CHAR-Spalten aller Datensaetze werden aktualisiert, wenn die betreffende Tabelle Datensaetze enthaelt.';
	ELSIF selection_mode = 'OLDALLCHARCOLS' THEN
		RAISE NOTICE 'Wie in der urspruenglichen Version werden die CHAR-Spalten aller Datensaetze aktualisiert. (DEFAULT)';
	ELSIF selection_mode = 'TEMPTABLE' THEN
		RAISE NOTICE 'Bereinigung der Tabelle erfolgt ggf. ueber eine temporaere Tabelle. Schluessel-Spalten vom Typ CHAR werden vorher direkt bereinigt.';
	ELSIF selection_mode IS NULL THEN
		selection_mode := 'OLDALLCHARCOLS';
		RAISE NOTICE 'Parameter SELECTION-Modus konnte nicht gefunden werden! Setze SELECTION-Modus auf %! (DEFAULT)', selection_mode;
	ELSE
		RAISE NOTICE 'Der im Kommentar zur Funktion angegebene SELECTION-Modus (%) ist unbekannt!', selection_mode;
		selection_mode := 'OLDALLCHARCOLS';
		RAISE NOTICE 'Setze SELECTION-Modus auf %! (DEFAULT)', selection_mode;
	END IF;

	--TRIM-Modus: 'RIGHT' oder 'BOTH' ( = RIGHT und LEFT ) - bislang wurde nur RTRIM verwendet.
	IF SUBSTRING( c_txt FROM E'.*(TRIM-Modus:.*?)\\s+.*') IS NOT NULL THEN
		trim_mode_string := SUBSTRING( c_txt FROM E'.*(TRIM-Modus:.*?)\\s+.*');
	ELSIF SUBSTRING( c_txt FROM E'.*(TRIM-Modus:.*?)\\s*?') IS NOT NULL THEN
		trim_mode_string := SUBSTRING( c_txt FROM E'.*(TRIM-Modus:.*?)\\s*?');
	END IF;
	trim_mode := SUBSTRING( trim_mode_string FROM E'TRIM-Modus:(.*)');
	trim_mode := UPPER(trim_mode);
	IF trim_mode = 'BOTH' THEN
		RAISE NOTICE 'In CHAR-Feldern werden die Leerzeichen am Anfang und Ende entfernt!';
		trim_mode := 'trim';
	ELSIF trim_mode = 'RIGHT' THEN
		RAISE NOTICE 'In CHAR-Feldern werden nur nachfolgende Leerzeichen entfernt! (DEFAULT)';
		trim_mode := 'rtrim';
	ELSIF trim_mode IS NULL THEN
		trim_mode := 'rtrim';
		RAISE NOTICE 'Parameter TRIM-Modus konnte nicht gefunden werden! Setze TRIM-Modus auf %! (DEFAULT)', trim_mode;
	ELSE
		RAISE NOTICE 'Der im Kommentar zur Funktion angegebene TRIM-Modus (%) ist unbekannt!', trim_mode;
		trim_mode := 'rtrim';
		RAISE NOTICE 'Setze TRIM-Modus auf %! (DEFAULT)', trim_mode;
	END IF;

	--SIM-Modus: 'ON' oder 'OFF'
		--ON: Alle SQL-Anweisungen zum Aendern der Datenbank werden nur gemeldet aber nicht ausgefuehrt
	IF SUBSTRING( c_txt FROM E'.*(SIM-Modus:.*?)\\s+.*') IS NOT NULL THEN
		sim_mode_string := SUBSTRING( c_txt FROM E'.*(SIM-Modus:.*?)\\s+.*');
	ELSIF SUBSTRING( c_txt FROM E'.*(SIM-Modus:.*?)\\s*?') IS NOT NULL THEN
		sim_mode_string := SUBSTRING( c_txt FROM E'.*(SIM-Modus:.*?)\\s*?');
	END IF;
	sim_mode_string := SUBSTRING( sim_mode_string FROM E'SIM-Modus:(.*)');
	sim_mode_string := UPPER(sim_mode_string);
	IF sim_mode_string = 'ON' THEN
		RAISE NOTICE 'Es werden keine Aenderungen an der Datenbank durchgefuehrt.';
		sim_mode := true;
	ELSIF sim_mode_string = 'OFF' THEN
		RAISE NOTICE 'Etwaige Aenderungen werden durchgefuehrt. (DEFAULT)';
		sim_mode := false;
	ELSIF sim_mode_string IS NULL THEN
		sim_mode := false;
		RAISE NOTICE 'Parameter SIM-Modus konnte nicht gefunden werden! Setze SIM-Modus auf %! (DEFAULT)', sim_mode::text;
	ELSE
		RAISE NOTICE 'Der im Kommentar zur Funktion angegebene SIM-Modus (%) ist unbekannt!', sim_mode_string;
		sim_mode := false;
		RAISE NOTICE 'Setze SIM-Modus auf % (DEFAULT)', sim_mode;
	END IF;

	--DEBUG-Modus: 'ON' oder 'OFF'
		--ON: Erweiterte Ausgabe
	IF SUBSTRING( c_txt FROM E'.*(DEBUG-Modus:.*?)\\s+.*') IS NOT NULL THEN
		debug_mode_string := SUBSTRING( c_txt FROM E'.*(DEBUG-Modus:.*?)\\s+.*');
	ELSIF SUBSTRING( c_txt FROM E'.*(DEBUG-Modus:.*?)\\s*?') IS NOT NULL THEN
		debug_mode_string := SUBSTRING( c_txt FROM E'.*(DEBUG-Modus:.*?)\\s*?');
	END IF;
	debug_mode_string := SUBSTRING( debug_mode_string FROM E'DEBUG-Modus:(.*)');
	debug_mode_string := UPPER(debug_mode_string);
	IF debug_mode_string = 'ON' THEN
		RAISE NOTICE 'Erweiterte Ausgabe.';
		debug_mode := true;
	ELSIF debug_mode_string = 'OFF' THEN
		RAISE NOTICE 'Keine erweiterte Ausgabe. (DEFAULT)';
		debug_mode := false;
	ELSIF debug_mode_string IS NULL THEN
		debug_mode := false;
		RAISE NOTICE 'Parameter DEBUG-Modus konnte nicht gefunden werden! Setze DEBUG-Modus auf %!', debug_mode::text;
	ELSE
		RAISE NOTICE 'Der im Kommentar zur Funktion angegebene DEBUG-Modus (%) ist unbekannt!', debug_mode_string;
		debug_mode := false;
		RAISE NOTICE 'Setze DEBUG-Modus auf %', debug_mode;
	END IF;

	FOR rec_tab IN SELECT * FROM pg_tables WHERE schemaname = current_schema() ORDER BY tablename LOOP
		name_tab := rec_tab.tablename;
		SELECT oid INTO tab_oid FROM pg_class WHERE relname = quote_ident(name_tab) AND relnamespace = schema_oid;

		--Werte zuruecksetzen
		icr := 0;
		indexcreate := NULL;
		indexcreatearr := NULL;
		idrop := NULL;
		idroparr := NULL;
		uicr := 0;
		uindexcreate := NULL;
		uindexcreatearr := NULL;
		uidrop := NULL;
		uidroparr := NULL;

		sql_arr := ARRAY[''];

		luidx := 0;
		uidxtxt := '';

		pk_exists := false;
		temprows := 0;
		changes := 0;
		charcolarr := NULL;
		tdirty := false;
		skiptt := false;

		abfrage := 'SELECT COUNT(*) FROM ' || quote_ident(name_tab) || ';';
		EXECUTE abfrage INTO ds_counter;
		IF ds_counter = 0 AND ( selection_mode = 'TEMPTABLE' OR selection_mode = 'ALLCHARCOLS' ) THEN
			RAISE NOTICE '% enthaelt keine Datensaetze!', name_tab;
			CONTINUE;
		END IF;

		IF selection_mode IN ('OLDALLCHARCOLS', 'ALLCHARCOLS', 'TEMPTABLE') THEN
			IF selection_mode <> 'OLDALLCHARCOLS' THEN
				RAISE NOTICE '%', name_tab;
			END IF;
			dtabname := quote_ident(name_tab) || '_konsistenz';
			tt1 := 'CREATE TEMP TABLE ' || dtabname || ' AS SELECT ';
			tt2 := ' WHERE ';

			sql_arr := ARRAY[''];
			zaehler_update := 0;
			abfrage := 'update '||quote_ident(name_tab)|| ' set ';
			simst := 'SELECT COUNT(*) FROM '||quote_ident(name_tab)|| ' WHERE ';
			wstr := '';

			IF selection_mode = 'TEMPTABLE' THEN
				--Alle Unique Indexe zur Tabelle pruefen - in Reihenfolge der Spalten-Anzahl ( aufsteigend )
				FOR idx_rec IN SELECT * FROM pg_index WHERE indrelid = tab_oid AND indisunique ORDER BY array_length(indkey::int[], 1) ASC LOOP
					idx_oid := idx_rec.indexrelid;
					idx_cols := idx_rec.indkey;

					--Pruefung ob Index zu einem Primary Key gehoert:
					SELECT relname INTO idx_name FROM pg_class WHERE oid = idx_oid;
					SELECT column_name INTO pk_name FROM information_schema.key_column_usage WHERE table_schema = current_schema() AND table_name = name_tab AND constraint_name = idx_name;
					IF debug_mode THEN
						IF pk_name IS NULL THEN
							RAISE NOTICE E'   unique index: % (OID: %)', idx_name, idx_oid;
						ELSE
							RAISE NOTICE E'   PK: % (OID: %)', idx_name, idx_oid;
						END IF;
						RAISE NOTICE '    % Spalte(n)', array_length(idx_cols::int[], 1);
					END IF;

					--Index nur pruefen, wenn bislang noch kein geeigneter Index gefunden worden ist ( = eindeutige Zuordnung zu Zeilen in temporaerer Tabelle moeglich ):
					IF luidx = 0 THEN
						luidx := array_length(idx_cols::int[], 1);
						FOR i IN 0..array_upper(idx_cols, 1) LOOP
							SELECT attname, atttypid, atttypmod INTO name_sp, typ_sp, mod_sp FROM pg_attribute WHERE attrelid = tab_oid AND NOT attisdropped AND attnum = idx_cols[i];
							a1 := 'SELECT COUNT(*) FROM ' || quote_ident(name_tab) || ' WHERE ' || quote_ident(name_sp)|| ' IS NULL';
							IF debug_mode THEN
								RAISE NOTICE '      %', a1;
							END IF;
							EXECUTE a1 INTO nc;
							IF nc > 0 THEN
								IF debug_mode THEN
									RAISE WARNING '      NULLs in Index-Spalte % gefunden! Verwerfe Index %', name_sp, idx_name;
								END IF;
								luidx := 0;
								EXIT;
							END IF;
							IF format_type(typ_sp, mod_sp) LIKE 'char%' THEN
								IF fsv_mode = 'ON' AND skip_tab @> ARRAY[name_tab::text] AND skip_sp @> ARRAY[name_sp::text] THEN
									IF debug_mode THEN
										RAISE WARNING '     % ist eine FSV-Spalte!', name_sp;
									END IF;
									spart := '(CASE WHEN( ' || quote_ident(name_sp) || ' IS NULL OR ' || quote_ident(name_sp) || ' = '''' ) OR ( ' || trim_mode || '(' || quote_ident(name_sp) || ') = '''' AND ' || quote_ident(name_sp) || ' <> '' '' ) OR ' || quote_ident(name_sp) || ' = '' '' THEN '' '' ELSE ' || trim_mode || '(' || quote_ident(name_sp) || ') END)';
									wpart := '(( LENGTH(' || quote_ident(name_sp) || ') <> LENGTH(' || trim_mode || '(' || quote_ident(name_sp) || ')) AND ' || quote_ident(name_sp) || ' <> '' '' ) OR ( ' || quote_ident(name_sp) || ' IS NULL OR ' || quote_ident(name_sp) || ' = '''' ))';
								ELSIF null_mode = 'ON' THEN
									IF debug_mode THEN
										RAISE WARNING '     % ist eine CHAR-Spalte! (NULL-Mode)', name_sp;
									END IF;
									spart := '(CASE WHEN ' || trim_mode || '(' || quote_ident(name_sp) || ') = '''' THEN NULL ELSE ' || trim_mode || '(' || quote_ident(name_sp) || ') END)';
									wpart = trim_mode || '(' || quote_ident(name_sp) || ') = '''' OR LENGTH(' || quote_ident(name_sp) || ') <> LENGTH(' || trim_mode || '(' || quote_ident(name_sp) || '))';
								ELSE
									IF debug_mode THEN
										RAISE WARNING '     % ist eine CHAR-Spalte!', name_sp;
									END IF;
									spart := trim_mode || '(' || quote_ident(name_sp) || ')';
									wpart := 'LENGTH(' || quote_ident(name_sp) || ') <> LENGTH(' || trim_mode || '(' || quote_ident(name_sp) || '))';
								END IF;
								a1 := 'UPDATE ' || quote_ident(name_tab) || ' SET ' || quote_ident(name_sp) || ' = ' || spart || ' WHERE ' || wpart || ';';
								c_name_sp := spart || ' AS ' || quote_ident(name_sp);
								IF sim_mode THEN
									simst := 'SELECT COUNT(*) FROM ' || quote_ident(name_tab) || ' WHERE ' || wpart || ';';
									RAISE NOTICE '      SIM: %', a1;
									RAISE NOTICE '      %', simst;
									EXECUTE simst INTO changes;
									IF changes > 0 THEN
										RAISE NOTICE '      Index-Spalte % - Anzahl zu bereinigender Zeilen: %', name_sp, changes;
										tdirty := true;
										IF selection_mode = 'TEMPTABLE' AND NOT skiptt THEN
											RAISE WARNING '      Kein Update ueber eine temporaere Tabelle!';
											skiptt := true;
										END IF;
									END IF;
								ELSE
									IF debug_mode THEN
										RAISE NOTICE '      %', a1;
									END IF;
									EXECUTE a1;
									GET DIAGNOSTICS changes = ROW_COUNT;
									IF changes > 0 THEN
										RAISE NOTICE '       Anzahl geaenderter Zeilen in % ( durch Update von Spalte % ): %', name_tab, name_sp, changes;
										tdirty := true;
										IF selection_mode = 'TEMPTABLE' AND NOT skiptt THEN
											RAISE WARNING '      Kein Update ueber eine temporaere Tabelle!';
											skiptt := true;
										END IF;
									ELSIF debug_mode THEN
										RAISE NOTICE '       Keine Aenderungen durch Update von Spalte % in Tabelle %.', name_sp, name_tab;
									END IF;
								END IF;
							ELSE
								c_name_sp := name_sp;
							END IF;
							IF i = 0 THEN
								uidxcols := ARRAY[name_sp::text];
								c_uidxcols := ARRAY[c_name_sp::text];
							ELSE
								uidxcols := array_append( uidxcols, name_sp::text );
								c_uidxcols := array_append( c_uidxcols, c_name_sp::text );
							END IF;
							SELECT pg_get_expr(adbin, adrelid) INTO col_dv_type FROM pg_attrdef WHERE adrelid = tab_oid AND adnum = idx_cols[i];
							IF col_dv_type IS NULL OR col_dv_type NOT LIKE 'nextval(%' THEN
								IF debug_mode THEN
									RAISE NOTICE E'     %: %', idx_cols[i], name_sp;
								END IF;
							ELSE
								IF debug_mode THEN
									RAISE NOTICE E'     %: % (serial)', idx_cols[i], name_sp;
								END IF;
							END IF;
						END LOOP;
					END IF;
				END LOOP;

				IF luidx <> 0 THEN
					uidxtxt := '';
					FOR i IN 1..array_upper(uidxcols, 1) LOOP
						uidxtxt := uidxtxt || c_uidxcols[i] || ', ';
					END LOOP;
					tt1 := tt1 || uidxtxt;
					pk_exists := true;
				ELSE
					IF debug_mode THEN
						RAISE NOTICE '   keinen geeigneten Index fuer ein Update ueber eine temporaere Tabelle gefunden!';
					END IF;
				END IF;
			END IF;

			FOR rec_sp IN SELECT * FROM pg_attribute WHERE attrelid = tab_oid AND attnum > 0 AND NOT attisdropped LOOP
				name_sp := rec_sp.attname;
				typ_sp := rec_sp.atttypid;
				mod_sp := rec_sp.atttypmod;

				--Check auf Arraydatentyp
				IF format_type(typ_sp, mod_sp) ~ '.*.[]].*' THEN
					RAISE NOTICE 'Spalte % in Tabelle % enthaelt ein Array als Datentyp (%)! ', name_sp, name_tab, format_type(typ_sp, mod_sp);
					CONTINUE;
				END IF;

				IF format_type(typ_sp, mod_sp) LIKE 'char%' THEN
					zaehler_update := zaehler_update + 1;
					IF selection_mode = 'TEMPTABLE' THEN
						IF charcolarr IS NOT NULL THEN
							charcolarr := array_append( charcolarr, name_sp::text );
						ELSE
							charcolarr := ARRAY[name_sp::text];
						END IF;
					END IF;

					IF fsv_mode = 'ON' AND skip_tab @> ARRAY[name_tab::text] AND skip_sp @> ARRAY[name_sp::text] THEN
						spart := '(CASE WHEN( ' || quote_ident(name_sp) || ' IS NULL OR ' || quote_ident(name_sp) || ' = '''' ) OR ( ' || trim_mode || '(' || quote_ident(name_sp) || ') = '''' AND ' || quote_ident(name_sp) || ' <> '' '' ) OR ' || quote_ident(name_sp) || ' = '' '' THEN '' '' ELSE ' || trim_mode || '(' || quote_ident(name_sp) || ') END)';
						wpart := '(( LENGTH(' || quote_ident(name_sp) || ') <> LENGTH(' || trim_mode || '(' || quote_ident(name_sp) || ')) AND ' || quote_ident(name_sp) || ' <> '' '' ) OR ( ' || quote_ident(name_sp) || ' IS NULL OR ' || quote_ident(name_sp) || ' = '''' ))';
					ELSIF null_mode = 'ON' THEN
						spart := '(CASE WHEN ' || trim_mode || '(' || quote_ident(name_sp) || ') = '''' THEN NULL ELSE ' || trim_mode || '(' || quote_ident(name_sp) || ') END)';
						wpart = trim_mode || '(' || quote_ident(name_sp) || ') = '''' OR LENGTH(' || quote_ident(name_sp) || ') <> LENGTH(' || trim_mode || '(' || quote_ident(name_sp) || '))';
					ELSE
						IF selection_mode = 'OLDALLCHARCOLS' THEN
							spart := trim_mode || '(' || quote_ident(name_sp) || ',' || quote_literal(' ') || ')';
						ELSE
							spart := trim_mode || '(' || quote_ident(name_sp) || ')';
						END IF;
						wpart := 'LENGTH(' || quote_ident(name_sp) || ') <> LENGTH(' || trim_mode || '(' || quote_ident(name_sp) || '))';
					END IF;
					abfrage := abfrage || quote_ident(name_sp) || ' = ' || spart || ', ';
					wstr := wstr || wpart || ' OR ';
					IF uidxcols @> ARRAY[name_sp::text] AND selection_mode = 'TEMPTABLE' THEN
						IF debug_mode THEN
							RAISE WARNING '      Spalte % gehoert zum verwendeten Unique Index!', name_sp;
						END IF;
					ELSE
						tt1 := tt1 || spart || ' AS ' || quote_ident(name_sp) || ', ';
						tt2 := tt2 || wpart || ' OR ';
					END IF;
				END IF;
			END LOOP;

			IF selection_mode = 'TEMPTABLE' THEN
				IF pk_exists AND charcolarr IS NOT NULL THEN
					tt1 := substring(tt1 FROM 1 FOR ((length(tt1))-2) ) || ' FROM ' || quote_ident(name_tab);
					tt2 := substring(tt2 FROM 1 FOR ((length(tt2))-4) );
					tt1 := tt1 || tt2 || ';';
					IF debug_mode THEN
						RAISE NOTICE '       %', tt1;
					END IF;
					EXECUTE tt1;
					GET DIAGNOSTICS temprows = ROW_COUNT;
					IF temprows > 0 THEN
						RAISE NOTICE '        Anzahl Datensaetze in %: %!', dtabname, temprows;
					END IF;
				ELSIF charcolarr IS NULL THEN
					RAISE NOTICE '   Keine CHAR-Spalten gefunden!';
				ELSE
					RAISE NOTICE '   Update ueber temporaere Tabelle nicht moeglich! Weiche auf direktes Update aus!';
					skiptt := true;
				END IF;
			END IF;

			IF zaehler_update > 0 AND ( ( selection_mode = 'TEMPTABLE' AND skiptt ) OR selection_mode <> 'TEMPTABLE') THEN
				IF selection_mode = 'OLDALLCHARCOLS' THEN
					abfrage := SUBSTRING(abfrage FROM 1 FOR ((LENGTH(abfrage))-2) );
				ELSE
					abfrage := SUBSTRING(abfrage FROM 1 FOR ((LENGTH(abfrage))-2) ) || ' WHERE ' || SUBSTRING(wstr FROM 1 FOR ((LENGTH(wstr))-4) ) ||  ';';
					IF sim_mode THEN
						simst := 'SELECT COUNT(*) FROM ' || quote_ident(name_tab) || ' WHERE ' || SUBSTRING(wstr FROM 1 FOR ((LENGTH(wstr))-4) ) || ';';
						--RAISE NOTICE '    %', simst;
						EXECUTE simst INTO changes;
						IF changes > 0 THEN
							RAISE NOTICE 'Anzahl der Zeilen in Tabelle % die aktualisiert wuerden: %', name_tab, changes;
							tdirty := true;
						END IF;
					END IF;
				END IF;
				sql_arr := array_append( sql_arr, abfrage );
			END IF;
		END IF;

		IF ((array_length(sql_arr, 1))-1) > 0 OR selection_mode = 'OLDALLCHARCOLS' OR ( selection_mode = 'TEMPTABLE' AND temprows > 0 AND charcolarr IS NOT NULL ) THEN
			IF idxdrop_mode = 'IDX' OR idxdrop_mode = 'UIDX' OR idxdrop_mode = 'OLDIDX' THEN
				FOR indexliste IN SELECT * FROM pg_indexes WHERE schemaname = current_schema() AND tablename = quote_ident(name_tab) AND indexdef LIKE 'CREATE INDEX%' ORDER BY indexname ASC LOOP
					icr := icr +1;
					indexcreate := indexliste.indexdef;
					indexcreatearr[icr] := indexcreate::text;
					idrop := indexliste.indexname;
					idroparr[icr] := idrop::text;
				END LOOP;

				IF icr = 0 THEN
					SELECT COUNT(*) INTO ic FROM pg_indexes WHERE schemaname = current_schema() AND tablename = quote_ident(name_tab);
					IF ic > 0 THEN
						IF selection_mode = 'OLDALLCHARCOLS' THEN
							RAISE NOTICE 'Kein NON-Unique Index in % ', name_tab;
						ELSE
							RAISE NOTICE '   Kein Index ohne Unique Constraint.';
						END IF;
					ELSIF selection_mode = 'OLDALLCHARCOLS' THEN
						RAISE NOTICE 'Kein NON-Unique Index in % ', name_tab;
					END IF;
				END IF;

				--Loeschen von NON-UNIQUE Indices
				IF icr > 0 THEN
					IF selection_mode = 'OLDALLCHARCOLS' THEN
						RAISE NOTICE 'In der Tabelle % gibt es % NON-Unique Index(e)', name_tab, array_upper(idroparr, 1)::text;
					ELSE
						RAISE NOTICE '   hat % Index(e) ohne Unique Constraint.', array_upper(idroparr, 1)::text;
					END IF;
					FOR i IN 1..array_upper(idroparr, 1) LOOP
						idropstring := 'DROP INDEX ' || quote_ident(idroparr[i]::text);
						IF sim_mode THEN
							RAISE NOTICE '    SIM: %', idropstring;
						ELSE
							RAISE NOTICE '    %', idropstring;
							EXECUTE idropstring;
						END IF;
					END LOOP;
				END IF;
			END IF;

			FOR i IN (array_lower(sql_arr, 1)+1)..array_upper(sql_arr, 1) LOOP
				abfrage := sql_arr[i];
				ausgabe := abfrage;
				IF LENGTH(ausgabe) > 4000 THEN
					ausgabe := substring(ausgabe from 1 for 4000) || ' ... <Rest der Abfrage unterdrueckt>';
				END IF;
				IF sim_mode THEN
					RAISE NOTICE '    SIM: %', ausgabe;
				ELSE
					RAISE NOTICE '    %', ausgabe;
					EXECUTE abfrage;
					GET DIAGNOSTICS changes = ROW_COUNT;
					IF changes > 0 THEN
						tdirty := true;
					END IF;
				END IF;
			END LOOP;

			--UPDATE ueber temporaere Tabelle
			IF selection_mode = 'TEMPTABLE' AND NOT skiptt THEN
				IF pk_exists THEN
					IF charcolarr IS NOT NULL THEN
						tdirty := true;
						abfrage := 'UPDATE ' || quote_ident(name_tab) || ' t1 SET ';
						FOR i IN 1..array_upper(charcolarr, 1) LOOP
							abfrage := abfrage || charcolarr[i] || ' = t2.' || charcolarr[i] || ', ';
						END LOOP;
						abfrage := substring(abfrage FROM 1 FOR ((length(abfrage))-2) );
						abfrage := abfrage || ' FROM ' || dtabname || ' t2 WHERE ';
						FOR i IN 1..array_upper(uidxcols, 1) LOOP
							abfrage := abfrage || 't1.' || uidxcols[i] || ' = t2.' || uidxcols[i] || ' AND ';
						END LOOP;
						abfrage := substring(abfrage FROM 1 FOR ((length(abfrage))-5) );
						IF sim_mode THEN
							RAISE NOTICE '   SIM: %', abfrage;
						ELSE
							RAISE NOTICE '   %', abfrage;
							EXECUTE abfrage;
							GET DIAGNOSTICS changes = ROW_COUNT;
							IF changes <> temprows THEN
								RAISE EXCEPTION '   Anzahl geanderter Zeilen (%) weicht von der Anzahl in Tabelle % (%) ab!', changes, temprows, dtabname;
							ELSE
								RAISE NOTICE '   Anzahl geaenderter Zeilen: %', changes;
							END IF;
						END IF;
					ELSE
						RAISE NOTICE '   Keine CHAR-Spalte vorhanden?';
					END IF;
				END IF;
			END IF;

			IF idxdrop_mode = 'UIDX' THEN
				FOR uindexliste IN SELECT * FROM pg_indexes WHERE schemaname = current_schema() AND tablename = quote_ident(name_tab) AND indexdef LIKE 'CREATE UNIQUE INDEX%' ORDER BY indexname ASC LOOP
					uicr := uicr +1;
					uindexcreate := uindexliste.indexdef;
					uindexcreatearr[uicr] := uindexcreate::text;
					uidrop := uindexliste.indexname;
					uidroparr[uicr] := uidrop::text;
				END LOOP;

				IF icr > 0 THEN
					IF uicr = 0 THEN
						RAISE NOTICE 'Es existiert kein Unique Index auf %.', name_tab;
					END IF;
					--Loeschen von UNIQUE Indices
					IF uicr > 0 THEN
						RAISE NOTICE 'Auf Tabelle % gibt es % Unique Index(e)', name_tab, array_upper(uidroparr, 1)::text;
						FOR i IN 1..array_upper(uidroparr, 1) LOOP
							uidropstring := 'DROP INDEX ' || quote_ident(uidroparr[i]::text);
							IF sim_mode THEN
								RAISE NOTICE '    SIM: %', uidropstring;
							ELSE
								RAISE NOTICE '    %', uidropstring;
								EXECUTE uidropstring;
							END IF;
						END LOOP;
					END IF;
				ELSE
					abfrage := 'REINDEX TABLE ' || quote_ident(name_tab) || ';';
					IF sim_mode THEN
						RAISE NOTICE '    SIM: %', abfrage;
					ELSE
						RAISE NOTICE '    %', abfrage;
						EXECUTE abfrage;
					END IF;
				END IF;
			END IF;

			IF idxdrop_mode = 'UIDX' AND icr > 0 THEN
				--Neuanlage der entfernten UNIQUE Indices
				IF uicr > 0 THEN
					FOR i IN 1..array_upper(uindexcreatearr, 1) LOOP
						IF sim_mode THEN
							RAISE NOTICE '    SIM: %', uindexcreatearr[i]::text;
						ELSE
							RAISE NOTICE '    %', uindexcreatearr[i]::text;
							EXECUTE uindexcreatearr[i]::text;
						END IF;
					END LOOP;
				END IF;
			END IF;

			IF idxdrop_mode = 'IDX' OR idxdrop_mode = 'UIDX' OR idxdrop_mode = 'OLDIDX' THEN
				--Neuanlage der entfernten Indices
				IF icr > 0 THEN
					FOR i IN 1..array_upper(indexcreatearr, 1) LOOP
						IF sim_mode THEN
							RAISE NOTICE '    SIM: %', indexcreatearr[i]::text;
						ELSE
							RAISE NOTICE '    %', indexcreatearr[i]::text;
							EXECUTE indexcreatearr[i]::text;
						END IF;
					END LOOP;
				END IF;
			END IF;

			abfrage := 'ANALYZE ' || quote_ident(name_tab);
			IF sim_mode AND selection_mode <> 'OLDALLCHARCOLS' THEN
				IF debug_mode THEN
					RAISE NOTICE '   SIM: %', abfrage;
				END IF;
			ELSIF selection_mode <> 'OLDALLCHARCOLS' THEN
				IF debug_mode THEN
					RAISE NOTICE '   %', abfrage;
				END IF;
				EXECUTE abfrage;
			END IF;
		ELSE
			RAISE NOTICE '   % wurde geprueft.', name_tab;
		END IF;

		IF selection_mode = 'TEMPTABLE' THEN
			IF pk_exists AND charcolarr IS NOT NULL THEN
				--Temporaere Tabelle ggf. entfernen
				abfrage := 'DROP TABLE ' || dtabname || ';';
				IF debug_mode THEN
					RAISE NOTICE '       %', abfrage;
				END IF;
				EXECUTE abfrage;
			END IF;
		END IF;

		IF tdirty THEN
			dtc := dtc + 1;
		END IF;
	END LOOP;

	IF sim_mode AND dtc > 0 AND selection_mode <> 'OLDALLCHARCOLS' THEN
		RAISE NOTICE 'Aufgrund von SIM-Modus = ON wurden die geplanten Aenderungen fuer % Tabelle(n) nicht durchgefuehrt.', dtc;
	ELSIF sim_mode AND dtc = 0 AND selection_mode <> 'OLDALLCHARCOLS' THEN
		RAISE NOTICE 'Bei Verwendung von FSV-Modus = ''%'' und TRIM-Modus = ''%'' und NULL-Modus = ''%'' waere keine Bereinigung erforderlich!', fsv_mode, trim_mode, null_mode;
	ELSIF sim_mode = false AND dtc > 0 AND selection_mode <> 'OLDALLCHARCOLS' THEN
		RAISE NOTICE 'Aenderungen an % Tabelle(n) vorgenommen.', dtc;
	ELSIF selection_mode <> 'OLDALLCHARCOLS' THEN
		RAISE NOTICE 'Es erfolgten keine Aenderungen (FSV-Modus = ''%'' und TRIM-Modus = ''%'' und NULL-Modus = ''%'')!', fsv_mode, trim_mode, null_mode;
	END IF;

	RETURN 'Erfolgreich beendet';
END;
$_$;


--
-- Name: FUNCTION f_konsistenz(); Type: COMMENT; Schema: cob; Owner: -
--

COMMENT ON FUNCTION cob.f_konsistenz() IS 'f_konsistenz() v1.32 FSV-Modus:OFF TRIM-Modus:RIGHT IDXDROP-Modus:IDX SIM-Modus:OFF NULL-Modus:OFF SELECTION-Modus:OLDALLCHARCOLS DEBUG-Modus:OFF';


--
-- Name: f_r_dokumente(); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.f_r_dokumente() RETURNS void
    LANGUAGE plpgsql
    AS $$

   DECLARE
      counter INT;

   BEGIN

	counter := (SELECT SUM(protokollierung) FROM db_tabellen WHERE (name = 'r_dokumente'));
	IF counter > 0 THEN
		RAISE EXCEPTION 'Protokollierung fuer die COB-Tabelle r_dokumente ausschalten!!!';
	ELSE
		DROP TRIGGER IF EXISTS r_dokumente_cobdb on r_dokumente;
		DROP TRIGGER IF EXISTS r_dokumente_integriertdb on r_dokumente;
	END IF;

   END;

$$;


--
-- Name: f_rechte_sequenzen(); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.f_rechte_sequenzen() RETURNS character
    LANGUAGE plpgsql
    AS $$ 
DECLARE 
anzahl_tab integer; 
anzahl_sp integer; 
oid_tab pg_class.oid%type; 
name_tab pg_tables.tablename%type; 
name_sp pg_attribute.attname%type; 
rec_tab pg_tables%rowtype; 
rec_sp pg_attribute%rowtype; 
typ_sp pg_attribute.atttypid%type; 
mod_sp pg_attribute.atttypmod%type; 
num_sp pg_attribute.attnum%type; 
attr_bin pg_attrdef.adbin%type; 
attr_sp text; 
oid_seq pg_class.oid%type; 
name_seq pg_class.relname%type; 
name_new_seq pg_class.relname%type; 
abfrage text; 
st_name_seq text; 
schema_oid oid; 
seq_owned_by_check text; 
seq_exists text; 
nextval_seq text; 
nvsuch_seq text; 
BEGIN 
	RAISE NOTICE 'f_rechte_sequenzen() v1.3 (10.06.2011)'; 
	RAISE NOTICE 'Schema % in Datenbank %.', current_schema()::text, current_database()::text; 
	SELECT pg_namespace.oid INTO schema_oid FROM pg_namespace WHERE pg_namespace.nspname = current_schema()::name; 
	FOR rec_tab IN SELECT * FROM pg_tables WHERE schemaname = current_schema() ORDER BY tablename LOOP 
		name_tab := rec_tab.tablename; 
		SELECT oid INTO oid_tab FROM pg_class WHERE relname = name_tab AND relnamespace = schema_oid; 
		FOR rec_sp IN SELECT * FROM pg_attribute WHERE attrelid = oid_tab AND attnum > 0 AND NOT attisdropped LOOP 
			name_seq := ''; 
			name_sp := rec_sp.attname; 
			typ_sp := rec_sp.atttypid; 
			mod_sp := rec_sp.atttypmod; 
			-- alle integer-spalten auf serial pruefen 
			IF format_type(typ_sp, mod_sp) LIKE 'int%' THEN 
				num_sp := rec_sp.attnum; 
				SELECT adbin INTO attr_bin FROM pg_attrdef WHERE adrelid = oid_tab AND adnum = num_sp; 

				IF pg_get_expr(attr_bin, oid_tab)::text LIKE 'nextval%' THEN 
					attr_sp := pg_get_expr(attr_bin, oid_tab)::text; 

					--Ueberpruefen ob Verknuepfung ueber OWNED BY gesetzt 
					name_seq := (pg_get_serial_sequence(name_tab, name_sp))::text; 
					IF name_seq IS NULL THEN 
						IF name_tab IS NULL THEN 
							name_tab := 'NULL'; 
						END IF; 
						IF name_sp IS NULL THEN 
							name_sp := 'NULL'; 
						END IF; 
						RAISE EXCEPTION 'Fehlende Verknuepfung zwischen Serial-Spalte %.% und Sequenz. Wartungsfunktion f_setze_sequenzen() ausfuehren!', name_tab, name_sp; 
					END IF; 
    				-- alle rechte fuer alle auf allen sequenzen 
    				abfrage := 'grant all on '|| name_seq ||' to public'; 
    				RAISE NOTICE '%', abfrage; 
    				EXECUTE abfrage; 
				END IF; 
			END IF; 
		END LOOP; 
	END LOOP; 
RETURN 'Erfolgreich beendet'; 
END; 
$$;


--
-- Name: FUNCTION f_rechte_sequenzen(); Type: COMMENT; Schema: cob; Owner: -
--

COMMENT ON FUNCTION cob.f_rechte_sequenzen() IS 'f_rechte_sequenzen() v1.3';


--
-- Name: f_reindex_alle_tabellen(); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.f_reindex_alle_tabellen() RETURNS character
    LANGUAGE plpgsql
    AS $$ 
declare 
anzahl_tab integer; 
name_tab pg_tables.tablename%type; 
rec_tab pg_tables%rowtype; 
abfrage text; 
begin 
-- select count(tablename) into anzahl_tab from pg_tables where schemaname = current_schema; 
-- raise notice 'Insgesamt % Tabellen', anzahl_tab; 
for rec_tab in select * from pg_tables where schemaname = current_schema() loop 
 name_tab := rec_tab.tablename; 
 -- speicher freigeben 
 abfrage := 'reindex table '||quote_ident(name_tab); 
 raise notice '%', abfrage; 
 execute abfrage; 
end loop; 
return 'Erfolgreich beendet'; 
end; 
$$;


--
-- Name: f_restore_nuidx(); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.f_restore_nuidx() RETURNS character
    LANGUAGE plpgsql
    AS $$
DECLARE
	abfrage1 text;
	abfrage2 text;
BEGIN

abfrage1 := 'SELECT indexdef FROM _idx_sicherung';

FOR abfrage2 IN EXECUTE abfrage1 LOOP
	RAISE NOTICE '%', abfrage2;
	EXECUTE abfrage2;
END LOOP;

DROP TABLE _idx_sicherung;

RETURN 'Erfolgreich beendet';
END;
$$;


--
-- Name: f_restore_single_table_nuidx(text); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.f_restore_single_table_nuidx(name_tab text) RETURNS character
    LANGUAGE plpgsql
    AS $$  DECLARE     abfrage1 text;     abfrage2 text;  BEGIN  abfrage1 := 'SELECT indexdef FROM ' || name_tab || '_idx_backup;';  FOR abfrage2 IN EXECUTE abfrage1 LOOP     RAISE NOTICE '%', abfrage2;     EXECUTE abfrage2;  END LOOP;  abfrage1 := 'DROP TABLE ' || name_tab || '_idx_backup;';  EXECUTE abfrage1;  RETURN 'Erfolgreich beendet';  END;  $$;


--
-- Name: f_rm_integrationsstatus(); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.f_rm_integrationsstatus() RETURNS character
    LANGUAGE plpgsql
    AS $$
DECLARE
	fver text;
	cver text;
	wschema name;
	f_oid oid;
	c_txt text;
	schema_oid oid;
	silent_mode_string text;
	silent_mode boolean;
	check_mode_string text;
	quick_check boolean;

	int_variante text;
	int_tabelle text;
	int_status text;
	v_counter int;
	inttab int;
	sv_int_c int;
	sysgeneral int;
	taboid oid;
	refclass oid;
	eviews int;
	vname text;
	sysint BOOLEAN;
	rzugriff BOOLEAN;

	dbstamm BOOLEAN;
	dbkore BOOLEAN;
	dbpnorm BOOLEAN;
	dbfibu BOOLEAN;
	dbzp BOOLEAN;
	dbpersonal BOOLEAN;
	dbbau BOOLEAN;

	sstamm BOOLEAN;
	skore BOOLEAN;
	spnorm BOOLEAN;
	sfibu BOOLEAN;
	szp BOOLEAN;
	spersonal BOOLEAN;
	sbau BOOLEAN;

BEGIN
	int_status := 'Nein';
	sysint := false;
	rzugriff := false;

	dbstamm := false;
	dbkore := false;
	dbpnorm := false;
	dbfibu := false;
	dbzp := false;
	dbpersonal := false;
	dbbau := false;

	sstamm := false;
	skore := false;
	spnorm := false;
	sfibu := false;
	szp := false;
	spersonal := false;
	sbau := false;

	wschema := current_schema()::name;
	IF wschema IS NULL THEN
		wschema := public;
	END IF;
	SELECT pg_namespace.oid INTO schema_oid FROM pg_namespace WHERE pg_namespace.nspname = wschema;

	SELECT p.oid INTO f_oid FROM pg_catalog.pg_proc p LEFT JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = wschema AND p.oid::regprocedure::text LIKE E'%f\\_\\rm\\_integrationsstatus()';
	IF f_oid IS NULL THEN
		RAISE WARNING 'OID der Funktion f_rm_integrationsstatus() nicht gefunden!';
		RAISE EXCEPTION 'Funktion f_rm_integrationsstatus() abgebrochen!';
	END IF;
	SELECT obj_description(f_oid, 'pg_proc') INTO c_txt;

	fver := '1.7';
	cver := TRIM(SUBSTRING( c_txt FROM LOWER(E'f_rm_integrationsstatus\\(\\)\\s+.*?(\\d*?\\.\\d*?)\\s+.*')));
	IF cver IS NULL THEN
		RAISE WARNING 'Keine Versionsangabe im Kommentar gefunden. Abbruch!';
		RAISE EXCEPTION 'Funktion f_rm_integrationsstatus() abgebrochen!';
	ELSIF cver <> fver THEN
		RAISE WARNING 'Version in Funktion (%) weicht von Version im Kommentar (%) zur Funktion ab!', fver, cver;
	END IF;

	--SILENT-Modus:
	IF SUBSTRING( c_txt FROM E'.*(SILENT-Modus:.*?)\\s+.*') IS NOT NULL THEN
		silent_mode_string := SUBSTRING( c_txt FROM E'.*(SILENT-Modus:.*?)\\s+.*');
	ELSIF SUBSTRING( c_txt FROM E'.*(SILENT-Modus:.*?)\\s*?') IS NOT NULL THEN
		silent_mode_string := SUBSTRING( c_txt FROM E'.*(SILENT-Modus:.*?)\\s*?');
	END IF;
	silent_mode_string := SUBSTRING( silent_mode_string FROM E'SILENT-Modus:(.*)');
	silent_mode_string := UPPER(silent_mode_string);
	IF silent_mode_string = 'ON' THEN
		silent_mode := true;
	ELSE
		silent_mode := false;
	END IF;

	IF NOT silent_mode THEN
		RAISE NOTICE 'f_rm_integrationsstatus() % (15.01.2020)', fver;
	END IF;

	IF NOT silent_mode THEN
		RAISE NOTICE 'Pruefe Schema % in Datenbank %', current_schema()::text, current_database()::text;
	END IF;

	--CHECK-Modus: QUICK oder FULL
	IF SUBSTRING( c_txt FROM E'.*(CHECK-Modus:.*?)\\s+.*') IS NOT NULL THEN
		check_mode_string := SUBSTRING( c_txt FROM E'.*(CHECK-Modus:.*?)\\s+.*');
	ELSIF SUBSTRING( c_txt FROM E'.*(CHECK-Modus:.*?)\\s*?') IS NOT NULL THEN
		check_mode_string := SUBSTRING( c_txt FROM E'.*(CHECK-Modus:.*?)\\s*?');
	END IF;
	check_mode_string := SUBSTRING( check_mode_string FROM E'CHECK-Modus:(.*)');
	check_mode_string := UPPER(check_mode_string);
	IF check_mode_string = 'QUICK' THEN
		quick_check := true;
		IF NOT silent_mode THEN
			RAISE NOTICE 'Schneller Check auf Verweise auf die eigene Datenbank.';
		END IF;
	ELSE
		quick_check := false;
		IF NOT silent_mode THEN
			RAISE NOTICE 'Voller Check auf Verweise auf die eigene Datenbank (DEFAULT).';
		END IF;
	END IF;

	--Pruefung des Datenbankschemas
	FOR int_variante IN SELECT DISTINCT bezeichner FROM sv_konfig_int ORDER BY bezeichner LOOP
		IF NOT silent_mode THEN
			RAISE NOTICE '%', int_variante;
		END IF;
		--Sind die lokalen Integrationstabellen Views?
		SELECT COUNT(*) INTO v_counter FROM sv_konfig_int ski WHERE bezeichner = int_variante AND EXISTS ( SELECT relname FROM pg_class pc WHERE relnamespace = schema_oid AND relkind = 'v' AND ski.tabelle = pc.relname );
		IF v_counter > 0 THEN
			IF NOT silent_mode THEN
				RAISE NOTICE '% aktiv (%)', int_variante, v_counter;
			END IF;
			SELECT COUNT(*) INTO inttab FROM sv_konfig_int WHERE bezeichner = int_variante;
			IF v_counter < inttab THEN
				RAISE EXCEPTION 'Nicht alle % Integrationstabellen sind Views!', inttab;
			END IF;
			int_status := 'Ja';
			IF int_variante = 'stamm' THEN
				dbstamm := true;
			ELSIF int_variante = 'kore' THEN
				dbkore := true;
			ELSIF int_variante = 'pnorm' THEN
				dbpnorm := true;
			ELSIF int_variante = 'fibu' THEN
				dbfibu := true;
			ELSIF int_variante = 'zp' THEN
				dbzp := true;
			ELSIF int_variante = 'personal' THEN
				dbpersonal := true;
			ELSIF int_variante = 'bau' THEN
				dbbau := true;
			ELSE
				RAISE EXCEPTION 'Integrationsvariante ''%'' unbekannt!', int_variante;
			END IF;
		END IF;
		--Greifen Views in anderen PostgreSQL-Schemata auf die Integrationstabelle zu?
		FOR int_tabelle IN SELECT tabelle FROM sv_konfig_int WHERE bezeichner = int_variante LOOP
			SELECT oid, (SELECT oid FROM pg_class WHERE relname = 'pg_class') INTO taboid, refclass FROM pg_class pc WHERE pc.relnamespace = schema_oid AND pc.relname = int_tabelle;
			SELECT COUNT(*) INTO eviews FROM f_dependency_lister(1,taboid,refclass) WHERE intern <> 't' AND objekttype = 'VIEW' AND ebene = 1 AND dpschema <> current_schema();
			IF eviews > 0 THEN
				IF NOT silent_mode THEN
					RAISE NOTICE ' Externe Views auf %!', int_tabelle;
				END IF;
				rzugriff := true;
				IF quick_check THEN
					CONTINUE;
				ELSE
					FOR vname IN SELECT dpschema || '.' || dpname FROM f_dependency_lister(1,taboid,refclass) WHERE intern <> 't' AND objekttype = 'VIEW' AND ebene = 1 AND dpschema <> current_schema() LOOP
						IF NOT silent_mode THEN
							RAISE NOTICE '   %', vname;
						END IF;
					END LOOP;
				END IF;
			END IF;
		END LOOP;
	END LOOP;

	--Auswertung der in Tabelle sv_integration abgelegten Informationen
	SELECT COUNT(*) INTO sv_int_c FROM sv_integration;
	IF sv_int_c > 1 THEN --Tabelle sv_integration darf maximal nur einen Datensatz enthalten!
		RAISE EXCEPTION 'GX-System-Tabelle enthaelt mehr als eine Zeile mit Integrationsinformationen!';
	ELSIF sv_int_c = 1 THEN
		SELECT COUNT(*) INTO sysgeneral FROM sv_integration WHERE integration_aktiv = '1'; --Eine Integration wurde aktiviert
		IF sysgeneral = 1 THEN
			IF ( SELECT COUNT(*) FROM sv_integration WHERE stamm_aktiv = 'J' ) = 1 THEN
				sstamm := true;
				sysint := true;
			END IF;
			IF ( SELECT COUNT(*) FROM sv_integration WHERE kore_aktiv = 'J' ) = 1 THEN
				skore := true;
				sysint := true;
			END IF;
			IF ( SELECT COUNT(*) FROM sv_integration WHERE pnorm_aktiv = 'J' ) = 1 THEN
				spnorm := true;
				sysint := true;
			END IF;
			IF ( SELECT COUNT(*) FROM sv_integration WHERE fibu_aktiv = 'J' ) = 1 THEN
				sfibu := true;
				sysint := true;
			END IF;
			IF ( SELECT COUNT(*) FROM sv_integration WHERE zp_aktiv = 'J' ) = 1 THEN
				szp := true;
				sysint := true;
			END IF;
			IF ( SELECT COUNT(*) FROM sv_integration WHERE personal_aktiv = 'J' ) = 1 THEN
				spersonal := true;
				sysint := true;
			END IF;
			IF ( SELECT COUNT(*) FROM sv_integration WHERE bau_aktiv = 'J' ) = 1 THEN
				sbau := true;
				sysint := true;
			END IF;
			IF dbstamm <> sstamm AND current_schema() <> 'cob' THEN
				IF dbstamm THEN
					RAISE EXCEPTION '''Zentrale Stammtabellen'' sind integriert. Diese Integrationsvariante ist jedoch in der Systemtabelle als inaktiv gekennzeichnet!';
				ELSIF sstamm THEN
					RAISE EXCEPTION 'Die Integrationsvariante ''Zentrale Stammtabellen'' ist in der Systemtabelle als aktiv gekennzeichnet! Deren Tabellen sind in der Datenbank jedoch NICHT integriert!';
				END IF;
			END IF;
			IF dbkore <> skore THEN
				IF dbkore THEN
					RAISE EXCEPTION 'Die Tabellen der Integrationsvariante ''COB-Export Online'' sind integriert. Diese ist jedoch in der Systemtabelle als inaktiv gekennzeichnet!';
				ELSIF skore THEN
					RAISE EXCEPTION 'Die Integrationsvariante ''COB-Export Online'' ist in der Systemtabelle als aktiv gekennzeichnet! Deren Tabellen sind in der Datenbank jedoch NICHT integriert!';
				END IF;
			END IF;
			IF dbpnorm <> spnorm THEN
				IF dbpnorm THEN
					RAISE EXCEPTION 'Die Tabellen der Integrationsvariante ''Personalnormkosten'' sind integriert. Diese ist jedoch in der Systemtabelle als inaktiv gekennzeichnet!';
				ELSIF spnorm THEN
					RAISE EXCEPTION 'Die Integrationsvariante ''Personalnormkosten'' ist in der Systemtabelle als aktiv gekennzeichnet! Deren Tabellen sind in der Datenbank jedoch NICHT integriert!';
				END IF;
			END IF;
			IF dbfibu <> sfibu THEN
				IF dbfibu THEN
					RAISE EXCEPTION 'Die Tabellen der Integrationsvariante ''MBS-Buchungen'' sind integriert. Diese ist jedoch in der Systemtabelle als inaktiv gekennzeichnet!';
				ELSIF sfibu THEN
					RAISE EXCEPTION 'Die Integrationsvariante ''MBS-Buchungen'' ist in der Systemtabelle als aktiv gekennzeichnet! Deren Tabellen sind in der Datenbank jedoch NICHT integriert!';
				END IF;
			END IF;
			IF dbzp <> szp THEN
				IF dbzp THEN
					RAISE EXCEPTION 'Die Tabellen der Integrationsvariante ''Zahlungspartner'' sind integriert. Diese ist jedoch in der Systemtabelle als inaktiv gekennzeichnet!';
				ELSIF szp THEN
					RAISE EXCEPTION 'Die Integrationsvariante ''Zahlungspartner'' ist in der Systemtabelle als aktiv gekennzeichnet! Deren Tabellen sind in der Datenbank jedoch NICHT integriert!';
				END IF;
			END IF;
			IF dbpersonal <> spersonal THEN
				IF dbpersonal THEN
					RAISE EXCEPTION 'Die Tabellen der Integrationsvariante ''Personalstamm'' sind integriert. Diese ist jedoch in der Systemtabelle als inaktiv gekennzeichnet!';
				ELSIF spersonal THEN
					RAISE EXCEPTION 'Die Integrationsvariante ''Personalstamm'' ist in der Systemtabelle als aktiv gekennzeichnet! Deren Tabellen sind in der Datenbank jedoch NICHT integriert!';
				END IF;
			END IF;
			IF dbbau <> sbau THEN
				IF dbbau THEN
					RAISE EXCEPTION 'Die Tabellen der Integrationsvariante ''Baubestand'' sind integriert. Diese ist jedoch in der Systemtabelle als inaktiv gekennzeichnet!';
				ELSIF sbau THEN
					RAISE EXCEPTION 'Die Integrationsvariante ''Baubestand'' ist in der Systemtabelle als aktiv gekennzeichnet! Deren Tabellen sind in der Datenbank jedoch NICHT integriert!';
				END IF;
			END IF;
		END IF;
	END IF;

	IF int_status = 'Ja' AND NOT sysint THEN
		RAISE EXCEPTION 'Lokal: NICHT EINDEUTIG! DB aktiv - SYSTEM inaktiv!';
	ELSIF int_status = 'Nein' AND NOT sysint AND sysgeneral = 0 THEN
		IF NOT silent_mode THEN
			RAISE NOTICE 'Lokal: Bislang keine Integration eingerichtet?';
		END IF;
	END IF;

	IF sysgeneral = 1 THEN
		int_status := 'Integration eingerichtet. Aktiv: Lokal: ' || int_status;
	ELSE
		int_status := 'Aktiv: Lokal: ' || int_status;
	END IF;

	IF rzugriff THEN
		int_status := int_status || '. Remote: Ja';
	ELSE
		int_status := int_status || '. Remote: Nein';
	END IF;

	RETURN int_status;
END;
$$;


--
-- Name: FUNCTION f_rm_integrationsstatus(); Type: COMMENT; Schema: cob; Owner: -
--

COMMENT ON FUNCTION cob.f_rm_integrationsstatus() IS 'f_rm_integrationsstatus() 1.7 (15.01.2020) SILENT-Modus:OFF CHECK-Modus:FULL';


--
-- Name: f_setze_schema_rechte(); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.f_setze_schema_rechte() RETURNS character
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
 c_txt TEXT;
 grant_level_string TEXT;
 grant_level INT;
 public_mode TEXT;
 public_mode_string TEXT;
 sim_mode BOOLEAN;
 sim_mode_string TEXT;
 target_mode TEXT;
 target_mode_string TEXT;
 qis_mode_string TEXT;
 qis_mode TEXT;
 qis VARCHAR(1); --db_sachbearbeiter.wwwuser
 sowner TEXT;
 oldsowner TEXT;
 sowner_oid OID;
 tabowner TEXT;
 sname TEXT;
 oschema NAME;
 fschema NAME; -- PostgreSQL-Schema, in dem sich die Funktion befindet
 progname TEXT;
 f_schema_oid OID;
 rname VARCHAR(20); --db_rolle_sb.rolle%type;
 lname VARCHAR(20); --db_sachbearbeiter.login%type
 ergebnis TEXT;
 abfrage TEXT;
 dbrecht BOOLEAN;
 rec_tab information_schema.tables%ROWTYPE;
 functionlist TEXT;
 f_oid OID;
 f_owner OID;
 ftext text;
 fver TEXT;
 cver TEXT;
BEGIN
	fver := '1.34';
	RAISE NOTICE 'f_setze_schema_rechte() v%', fver;

	--Zwischenspeichern des aktuellen PostgreSQL-Schemas (fuer TARGET-Modus:DB)
	IF current_schema()::name IS NOT NULL THEN
		oschema := current_schema()::name;
		RAISE NOTICE 'Aktuelles PostgreSQL-Schema: %', oschema;
	ELSE
		RAISE EXCEPTION 'current_schema() IS NULL!';
	END IF;

	--Pruefung, ob bei Aufruf der Funktion ein PostgreSQL-Schema angegeben worden ist (Bsp: SELECT hisrm.f_setze_schema_rechte();):
	    --***: kennzeichnet AREs (Advanced Regular Expressions) -> Hier Option i = case insensitive
		--current_query kann mehr als ein SQL-Statement enthalten!
	ftext := TRIM(current_query());
	WHILE ftext ~ E';\\s*$' LOOP
		ftext := regexp_replace( ftext, E';\\s*$', '');
	END LOOP;
	ftext := SUBSTRING( ftext FROM E'([^;]*)$');
	ftext := TRIM( SUBSTRING( ftext FROM E'***:(?i)\\s*(?:select|perform)\\s*(\\S*?)f_setze_schema_rechte\\(\\)'));
	IF ftext IS NOT NULL AND ftext <> '' THEN
		ftext := regexp_replace( ftext, E'\\.$', '');
		ftext := regexp_replace( ftext, E'\\*$', '');
		ftext := TRIM(ftext);
		IF ftext ~ E'\\s*' THEN
			ftext := regexp_replace( ftext, E'.*?\\s*?(\\S*?)$', E'\\1');
		END IF;
		IF ftext ~ E'"' THEN
			ftext := regexp_replace( ftext, E'"(\\S*?)"$', E'\\1');
			IF TRIM(ftext) = '' OR ftext IS NULL THEN
				RAISE EXCEPTION 'Problem beim Entfernen von Identifier-Anfuehrungszeichen aufgetreten!';
			END IF;
		END IF;
		SELECT pg_namespace.oid INTO f_schema_oid FROM pg_namespace WHERE pg_namespace.nspname = ftext::name;
		IF f_schema_oid IS NULL THEN
			IF ftext <> '' THEN
				RAISE WARNING 'Schema ''%'' nicht gefunden! Weiche auf das aktuelle Schema % aus!', ftext, oschema;
			END IF;
			fschema := oschema;
		ELSIF TRIM(ftext) <> '' THEN
			fschema := ftext::name;
			RAISE NOTICE 'Es wird die Funktion in PostgreSQL-Schema % verwendet.', fschema;
		ELSE
			fschema := oschema;
		END IF;
	ELSE
		fschema := oschema;
		RAISE NOTICE 'Verwende Funktion in PostgreSQL-Schema %.', fschema;
	END IF;
	SELECT pg_namespace.oid INTO f_schema_oid FROM pg_namespace WHERE pg_namespace.nspname = fschema;
	--RAISE NOTICE 'OID des Schemas %: %', fschema, f_schema_oid;
	SELECT p.oid INTO f_oid FROM pg_catalog.pg_proc p LEFT JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace WHERE n.oid = f_schema_oid AND p.oid::regprocedure::text = 'f_setze_schema_rechte()';
	IF f_oid IS NULL THEN
		SELECT p.oid INTO f_oid FROM pg_catalog.pg_proc p LEFT JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace WHERE n.oid = f_schema_oid AND p.oid::regprocedure::text = quote_ident(fschema) || '.f_setze_schema_rechte()';
	END IF;
	--RAISE NOTICE 'OID der Funktion: %', f_oid;
	SELECT obj_description(f_oid, 'pg_proc') INTO c_txt;
	SELECT obj_description(f_oid, 'pg_proc') INTO c_txt;
	cver := TRIM(SUBSTRING( c_txt FROM LOWER(E'f_setze_schema_rechte\\(\\)\\s+.*?(\\d*?\\.\\d*?)\\s+.*')));
	IF cver IS NULL THEN
		RAISE WARNING 'Keine Versionsangabe im Kommentar gefunden. Abbruch!';
		RETURN 'Funktion f_setze_schema_rechte() abgebrochen!';
	ELSIF cver <> fver THEN
		RAISE WARNING 'Version in Funktion (%) weicht von Version im Kommentar (%) zur Funktion ab!', fver, cver;
		RETURN 'Sie verwenden moeglicherweise eine veraltete Version der Funktion, da Versionsinformation innerhalb der Funktion von der im Kommentar zur Funktion abweicht!';
	END IF;

	--SIM-Modus: 'ON' oder 'OFF'
		--ON: Alle SQL-Anweisungen zum Aendern der Datenbank werden nur gemeldet aber nicht ausgefuehrt
	IF SUBSTRING( c_txt FROM E'.*(SIM-Modus:.*?)\\s+.*') IS NOT NULL THEN
		sim_mode_string := SUBSTRING( c_txt FROM E'.*(SIM-Modus:.*?)\\s+.*');
	ELSIF SUBSTRING( c_txt FROM E'.*(SIM-Modus:.*?)\\s*?') IS NOT NULL THEN
		sim_mode_string := SUBSTRING( c_txt FROM E'.*(SIM-Modus:.*?)\\s*?');
	END IF;
	sim_mode_string := SUBSTRING( sim_mode_string FROM E'SIM-Modus:(.*)');
	sim_mode_string := UPPER(sim_mode_string);
	IF sim_mode_string = 'ON' THEN
		RAISE NOTICE 'SIM-Modus:% -> Es werden keine Aenderungen an der Datenbank durchgefuehrt. (DEFAULT)', sim_mode_string;
		sim_mode := true;
	ELSIF sim_mode_string = 'OFF' THEN
		RAISE NOTICE 'Etwaige Aenderungen werden durchgefuehrt.';
		sim_mode := false;
	ELSIF sim_mode_string IS NULL THEN
		sim_mode := true;
		RAISE NOTICE 'Parameter SIM-Modus konnte nicht gefunden werden! Setze sim_mode auf %!', sim_mode::text;
	ELSE
		RAISE NOTICE 'Der im Kommentar zur Funktion angegebene SIM-Modus (%) ist unbekannt!', sim_mode_string;
		sim_mode := true;
		RAISE NOTICE 'Setze sim_mode auf %.', sim_mode::text;
	END IF;

	--PUBLIC-Modus
		--DE: public wird das Recht entzogen
		--ADD: public werden Rechte gegeben
		--OFF: public wird ignoriert
	IF SUBSTRING( c_txt FROM E'.*(PUBLIC-Modus:.*?)\\s+.*') IS NOT NULL THEN
		public_mode_string := SUBSTRING( c_txt FROM E'.*(PUBLIC-Modus:.*?)\\s+.*');
	ELSIF SUBSTRING( c_txt FROM E'.*(PUBLIC-Modus:.*?)\\s*?') IS NOT NULL THEN
		public_mode_string := SUBSTRING( c_txt FROM E'.*(PUBLIC-Modus:.*?)\\s*?');
	END IF;
	public_mode := SUBSTRING( public_mode_string FROM E'PUBLIC-Modus:(.*)');
	public_mode := UPPER(public_mode);
	IF public_mode = 'DE' THEN
		RAISE NOTICE 'Der Gruppe public werden Rechte auf das PostgreSQL-Schema entzogen. (DEFAULT)';
	ELSIF public_mode = 'ADD' THEN
		RAISE NOTICE 'Der Gruppe public werden Rechte auf das PostgreSQL-Schema gegeben.';
	ELSIF public_mode = 'OFF' THEN
		RAISE NOTICE 'Gruppe public wird ignoriert.';
	ELSIF public_mode IS NULL THEN
		public_mode := 'DE';
		RAISE NOTICE 'Parameter PUBLIC-Modus konnte nicht gefunden werden! PUBLIC-Modus wird daher auf % gesetzt!', public_mode;
	ELSE
		RAISE NOTICE 'Der im Kommentar zur Funktion angegebene PUBLIC-Modus (%) ist unbekannt!', public_mode;
		public_mode := 'DE';
		RAISE NOTICE 'PUBLIC-Modus wird daher auf % gesetzt!', public_mode;
	END IF;

	--GRANT-Level
	IF SUBSTRING( c_txt FROM E'.*(GRANT-Level:.*?)\\s+.*') IS NOT NULL THEN
		grant_level_string := SUBSTRING( c_txt FROM E'.*(GRANT-Level:.*?)\\s+.*');
	ELSIF SUBSTRING( c_txt FROM E'.*(GRANT-Level:.*?)\\s*?') IS NOT NULL THEN
		grant_level_string := SUBSTRING( c_txt FROM E'.*(GRANT-Level:.*?)\\s*?');
	END IF;
	grant_level_string := SUBSTRING( grant_level_string FROM E'GRANT-Level:(.*)');
	IF grant_level_string = '0' THEN
		RAISE NOTICE 'Nur die noetigsten Rechte werden vergeben. (DEFAULT)';
		grant_level := grant_level_string::int;
	ELSIF grant_level_string = '1' THEN
		RAISE NOTICE 'Erweiterte Rechte fuer Sachbearbeiter ( ausser auf Tabellen ).';
		grant_level := grant_level_string::int;
	ELSIF grant_level_string = '2' THEN
		RAISE NOTICE 'Erweiterte Rechte fuer Sachbearbeiter ( ausser auf Tabellen ) - zusaetzlich Rechte auf Funktionen fuer Datenbankbesitzer.';
		grant_level := grant_level_string::int;
	ELSIF grant_level_string = '3' THEN
		RAISE NOTICE 'Erweiterte Rechte ( inkl. Funktionen ) fuer Sachbearbeiter ( ausser auf Tabellen ) und Datenbankbesitzer.';
		grant_level := grant_level_string::int;
	ELSIF grant_level_string IS NULL THEN
		grant_level_string := '0';
		RAISE NOTICE 'Parameter GRANT-Level konnte nicht gefunden werden! GRANT-Level wird daher auf % gesetzt!', grant_level_string;
	ELSE
		RAISE NOTICE 'Der im Kommentar zur Funktion angegebene GRANT-Level (%) ist unbekannt!', grant_level_string;
		grant_level := 0;
		RAISE NOTICE 'GRANT-Level wird daher auf % gesetzt!', grant_level;
	END IF;

	--TARGET-Modus: DB = alle PostgreSQL-Schemata, die nicht zum System gehoeren, SCHEMA = nur das aktuelle Schema
	IF SUBSTRING( c_txt FROM E'.*(TARGET-Modus:.*?)\\s+.*') IS NOT NULL THEN
		target_mode_string := SUBSTRING( c_txt FROM E'.*(TARGET-Modus:.*?)\\s+.*');
	ELSIF SUBSTRING( c_txt FROM E'.*(TARGET-Modus:.*?)\\s*?') IS NOT NULL THEN
		target_mode_string := SUBSTRING( c_txt FROM E'.*(TARGET-Modus:.*?)\\s*?');
	END IF;
	target_mode := SUBSTRING( target_mode_string FROM E'TARGET-Modus:(.*)');
	target_mode := UPPER(target_mode);
	IF target_mode = 'DB' THEN
		RAISE NOTICE 'Bearbeite alle PostgreSQL-Schemata, die nicht zum System gehoeren.';
	ELSIF target_mode = 'SCHEMA' THEN
		RAISE NOTICE 'Bearbeite das aktuelle PostgreSQL-Schema. (DEFAULT)';
	ELSE
		RAISE NOTICE 'Der im Kommentar zur Funktion angegebene TARGET-Modus (%) ist unbekannt!', target_mode;
		target_mode := 'SCHEMA';
		RAISE NOTICE 'TARGET-Modus wird daher auf % gesetzt! (DEFAULT)', target_mode;
	END IF;

	--QIS-Modus: ON: QIS-Benutzer (db_sachbearbeiter.wwwuser = 'J') erhalten ebenfalls Rechte
	IF SUBSTRING( c_txt FROM E'.*(QIS-Modus:.*?)\\s+.*') IS NOT NULL THEN
		qis_mode_string := SUBSTRING( c_txt FROM E'.*(QIS-Modus:.*?)\\s+.*');
	ELSIF SUBSTRING( c_txt FROM E'.*(QIS-Modus:.*?)\\s*?') IS NOT NULL THEN
		qis_mode_string := SUBSTRING( c_txt FROM E'.*(QIS-Modus:.*?)\\s*?');
	END IF;
	qis_mode := SUBSTRING( qis_mode_string FROM E'QIS-Modus:(.*)');
	qis_mode := UPPER(qis_mode);
	IF qis_mode = 'ON' THEN
		RAISE NOTICE 'QIS-Benutzer erhalten ebenfalls Rechte.';
	ELSIF qis_mode = 'OFF' THEN
		RAISE NOTICE 'QIS-Benutzer erhalten keine Rechte. (DEFAULT)';
	ELSE
		RAISE NOTICE 'Der im Kommentar zur Funktion angegebene QIS-Modus (%) ist unbekannt!', qis_mode;
		qis_mode := 'OFF';
		RAISE NOTICE 'QIS-Modus wird daher auf % gesetzt! (DEFAULT)', qis_mode;
	END IF;

	FOR sname IN SELECT nspname FROM pg_namespace WHERE nspname !~* 'information_schema' AND nspname !~* '^pg_' ORDER BY nspname LOOP
		oldsowner := NULL;
		sowner := NULL;
		IF target_mode = 'DB' OR (target_mode = 'SCHEMA' AND sname = current_schema) THEN
			RAISE NOTICE 'Bearbeite PostgreSQL-Schema %:', sname;
			SELECT schema_owner::text INTO sowner FROM information_schema.schemata WHERE catalog_name = current_database() AND schema_name = sname;
			IF sowner IS NULL THEN
				RAISE EXCEPTION ' Fehler beim Auslesen des Besitzers des Schemas. Fehlen zum Ausfuehren Superuser-Rechte?';
			END IF;
			SELECT oid INTO sowner_oid FROM pg_catalog.pg_authid p WHERE p.rolname::text = sowner;
			IF sowner_oid IS NULL THEN
				RAISE EXCEPTION ' OID des PostgreSQL-Schema-Besitzers konnte nicht ermittelt werden!';
			END IF;

			IF target_mode = 'DB' THEN
				abfrage := 'SET search_path TO ' || quote_ident(sname) || ';';
				EXECUTE abfrage;
			END IF;

			IF sname = 'cob' THEN
				IF sowner <> 'cob' THEN
					oldsowner := sowner;
					sowner := 'cob';
					IF NOT sim_mode THEN
						RAISE WARNING ' Der Owner des PostgreSQL-Schemas % wird auf % gesetzt (vorher: %)!', sname, sowner, oldsowner;
						ALTER SCHEMA cob OWNER TO cob;
					END IF;
				END IF;
			ELSIF sname = 'mbs' THEN
				IF sowner <> 'fsv' THEN
					oldsowner := sowner;
					sowner := 'fsv';
					IF NOT sim_mode THEN
						RAISE WARNING ' Der Owner des PostgreSQL-Schemas % wird auf % gesetzt (vorher: %)!', sname, sowner, oldsowner;
						ALTER SCHEMA mbs OWNER TO fsv;
					END IF;
				END IF;
			ELSIF sname = 'sva4' THEN
				IF sowner <> 'sva' THEN
					oldsowner := sowner;
					sowner := 'sva';
					IF NOT sim_mode THEN
						RAISE WARNING ' Der Owner des PostgreSQL-Schemas % wird auf % gesetzt (vorher: %)!', sname, sowner, oldsowner;
						ALTER SCHEMA sva4 OWNER TO sva;
					END IF;
				END IF;
			ELSE
				BEGIN
					SELECT his_system INTO progname FROM db_version WHERE kern_system = '1';
				EXCEPTION
					WHEN SQLSTATE '42P01' THEN
						RAISE NOTICE ' PostgreSQL-Schema % enthaelt anscheinend keine Hochschul-ERP-Datenbank und wird daher ignoriert!', current_schema();
						CONTINUE;
					WHEN OTHERS THEN
						RAISE WARNING ' %: Kein Zugriff auf Tabelle db_version!', SQLSTATE;
						CONTINUE;
				END;
				IF progname = 'HISCOB-GX' THEN
					IF sowner <> 'cob' THEN
						oldsowner := sowner;
						sowner := 'cob';
					END IF;
				ELSIF progname = 'HISFSV-GX' THEN
					IF sowner <> 'fsv' THEN
						oldsowner := sowner;
						sowner := 'fsv';
					END IF;
				ELSIF progname = 'HISSVA-GX' THEN
					IF sowner <> 'sva' THEN
						oldsowner := sowner;
						sowner := 'sva';
					END IF;
				ELSIF progname = 'HISKBS' THEN
					RAISE NOTICE ' Wird ignoriert his_system: % !', progname;
					CONTINUE;
				ELSE
					RAISE EXCEPTION ' Unbekanntes his_system: % !', progname;
				END IF;
				IF oldsowner IS NOT NULL AND sowner IS NOT NULL AND oldsowner <> sowner THEN
					abfrage := 'ALTER SCHEMA ' || quote_ident(sname) || ' OWNER TO ' || sowner || ';';
					RAISE NOTICE ' %', abfrage;
					IF NOT sim_mode THEN
						EXECUTE abfrage;
					END IF;
				END IF;
			END IF;

			abfrage := 'GRANT ALL ON LANGUAGE plpgsql TO ' || quote_ident(sowner) || ' WITH GRANT OPTION;';
			RAISE NOTICE ' %', abfrage;
			IF NOT sim_mode THEN
				EXECUTE abfrage;
			END IF;

			IF grant_level >= 3 THEN
				abfrage := 'GRANT CONNECT, TEMPORARY ON DATABASE ' || quote_ident(current_database()) || ' TO ' || sowner || ' WITH GRANT OPTION;';
				RAISE NOTICE ' %', abfrage;
				IF NOT sim_mode THEN
					EXECUTE abfrage;
				END IF;
			END IF;

			abfrage := 'GRANT ALL ON SCHEMA ' || quote_ident(current_schema()) || ' TO ' || sowner || ' WITH GRANT OPTION;';
			RAISE NOTICE ' %', abfrage;
			IF NOT sim_mode THEN
				EXECUTE abfrage;
			END IF;

			IF public_mode = 'DE' THEN
				abfrage := ' REVOKE ALL ON SCHEMA ' || quote_ident(current_schema()) || ' FROM public;';
				RAISE NOTICE '%', abfrage;
				IF NOT sim_mode THEN
					EXECUTE abfrage;
				END IF;
			ELSIF public_mode = 'ADD' THEN
				abfrage := ' GRANT ALL ON SCHEMA ' || quote_ident(current_schema()) || ' TO public;';
				RAISE NOTICE '%', abfrage;
				IF NOT sim_mode THEN
					EXECUTE abfrage;
				END IF;
			END IF;

			FOR rec_tab IN SELECT * FROM information_schema.tables WHERE table_schema = current_schema() ORDER BY table_name LOOP
				SELECT tableowner INTO tabowner FROM pg_tables WHERE schemaname = sname AND tablename = rec_tab.table_name;
				IF tabowner <> sowner THEN
					IF ( rec_tab.table_name NOT LIKE E'exp\\_%' OR rec_tab.table_name LIKE E'exp\\_' || sowner || E'\\_%') THEN
						abfrage := 'ALTER TABLE ' || quote_ident(rec_tab.table_name) || ' OWNER TO ' || quote_ident(sowner) || ';';
						RAISE NOTICE ' %', abfrage;
						IF NOT sim_mode THEN
							EXECUTE abfrage;
						END IF;
					ELSE
						RAISE NOTICE ' Tabelle % ignoriert', rec_tab.table_name;
					END IF;
				END IF;

				IF grant_level >= 1 THEN
					abfrage := 'GRANT ALL ON TABLE ' || quote_ident(rec_tab.table_name) || ' TO ' || quote_ident(sowner) || ' WITH GRANT OPTION;';
					RAISE NOTICE ' %', abfrage;
					IF NOT sim_mode THEN
						EXECUTE abfrage;
					END IF;
				END IF;
			END LOOP;

			FOR functionlist, f_owner IN SELECT DISTINCT p.oid::regprocedure, proowner FROM pg_catalog.pg_proc p LEFT JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = current_schema() LOOP
				IF grant_level >= 2 THEN
					IF f_owner <> sowner_oid AND functionlist <> 'f_setze_schema_rechte()' THEN
						abfrage := 'ALTER FUNCTION ' || functionlist || ' OWNER TO ' || quote_ident(sowner) || ';';
						RAISE NOTICE ' %', abfrage;
						IF NOT sim_mode THEN
							EXECUTE abfrage;
						END IF;
					END IF;

					abfrage := 'GRANT ALL ON FUNCTION ' || functionlist || ' TO ' || quote_ident(sowner) || ' WITH GRANT OPTION;';
					RAISE NOTICE ' %', abfrage;
					IF NOT sim_mode THEN
						EXECUTE abfrage;
					END IF;
				END IF;
			END LOOP;

			RAISE NOTICE 'Setze Rechte auf Schema % fuer die aktiven Rollen:', current_schema();
			FOR rname IN SELECT login FROM db_sachbearbeiter WHERE UPPER(aktiv) = 'J' AND UPPER(rolle) = 'J' ORDER BY login LOOP
				--Existieren die Rollen im Cluster/Server?:
				SELECT rolname INTO ergebnis FROM pg_roles WHERE rolname = rname;
				IF ergebnis IS NOT NULL THEN
					IF grant_level >= 1 THEN
						IF grant_level >= 3 THEN
							abfrage := 'GRANT TEMPORARY ON DATABASE ' || quote_ident(current_database()) || ' TO ' || quote_ident(rname) || ';';
							RAISE NOTICE '  %', abfrage;
							IF NOT sim_mode THEN
								EXECUTE abfrage;
							END IF;
						END IF;

						abfrage := 'GRANT USAGE ON LANGUAGE plpgsql TO ' || quote_ident(rname) || ';';
						RAISE NOTICE '  %', abfrage;
						IF NOT sim_mode THEN
							EXECUTE abfrage;
						END IF;
					END IF;

					--Alle Rechte auf das Schema geben (Aktuell: USAGE und CREATE):
					abfrage := 'GRANT ALL ON SCHEMA ' || quote_ident(current_schema()) || ' TO ' || quote_ident(rname) || ';';
					RAISE NOTICE '  %', abfrage;
					IF NOT sim_mode THEN
						EXECUTE abfrage;
					END IF;

					IF grant_level >= 4 THEN
						FOR functionlist IN SELECT DISTINCT p.oid::regprocedure FROM pg_catalog.pg_proc p LEFT JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = current_schema() LOOP
							abfrage := 'GRANT EXECUTE ON FUNCTION ' || functionlist || ' TO ' || quote_ident(rname) || ';';
							RAISE NOTICE '  %', abfrage;
							IF NOT sim_mode THEN
								EXECUTE abfrage;
							END IF;
						END LOOP;
					END IF;
				ELSE
					RAISE WARNING ' Rolle "%" existiert nicht im Cluster/Server!', rname;
				END IF;
			END LOOP;

			RAISE NOTICE 'Setze Rechte auf Schema % fuer die aktiven Sachbearbeiter:', current_schema();
			FOR lname, qis IN SELECT login, wwwuser FROM db_sachbearbeiter WHERE UPPER(aktiv) = 'J' AND login <> sowner AND rolle = 'N' ORDER BY login LOOP

				IF qis IS NULL THEN
					qis := 'N';
				END IF;

				--Existieren die Sachbearbeiter im Cluster/Server?:
				SELECT rolname INTO ergebnis FROM pg_roles WHERE rolname = lname;
				IF ergebnis IS NOT NULL THEN
					IF (qis_mode = 'ON' AND qis = 'J') OR qis = 'N' THEN
						IF qis = 'J' THEN
							RAISE NOTICE ' % ist ein QIS-Benutzer!', lname;
						END IF;

						IF grant_level >= 3 THEN
							--Duerfen sich die Sachbearbeiter an der Datenbank anmelden?:
							--Vorsicht! Auch true, wenn public CONNECT-Recht hat!
							SELECT INTO dbrecht has_database_privilege(lname, current_database(), 'CONNECT');

							IF NOT dbrecht THEN
								RAISE NOTICE '  Sachbearbeiter % hatte kein CONNECT-Recht fuer die Datenbank', lname;
							END IF;

							abfrage := 'GRANT CONNECT, TEMPORARY ON DATABASE ' || quote_ident(current_database()) || ' TO ' || quote_ident(lname) || ';';
							RAISE NOTICE '  %', abfrage;
							IF NOT sim_mode THEN
								EXECUTE abfrage;
							END IF;
						END IF;
						abfrage := 'GRANT USAGE ON LANGUAGE plpgsql TO ' || quote_ident(lname) || ';';
						RAISE NOTICE '  %', abfrage;
						IF NOT sim_mode THEN
							EXECUTE abfrage;
						END IF;

						--Alle Rechte auf das Schema geben (Aktuell: USAGE und CREATE):
						abfrage := 'GRANT ALL ON SCHEMA ' || quote_ident(current_schema()) || ' TO ' || quote_ident(lname) || ';';
						RAISE NOTICE '  %', abfrage;
						IF NOT sim_mode THEN
							EXECUTE abfrage;
						END IF;

						IF grant_level >= 4 THEN
							FOR functionlist IN SELECT DISTINCT p.oid::regprocedure FROM pg_catalog.pg_proc p LEFT JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = current_schema() LOOP
								abfrage := 'GRANT EXECUTE ON FUNCTION ' || functionlist || ' TO ' || quote_ident(lname) || ';';
								RAISE NOTICE '  %', abfrage;
								IF NOT sim_mode THEN
									EXECUTE abfrage;
								END IF;
							END LOOP;
						END IF;
					ELSIF (qis_mode = 'OFF' AND qis = 'J') THEN
						RAISE NOTICE ' % wird als QIS-Benutzer ignoriert!', lname;
					END IF;
				ELSIF ergebnis IS NULL AND qis_mode = 'OFF' AND qis = 'J' THEN
					RAISE NOTICE ' QIS-Benutzer % existiert nicht im Cluster/Server.', lname;
				ELSIF ergebnis IS NULL AND qis_mode = 'OFF' THEN
					RAISE WARNING ' Sachbearbeiter % existiert nicht im Cluster/Server!', lname;
				ELSE
					RAISE WARNING ' Unbekanntes Problem bei Sachbearbeiter %!', lname;
				END IF;
			END LOOP;
		ELSIF target_mode = 'SCHEMA' THEN
			RAISE NOTICE 'PostgreSQL-Schema % wird ignoriert.', sname;
		END IF;
	END LOOP;
 IF target_mode = 'DB' THEN
	abfrage := 'SET search_path TO ' || quote_ident(oschema) || ';';
	RAISE NOTICE 'Zuruecksetzen auf vorheriges PostgreSQL-Schema: %', abfrage;
	EXECUTE abfrage;
 END IF;
 RETURN 'Erfolgreich beendet';

END;
$_$;


--
-- Name: FUNCTION f_setze_schema_rechte(); Type: COMMENT; Schema: cob; Owner: -
--

COMMENT ON FUNCTION cob.f_setze_schema_rechte() IS 'f_setze_schema_rechte() v1.34 PUBLIC-Modus:DE SIM-Modus:OFF GRANT-Level:0 TARGET-Modus:SCHEMA QIS-Modus:OFF';


--
-- Name: f_setze_sequenzen(); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.f_setze_sequenzen() RETURNS character
    LANGUAGE plpgsql
    AS $_$
DECLARE
anzahl_tab integer;
anzahl_sp integer;
oid_tab pg_class.oid%type;
name_tab pg_tables.tablename%type;
name_sp pg_attribute.attname%type;
rec_tab pg_tables%rowtype;
rec_sp pg_attribute%rowtype;
typ_sp pg_attribute.atttypid%type;
mod_sp pg_attribute.atttypmod%type;
num_sp pg_attribute.attnum%type;
attr_bin pg_attrdef.adbin%type;
attr_sp text;
oid_seq pg_class.oid%type;
name_seq text;
name_seq_arr text[];
name_new_seq pg_class.relname%type;
tcast boolean;
abfrage text;
st_name_seq text;
schema_oid oid;
seq_owned_by_check text;
seq_exists text;
nextval_seq text;
nvsuch_seq text;
ftext text;
wschema name;
f_oid oid;
c_txt text;
setval_mode_string text;
setval_mode text;
col_val bigint;
seq_val bigint;
BEGIN
	RAISE NOTICE 'f_setze_sequenzen() v1.18 (03.04.2020)';
	ftext := TRIM( SUBSTRING( LOWER(current_query()) FROM E'.*select\\s*(.*?)f_setze_sequenzen\\(\\)'));
	IF ftext IS NULL THEN
		wschema := current_schema()::name;
	END IF;
	ftext := regexp_replace( ftext, E'\\.$', '');
	ftext := regexp_replace( ftext, E'\\*$', '');
	ftext := TRIM(ftext);
	IF ftext ~ E'\\s*' THEN
		ftext := regexp_replace( ftext, E'.*?\\s*?(\\S*?)$', E'\\1');
	END IF;
	SELECT pg_namespace.oid INTO schema_oid FROM pg_namespace WHERE pg_namespace.nspname = ftext::name;
	IF schema_oid IS NULL THEN
		IF ftext <> '' THEN
			RAISE WARNING 'Schema ''%'' nicht gefunden! Weiche auf das aktuelle Schema % aus!', ftext, current_schema();
		END IF;
		wschema := current_schema()::name;
	ELSIF ftext <> '' THEN
		wschema := ftext::name;
	ELSE
		wschema := current_schema()::name;
	END IF;
	IF wschema::text <> current_schema THEN
		RAISE NOTICE 'Ausfuehrung auf Tabellen in Schema % in Datenbank % und nicht im aktuellen Schema %!', wschema::text, current_database()::text, current_schema()::text;
	ELSE
		RAISE NOTICE 'Im Schema % von Datenbank %.', wschema::text, current_database()::text;
	END IF;
	SELECT pg_namespace.oid INTO schema_oid FROM pg_namespace WHERE pg_namespace.nspname = wschema::name;

	SELECT p.oid INTO f_oid FROM pg_catalog.pg_proc p LEFT JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = wschema AND p.oid::regprocedure::text LIKE E'%f\\_setze\\_sequenzen()';
	IF f_oid IS NULL THEN
		RAISE WARNING 'OID der Funktion f_setze_sequenzen() nicht gefunden!';
		RETURN 'Funktion f_setze_sequenzen() abgebrochen!';
	END IF;
	SELECT obj_description(f_oid, 'pg_proc') INTO c_txt;

	--SETVAL-Modus
	IF SUBSTRING( c_txt FROM E'.*(SETVAL-Modus:.*?)\\s+.*') IS NOT NULL THEN
		setval_mode_string := SUBSTRING( c_txt FROM E'.*(SETVAL-Modus:.*?)\\s+.*');
	ELSIF SUBSTRING( c_txt FROM E'.*(SETVAL-Modus:.*?)\\s*?') IS NOT NULL THEN
		setval_mode_string := SUBSTRING( c_txt FROM E'.*(SETVAL-Modus:.*?)\\s*?');
	END IF;
	setval_mode := SUBSTRING( setval_mode_string FROM E'SETVAL-Modus:(.*)');
	setval_mode := UPPER(setval_mode);
	IF setval_mode = 'ALL' THEN
		RAISE NOTICE 'Alle Sequenzen werden auf den maximalen Wert der jeweiligen Serialspalte gesetzt.';
	ELSIF setval_mode = 'HISINONE' THEN
		RAISE NOTICE 'Sequenzen werden nur aktualisiert, wenn der Wert der Sequenz niedriger als der der Serial-Spalte ist.';
	ELSE
		RAISE NOTICE 'Der im Kommentar zur Funktion angegebene SETVAL-Modus (%) ist unbekannt!', setval_mode;
		setval_mode := 'ALL';
		RAISE NOTICE 'SETVAL-Modus wurde daher auf % gesetzt!', setval_mode;
	END IF;

	name_seq_arr := ARRAY['----'];

	FOR rec_tab IN SELECT * FROM pg_tables WHERE schemaname = wschema ORDER BY tablename LOOP
		name_tab := rec_tab.tablename;
		SELECT oid INTO oid_tab FROM pg_class WHERE relname = name_tab AND relnamespace = schema_oid;
		FOR rec_sp IN SELECT * FROM pg_attribute WHERE attrelid = oid_tab AND attnum > 0 AND NOT attisdropped LOOP
			name_seq := '';
			name_sp := rec_sp.attname;
			typ_sp := rec_sp.atttypid;
			mod_sp := rec_sp.atttypmod;
			-- alle integer-spalten auf serial pruefen
			IF format_type(typ_sp, mod_sp) LIKE 'int%' THEN
				num_sp := rec_sp.attnum;
				SELECT adbin INTO attr_bin FROM pg_attrdef WHERE adrelid = oid_tab AND adnum = num_sp;

				--Pruefen, ob der Verweis auf die Sequenz einen Text-Cast aufweist. Dies ist bei PostgreSQL < 8.1 die einzige Moeglichkeit zum Verweis auf die Sequenz gewesen.
				--Dies fuehrt in der Regel dazu, dass der Verweis auf die Sequenz bei einer Umbenennung des PostgreSQL-Schemas NICHT aktualisiert wird.
				--Test: ALTER TABLE mbs.db_tabellen ALTER COLUMN tabellen_id SET DEFAULT nextval('mbs.db_tabellen_tabellen_id_seq'::text);
				IF pg_get_expr(attr_bin, oid_tab)::text LIKE 'nextval%' THEN
					attr_sp := pg_get_expr(attr_bin, oid_tab)::text;
					IF substring( attr_sp FROM E'%#"::text#"%' FOR '#') IS NOT NULL THEN
						tcast := true;
					ELSE
						tcast := false;
				   	END IF;

					--Den Namen der Sequenz aus dem DEFAULT-Wert-Eintrag der Serial-Spalte extrahieren (nextval ...)
				   	--Pruefung auf Format 'Schema.Sequenz' (-> nextval_seq IS NOT NULL)
					nextval_seq := substring( attr_sp::text FROM '%' || E'\'' || '#"' || E'%\.%' || '#"' || E'\'' || '%' FOR '#');
					IF nextval_seq IS NULL THEN
						--Extraktion des Strings innerhalb der Anfuehrungszeichen
						nextval_seq := substring( attr_sp::text FROM '%' || E'\'#"%#"\'%' FOR '#');
						IF nextval_seq IS NULL THEN
							RAISE NOTICE 'Nextval Eintrag: %', attr_sp;
							RAISE EXCEPTION 'Die Struktur des Nextval-Eintrags fuer den Default-Wert der Spalte %.%.% wurde nicht erkannt', wschema, name_tab, name_sp;
						END IF;
					ELSE
						--Pruefung und Entfernung des angegebenen Schemas in nextval_seq
						IF nextval_seq = regexp_replace(nextval_seq, '^' || wschema || E'\.', '') THEN
							--Test: ALTER TABLE mbs.db_tabellen ALTER COLUMN tabellen_id SET DEFAULT nextval('sva4.db_tabellen_tabellen_id_seq'::regclass);
							RAISE EXCEPTION 'Das angegebene Datenbankschema % fuer die fuer den Default-Wert der Spalte %.%.% verwendete Sequenz scheint nicht zu stimmen', substring( nextval_seq FROM E'^#"%#"\.%' FOR '#'), wschema, name_tab, name_sp;
						ELSE
--							RAISE NOTICE '%', nextval_seq;
							nextval_seq := regexp_replace(nextval_seq, '^' || wschema || E'\.', '');
--							RAISE NOTICE '%', nextval_seq;
						END IF;
					END IF;

					IF tcast THEN
						--RAISE NOTICE 'Argument vom Typ text von nextval wird durch regclass ersetzt.';
						abfrage := 'ALTER TABLE ' || wschema || '.' || name_tab || ' ALTER COLUMN ' || name_sp || E' SET DEFAULT nextval(' || quote_literal( wschema || '.' || nextval_seq) || '::regclass);';
						RAISE NOTICE '%', abfrage;
						EXECUTE abfrage;
					END IF;

					--Ueberpruefen ob Verknuepfung ueber OWNED BY gesetzt
					seq_owned_by_check := (pg_get_serial_sequence( wschema || '.' || name_tab, name_sp))::text;
					IF seq_owned_by_check IS NULL THEN
						--Bei Fehlen von OWNED BY Suche nach Eintrag in pg_depend
						RAISE NOTICE ' %.%.% hat keinen korrekten Verweis auf eine Sequenz! ', wschema, name_tab, name_sp;
						SELECT objid FROM pg_depend INTO oid_seq WHERE refobjid = oid_tab AND refobjsubid = num_sp AND deptype = 'i';
						IF oid_seq IS NOT NULL THEN
							SELECT relname FROM pg_class INTO name_seq WHERE oid = oid_seq;
							RAISE NOTICE ' Eintrag % in pg_depend gefunden', name_seq;

							--Abbruch wenn der Name der Sequenz in 'nextval' von dem in pg_depend abweicht
							IF nextval_seq <> name_seq THEN
									RAISE NOTICE 'Eintraege weichen voneinander ab!';
									RAISE EXCEPTION 'pg_depend: %  nextval: % ', name_seq, nextval_seq;
							ELSE
								RAISE NOTICE 'Sowohl pg_depend als auch nextval zeigen auf: %', nextval_seq;
							END IF;
						ELSE
							RAISE NOTICE 'Tabellen-OID: % ( Spalte Nr. %)', oid_tab, num_sp;
							RAISE NOTICE 'Es wurde auch kein Verweis in pg_depend gefunden!';

							SELECT relname FROM pg_class INTO seq_exists WHERE relkind = 'S' AND relname = nextval_seq AND relnamespace = schema_oid;
							IF seq_exists IS NOT NULL THEN
								RAISE NOTICE 'nextval zeigt auf %', wschema || '.' || nextval_seq;
								name_seq := nextval_seq;
							ELSE
								RAISE EXCEPTION 'nextval zeigt auf eine nicht vorhandene Sequenz!';
							END IF;
						END IF;
						name_seq := wschema || '.' || name_seq;
						abfrage := 'ALTER SEQUENCE ' || name_seq || ' OWNED BY ' || wschema || '.' || name_tab || '.' || name_sp;
						RAISE NOTICE '%', abfrage;
						EXECUTE abfrage;
					ELSE
						name_seq := seq_owned_by_check;
					END IF;

					IF ARRAY[name_seq::text] <@ name_seq_arr THEN
						RAISE WARNING 'Sequenz % wird nicht nur von Serial-Spalte %.% als Default verwendet! Bereinigen!', name_seq, name_tab, name_sp;
					ELSE
						name_seq_arr := array_append( name_seq_arr, name_seq::text );
					END IF;

					IF name_seq::text NOT LIKE '%.' || name_tab || E'\\_' || name_sp || E'\\_seq' THEN
						RAISE WARNING '% entspricht nicht der PostgreSQL-Namenskonvention fuer Sequenzen (Serial-Spalte: %)!', name_seq, name_tab || '.' || name_sp;
					END IF;
					abfrage := 'SELECT max('||quote_ident(name_sp)||') FROM ' || wschema || '.' || quote_ident(name_tab);
					EXECUTE abfrage INTO col_val;
					--RAISE NOTICE '% col_val: %', name_seq, col_val;
					IF setval_mode = 'HISINONE' THEN
						abfrage := 'SELECT last_value FROM ' || name_seq;
						EXECUTE abfrage INTO seq_val;
						IF col_val IS NOT NULL THEN
							IF seq_val < col_val OR seq_val < 100000 THEN
								IF col_val < 100001 THEN
									col_val := col_val + 100000;
								END IF;
								abfrage := 'SELECT setval('||quote_literal(name_seq)||', ' || col_val || ')';
								RAISE NOTICE '%', abfrage;
								EXECUTE abfrage;
							END IF;
						ELSIF seq_val < 100000 THEN
							abfrage := 'SELECT setval('||quote_literal(name_seq)||', 100001, false)';
							RAISE NOTICE '%', abfrage;
							EXECUTE abfrage;
						END IF;
					ELSIF setval_mode = 'ALL' THEN
						IF col_val IS NULL OR col_val < 1 THEN
							abfrage := 'SELECT setval('||quote_literal(name_seq)||', 1, false)';
						ELSE
							abfrage := 'SELECT setval('||quote_literal(name_seq)||', (SELECT max('||quote_ident(name_sp)||') FROM ' || wschema || '.' || quote_ident(name_tab)||'))';
						END IF;
						RAISE NOTICE '%', abfrage;
						EXECUTE abfrage;
					END IF;
				END IF;
			END IF;
		END LOOP;
	END LOOP;
RETURN 'Erfolgreich beendet';
END;
$_$;


