--
-- Name: fikrdi(cob.fikr); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.fikrdi(cob.fikr) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
IF EXISTS(SELECT * FROM cob.alt_fikr alt_fikr WHERE old_row.key = alt_fikr.key) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "alt_fikr" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.alt_fikr alt_fikr WHERE old_row.key = alt_fikr.parent_key) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "alt_fikr" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.busa busa WHERE old_row.key = busa.busa_fikrkey) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "busa" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.dabu_empf dabu_empf WHERE old_row.key = dabu_empf.fikr_key) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "dabu_empf" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.fikr fikr WHERE old_row.key = fikr.ueberg) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "fikr" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.p_bzgrko p_bzgrko WHERE old_row.key = p_bzgrko.fikrkey) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "p_bzgrko" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.p_miete p_miete WHERE old_row.key = p_miete.fikrkey) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "p_miete" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.p_persko p_persko WHERE old_row.key = p_persko.fikrkey) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "p_persko" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.pag_to_kalk_fikr pag_to_kalk_fikr WHERE old_row.key = pag_to_kalk_fikr.fikr_kalk) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "pag_to_kalk_fikr" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.pag_to_kalk_fikr pag_to_kalk_fikr WHERE old_row.key = pag_to_kalk_fikr.fikr_pag) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "pag_to_kalk_fikr" verwendet!';
END IF;
DELETE FROM cob.r_fikr_attribut r_fikr_attribut WHERE old_row.key = r_fikr_attribut.fikr_key;
IF EXISTS(SELECT * FROM cob.umks umks WHERE old_row.key = umks.umks_fikrkey) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "umks" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.umks_e umks_e WHERE old_row.key = umks_e.fikrkey) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "umks_e" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.umvm_aus umvm_aus WHERE old_row.key = umvm_aus.umvm_aus_fikr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "umvm_aus" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.umvm_vert umvm_vert WHERE old_row.key = umvm_vert.umvm_vert_fikr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "umvm_vert" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.umvm_vert umvm_vert WHERE old_row.key = umvm_vert.zfikr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "umvm_vert" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.vtbu vtbu WHERE old_row.key = vtbu.vtbu_ziel_fikrkey) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "vtbu" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.vtbu_e vtbu_e WHERE old_row.key = vtbu_e.ziel_fikrkey) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "vtbu_e" verwendet!';
END IF;
 RETURN old_row; END; $_$;


