--
-- Name: gc(character varying); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.gc(character varying) RETURNS text
    LANGUAGE plpgsql STABLE STRICT SECURITY DEFINER
    AS $_$Declare
   ident ALIAS FOR $1;
   ret text;
   vhost text;
   vport text;
   vdb text;
   vuser text;
   vpasswd text;
BEGIN
SELECT host,port,db,login,pwd INTO vhost,vport,vdb,vuser,vpasswd FROM _sv_connstr WHERE db = ident;
 IF FOUND then
   ret = 'host=' || vhost || ' port=' || vport || ' dbname=' || vdb || ' user=' || vuser || ' password=' || vpasswd;
   RETURN ret;
 else
   RAISE EXCEPTION 'Keine Connection-Infos in Tabelle _sv_connstr !';
 end if;
END;$_$;


