--
-- Name: gegedi(cob.gege); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.gegedi(cob.gege) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
IF EXISTS(SELECT * FROM cob.busa busa WHERE old_row.ggnr = busa.busa_ggnr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "busa" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.dabu_empf dabu_empf WHERE old_row.ggnr = dabu_empf.ggnr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "dabu_empf" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.kaptit_to_gege kaptit_to_gege WHERE old_row.ggnr = kaptit_to_gege.gege_key) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "kaptit_to_gege" verwendet!';
END IF;
DELETE FROM cob.prge prge WHERE old_row.ggnr = prge.ggnr;
 RETURN old_row; END; $_$;


