    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
BEGIN
 PERFORM cob.imp_verzdi(OLD);
 RETURN OLD; END; $$;


--
-- Name: imp_verz; Type: TABLE; Schema: cob; Owner: -
--

CREATE TABLE cob.imp_verz (
    db_einfuegemarke character varying(6),
    id integer NOT NULL,
    dateibezeichner character varying(50),
    liefersystem character varying(12),
    dienststelle character varying(10),
    zielbereich character varying(50),
    beendet timestamp without time zone,
    quellversion character varying(3)
);


--
-- Name: imp_verzdi(cob.imp_verz); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.imp_verzdi(cob.imp_verz) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM cob.imp_aklwerte imp_aklwerte WHERE old_row.id = imp_aklwerte.imp_verz_id;
DELETE FROM cob.imp_busa imp_busa WHERE old_row.id = imp_busa.imp_verz_id;
DELETE FROM cob.imp_bzgr imp_bzgr WHERE old_row.id = imp_bzgr.imp_verz_key;
DELETE FROM cob.imp_flaeche imp_flaeche WHERE old_row.id = imp_flaeche.imp_verz_id;
DELETE FROM cob.imp_lus imp_lus WHERE old_row.id = imp_lus.imp_verz_id;
DELETE FROM cob.imp_sva_pbv imp_sva_pbv WHERE old_row.id = imp_sva_pbv.imp_verz_id;
IF EXISTS(SELECT * FROM cob.p_bzgrko p_bzgrko WHERE old_row.id = p_bzgrko.imp_verz_id) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "p_bzgrko" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.p_miete p_miete WHERE old_row.id = p_miete.imp_verz_id) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "p_miete" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.p_persko p_persko WHERE old_row.id = p_persko.imp_verz_id) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "p_persko" verwendet!';
END IF;
 RETURN old_row; END; $_$;


