--
-- Name: instdi(cob.inst); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.instdi(cob.inst) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
IF EXISTS(SELECT * FROM cob.alt_inst alt_inst WHERE old_row.inst_nr = alt_inst.key) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "alt_inst" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.alt_inst alt_inst WHERE old_row.inst_nr = alt_inst.parent_key) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "alt_inst" verwendet!';
END IF;
DELETE FROM cob.ansc_to_inst ansc_to_inst WHERE old_row.inst_nr = ansc_to_inst.instnr;
IF EXISTS(SELECT * FROM cob.busa busa WHERE old_row.inst_nr = busa.busa_instnr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "busa" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.bzgr_empf bzgr_empf WHERE old_row.inst_nr = bzgr_empf.bzgr_instnr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "bzgr_empf" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.dabu_empf dabu_empf WHERE old_row.inst_nr = dabu_empf.inst_nr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "dabu_empf" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.inst inst WHERE old_row.inst_nr = inst.uebinst_nr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "inst" verwendet!';
END IF;
DELETE FROM cob.inst_rechte inst_rechte WHERE old_row.inst_nr = inst_rechte.rechtestelle;
DELETE FROM cob.inst_to_ext inst_to_ext WHERE old_row.inst_nr = inst_to_ext.instnr;
IF EXISTS(SELECT * FROM cob.lvm lvm WHERE old_row.inst_nr = lvm.lvm_lekey) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "lvm" verwendet!';
END IF;
DELETE FROM cob.proj_to_inst proj_to_inst WHERE old_row.inst_nr = proj_to_inst.inst_nr;
DELETE FROM cob.r_inst_attribut r_inst_attribut WHERE old_row.inst_nr = r_inst_attribut.inst_inst_nr;
IF EXISTS(SELECT * FROM cob.stug stug WHERE old_row.inst_nr = stug.key_lehreinh) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "stug" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.umks umks WHERE old_row.inst_nr = umks.umks_instnr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "umks" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.umks_e umks_e WHERE old_row.inst_nr = umks_e.instnr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "umks_e" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.umvm umvm WHERE old_row.inst_nr = umvm.umvm_instnr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "umvm" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.umvm_vert umvm_vert WHERE old_row.inst_nr = umvm_vert.umvm_vert_instnr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "umvm_vert" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.vtbu vtbu WHERE old_row.inst_nr = vtbu.vtbu_quell_instnr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "vtbu" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.vtbu vtbu WHERE old_row.inst_nr = vtbu.vtbu_ziel_instnr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "vtbu" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.vtbu_e vtbu_e WHERE old_row.inst_nr = vtbu_e.quell_instnr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "vtbu_e" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.vtbu_e vtbu_e WHERE old_row.inst_nr = vtbu_e.ziel_instnr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "vtbu_e" verwendet!';
END IF;
 RETURN old_row; END; $_$;


--
-- Name: integration_pruefung(); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.integration_pruefung() RETURNS boolean
    LANGUAGE plpgsql
    AS $$    DECLARE     integration_count INTEGER;    BEGIN     SELECT count(*) INTO integration_count FROM sv_integration WHERE stamm_aktiv = 'J' OR personal_aktiv = 'J' OR fibu_aktiv = 'J' OR kore_aktiv = 'J' OR zp_aktiv ='J' OR pnorm_aktiv = 'J';     IF integration_count = 1 THEN      RAISE EXCEPTION 'Die Integration muss ausgeschaltet sein !!!';      RETURN false;     END IF;     RETURN true;    END;   $$;


