--

CREATE TABLE cob.k_umvm (
    db_einfuegemarke character varying(6),
    key_umvm character varying(8) NOT NULL,
    text_umvm character varying(25),
    altkost_umvm integer NOT NULL,
    altkoar_umvm integer NOT NULL
);


--
-- Name: k_umvmdi(cob.k_umvm); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.k_umvmdi(cob.k_umvm) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
IF EXISTS(SELECT * FROM cob.lva_exp lva_exp WHERE old_row.key_umvm = lva_exp.gruppe) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "lva_exp" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.lva_expcfg lva_expcfg WHERE old_row.key_umvm = lva_expcfg.gruppe) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "lva_expcfg" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.umvm umvm WHERE old_row.key_umvm = umvm.umvm_key) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "umvm" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.vspe vspe WHERE old_row.key_umvm = vspe.vspe_umvmkey) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "vspe" verwendet!';
END IF;
 RETURN old_row; END; $_$;


