--
-- Name: kollisions_pruefung(); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.kollisions_pruefung() RETURNS boolean
    LANGUAGE plpgsql
    AS $$         DECLARE         count_double INTEGER;    meldung text;   BEGIN    SELECT count(*) FROM fikr WHERE REPLACE ( key, 'Z', '' ) IN ( SELECT key FROM fikr ) AND key LIKE '%Z' INTO count_double;    IF count_double <> 0 THEN     meldung := E'Wegen Kollision mit den Kostenarten behalten die Ausgabearten ein Z am Ende!!! Lassen Sie sich mit COB_fikr_umsetz_nach_2.sql die betreffenden Schluessel ausgeben!';     RAISE EXCEPTION '%', meldung;     RETURN false;    END IF;    RETURN true;   END;   $$;


