 RETURN OLD; END; $$;


--
-- Name: kpum; Type: TABLE; Schema: cob; Owner: -
--

CREATE TABLE cob.kpum (
    db_einfuegemarke character varying(6),
    kpum_id integer NOT NULL,
    kpum_key character varying(20) NOT NULL,
    kpum_kbez character varying(10),
    kpum_dbez character varying(25),
    kpum_lbez character varying(40),
    kpum_einhkbez character varying(10),
    kpum_type smallint
);


--
-- Name: kpumdi(cob.kpum); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.kpumdi(cob.kpum) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
IF EXISTS(SELECT * FROM cob.bzgr bzgr WHERE old_row.kpum_key = bzgr.bzgr_kpumkey) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "bzgr" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.umks umks WHERE old_row.kpum_key = umks.umks_kpumkey) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "umks" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.umks_e umks_e WHERE old_row.kpum_key = umks_e.kpumkey) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "umks_e" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.umvm_vert umvm_vert WHERE old_row.kpum_key = umvm_vert.umvm_vert_kpumkey) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "umvm_vert" verwendet!';
END IF;
 RETURN old_row; END; $_$;


