--
-- Name: pgddi(cob.__pgd); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.pgddi(cob.__pgd) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM cob.account_history account_history WHERE old_row.pgd_join_id = account_history.user_id;
DELETE FROM cob.pbv pbv WHERE old_row.pgd_join_id = pbv.pbv_pgd_join_id;
DELETE FROM cob.wof_berechtigung wof_berechtigung WHERE old_row.pgd_join_id = wof_berechtigung.wof_berechtigung_pgd_join_id;
DELETE FROM cob.wof_berechtigung_im_auftrag wof_berechtigung_im_auftrag WHERE old_row.pgd_join_id = wof_berechtigung_im_auftrag.antragsteller_im_auftrag_pgd_join_id;
DELETE FROM cob.wof_berechtigung_im_auftrag wof_berechtigung_im_auftrag WHERE old_row.pgd_join_id = wof_berechtigung_im_auftrag.antragsteller_pgd_join_id;
DELETE FROM cob.workflow_next_responsible_person_preallocation workflow_next_responsible_person_preallocation WHERE old_row.pgd_join_id = workflow_next_responsible_person_preallocation.pgd_join_id;
DELETE FROM cob.workflow_next_responsible_person_preallocation workflow_next_responsible_person_preallocation WHERE old_row.pgd_join_id = workflow_next_responsible_person_preallocation.preallocated_pgd_join_id;
 RETURN old_row; END; $_$;


