--
-- Name: projdi(cob.proj); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.projdi(cob.proj) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
IF EXISTS(SELECT * FROM cob.alt_proj alt_proj WHERE old_row.projnr = alt_proj.key) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "alt_proj" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.alt_proj alt_proj WHERE old_row.projnr = alt_proj.parent_key) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "alt_proj" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.busa busa WHERE old_row.projnr = busa.busa_projnr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "busa" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.bzgr_empf bzgr_empf WHERE old_row.projnr = bzgr_empf.bzgr_projnr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "bzgr_empf" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.dabu_empf dabu_empf WHERE old_row.projnr = dabu_empf.projnr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "dabu_empf" verwendet!';
END IF;
DELETE FROM cob.prge prge WHERE old_row.projnr = prge.projnr;
IF EXISTS(SELECT * FROM cob.proj proj WHERE old_row.projnr = proj.ueberkey) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "proj" verwendet!';
END IF;
DELETE FROM cob.proj_to_inst proj_to_inst WHERE old_row.projnr = proj_to_inst.projnr;
DELETE FROM cob.proj_to_pbv proj_to_pbv WHERE old_row.projnr = proj_to_pbv.projnr;
IF EXISTS(SELECT * FROM cob.proj_to_stug proj_to_stug WHERE old_row.projnr = proj_to_stug.projnr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "proj_to_stug" verwendet!';
END IF;
DELETE FROM cob.r_proj_attribut r_proj_attribut WHERE old_row.projnr = r_proj_attribut.proj_projnr;
IF EXISTS(SELECT * FROM cob.umks umks WHERE old_row.projnr = umks.umks_projnr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "umks" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.umks_e umks_e WHERE old_row.projnr = umks_e.projnr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "umks_e" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.umvm umvm WHERE old_row.projnr = umvm.umvm_projnr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "umvm" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.vtbu vtbu WHERE old_row.projnr = vtbu.vtbu_quell_projnr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "vtbu" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.vtbu vtbu WHERE old_row.projnr = vtbu.vtbu_ziel_projnr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "vtbu" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.vtbu_e vtbu_e WHERE old_row.projnr = vtbu_e.quell_projnr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "vtbu_e" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.vtbu_e vtbu_e WHERE old_row.projnr = vtbu_e.ziel_projnr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "vtbu_e" verwendet!';
END IF;
 RETURN old_row; END; $_$;


