    stug_lbez character varying(50),
    stug_rstuz smallint,
    stug_cnw double precision,
    stug_bis date,
    key_lehreinh character varying(10),
    stug_plaetze smallint,
    key_extkotr character varying(20),
    stug_id integer NOT NULL
