--
-- Name: stugdi(cob.stug); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.stugdi(cob.stug) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
IF EXISTS(SELECT * FROM cob.bzgr_empf bzgr_empf WHERE old_row.stug_key = bzgr_empf.bzgr_stugkey) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "bzgr_empf" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.ff_to_stug ff_to_stug WHERE old_row.stug_key = ff_to_stug.stugkey) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "ff_to_stug" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.proj_to_stug proj_to_stug WHERE old_row.stug_key = proj_to_stug.stug_key) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "proj_to_stug" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.stud stud WHERE old_row.stug_key = stud.stud_stugkey) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "stud" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.stupl stupl WHERE old_row.stug_key = stupl.stug_key) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "stupl" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.umks umks WHERE old_row.stug_key = umks.umks_stugkey) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "umks" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.umks_e umks_e WHERE old_row.stug_key = umks_e.stugkey) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "umks_e" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.umvm umvm WHERE old_row.stug_key = umvm.umvm_stugkey) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "umvm" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.vtbu vtbu WHERE old_row.stug_key = vtbu.vtbu_quell_stug) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "vtbu" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.vtbu vtbu WHERE old_row.stug_key = vtbu.vtbu_ziel_stug) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "vtbu" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.vtbu_e vtbu_e WHERE old_row.stug_key = vtbu_e.quell_stug) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "vtbu_e" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.vtbu_e vtbu_e WHERE old_row.stug_key = vtbu_e.ziel_stug) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "vtbu_e" verwendet!';
END IF;
 RETURN old_row; END; $_$;


