--
-- Name: vari; Type: TABLE; Schema: cob; Owner: -
--

CREATE TABLE cob.vari (
    db_einfuegemarke character varying(6),
    vari_nr integer NOT NULL,
    vari_dbez character varying(25),
    vari_ueberid integer,
    vari_mhk smallint,
    vari_fikr smallint
);


--
-- Name: varidi(cob.vari); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.varidi(cob.vari) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
IF EXISTS(SELECT * FROM cob.lva_exp lva_exp WHERE old_row.vari_nr = lva_exp.varnr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "lva_exp" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.umks umks WHERE old_row.vari_nr = umks.umks_varnr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "umks" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.umks_e umks_e WHERE old_row.vari_nr = umks_e.varnr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "umks_e" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.vspe vspe WHERE old_row.vari_nr = vspe.vspe_varnr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "vspe" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.vtbu vtbu WHERE old_row.vari_nr = vtbu.vtbu_varnr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "vtbu" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.vtbu_e vtbu_e WHERE old_row.vari_nr = vtbu_e.varnr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "vtbu_e" verwendet!';
END IF;
 RETURN old_row; END; $_$;


