    db_einfuegemarke character varying(6),
    zeit_nr smallint NOT NULL,
    zeit_abk character varying(8),
    zeit_dbez character varying(25),
    zeit_monat_von smallint,
    zeit_monat_bis smallint,
    zeit_jahre_diff smallint,
    zeit_fix character varying(1),
    zeit_korflag character varying(1),
    zeit_vorgaenger smallint
);


--
-- Name: zeitdi(cob.zeit); Type: FUNCTION; Schema: cob; Owner: -
--

CREATE FUNCTION cob.zeitdi(cob.zeit) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
IF EXISTS(SELECT * FROM cob.dta_verzvtbu dta_verzvtbu WHERE old_row.zeit_nr = dta_verzvtbu.monat) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "dta_verzvtbu" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.lva_exp lva_exp WHERE old_row.zeit_nr = lva_exp.monat) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "lva_exp" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.p_kompress p_kompress WHERE old_row.zeit_nr = p_kompress.zeit_nr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "p_kompress" verwendet!';
END IF;
IF EXISTS(SELECT * FROM cob.vspe vspe WHERE old_row.zeit_nr = vspe.vspe_monat) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "vspe" verwendet!';
END IF;
 RETURN old_row; END; $_$;


