--
-- Name: _huel_dezkonto_proc(character varying); Type: FUNCTION; Schema: mbs; Owner: -
--

CREATE FUNCTION mbs._huel_dezkonto_proc(character varying) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
