--
-- Name: ansc_del(integer); Type: FUNCTION; Schema: mbs; Owner: -
--

CREATE FUNCTION mbs.ansc_del(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE sql text; id1 ALIAS FOR $1;  BEGIN sql = 'DELETE FROM ansc WHERE ansc_id= ' || quote_literal(id1); return dblink_exec(gc('cob'), sql); END;$_$;


--
-- Name: ansc_ins(character varying); Type: FUNCTION; Schema: mbs; Owner: -
--

CREATE FUNCTION mbs.ansc_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _ansc_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _anscinst_buffer!'; end if; SELECT * INTO rec FROM _ansc_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO ansc (db_einfuegemarke, ansc_gebaeude, ansc_strasse, ansc_ort, ansc_plz, ansc_land, ansc_raum) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.ansc_gebaeude),'NULL') || ' , ' || COALESCE(quote_literal(rec.ansc_strasse),'NULL') || ' , ' || COALESCE(quote_literal(rec.ansc_ort),'NULL') || ' , ' || COALESCE(quote_literal(rec.ansc_plz),'NULL') || ' , ' || COALESCE(quote_literal(rec.ansc_land),'NULL') || ' , ' || COALESCE(quote_literal(rec.ansc_raum),'NULL') || ')'; ret_dblink = dblink_exec(gc('cob'), sql); DELETE FROM _ansc_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


--
-- Name: ansc_to_inst_del(integer, character varying); Type: FUNCTION; Schema: mbs; Owner: -
--

CREATE FUNCTION mbs.ansc_to_inst_del(integer, character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE sql text; id1 ALIAS FOR $1;  id2 ALIAS FOR $2;  BEGIN sql = 'DELETE FROM ansc_to_inst WHERE anscid= ' || quote_literal(id1) ||' AND instnr= ' || quote_literal(id2); return dblink_exec(gc('cob'), sql); END;$_$;


--
-- Name: ansc_to_inst_ins(character varying); Type: FUNCTION; Schema: mbs; Owner: -
--

CREATE FUNCTION mbs.ansc_to_inst_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _ansc_to_inst_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _ansc_to_instinst_buffer!'; end if; SELECT * INTO rec FROM _ansc_to_inst_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO ansc_to_inst (db_einfuegemarke, anscid, instnr) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.anscid),'NULL') || ' , ' || COALESCE(quote_literal(rec.instnr),'NULL') || ')'; ret_dblink = dblink_exec(gc('cob'), sql); DELETE FROM _ansc_to_inst_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


--
-- Name: ansc_to_inst_upd(integer, character varying); Type: FUNCTION; Schema: mbs; Owner: -
--

CREATE FUNCTION mbs.ansc_to_inst_upd(integer, character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1;  id2 ALIAS FOR $2; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(anscid) INTO anz FROM _ansc_to_inst_buffer WHERE anscid= id1  AND instnr= id2; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _ansc_to_inst_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _ansc_to_inst_buffer WHERE anscid= id1  AND instnr= id2; If FOUND then sql = 'UPDATE ansc_to_inst SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , anscid= ' || COALESCE(quote_literal(rec.anscid),'NULL') || ' , instnr= ' || COALESCE(quote_literal(rec.instnr),'NULL') || ' WHERE anscid=' || quote_literal(rec.anscid) || ' AND instnr=' || quote_literal(rec.instnr) ; ret_dblink = dblink_exec(gc('cob'), sql); DELETE FROM _ansc_to_inst_buffer WHERE anscid= id1  AND instnr= id2; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


