--
-- Name: anscdi(mbs.__ansc); Type: FUNCTION; Schema: mbs; Owner: -
--

CREATE FUNCTION mbs.anscdi(mbs.__ansc) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM mbs.ansc_to_inst ansc_to_inst WHERE old_row.ansc_id = ansc_to_inst.anscid;
IF EXISTS(SELECT * FROM mbs.inst inst WHERE old_row.ansc_id = inst.anscid) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "inst" verwendet!';
END IF;
 RETURN old_row; END; $_$;


