);


--
-- Name: babsdi(mbs.__babs); Type: FUNCTION; Schema: mbs; Owner: -
--

CREATE FUNCTION mbs.babsdi(mbs.__babs) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
IF EXISTS(SELECT * FROM mbs.inst inst WHERE old_row.babs_key = inst.orgstruktur) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "inst" verwendet!';
END IF;
 RETURN old_row; END; $_$;


