--
-- Name: db_sachbearbeiter; Type: TABLE; Schema: mbs; Owner: -
--

CREATE TABLE mbs.db_sachbearbeiter (
    db_einfuegemarke character varying(6),
    sachbearbeiter_id integer NOT NULL,
    login character varying(20) NOT NULL,
    telefon character varying(20),
    kuerzel character varying(7),
    kategorie_id integer,
    name character varying(50),
    vorname character varying(50),
    geschlecht character varying(1),
    email character varying(255),
    fax character varying(20),
    institut character varying(10),
    vorgang_id integer,
    festuerecht character varying(1),
    istuerecht character varying(1),
    ansatzuerecht character varying(1),
    uebetrag numeric(14,2),
    auftragswertrecht character varying(1),
    auftragswert numeric(14,2),
    zeichnungsrecht character varying(1),
    zeichnungswert numeric(14,2),
    wwwuser character varying(1),
    treffdruck character varying(1),
    editroledefaults character varying(1) DEFAULT 'N'::character varying,
    aktiv character varying(1),
    ekost character varying(1),
    ugkost character varying(1),
    funktion character varying(25),
    rolle character varying(1),
    dezentral character varying(1),
    raumnummer character varying(25),
    hisinone_person_id integer,
    local_import_path character varying(255),
    local_export_path character varying(255),
    last_login date,
    pgd_join_id integer,
    obj_guid character varying(36) DEFAULT '0'::character varying,
    lock_version bigint DEFAULT 0
);


--
-- Name: db_sachbearbeiterdi(mbs.db_sachbearbeiter); Type: FUNCTION; Schema: mbs; Owner: -
--

CREATE FUNCTION mbs.db_sachbearbeiterdi(mbs.db_sachbearbeiter) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM mbs.r_db_sachbearbeiter_attribut r_db_sachbearbeiter_attribut WHERE old_row.sachbearbeiter_id = r_db_sachbearbeiter_attribut.db_sachbearbeiter_join_id;
IF EXISTS(SELECT * FROM mbs.rev_ereignis rev_ereignis WHERE old_row.login = rev_ereignis.login) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "rev_ereignis" verwendet!';
END IF;
IF EXISTS(SELECT * FROM mbs.rev_queryprot_exp rev_queryprot_exp WHERE old_row.login = rev_queryprot_exp.login) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "rev_queryprot_exp" verwendet!';
END IF;
IF EXISTS(SELECT * FROM mbs.rev_queryprot_sel rev_queryprot_sel WHERE old_row.login = rev_queryprot_sel.login) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "rev_queryprot_sel" verwendet!';
END IF;
DELETE FROM mbs.sv_appcontext sv_appcontext WHERE old_row.sachbearbeiter_id = sv_appcontext.eigentuemer;
 RETURN old_row; END; $_$;


