CREATE FUNCTION mbs.delete_dokumente() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$

DECLARE
    r_dokumente_anzahl INT;

  BEGIN

    r_dokumente_anzahl := (SELECT COUNT(*) FROM mbs.r_dokumente WHERE dokumente_join_id = OLD.dokumente_join_id);

    IF r_dokumente_anzahl < 1 THEN
	--Dokument loeschen:
			DELETE FROM mbs.dokumente WHERE dokumente_serial = OLD.dokumente_join_id;
    END IF;

    --Rueckgabewerte
    RETURN OLD;

  END;
$$;


