-- Name: dokumentedi(mbs.__dokumente); Type: FUNCTION; Schema: mbs; Owner: -
--

CREATE FUNCTION mbs.dokumentedi(mbs.__dokumente) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM mbs.dokumente_queue dokumente_queue WHERE old_row.dokumente_serial = dokumente_queue.dokumente_join_id;
 RETURN old_row; END; $_$;


