--
-- Name: fikr_ins(character varying); Type: FUNCTION; Schema: mbs; Owner: -
--

CREATE FUNCTION mbs.fikr_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _fikr_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _fikrinst_buffer!'; end if; SELECT * INTO rec FROM _fikr_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO fikr (db_einfuegemarke, key, ueberg, kbez, lbez, kokl, habpos, key_von, key_bis, svarel, mbsrel, ivsrel, baurel, cobrel, besrel, aost_nr, mbs_to_cob, syf, ivs_bga) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.key),'NULL') || ' , ' || COALESCE(quote_literal(rec.ueberg),'NULL') || ' , ' || COALESCE(quote_literal(rec.kbez),'NULL') || ' , ' || COALESCE(quote_literal(rec.lbez),'NULL') || ' , ' || COALESCE(quote_literal(rec.kokl),'NULL') || ' , ' || COALESCE(quote_literal(rec.habpos),'NULL') || ' , ' || COALESCE(quote_literal(rec.key_von),'NULL') || ' , ' || COALESCE(quote_literal(rec.key_bis),'NULL') || ' , ' || COALESCE(quote_literal(rec.svarel),'NULL') || ' , ' || COALESCE(quote_literal(rec.mbsrel),'NULL') || ' , ' || COALESCE(quote_literal(rec.ivsrel),'NULL') || ' , ' || COALESCE(quote_literal(rec.baurel),'NULL') || ' , ' || COALESCE(quote_literal(rec.cobrel),'NULL') || ' , ' || COALESCE(quote_literal(rec.besrel),'NULL') || ' , ' || COALESCE(quote_literal(rec.aost_nr),'NULL') || ' , ' || COALESCE(quote_literal(rec.mbs_to_cob),'NULL') || ' , ' || COALESCE(quote_literal(rec.syf),'NULL') || ' , ' || COALESCE(quote_literal(rec.ivs_bga),'NULL') || ')'; ret_dblink = dblink_exec(gc('cob'), sql); DELETE FROM _fikr_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


--
-- Name: fikr_upd(character varying); Type: FUNCTION; Schema: mbs; Owner: -
--

CREATE FUNCTION mbs.fikr_upd(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(key) INTO anz FROM _fikr_buffer WHERE key= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _fikr_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _fikr_buffer WHERE key= id1 ; If FOUND then sql = 'UPDATE fikr SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , key= ' || COALESCE(quote_literal(rec.key),'NULL') || ' , ueberg= ' || COALESCE(quote_literal(rec.ueberg),'NULL') || ' , kbez= ' || COALESCE(quote_literal(rec.kbez),'NULL') || ' , lbez= ' || COALESCE(quote_literal(rec.lbez),'NULL') || ' , kokl= ' || COALESCE(quote_literal(rec.kokl),'NULL') || ' , habpos= ' || COALESCE(quote_literal(rec.habpos),'NULL') || ' , key_von= ' || COALESCE(quote_literal(rec.key_von),'NULL') || ' , key_bis= ' || COALESCE(quote_literal(rec.key_bis),'NULL') || ' , svarel= ' || COALESCE(quote_literal(rec.svarel),'NULL') || ' , mbsrel= ' || COALESCE(quote_literal(rec.mbsrel),'NULL') || ' , ivsrel= ' || COALESCE(quote_literal(rec.ivsrel),'NULL') || ' , baurel= ' || COALESCE(quote_literal(rec.baurel),'NULL') || ' , cobrel= ' || COALESCE(quote_literal(rec.cobrel),'NULL') || ' , besrel= ' || COALESCE(quote_literal(rec.besrel),'NULL') || ' , aost_nr= ' || COALESCE(quote_literal(rec.aost_nr),'NULL') || ' , mbs_to_cob= ' || COALESCE(quote_literal(rec.mbs_to_cob),'NULL') || ' , syf= ' || COALESCE(quote_literal(rec.syf),'NULL') || ' , ivs_bga= ' || COALESCE(quote_literal(rec.ivs_bga),'NULL') || ' WHERE key=' || quote_literal(rec.key); ret_dblink = dblink_exec(gc('cob'), sql); DELETE FROM _fikr_buffer WHERE key= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


