--

CREATE FUNCTION mbs.fikrdi(mbs.__fikr) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
IF EXISTS(SELECT * FROM mbs.fikr fikr WHERE old_row.key = fikr.ueberg) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "fikr" verwendet!';
END IF;
DELETE FROM mbs.r_fikr_attribut r_fikr_attribut WHERE old_row.key = r_fikr_attribut.fikr_key;
 RETURN old_row; END; $_$;


