--

CREATE FUNCTION mbs.gege_del(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE sql text; id1 ALIAS FOR $1;  BEGIN sql = 'DELETE FROM gege WHERE ggnr= ' || quote_literal(id1); return dblink_exec(gc('cob'), sql); END;$_$;


--
-- Name: gege_ins(character varying); Type: FUNCTION; Schema: mbs; Owner: -
--

CREATE FUNCTION mbs.gege_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _gege_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _gegeinst_buffer!'; end if; SELECT * INTO rec FROM _gege_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO gege (db_einfuegemarke, ggnr, ueberkey, ggkey, fikey, ggkurz, ggdruck, ggname1, ggname2, ggname3, ggstr, ggort, ggplz, key_von, key_bis, bund_geldgeber, svarel, mbsrel, ivsrel, baurel, cobrel, klr_geldgeber) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.ggnr),'NULL') || ' , ' || COALESCE(quote_literal(rec.ueberkey),'NULL') || ' , ' || COALESCE(quote_literal(rec.ggkey),'NULL') || ' , ' || COALESCE(quote_literal(rec.fikey),'NULL') || ' , ' || COALESCE(quote_literal(rec.ggkurz),'NULL') || ' , ' || COALESCE(quote_literal(rec.ggdruck),'NULL') || ' , ' || COALESCE(quote_literal(rec.ggname1),'NULL') || ' , ' || COALESCE(quote_literal(rec.ggname2),'NULL') || ' , ' || COALESCE(quote_literal(rec.ggname3),'NULL') || ' , ' || COALESCE(quote_literal(rec.ggstr),'NULL') || ' , ' || COALESCE(quote_literal(rec.ggort),'NULL') || ' , ' || COALESCE(quote_literal(rec.ggplz),'NULL') || ' , ' || COALESCE(quote_literal(rec.key_von),'NULL') || ' , ' || COALESCE(quote_literal(rec.key_bis),'NULL') || ' , ' || COALESCE(quote_literal(rec.bund_geldgeber),'NULL') || ' , ' || COALESCE(quote_literal(rec.svarel),'NULL') || ' , ' || COALESCE(quote_literal(rec.mbsrel),'NULL') || ' , ' || COALESCE(quote_literal(rec.ivsrel),'NULL') || ' , ' || COALESCE(quote_literal(rec.baurel),'NULL') || ' , ' || COALESCE(quote_literal(rec.cobrel),'NULL') || ' , ' || COALESCE(quote_literal(rec.klr_geldgeber),'NULL') || ')'; ret_dblink = dblink_exec(gc('cob'), sql); DELETE FROM _gege_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


--
-- Name: gege_upd(character varying); Type: FUNCTION; Schema: mbs; Owner: -
--

CREATE FUNCTION mbs.gege_upd(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(ggnr) INTO anz FROM _gege_buffer WHERE ggnr= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _gege_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _gege_buffer WHERE ggnr= id1 ; If FOUND then sql = 'UPDATE gege SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , ggnr= ' || COALESCE(quote_literal(rec.ggnr),'NULL') || ' , ueberkey= ' || COALESCE(quote_literal(rec.ueberkey),'NULL') || ' , ggkey= ' || COALESCE(quote_literal(rec.ggkey),'NULL') || ' , fikey= ' || COALESCE(quote_literal(rec.fikey),'NULL') || ' , ggkurz= ' || COALESCE(quote_literal(rec.ggkurz),'NULL') || ' , ggdruck= ' || COALESCE(quote_literal(rec.ggdruck),'NULL') || ' , ggname1= ' || COALESCE(quote_literal(rec.ggname1),'NULL') || ' , ggname2= ' || COALESCE(quote_literal(rec.ggname2),'NULL') || ' , ggname3= ' || COALESCE(quote_literal(rec.ggname3),'NULL') || ' , ggstr= ' || COALESCE(quote_literal(rec.ggstr),'NULL') || ' , ggort= ' || COALESCE(quote_literal(rec.ggort),'NULL') || ' , ggplz= ' || COALESCE(quote_literal(rec.ggplz),'NULL') || ' , key_von= ' || COALESCE(quote_literal(rec.key_von),'NULL') || ' , key_bis= ' || COALESCE(quote_literal(rec.key_bis),'NULL') || ' , bund_geldgeber= ' || COALESCE(quote_literal(rec.bund_geldgeber),'NULL') || ' , svarel= ' || COALESCE(quote_literal(rec.svarel),'NULL') || ' , mbsrel= ' || COALESCE(quote_literal(rec.mbsrel),'NULL') || ' , ivsrel= ' || COALESCE(quote_literal(rec.ivsrel),'NULL') || ' , baurel= ' || COALESCE(quote_literal(rec.baurel),'NULL') || ' , cobrel= ' || COALESCE(quote_literal(rec.cobrel),'NULL') || ' , klr_geldgeber= ' || COALESCE(quote_literal(rec.klr_geldgeber),'NULL') || ' WHERE ggnr=' || quote_literal(rec.ggnr); ret_dblink = dblink_exec(gc('cob'), sql); DELETE FROM _gege_buffer WHERE ggnr= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


