CREATE FUNCTION mbs.hueldi(mbs.huel) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM mbs.r_huel_attribut r_huel_attribut WHERE old_row.join_nr = r_huel_attribut.huel_join_id;
 RETURN old_row; END; $_$;


