CREATE FUNCTION mbs.inst_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _inst_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _instinst_buffer!'; end if; SELECT * INTO rec FROM _inst_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO inst (db_einfuegemarke, inst_nr, uebinst_nr, kname, dname, lname1, lname2, str, gebname, plz, ort, bes_pers, bes_tel, bes_umsatz, bes_vj_umsatz1, bes_vj_umsatz2, ivs_pers, ivs_tel, fins, lehr, habpos, orgstruktur, key_von, key_bis, anscid, svarel, mbsrel, ivsrel, baurel, cobrel, besrel, lsfrel, bund_kategorie, bund_lehr_forsch, bund_fachgebiet, land_fachgebiet, sis_fachbereich, land_institut, genehmigungsstufe, aost_nr, bund_rahmenplan, listendruck, art, key_ext, bes_fax, bes_email, ivs_fax, ivs_email, ggnr, svagvp_relevant) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.inst_nr),'NULL') || ' , ' || COALESCE(quote_literal(rec.uebinst_nr),'NULL') || ' , ' || COALESCE(quote_literal(rec.kname),'NULL') || ' , ' || COALESCE(quote_literal(rec.dname),'NULL') || ' , ' || COALESCE(quote_literal(rec.lname1),'NULL') || ' , ' || COALESCE(quote_literal(rec.lname2),'NULL') || ' , ' || COALESCE(quote_literal(rec.str),'NULL') || ' , ' || COALESCE(quote_literal(rec.gebname),'NULL') || ' , ' || COALESCE(quote_literal(rec.plz),'NULL') || ' , ' || COALESCE(quote_literal(rec.ort),'NULL') || ' , ' || COALESCE(quote_literal(rec.bes_pers),'NULL') || ' , ' || COALESCE(quote_literal(rec.bes_tel),'NULL') || ' , ' || COALESCE(quote_literal(rec.bes_umsatz),'NULL') || ' , ' || COALESCE(quote_literal(rec.bes_vj_umsatz1),'NULL') || ' , ' || COALESCE(quote_literal(rec.bes_vj_umsatz2),'NULL') || ' , ' || COALESCE(quote_literal(rec.ivs_pers),'NULL') || ' , ' || COALESCE(quote_literal(rec.ivs_tel),'NULL') || ' , ' || COALESCE(quote_literal(rec.fins),'NULL') || ' , ' || COALESCE(quote_literal(rec.lehr),'NULL') || ' , ' || COALESCE(quote_literal(rec.habpos),'NULL') || ' , ' || COALESCE(quote_literal(rec.orgstruktur),'NULL') || ' , ' || COALESCE(quote_literal(rec.key_von),'NULL') || ' , ' || COALESCE(quote_literal(rec.key_bis),'NULL') || ' , ' || COALESCE(quote_literal(rec.anscid),'NULL') || ' , ' || COALESCE(quote_literal(rec.svarel),'NULL') || ' , ' || COALESCE(quote_literal(rec.mbsrel),'NULL') || ' , ' || COALESCE(quote_literal(rec.ivsrel),'NULL') || ' , ' || COALESCE(quote_literal(rec.baurel),'NULL') || ' , ' || COALESCE(quote_literal(rec.cobrel),'NULL') || ' , ' || COALESCE(quote_literal(rec.besrel),'NULL') || ' , ' || COALESCE(quote_literal(rec.lsfrel),'NULL') || ' , ' || COALESCE(quote_literal(rec.bund_kategorie),'NULL') || ' , ' || COALESCE(quote_literal(rec.bund_lehr_forsch),'NULL') || ' , ' || COALESCE(quote_literal(rec.bund_fachgebiet),'NULL') || ' , ' || COALESCE(quote_literal(rec.land_fachgebiet),'NULL') || ' , ' || COALESCE(quote_literal(rec.sis_fachbereich),'NULL') || ' , ' || COALESCE(quote_literal(rec.land_institut),'NULL') || ' , ' || COALESCE(quote_literal(rec.genehmigungsstufe),'NULL') || ' , ' || COALESCE(quote_literal(rec.aost_nr),'NULL') || ' , ' || COALESCE(quote_literal(rec.bund_rahmenplan),'NULL') || ' , ' || COALESCE(quote_literal(rec.listendruck),'NULL') || ' , ' || COALESCE(quote_literal(rec.art),'NULL') || ' , ' || COALESCE(quote_literal(rec.key_ext),'NULL') || ' , ' || COALESCE(quote_literal(rec.bes_fax),'NULL') || ' , ' || COALESCE(quote_literal(rec.bes_email),'NULL') || ' , ' || COALESCE(quote_literal(rec.ivs_fax),'NULL') || ' , ' || COALESCE(quote_literal(rec.ivs_email),'NULL') || ' , ' || COALESCE(quote_literal(rec.ggnr),'NULL') || ' , ' || COALESCE(quote_literal(rec.svagvp_relevant),'NULL') || ')'; ret_dblink = dblink_exec(gc('cob'), sql); DELETE FROM _inst_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


