--
-- Name: instdi(mbs.__inst); Type: FUNCTION; Schema: mbs; Owner: -
--

CREATE FUNCTION mbs.instdi(mbs.__inst) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM mbs.ansc_to_inst ansc_to_inst WHERE old_row.inst_nr = ansc_to_inst.instnr;
IF EXISTS(SELECT * FROM mbs.inst inst WHERE old_row.inst_nr = inst.uebinst_nr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "inst" verwendet!';
END IF;
DELETE FROM mbs.inst_rechte inst_rechte WHERE old_row.inst_nr = inst_rechte.rechtestelle;
DELETE FROM mbs.inst_to_ext inst_to_ext WHERE old_row.inst_nr = inst_to_ext.instnr;
DELETE FROM mbs.proj_to_inst proj_to_inst WHERE old_row.inst_nr = proj_to_inst.inst_nr;
DELETE FROM mbs.r_inst_attribut r_inst_attribut WHERE old_row.inst_nr = r_inst_attribut.inst_inst_nr;
 RETURN old_row; END; $_$;


