    LANGUAGE plpgsql
    AS $_$DECLARE sql text; id1 ALIAS FOR $1;  BEGIN sql = 'DELETE FROM k_extkotr WHERE key_extkotr= ' || quote_literal(id1); return dblink_exec(gc('cob'), sql); END;$_$;


--
-- Name: k_extkotr_ins(character varying); Type: FUNCTION; Schema: mbs; Owner: -
--

CREATE FUNCTION mbs.k_extkotr_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _k_extkotr_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _k_extkotrinst_buffer!'; end if; SELECT * INTO rec FROM _k_extkotr_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO k_extkotr (db_einfuegemarke, key_extkotr, text_extkotr, kategorie, fins_stugfach) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.key_extkotr),'NULL') || ' , ' || COALESCE(quote_literal(rec.text_extkotr),'NULL') || ' , ' || COALESCE(quote_literal(rec.kategorie),'NULL') || ' , ' || COALESCE(quote_literal(rec.fins_stugfach),'NULL') || ')'; ret_dblink = dblink_exec(gc('cob'), sql); DELETE FROM _k_extkotr_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


--
-- Name: k_extkotr_upd(character varying); Type: FUNCTION; Schema: mbs; Owner: -
--

