    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(key_extkotr) INTO anz FROM _k_extkotr_buffer WHERE key_extkotr= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _k_extkotr_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _k_extkotr_buffer WHERE key_extkotr= id1 ; If FOUND then sql = 'UPDATE k_extkotr SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , key_extkotr= ' || COALESCE(quote_literal(rec.key_extkotr),'NULL') || ' , text_extkotr= ' || COALESCE(quote_literal(rec.text_extkotr),'NULL') || ' , kategorie= ' || COALESCE(quote_literal(rec.kategorie),'NULL') || ' , fins_stugfach= ' || COALESCE(quote_literal(rec.fins_stugfach),'NULL') || ' WHERE key_extkotr=' || quote_literal(rec.key_extkotr); ret_dblink = dblink_exec(gc('cob'), sql); DELETE FROM _k_extkotr_buffer WHERE key_extkotr= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


