--
-- Name: k_staat_del(character varying); Type: FUNCTION; Schema: mbs; Owner: -
--

CREATE FUNCTION mbs.k_staat_del(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE sql text; id1 ALIAS FOR $1;  BEGIN sql = 'DELETE FROM k_staat WHERE key_staat= ' || quote_literal(id1); return dblink_exec(gc('cob'), sql); END;$_$;


--
-- Name: k_staat_ins(character varying); Type: FUNCTION; Schema: mbs; Owner: -
--

CREATE FUNCTION mbs.k_staat_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _k_staat_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _k_staatinst_buffer!'; end if; SELECT * INTO rec FROM _k_staat_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO k_staat (db_einfuegemarke, key_staat, ueberkey, kurz_land, druck_land, text_land, text_staatsangehoe, bund_staat, text_post_staat, eg_mitglied, key_von, key_bis) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.key_staat),'NULL') || ' , ' || COALESCE(quote_literal(rec.ueberkey),'NULL') || ' , ' || COALESCE(quote_literal(rec.kurz_land),'NULL') || ' , ' || COALESCE(quote_literal(rec.druck_land),'NULL') || ' , ' || COALESCE(quote_literal(rec.text_land),'NULL') || ' , ' || COALESCE(quote_literal(rec.text_staatsangehoe),'NULL') || ' , ' || COALESCE(quote_literal(rec.bund_staat),'NULL') || ' , ' || COALESCE(quote_literal(rec.text_post_staat),'NULL') || ' , ' || COALESCE(quote_literal(rec.eg_mitglied),'NULL') || ' , ' || COALESCE(quote_literal(rec.key_von),'NULL') || ' , ' || COALESCE(quote_literal(rec.key_bis),'NULL') || ')'; ret_dblink = dblink_exec(gc('cob'), sql); DELETE FROM _k_staat_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


--
-- Name: k_staat_upd(character varying); Type: FUNCTION; Schema: mbs; Owner: -
--

CREATE FUNCTION mbs.k_staat_upd(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(key_staat) INTO anz FROM _k_staat_buffer WHERE key_staat= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _k_staat_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _k_staat_buffer WHERE key_staat= id1 ; If FOUND then sql = 'UPDATE k_staat SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , key_staat= ' || COALESCE(quote_literal(rec.key_staat),'NULL') || ' , ueberkey= ' || COALESCE(quote_literal(rec.ueberkey),'NULL') || ' , kurz_land= ' || COALESCE(quote_literal(rec.kurz_land),'NULL') || ' , druck_land= ' || COALESCE(quote_literal(rec.druck_land),'NULL') || ' , text_land= ' || COALESCE(quote_literal(rec.text_land),'NULL') || ' , text_staatsangehoe= ' || COALESCE(quote_literal(rec.text_staatsangehoe),'NULL') || ' , bund_staat= ' || COALESCE(quote_literal(rec.bund_staat),'NULL') || ' , text_post_staat= ' || COALESCE(quote_literal(rec.text_post_staat),'NULL') || ' , eg_mitglied= ' || COALESCE(quote_literal(rec.eg_mitglied),'NULL') || ' , key_von= ' || COALESCE(quote_literal(rec.key_von),'NULL') || ' , key_bis= ' || COALESCE(quote_literal(rec.key_bis),'NULL') || ' WHERE key_staat=' || quote_literal(rec.key_staat); ret_dblink = dblink_exec(gc('cob'), sql); DELETE FROM _k_staat_buffer WHERE key_staat= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


