    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
IF EXISTS(SELECT * FROM mbs.ansc ansc WHERE old_row.key_staat = ansc.ansc_land) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "ansc" verwendet!';
END IF;
 RETURN old_row; END; $_$;


