CREATE FUNCTION mbs.mbs_importdi(mbs.mbs_import) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM mbs.r_mbs_import_attribut r_mbs_import_attribut WHERE old_row.join_nr = r_mbs_import_attribut.mbs_import_join_id;
 RETURN old_row; END; $_$;


