--
-- Name: pbvdi(mbs.__pbv); Type: FUNCTION; Schema: mbs; Owner: -
--

CREATE FUNCTION mbs.pbvdi(mbs.__pbv) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
IF EXISTS(SELECT * FROM mbs.proj_to_pbv proj_to_pbv WHERE old_row.pbv_pgd_join_id = proj_to_pbv.pbv_pgd_join_id AND old_row.pbv_nr = proj_to_pbv.pbv_nr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "proj_to_pbv" verwendet!';
END IF;
 RETURN old_row; END; $_$;


