--
-- Name: pgddi(mbs.__pgd); Type: FUNCTION; Schema: mbs; Owner: -
--

CREATE FUNCTION mbs.pgddi(mbs.__pgd) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM mbs.account_history account_history WHERE old_row.pgd_join_id = account_history.user_id;
DELETE FROM mbs.pbv pbv WHERE old_row.pgd_join_id = pbv.pbv_pgd_join_id;
DELETE FROM mbs.wof_berechtigung wof_berechtigung WHERE old_row.pgd_join_id = wof_berechtigung.wof_berechtigung_pgd_join_id;
DELETE FROM mbs.wof_berechtigung_im_auftrag wof_berechtigung_im_auftrag WHERE old_row.pgd_join_id = wof_berechtigung_im_auftrag.antragsteller_im_auftrag_pgd_join_id;
DELETE FROM mbs.wof_berechtigung_im_auftrag wof_berechtigung_im_auftrag WHERE old_row.pgd_join_id = wof_berechtigung_im_auftrag.antragsteller_pgd_join_id;
DELETE FROM mbs.workflow_next_responsible_person_preallocation workflow_next_responsible_person_preallocation WHERE old_row.pgd_join_id = workflow_next_responsible_person_preallocation.pgd_join_id;
DELETE FROM mbs.workflow_next_responsible_person_preallocation workflow_next_responsible_person_preallocation WHERE old_row.pgd_join_id = workflow_next_responsible_person_preallocation.preallocated_pgd_join_id;
 RETURN old_row; END; $_$;


