c.baurel),'NULL') || ' , ' || COALESCE(quote_literal(rec.cobrel),'NULL') || ' , ' || COALESCE(quote_literal(rec.besrel),'NULL') || ' , ' || COALESCE(quote_literal(rec.lsfrel),'NULL') || ' , ' || COALESCE(quote_literal(rec.mwpf),'NULL') || ' , ' || COALESCE(quote_literal(rec.laufzeitbeginn),'NULL') || ' , ' || COALESCE(quote_literal(rec.spklnr3),'NULL') || ' , ' || COALESCE(quote_literal(rec.spklnr4),'NULL') || ' , ' || COALESCE(quote_literal(rec.koordination),'NULL') || ' , ' || COALESCE(quote_literal(rec.key_extkotr),'NULL') || ' , ' || COALESCE(quote_literal(rec.key_ext),'NULL') || ')'; ret_dblink = dblink_exec(gc('cob'), sql); DELETE FROM _proj_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


