--
-- Name: projdi(mbs.__proj); Type: FUNCTION; Schema: mbs; Owner: -
--

CREATE FUNCTION mbs.projdi(mbs.__proj) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM mbs.prbb prbb WHERE old_row.projnr = prbb.projnr;
DELETE FROM mbs.prge prge WHERE old_row.projnr = prge.projnr;
DELETE FROM mbs.prgi prgi WHERE old_row.projnr = prgi.projnr;
DELETE FROM mbs.prgn prgn WHERE old_row.projnr = prgn.projnr;
DELETE FROM mbs.prgs prgs WHERE old_row.projnr = prgs.projnr;
IF EXISTS(SELECT * FROM mbs.proj proj WHERE old_row.projnr = proj.ueberkey) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "proj" verwendet!';
END IF;
DELETE FROM mbs.proj_to_inst proj_to_inst WHERE old_row.projnr = proj_to_inst.projnr;
DELETE FROM mbs.proj_to_pbv proj_to_pbv WHERE old_row.projnr = proj_to_pbv.projnr;
DELETE FROM mbs.r_proj_attribut r_proj_attribut WHERE old_row.projnr = r_proj_attribut.proj_projnr;
 RETURN old_row; END; $_$;


