--
-- Name: sys_del(character varying); Type: FUNCTION; Schema: mbs; Owner: -
--

CREATE FUNCTION mbs.sys_del(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE sql text; id1 ALIAS FOR $1;  BEGIN sql = 'DELETE FROM sys WHERE msnr= ' || quote_literal(id1); return dblink_exec(gc('cob'), sql); END;$_$;


--
-- Name: sys_ins(character varying); Type: FUNCTION; Schema: mbs; Owner: -
--

CREATE FUNCTION mbs.sys_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _sys_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _sysinst_buffer!'; end if; SELECT * INTO rec FROM _sys_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO sys (db_einfuegemarke, msnr, msbez, hlptxt, txt, nr, his_system_key, module) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.msnr),'NULL') || ' , ' || COALESCE(quote_literal(rec.msbez),'NULL') || ' , ' || COALESCE(quote_literal(rec.hlptxt),'NULL') || ' , ' || COALESCE(quote_literal(rec.txt),'NULL') || ' , ' || COALESCE(quote_literal(rec.nr),'NULL') || ' , ' || COALESCE(quote_literal(rec.his_system_key),'NULL') || ' , ' || COALESCE(quote_literal(rec.module),'NULL') || ')'; ret_dblink = dblink_exec(gc('cob'), sql); DELETE FROM _sys_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


--
-- Name: sys_upd(character varying); Type: FUNCTION; Schema: mbs; Owner: -
--

CREATE FUNCTION mbs.sys_upd(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(msnr) INTO anz FROM _sys_buffer WHERE msnr= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _sys_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _sys_buffer WHERE msnr= id1 ; If FOUND then sql = 'UPDATE sys SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , msnr= ' || COALESCE(quote_literal(rec.msnr),'NULL') || ' , msbez= ' || COALESCE(quote_literal(rec.msbez),'NULL') || ' , hlptxt= ' || COALESCE(quote_literal(rec.hlptxt),'NULL') || ' , txt= ' || COALESCE(quote_literal(rec.txt),'NULL') || ' , nr= ' || COALESCE(quote_literal(rec.nr),'NULL') || ' , his_system_key= ' || COALESCE(quote_literal(rec.his_system_key),'NULL') || ' , module= ' || COALESCE(quote_literal(rec.module),'NULL') || ' WHERE msnr=' || quote_literal(rec.msnr); ret_dblink = dblink_exec(gc('cob'), sql); DELETE FROM _sys_buffer WHERE msnr= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


