--
-- Name: titkoa_del(character varying, character varying, character varying); Type: FUNCTION; Schema: mbs; Owner: -
--

CREATE FUNCTION mbs.titkoa_del(character varying, character varying, character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE sql text; id1 ALIAS FOR $1;  id2 ALIAS FOR $2;  id3 ALIAS FOR $3;  BEGIN sql = 'DELETE FROM titkoa WHERE kap= ' || quote_literal(id1) ||' AND tit= ' || quote_literal(id2) ||' AND koa_nr= ' || quote_literal(id3); return dblink_exec(gc('cob'), sql); END;$_$;


--
-- Name: titkoa_ins(character varying); Type: FUNCTION; Schema: mbs; Owner: -
--

CREATE FUNCTION mbs.titkoa_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _titkoa_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _titkoainst_buffer!'; end if; SELECT * INTO rec FROM _titkoa_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO titkoa (db_einfuegemarke, kap, tit, koa_nr, haupt_koa_kz) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.kap),'NULL') || ' , ' || COALESCE(quote_literal(rec.tit),'NULL') || ' , ' || COALESCE(quote_literal(rec.koa_nr),'NULL') || ' , ' || COALESCE(quote_literal(rec.haupt_koa_kz),'NULL') || ')'; ret_dblink = dblink_exec(gc('cob'), sql); DELETE FROM _titkoa_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


--
-- Name: titkoa_upd(character varying, character varying, character varying); Type: FUNCTION; Schema: mbs; Owner: -
--

CREATE FUNCTION mbs.titkoa_upd(character varying, character varying, character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1;  id2 ALIAS FOR $2;  id3 ALIAS FOR $3; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(kap) INTO anz FROM _titkoa_buffer WHERE kap= id1  AND tit= id2 AND koa_nr= id3; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _titkoa_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _titkoa_buffer WHERE kap= id1  AND tit= id2 AND koa_nr= id3; If FOUND then sql = 'UPDATE titkoa SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , kap= ' || COALESCE(quote_literal(rec.kap),'NULL') || ' , tit= ' || COALESCE(quote_literal(rec.tit),'NULL') || ' , koa_nr= ' || COALESCE(quote_literal(rec.koa_nr),'NULL') || ' , haupt_koa_kz= ' || COALESCE(quote_literal(rec.haupt_koa_kz),'NULL') || ' WHERE kap=' || quote_literal(rec.kap) || ' AND tit=' || quote_literal(rec.tit)  || ' AND koa_nr=' || quote_literal(rec.koa_nr) ; ret_dblink = dblink_exec(gc('cob'), sql); DELETE FROM _titkoa_buffer WHERE kap= id1  AND tit= id2 AND koa_nr= id3; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


