--
-- Name: zpdi(mbs.zp); Type: FUNCTION; Schema: mbs; Owner: -
--

CREATE FUNCTION mbs.zpdi(mbs.zp) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM mbs.r_zp_attribut r_zp_attribut WHERE old_row.zp_nr = r_zp_attribut.zp_zp_nr;
 RETURN old_row; END; $_$;


