--
-- Name: admin_dms_einfuegen_menu(); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.admin_dms_einfuegen_menu() RETURNS void
    LANGUAGE plpgsql
    AS $$

DECLARE
	p_lfd_nr INT;
	p_menu_id INT;
	p_verweis_typ INT;

	BEGIN
		 p_verweis_typ:= (SELECT verweis_typ FROM sv_menu_item WHERE name = '&Integration');

		IF (p_verweis_typ = 0) THEN

			p_menu_id := (SELECT menu_id FROM sv_menu_item WHERE name = '&Integration');
			p_lfd_nr := (SELECT MAX(lfd_nr) FROM sv_menu_item WHERE name = '&Integration');

			p_lfd_nr := p_lfd_nr - 1;

			UPDATE sv_menu_item SET lfd_nr = lfd_nr + 1 WHERE lfd_nr > 21;

			INSERT INTO sv_menu_item (menu_id, name, lfd_nr, verweis_typ, verweis_id) VALUES (p_menu_id, '&DMS-Konfiguration', p_lfd_nr, 0, 18);

		END IF;

	END;
$$;


--
-- Name: admin_sachbearbeiter_zuordnen_menu(); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.admin_sachbearbeiter_zuordnen_menu() RETURNS void
    LANGUAGE plpgsql
    AS $$

DECLARE 
	p_lfd_nr INT;
	p_verweis_nr INT;
	p_verweis_typ INT;
	
	BEGIN
		SET search_path TO sva4;
	
		 p_verweis_typ:= (SELECT verweis_typ FROM sv_menu_item WHERE name = '&Sachbearbeiter');
		
		IF (p_verweis_typ = 0) THEN
		
			p_verweis_nr := (SELECT MAX(menu_id) FROM sv_menu_kategorie WHERE kategorie_id = 2147483647);
			p_lfd_nr := (SELECT MAX(lfd_menu_nr) FROM sv_menu_kategorie WHERE kategorie_id = 2147483647);
		
			p_lfd_nr := p_lfd_nr + 1;
			p_verweis_nr := p_verweis_nr + 1;
		
			INSERT INTO sv_menu_kategorie(kategorie_id,lfd_menu_nr,menu_id) VALUES (2147483647, p_lfd_nr, p_verweis_nr);
			UPDATE sv_menu_item SET verweis_typ = 2, verweis_id = 6 WHERE name = '&Sachbearbeiter';
			INSERT INTO sv_menu_item(menu_id,name,lfd_nr,verweis_typ,verweis_id) VALUES (p_verweis_nr,'&Anlegen und Bearbeiten', 1, 0, 8);
			INSERT INTO sv_menu_item(menu_id,name,lfd_nr,verweis_typ,verweis_id) VALUES (p_verweis_nr,'&Zuordnen', 2, 0, 17);
				
		END IF;
	
	END;
$$;


