--
-- Name: anscdi(sva4.__ansc); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.anscdi(sva4.__ansc) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM sva4.ansc_to_inst ansc_to_inst WHERE old_row.ansc_id = ansc_to_inst.anscid;
IF EXISTS(SELECT * FROM sva4.dra dra WHERE old_row.ansc_id = dra.dra_ansc_join_id) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "dra" verwendet!';
END IF;
IF EXISTS(SELECT * FROM sva4.inst inst WHERE old_row.ansc_id = inst.anscid) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "inst" verwendet!';
END IF;
IF EXISTS(SELECT * FROM sva4.rka rka WHERE old_row.ansc_id = rka.rka_ansc_join_id) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "rka" verwendet!';
END IF;
 RETURN old_row; END; $_$;


