--

CREATE FUNCTION sva4.babs_del(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE sql text; id1 ALIAS FOR $1;  BEGIN sql = 'DELETE FROM babs WHERE babs_key= ' || quote_literal(id1); return dblink_exec(gc('superx_cob_90_ap'), sql); END;$_$;


--
-- Name: babs_ins(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.babs_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _babs_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _babsinst_buffer!'; end if; SELECT * INTO rec FROM _babs_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO babs (db_einfuegemarke, babs_key, babs_dbez) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.babs_key),'NULL') || ' , ' || COALESCE(quote_literal(rec.babs_dbez),'NULL') || ')'; ret_dblink = dblink_exec(gc('superx_cob_90_ap'), sql); DELETE FROM _babs_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


--
-- Name: babs_upd(integer); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.babs_upd(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(babs_key) INTO anz FROM _babs_buffer WHERE babs_key= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _babs_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _babs_buffer WHERE babs_key= id1 ; If FOUND then sql = 'UPDATE babs SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , babs_key= ' || COALESCE(quote_literal(rec.babs_key),'NULL') || ' , babs_dbez= ' || COALESCE(quote_literal(rec.babs_dbez),'NULL') || ' WHERE babs_key=' || quote_literal(rec.babs_key); ret_dblink = dblink_exec(gc('superx_cob_90_ap'), sql); DELETE FROM _babs_buffer WHERE babs_key= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


