--
-- Name: babsdi(sva4.__babs); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.babsdi(sva4.__babs) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
IF EXISTS(SELECT * FROM sva4.inst inst WHERE old_row.babs_key = inst.orgstruktur) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "inst" verwendet!';
END IF;
 RETURN old_row; END; $_$;


