CREATE FUNCTION sva4.blz_upd(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(blz_key) INTO anz FROM _blz_buffer WHERE blz_key= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _blz_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _blz_buffer WHERE blz_key= id1 ; If FOUND then sql = 'UPDATE blz SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , blz_key= ' || COALESCE(quote_literal(rec.blz_key),'NULL') || ' , pz_kz= ' || COALESCE(quote_literal(rec.pz_kz),'NULL') || ' , bname= ' || COALESCE(quote_literal(rec.bname),'NULL') || ' , bort= ' || COALESCE(quote_literal(rec.bort),'NULL') || ' WHERE blz_key=' || quote_literal(rec.blz_key); ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _blz_buffer WHERE blz_key= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


