--
-- Name: btadi(sva4.bta); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.btadi(sva4.bta) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM sva4.bta_finanzierung bta_finanzierung WHERE old_row.bta_serial = bta_finanzierung.bta_finanzierung_bta_serial;
DELETE FROM sva4.bta_verlauf bta_verlauf WHERE old_row.bta_serial = bta_verlauf.bta_verlauf_bta_serial;
DELETE FROM sva4.r_dokumente r_dokumente WHERE old_row.bta_serial = r_dokumente.bta_join_id;
DELETE FROM sva4.r_fahrkosten_dr r_fahrkosten_dr WHERE old_row.bta_serial = r_fahrkosten_dr.bta_serial;
DELETE FROM sva4.r_wof r_wof WHERE old_row.bta_serial = r_wof.bta_join_id;
 RETURN old_row; END; $_$;


