--
-- Name: bw_lbvdi(sva4.bw_lbv); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.bw_lbvdi(sva4.bw_lbv) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM sva4.bw_lbv_beleg bw_lbv_beleg WHERE old_row.bw_lbv_serial = bw_lbv_beleg.bw_lbv_serial;
DELETE FROM sva4.r_dokumente r_dokumente WHERE old_row.bw_lbv_serial = r_dokumente.bw_lbv_join_id;
 RETURN old_row; END; $_$;


