    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _dau_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _dauinst_buffer!'; end if; SELECT * INTO rec FROM _dau_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO dau (db_einfuegemarke, jahr, kap, tit, ut, fb, ins, ins2, ins3, kz, huel, ftag, fbetrag, zkz, fbetrag2) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.jahr),'NULL') || ' , ' || COALESCE(quote_literal(rec.kap),'NULL') || ' , ' || COALESCE(quote_literal(rec.tit),'NULL') || ' , ' || COALESCE(quote_literal(rec.ut),'NULL') || ' , ' || COALESCE(quote_literal(rec.fb),'NULL') || ' , ' || COALESCE(quote_literal(rec.ins),'NULL') || ' , ' || COALESCE(quote_literal(rec.ins2),'NULL') || ' , ' || COALESCE(quote_literal(rec.ins3),'NULL') || ' , ' || COALESCE(quote_literal(rec.kz),'NULL') || ' , ' || COALESCE(quote_literal(rec.huel),'NULL') || ' , ' || COALESCE(quote_literal(rec.ftag),'NULL') || ' , ' || COALESCE(quote_literal(rec.fbetrag),'NULL') || ' , ' || COALESCE(quote_literal(rec.zkz),'NULL') || ' , ' || COALESCE(quote_literal(rec.fbetrag2),'NULL') || ')'; ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _dau_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


--
-- Name: dau_upd(integer); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.dau_upd(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(join_nr) INTO anz FROM _dau_buffer WHERE join_nr= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _dau_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _dau_buffer WHERE join_nr= id1 ; If FOUND then sql = 'UPDATE dau SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , jahr= ' || COALESCE(quote_literal(rec.jahr),'NULL') || ' , kap= ' || COALESCE(quote_literal(rec.kap),'NULL') || ' , tit= ' || COALESCE(quote_literal(rec.tit),'NULL') || ' , ut= ' || COALESCE(quote_literal(rec.ut),'NULL') || ' , fb= ' || COALESCE(quote_literal(rec.fb),'NULL') || ' , ins= ' || COALESCE(quote_literal(rec.ins),'NULL') || ' , ins2= ' || COALESCE(quote_literal(rec.ins2),'NULL') || ' , ins3= ' || COALESCE(quote_literal(rec.ins3),'NULL') || ' , kz= ' || COALESCE(quote_literal(rec.kz),'NULL') || ' , huel= ' || COALESCE(quote_literal(rec.huel),'NULL') || ' , ftag= ' || COALESCE(quote_literal(rec.ftag),'NULL') || ' , fbetrag= ' || COALESCE(quote_literal(rec.fbetrag),'NULL') || ' , zkz= ' || COALESCE(quote_literal(rec.zkz),'NULL') || ' , fbetrag2= ' || COALESCE(quote_literal(rec.fbetrag2),'NULL') || ' WHERE join_nr=' || quote_literal(rec.join_nr); ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _dau_buffer WHERE join_nr= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


