--
-- Name: db_sachbearbeiterdi(sva4.db_sachbearbeiter); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.db_sachbearbeiterdi(sva4.db_sachbearbeiter) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM sva4.r_db_sachbearbeiter_attribut r_db_sachbearbeiter_attribut WHERE old_row.sachbearbeiter_id = r_db_sachbearbeiter_attribut.db_sachbearbeiter_join_id;
IF EXISTS(SELECT * FROM sva4.rev_ereignis rev_ereignis WHERE old_row.login = rev_ereignis.login) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "rev_ereignis" verwendet!';
END IF;
IF EXISTS(SELECT * FROM sva4.rev_queryprot_exp rev_queryprot_exp WHERE old_row.login = rev_queryprot_exp.login) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "rev_queryprot_exp" verwendet!';
END IF;
IF EXISTS(SELECT * FROM sva4.rev_queryprot_sel rev_queryprot_sel WHERE old_row.login = rev_queryprot_sel.login) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "rev_queryprot_sel" verwendet!';
END IF;
DELETE FROM sva4.sv_appcontext sv_appcontext WHERE old_row.sachbearbeiter_id = sv_appcontext.eigentuemer;
 RETURN old_row; END; $_$;


