--
-- Name: dradi(sva4.dra); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.dradi(sva4.dra) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM sva4.r_dokumente r_dokumente WHERE old_row.dra_serial = r_dokumente.dra_join_id;
DELETE FROM sva4.r_wof r_wof WHERE old_row.dra_serial = r_wof.dra_join_id;
IF EXISTS(SELECT * FROM sva4.rka_anlagen rka_anlagen WHERE old_row.dra_serial = rka_anlagen.rka_anlagen_dra_serial) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "rka_anlagen" verwendet!';
END IF;
IF EXISTS(SELECT * FROM sva4.rka_finanzierung rka_finanzierung WHERE old_row.dra_serial = rka_finanzierung.rka_finanzierung_dra_serial) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "rka_finanzierung" verwendet!';
END IF;
IF EXISTS(SELECT * FROM sva4.rka_verlauf rka_verlauf WHERE old_row.dra_serial = rka_verlauf.rka_verlauf_dra_serial) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "rka_verlauf" verwendet!';
END IF;
IF EXISTS(SELECT * FROM sva4.rka_zusatz rka_zusatz WHERE old_row.dra_serial = rka_zusatz.rka_zus_dra_serial) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "rka_zusatz" verwendet!';
END IF;
 RETURN old_row; END; $_$;


--
-- Name: druck_del(integer); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.druck_del(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE sql text; id1 ALIAS FOR $1;  BEGIN sql = 'DELETE FROM druck WHERE join_nr= ' || quote_literal(id1); return dblink_exec(gc('superx_fsv_90_ap'), sql); END;$_$;


