--
-- Name: eau_migration(); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.eau_migration() RETURNS void
    LANGUAGE plpgsql
    AS $$

DECLARE 
	anzahl INT;
	out_eau_tab record;
	imp_eau_tab record;		

	BEGIN
		SET search_path to sva4;
	
		INSERT INTO out_eau_dakota2 (
		versionsnummer_basis, versionsnummer_header, absendernummer, empfaengernummer, datum_uhrzeit_erstellung, dateifolgenummer, prod_id_kommunikationsdaten, mod_id_kommunikationsdaten, name1_dateiersteller, name2_dateiersteller, name3_dateiersteller, plz_betrieb, ort_betrieb, strasse_betrieb, hausnummer_betrieb, anrede_ansprechpartner, name_ansprechpartner,
		telefon_ansprechpartner, fax_ansprechpartner, email_ansprechpartner, absendernummer_steuerung, empfaengernummer_steuerung, datum_uhrzeit_erstellung_steuerung, prod_id_steuerung, 
		mod_id_steuerung, aktenzeichen_verursacher_steuerung, betriebsnummer_verursacher, betriebsnummer_abrechnungsstelle, sb_name_ansprechpartner, sb_telefon_ansprechpartner,
		sb_fax_ansprechpartner, sb_email_ansprechpartner, betrieb_name, plz, ort, strasse, hausnummer, familienname, vorname, identifikation_versicherungsnummer, identifikation_geburtsname,
		identifikation_geburtsort, geburtsdatum, abwesenheit_ab_ag, fehlermeldung, kommentar, eau_id, paw_referenz_id, pgd_join_id,
		verfahrensmerkmal, versionsnummer_anforderung)
		SELECT 
		'2.0.0', '2.0.0', eau_absendernummer, eau_empfaengernummer_datenannahmestelle, eau_datum_uhrzeit_erstellung, eau_xml_id, eau_product_identifier,
		eau_modification_identifier, eau_sb_name_1, eau_sb_name_2, eau_sb_name_3, eau_sb_plz, eau_sb_ort, eau_sb_strasse, eau_sb_hausnr, eau_sb_geschlecht, eau_sb_name, 
		eau_sb_telefon, eau_sb_fax, eau_sb_email, eau_absendernummer, eau_empfaengernummer, eau_datum_uhrzeit_xml_erstellung, eau_product_identifier, eau_modification_identifier,
		eau_aktenzeichen_verursacher, eau_betriebsnummer_verursacher, eau_bbnr_abrechnungsstelle, eau_sb_name, eau_sb_telefon, eau_sb_fax, eau_sb_email, 
		eau_sb_name_1 || eau_sb_name_2 || eau_sb_name_3, eau_sb_plz, eau_sb_ort, eau_sb_strasse, eau_sb_hausnr, eau_name, eau_vorname, eau_vsnr, eau_geburtsname, eau_geburtsort,
		eau_geburtsdatum, eau_au_datum, fehlermeldung, kommentar, eau_id, eau_paw_referenz_id, eau_pgd_join_id, 'EAA', '2.0.0'
		FROM out_eau_dakota
		WHERE 1 = 1;
		
		UPDATE out_eau_dakota2 SET betrieb_name = name1_dateiersteller WHERE 1 = 1;
		UPDATE out_eau_dakota2 SET datensatz_id_steuerung = obj_guid WHERE 1 = 1;

		FOR out_eau_tab IN 
			SELECT eau_id, eau_referenz_id, eau_paw_referenz_id FROM out_eau_dakota WHERE eau_storno_kennzeichen = 'J'
		LOOP
			anzahl := (SELECT COUNT(*) FROM out_eau_dakota WHERE eau_xml_id = out_eau_tab.eau_referenz_id AND eau_paw_referenz_id = out_eau_tab.eau_paw_referenz_id);

			IF anzahl = 1 THEN
				UPDATE out_eau_dakota2 SET storno_datensatz_id_der_ursprungsmeldung = out_eau_tab.eau_referenz_id WHERE eau_id = out_eau_tab.eau_id;
			ELSE
				UPDATE out_eau_dakota2 SET fehlermeldung = 'Datenmigration aus Tabelle out_eau_dakota konnte nicht vorgenommen werden!' WHERE eau_id = out_eau_tab.eau_id;
			END IF;
		END LOOP;



		INSERT INTO imp_eau_dakota2 (
		versionsnummer_basis, versionsnummer_header, verfahrensmerkmal, absendernummer, empfaengernummer, datum_uhrzeit_erstellung, versionsnummer_verfahren, 
		absendernummer_steuerung, empfaengernummer_steuerung, datum_uhrzeit_erstellung_steuerung, prod_id_steuerung, mod_id_steuerung, datensatz_id_steuerung, aktenzeichen_verursacher_steuerung,
		betriebsnummer_verursacher, name_ansprechpartner, telefon_ansprechpartner, fax_ansprechpartner, email_ansprechpartner, name, plz, ort, strasse, hausnummer, 
		familienname, vorname, versicherungsnummer, eau_kennzeichen_au_aktuell, abwesenheit_ab_ag, nachweis_seit, tatsaechlich_nachweis_bis, festgestellt_am, arbeitsunfall, d_arzt_zugewiesen,
		sonstiger_unfall_unfallfolgen, nachweisart, fehlermeldung, kommentar, eau_id, imp_verz_serial, pgd_join_id, eau_referenz_id)
		SELECT 
		eau_versionsnummer, eau_versionsnummer, eau_verfahrensmerkmal, eau_absendernummer_datenannahmestelle, eau_empfaengernummer_datenannahmestelle, eau_datum_uhrzeit_erstellung, eau_versionsnummer, eau_absendernummer, eau_empfaengernummer, eau_datum_uhrzeit_erstellung, eau_product_identifier, eau_modification_identifier, eau_datei_folgenummer,
		eau_aktenzeichen_verursacher, eau_betriebsnummer_verursacher, eau_sb_name, eau_sb_telefon, eau_sb_fax, eau_sb_email, eau_sb_name_1 || eau_sb_name_2 || eau_sb_name_3, eau_sb_plz, 
		eau_sb_ort, eau_sb_strasse, eau_sb_hausnr, eau_name, eau_vorname, eau_vsnr, eau_kennzeichen_au_aktuell, eau_au_ab_ag, eau_au_beginndatum, eau_au_vrsl_endedatum, eau_feststellungsdatum,
		eau_arbeitsunfall, eau_d_arzt_zuweisung, eau_sonstiger_unfall, 2, fehlermeldung, kommentar, eau_id, imp_verz_serial, eau_pgd_join_id, eau_referenz_id
		FROM imp_eau_dakota
		WHERE 1 = 1;

		UPDATE imp_eau_dakota2 SET nachweisart = 1 WHERE eau_id = (SELECT eau_id FROM imp_eau_dakota WHERE eau_erstbescheinigung = 'J');
		UPDATE imp_eau_dakota2 SET nachweisart = 2 WHERE eau_id = (SELECT eau_id FROM imp_eau_dakota WHERE eau_folgebescheinigung = 'J');


		FOR imp_eau_tab IN
			SELECT eau_id, eau_referenz_id, eau_datei_folgenummer FROM imp_eau_dakota WHERE eau_storno_kennzeichen = 'J'
		LOOP
			anzahl := (SELECT COUNT(*) FROM imp_eau_dakota WHERE eau_id = imp_eau_tab.eau_referenz_id AND eau_datei_folgenummer = imp_eau_tab.eau_datei_folgenummer);			

			IF anzahl = 1 THEN
					UPDATE imp_eau_dakota2 SET storno_datensatz_id_der_ursprungsmeldung = imp_eau_tab.eau_datei_folgenummer WHERE eau_id = imp_eau_tab.eau_id;
			ELSE
					UPDATE imp_eau_dakota2 SET fehlermeldung = 'Datenmigration aus Tabelle out_eau_dakota konnte nicht vorgenommen werden!' WHERE eau_id = imp_eau_tab.eau_id;
			END IF;
		END LOOP;
	END;		

$$;


--
-- Name: entry_transactiondb(); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.entry_transactiondb() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
BEGIN
 PERFORM sva4.entry_transactiondi(OLD);
 RETURN OLD; END; $$;


--
-- Name: entry_transaction; Type: TABLE; Schema: sva4; Owner: -
--

CREATE TABLE sva4.entry_transaction (
    db_einfuegemarke character varying(6),
    id integer NOT NULL,
    state integer,
    login_user character varying(254),
    time_start timestamp without time zone,
    time_end timestamp without time zone,
    request text,
    response text
);


--
-- Name: entry_transactiondi(sva4.entry_transaction); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.entry_transactiondi(sva4.entry_transaction) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
 RETURN old_row; END; $_$;


--
-- Name: exists_role(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.exists_role(rolle character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$   DECLARE          abfrage TEXT;   BEGIN          IF NOT EXISTS (SELECT * FROM pg_roles WHERE rolname = rolle) THEN           abfrage := 'CREATE ROLE ' || rolle || ' WITH LOGIN NOSUPERUSER NOINHERIT NOCREATEDB NOCREATEROLE NOREPLICATION VALID UNTIL ''infinity'';';           EXECUTE abfrage;          END IF;           abfrage := 'GRANT USAGE ON SCHEMA ' || current_schema || ' TO ' || rolle || ';';           EXECUTE abfrage;          END;   $$;


