			k_azm_row.zuschlag_mi, 
			k_azm_row.zuschlag_do, 
			k_azm_row.zuschlag_fr, 
			k_azm_row.zuschlag_sa, 
			k_azm_row.zuschlag_so, 
			k_azm_row.zuschlag_feiertag, 
			k_azm_row.zeitguthaben_max2, 
			k_azm_row.monat_verfall_zgh2, 
			k_azm_row.zgh_max_anteilig2, 
			k_azm_row.maxarbzeit_total, 
			k_azm_row.zgh_max_dynamisch, 
			k_azm_row.zgh_max_dynamisch_null, 
			k_azm_row.kapp_1_tagesarbeitszeit, 
			k_azm_row.kapp_1_tagesarbeitszeit_faktor, 
			k_azm_row.kapp_2_tagesarbeitszeit, 
			k_azm_row.kapp_2_tagesarbeitszeit_faktor, 
			0, 
			0, 
			0, 
			az_config_key_v);

	END LOOP;

	RETURN 'Erfolgreich beendet';
END;
$$;


--
-- Name: f_conv_arbeitszeit_details(character varying, smallint, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: sva4; Owner: -
