--
-- Name: fbadb(); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.fbadb() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
BEGIN
 PERFORM sva4.fbadi(OLD);
 RETURN OLD; END; $$;


--
-- Name: fba; Type: TABLE; Schema: sva4; Owner: -
--

CREATE TABLE sva4.fba (
    db_einfuegemarke character varying(6),
    fba_serial integer NOT NULL,
    fba_status smallint NOT NULL,
    fba_pgd_join_id integer,
    fba_sem_id integer,
    fba_von date,
    fba_bis date,
    fba_notiz text,
    fba_antragsdatum date,
    fba_processing_step_id integer
);


--
-- Name: fbadi(sva4.fba); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.fbadi(sva4.fba) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM sva4.ffi ffi WHERE old_row.fba_serial = ffi.ffi_fba_join_id;
 RETURN old_row; END; $_$;


--
-- Name: fbdb(); Type: FUNCTION; Schema: sva4; Owner: -
