CREATE FUNCTION sva4.fbdr_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _fbdr_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _fbdrinst_buffer!'; end if; SELECT * INTO rec FROM _fbdr_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO fbdr (db_einfuegemarke, jahr, kap, dr, fb, fbdrbez, hhans, ans_a, ans_e, sperr, reste, zvert, fest, ausz, soll, ein, vojs, kz_ueber, sperrkz, soll_kontr, soll_kontr2, art, dtgr, ein_a, ein_e, soll_e, ausz_e, juekto_bewrest) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.jahr),'NULL') || ' , ' || COALESCE(quote_literal(rec.kap),'NULL') || ' , ' || COALESCE(quote_literal(rec.dr),'NULL') || ' , ' || COALESCE(quote_literal(rec.fb),'NULL') || ' , ' || COALESCE(quote_literal(rec.fbdrbez),'NULL') || ' , ' || COALESCE(quote_literal(rec.hhans),'NULL') || ' , ' || COALESCE(quote_literal(rec.ans_a),'NULL') || ' , ' || COALESCE(quote_literal(rec.ans_e),'NULL') || ' , ' || COALESCE(quote_literal(rec.sperr),'NULL') || ' , ' || COALESCE(quote_literal(rec.reste),'NULL') || ' , ' || COALESCE(quote_literal(rec.zvert),'NULL') || ' , ' || COALESCE(quote_literal(rec.fest),'NULL') || ' , ' || COALESCE(quote_literal(rec.ausz),'NULL') || ' , ' || COALESCE(quote_literal(rec.soll),'NULL') || ' , ' || COALESCE(quote_literal(rec.ein),'NULL') || ' , ' || COALESCE(quote_literal(rec.vojs),'NULL') || ' , ' || COALESCE(quote_literal(rec.kz_ueber),'NULL') || ' , ' || COALESCE(quote_literal(rec.sperrkz),'NULL') || ' , ' || COALESCE(quote_literal(rec.soll_kontr),'NULL') || ' , ' || COALESCE(quote_literal(rec.soll_kontr2),'NULL') || ' , ' || COALESCE(quote_literal(rec.art),'NULL') || ' , ' || COALESCE(quote_literal(rec.dtgr),'NULL') || ' , ' || COALESCE(quote_literal(rec.ein_a),'NULL') || ' , ' || COALESCE(quote_literal(rec.ein_e),'NULL') || ' , ' || COALESCE(quote_literal(rec.soll_e),'NULL') || ' , ' || COALESCE(quote_literal(rec.ausz_e),'NULL') || ' , ' || COALESCE(quote_literal(rec.juekto_bewrest),'NULL') || ')'; ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _fbdr_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


