CREATE FUNCTION sva4.fbdr_upd(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(join_nr) INTO anz FROM _fbdr_buffer WHERE join_nr= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _fbdr_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _fbdr_buffer WHERE join_nr= id1 ; If FOUND then sql = 'UPDATE fbdr SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , jahr= ' || COALESCE(quote_literal(rec.jahr),'NULL') || ' , kap= ' || COALESCE(quote_literal(rec.kap),'NULL') || ' , dr= ' || COALESCE(quote_literal(rec.dr),'NULL') || ' , fb= ' || COALESCE(quote_literal(rec.fb),'NULL') || ' , fbdrbez= ' || COALESCE(quote_literal(rec.fbdrbez),'NULL') || ' , hhans= ' || COALESCE(quote_literal(rec.hhans),'NULL') || ' , ans_a= ' || COALESCE(quote_literal(rec.ans_a),'NULL') || ' , ans_e= ' || COALESCE(quote_literal(rec.ans_e),'NULL') || ' , sperr= ' || COALESCE(quote_literal(rec.sperr),'NULL') || ' , reste= ' || COALESCE(quote_literal(rec.reste),'NULL') || ' , zvert= ' || COALESCE(quote_literal(rec.zvert),'NULL') || ' , fest= ' || COALESCE(quote_literal(rec.fest),'NULL') || ' , ausz= ' || COALESCE(quote_literal(rec.ausz),'NULL') || ' , soll= ' || COALESCE(quote_literal(rec.soll),'NULL') || ' , ein= ' || COALESCE(quote_literal(rec.ein),'NULL') || ' , vojs= ' || COALESCE(quote_literal(rec.vojs),'NULL') || ' , kz_ueber= ' || COALESCE(quote_literal(rec.kz_ueber),'NULL') || ' , sperrkz= ' || COALESCE(quote_literal(rec.sperrkz),'NULL') || ' , soll_kontr= ' || COALESCE(quote_literal(rec.soll_kontr),'NULL') || ' , soll_kontr2= ' || COALESCE(quote_literal(rec.soll_kontr2),'NULL') || ' , art= ' || COALESCE(quote_literal(rec.art),'NULL') || ' , dtgr= ' || COALESCE(quote_literal(rec.dtgr),'NULL') || ' , ein_a= ' || COALESCE(quote_literal(rec.ein_a),'NULL') || ' , ein_e= ' || COALESCE(quote_literal(rec.ein_e),'NULL') || ' , soll_e= ' || COALESCE(quote_literal(rec.soll_e),'NULL') || ' , ausz_e= ' || COALESCE(quote_literal(rec.ausz_e),'NULL') || ' , juekto_bewrest= ' || COALESCE(quote_literal(rec.juekto_bewrest),'NULL') || ' WHERE join_nr=' || quote_literal(rec.join_nr); ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _fbdr_buffer WHERE join_nr= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


