    lbez character varying(255),
    kokl character varying(1),
    habpos character varying(10),
    key_von date,
    key_bis date,
    svarel character varying(1),
    mbsrel character varying(1),
    ivsrel character varying(1),
    baurel character varying(1),
    cobrel character varying(1),
    besrel character varying(1),
