    obj_guid character varying(36) DEFAULT '0'::character varying,
    lock_version bigint DEFAULT 0
);


--
-- Name: fikrdi(sva4.__fikr); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.fikrdi(sva4.__fikr) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
IF EXISTS(SELECT * FROM sva4.fikr fikr WHERE old_row.key = fikr.ueberg) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "fikr" verwendet!';
END IF;
DELETE FROM sva4.r_fikr_attribut r_fikr_attribut WHERE old_row.key = r_fikr_attribut.fikr_key;
 RETURN old_row; END; $_$;


