    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _fins_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _finsinst_buffer!'; end if; SELECT * INTO rec FROM _fins_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO fins (db_einfuegemarke, fins_keygrp, fins_key, fins_lbez) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.fins_keygrp),'NULL') || ' , ' || COALESCE(quote_literal(rec.fins_key),'NULL') || ' , ' || COALESCE(quote_literal(rec.fins_lbez),'NULL') || ')'; ret_dblink = dblink_exec(gc('superx_cob_90_ap'), sql); DELETE FROM _fins_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


--
-- Name: fins_upd(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.fins_upd(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(fins_key) INTO anz FROM _fins_buffer WHERE fins_key= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _fins_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _fins_buffer WHERE fins_key= id1 ; If FOUND then sql = 'UPDATE fins SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , fins_keygrp= ' || COALESCE(quote_literal(rec.fins_keygrp),'NULL') || ' , fins_key= ' || COALESCE(quote_literal(rec.fins_key),'NULL') || ' , fins_lbez= ' || COALESCE(quote_literal(rec.fins_lbez),'NULL') || ' WHERE fins_key=' || quote_literal(rec.fins_key); ret_dblink = dblink_exec(gc('superx_cob_90_ap'), sql); DELETE FROM _fins_buffer WHERE fins_key= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


