--

CREATE TABLE sva4.__fins (
    db_einfuegemarke character varying(6),
    fins_keygrp character varying(4),
    fins_key character varying(4) NOT NULL,
    fins_lbez character varying(80),
    join_nr integer NOT NULL
);


--
-- Name: finsdi(sva4.__fins); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.finsdi(sva4.__fins) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
IF EXISTS(SELECT * FROM sva4.inst inst WHERE old_row.fins_key = inst.fins) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "inst" verwendet!';
END IF;
IF EXISTS(SELECT * FROM sva4.proj proj WHERE old_row.fins_key = proj.fins) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "proj" verwendet!';
END IF;
 RETURN old_row; END; $_$;


