    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _gege_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _gegeinst_buffer!'; end if; SELECT * INTO rec FROM _gege_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO gege (db_einfuegemarke, ggnr, ueberkey, ggkey, fikey, ggkurz, ggdruck, ggname1, ggname2, ggname3, ggstr, ggort, ggplz, key_von, key_bis, bund_geldgeber, svarel, mbsrel, ivsrel, baurel, cobrel, klr_geldgeber) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.ggnr),'NULL') || ' , ' || COALESCE(quote_literal(rec.ueberkey),'NULL') || ' , ' || COALESCE(quote_literal(rec.ggkey),'NULL') || ' , ' || COALESCE(quote_literal(rec.fikey),'NULL') || ' , ' || COALESCE(quote_literal(rec.ggkurz),'NULL') || ' , ' || COALESCE(quote_literal(rec.ggdruck),'NULL') || ' , ' || COALESCE(quote_literal(rec.ggname1),'NULL') || ' , ' || COALESCE(quote_literal(rec.ggname2),'NULL') || ' , ' || COALESCE(quote_literal(rec.ggname3),'NULL') || ' , ' || COALESCE(quote_literal(rec.ggstr),'NULL') || ' , ' || COALESCE(quote_literal(rec.ggort),'NULL') || ' , ' || COALESCE(quote_literal(rec.ggplz),'NULL') || ' , ' || COALESCE(quote_literal(rec.key_von),'NULL') || ' , ' || COALESCE(quote_literal(rec.key_bis),'NULL') || ' , ' || COALESCE(quote_literal(rec.bund_geldgeber),'NULL') || ' , ' || COALESCE(quote_literal(rec.svarel),'NULL') || ' , ' || COALESCE(quote_literal(rec.mbsrel),'NULL') || ' , ' || COALESCE(quote_literal(rec.ivsrel),'NULL') || ' , ' || COALESCE(quote_literal(rec.baurel),'NULL') || ' , ' || COALESCE(quote_literal(rec.cobrel),'NULL') || ' , ' || COALESCE(quote_literal(rec.klr_geldgeber),'NULL') || ')'; ret_dblink = dblink_exec(gc('superx_cob_90_ap'), sql); DELETE FROM _gege_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


