--
-- Name: gvpdi(sva4.gvp); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.gvpdi(sva4.gvp) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM sva4.gvp_to_pbv gvp_to_pbv WHERE old_row.gvp_join_id = gvp_to_pbv.gvp_join_id;
DELETE FROM sva4.gvp_to_sgd gvp_to_sgd WHERE old_row.gvp_join_id = gvp_to_sgd.gvp_join_id;
DELETE FROM sva4.gvp_vert gvp_vert WHERE old_row.gvp_join_id = gvp_vert.gvp_join_id;
DELETE FROM sva4.gvp_vert gvp_vert WHERE old_row.gvp_join_id = gvp_vert.gvp_vert_join_id;
DELETE FROM sva4.kpt_to_gvp kpt_to_gvp WHERE old_row.gvp_join_id = kpt_to_gvp.gvp_join_id;
 RETURN old_row; END; $_$;


