--
-- Name: hueldi(sva4.__huel); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.hueldi(sva4.__huel) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM sva4.r_huel_attribut r_huel_attribut WHERE old_row.join_nr = r_huel_attribut.huel_join_id;
 RETURN old_row; END; $_$;


