CREATE FUNCTION sva4.imp_busa_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _imp_busa_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _imp_busainst_buffer!'; end if; SELECT * INTO rec FROM _imp_busa_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO imp_busa (db_einfuegemarke, busa_quellsys, busa_quelldatnr, busa_quellidnr, busa_status, busa_hinweis, busa_jahr, busa_monat, busa_korepvon, busa_korepbis, busa_instnr, busa_projnr, busa_fikrkey, busa_kapitel, busa_titel, busa_verwzweck1, busa_verwzweck2, busa_stornokz, busa_wkz, busa_betrag, imp_verz_id, busa_ggnr, busa_fikrkey2) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.busa_quellsys),'NULL') || ' , ' || COALESCE(quote_literal(rec.busa_quelldatnr),'NULL') || ' , ' || COALESCE(quote_literal(rec.busa_quellidnr),'NULL') || ' , ' || COALESCE(quote_literal(rec.busa_status),'NULL') || ' , ' || COALESCE(quote_literal(rec.busa_hinweis),'NULL') || ' , ' || COALESCE(quote_literal(rec.busa_jahr),'NULL') || ' , ' || COALESCE(quote_literal(rec.busa_monat),'NULL') || ' , ' || COALESCE(quote_literal(rec.busa_korepvon),'NULL') || ' , ' || COALESCE(quote_literal(rec.busa_korepbis),'NULL') || ' , ' || COALESCE(quote_literal(rec.busa_instnr),'NULL') || ' , ' || COALESCE(quote_literal(rec.busa_projnr),'NULL') || ' , ' || COALESCE(quote_literal(rec.busa_fikrkey),'NULL') || ' , ' || COALESCE(quote_literal(rec.busa_kapitel),'NULL') || ' , ' || COALESCE(quote_literal(rec.busa_titel),'NULL') || ' , ' || COALESCE(quote_literal(rec.busa_verwzweck1),'NULL') || ' , ' || COALESCE(quote_literal(rec.busa_verwzweck2),'NULL') || ' , ' || COALESCE(quote_literal(rec.busa_stornokz),'NULL') || ' , ' || COALESCE(quote_literal(rec.busa_wkz),'NULL') || ' , ' || COALESCE(quote_literal(rec.busa_betrag),'NULL') || ' , ' || COALESCE(quote_literal(rec.imp_verz_id),'NULL') || ' , ' || COALESCE(quote_literal(rec.busa_ggnr),'NULL') || ' , ' || COALESCE(quote_literal(rec.busa_fikrkey2),'NULL') || ')'; ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _imp_busa_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


--
-- Name: imp_busa_upd(integer); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.imp_busa_upd(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(busa_id) INTO anz FROM _imp_busa_buffer WHERE busa_id= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _imp_busa_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _imp_busa_buffer WHERE busa_id= id1 ; If FOUND then sql = 'UPDATE imp_busa SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , busa_quellsys= ' || COALESCE(quote_literal(rec.busa_quellsys),'NULL') || ' , busa_quelldatnr= ' || COALESCE(quote_literal(rec.busa_quelldatnr),'NULL') || ' , busa_quellidnr= ' || COALESCE(quote_literal(rec.busa_quellidnr),'NULL') || ' , busa_status= ' || COALESCE(quote_literal(rec.busa_status),'NULL') || ' , busa_hinweis= ' || COALESCE(quote_literal(rec.busa_hinweis),'NULL') || ' , busa_jahr= ' || COALESCE(quote_literal(rec.busa_jahr),'NULL') || ' , busa_monat= ' || COALESCE(quote_literal(rec.busa_monat),'NULL') || ' , busa_korepvon= ' || COALESCE(quote_literal(rec.busa_korepvon),'NULL') || ' , busa_korepbis= ' || COALESCE(quote_literal(rec.busa_korepbis),'NULL') || ' , busa_instnr= ' || COALESCE(quote_literal(rec.busa_instnr),'NULL') || ' , busa_projnr= ' || COALESCE(quote_literal(rec.busa_projnr),'NULL') || ' , busa_fikrkey= ' || COALESCE(quote_literal(rec.busa_fikrkey),'NULL') || ' , busa_kapitel= ' || COALESCE(quote_literal(rec.busa_kapitel),'NULL') || ' , busa_titel= ' || COALESCE(quote_literal(rec.busa_titel),'NULL') || ' , busa_verwzweck1= ' || COALESCE(quote_literal(rec.busa_verwzweck1),'NULL') || ' , busa_verwzweck2= ' || COALESCE(quote_literal(rec.busa_verwzweck2),'NULL') || ' , busa_stornokz= ' || COALESCE(quote_literal(rec.busa_stornokz),'NULL') || ' , busa_wkz= ' || COALESCE(quote_literal(rec.busa_wkz),'NULL') || ' , busa_betrag= ' || COALESCE(quote_literal(rec.busa_betrag),'NULL') || ' , imp_verz_id= ' || COALESCE(quote_literal(rec.imp_verz_id),'NULL') || ' , busa_ggnr= ' || COALESCE(quote_literal(rec.busa_ggnr),'NULL') || ' , busa_fikrkey2= ' || COALESCE(quote_literal(rec.busa_fikrkey2),'NULL') || ' WHERE busa_id=' || quote_literal(rec.busa_id); ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _imp_busa_buffer WHERE busa_id= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


