DELETE FROM sva4.imp_pbz_kidicap imp_pbz_kidicap WHERE old_row.imp_verz_serial = imp_pbz_kidicap.imp_verz_serial;
DELETE FROM sva4.imp_pbz_kidicap2 imp_pbz_kidicap2 WHERE old_row.imp_verz_serial = imp_pbz_kidicap2.imp_verz_serial;
DELETE FROM sva4.imp_pbz_lba_mv imp_pbz_lba_mv WHERE old_row.imp_verz_serial = imp_pbz_lba_mv.imp_verz_serial;
DELETE FROM sva4.imp_pbz_lba_sh imp_pbz_lba_sh WHERE old_row.imp_verz_serial = imp_pbz_lba_sh.imp_verz_serial;
DELETE FROM sva4.imp_pbz_lbv imp_pbz_lbv WHERE old_row.imp_verz_serial = imp_pbz_lbv.imp_verz_serial;
DELETE FROM sva4.imp_pbz_sap1 imp_pbz_sap1 WHERE old_row.imp_verz_serial = imp_pbz_sap1.imp_verz_serial;
DELETE FROM sva4.imp_pbz_zceus imp_pbz_zceus WHERE old_row.imp_verz_serial = imp_pbz_zceus.imp_verz_serial;
DELETE FROM sva4.imp_pko_gehaltx imp_pko_gehaltx WHERE old_row.imp_verz_serial = imp_pko_gehaltx.imp_verz_serial;
DELETE FROM sva4.imp_pko_ion imp_pko_ion WHERE old_row.imp_verz_serial = imp_pko_ion.imp_verz_serial;
 RETURN old_row; END; $_$;


