CREATE FUNCTION sva4.isoland_upd(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(landschl) INTO anz FROM _isoland_buffer WHERE landschl= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _isoland_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _isoland_buffer WHERE landschl= id1 ; If FOUND then sql = 'UPDATE isoland SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , landschl= ' || COALESCE(quote_literal(rec.landschl),'NULL') || ' , landkz= ' || COALESCE(quote_literal(rec.landkz),'NULL') || ' , landname= ' || COALESCE(quote_literal(rec.landname),'NULL') || ' , waehrung= ' || COALESCE(quote_literal(rec.waehrung),'NULL') || ' , waehrbez= ' || COALESCE(quote_literal(rec.waehrbez),'NULL') || ' WHERE landschl=' || quote_literal(rec.landschl); ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _isoland_buffer WHERE landschl= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


