--
-- Name: jubilaeumsdaten(); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.jubilaeumsdaten() RETURNS void
    LANGUAGE plpgsql
    AS $$

   DECLARE
      counter INT;

   BEGIN
	SET search_path TO sva4;
	
	counter := (SELECT SUM(protokollierung) FROM db_tabellen WHERE name = 'pgd');
	IF counter > 0 THEN
		RAISE EXCEPTION 'Protokollierung fuer die SVA-Tabelle pgd ausschalten!!!';
	ELSE
	END IF;
  
   END;

$$;


