--
-- Name: jubilaeumsdaten_alter(sva4.pgd); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.jubilaeumsdaten_alter(sva4.pgd) RETURNS record
    LANGUAGE plpgsql
    AS $_$

DECLARE
    row_pgd ALIAS FOR $1;

    meldung NCHAR(100);

  BEGIN
    SET search_path TO sva4;
	
		IF (row_pgd.pgd_jubidtbermod = 'B' AND row_pgd.pgd_jubi_berech IS NOT NULL) THEN			
			row_pgd.pgd_jubi_25_datum := row_pgd.pgd_jubi_berech  + (25||'YEARS')::INTERVAL;
			row_pgd.pgd_jubi_40_datum := row_pgd.pgd_jubi_berech  + (40||'YEARS')::INTERVAL;
			row_pgd.pgd_jubi_50_datum := row_pgd.pgd_jubi_berech  + (50||'YEARS')::INTERVAL;

			--Neue Wiedervorlagen eintragen:
			INSERT INTO wvl (wvl_pgd_join_id, wvl_tabellenname, wvl_tab_serial, wvl_tab_spalte, wvl_status,
										 wvl_datum, wvl_termin, wvl_grund,
										 wvl_verarbeitung, wvl_vermerk, wvl_sachbearb, wvl_bearb_status)
			SELECT pgd_join_id, 'pgd', pgd_join_id, 'pgd_jubi_25_datum', 0, 
						current_date, pgd_jubi_25_datum - (((SELECT vorlaufzeit FROM sv_konfig_wvl WHERE feld_name = 'pgd_jubi_25_datum')::text || 'DAY')::interval), (SELECT wvl_grund FROM sv_konfig_wvl WHERE feld_name = 'pgd_jubi_25_datum'), 
						 'A', to_char(row_pgd.pgd_jubi_25_datum, 'DD.MM.YYYY'), pgd_inhaber, 'N'
			FROM pgd			 
			WHERE (pgd.pgd_austrittsdatum IS NULL OR pgd.pgd_austrittsdatum >= current_date)
				AND pgd_join_id = row_pgd.pgd_join_id
				AND NOT EXISTS (SELECT wvl_pgd_join_id FROM wvl WHERE wvl_tab_spalte = 'pgd_jubi_25_datum' AND wvl_pgd_join_id = row_pgd.pgd_join_id);
				
			INSERT INTO wvl (wvl_pgd_join_id, wvl_tabellenname, wvl_tab_serial, wvl_tab_spalte, wvl_status,
										 wvl_datum, wvl_termin, wvl_grund,
										 wvl_verarbeitung, wvl_vermerk, wvl_sachbearb, wvl_bearb_status)
			SELECT pgd_join_id, 'pgd', pgd_join_id, 'pgd_jubi_40_datum', 0, 
						current_date, pgd_jubi_40_datum - (((SELECT vorlaufzeit FROM sv_konfig_wvl WHERE feld_name = 'pgd_jubi_40_datum')::text || 'DAY')::interval), (SELECT wvl_grund FROM sv_konfig_wvl WHERE feld_name = 'pgd_jubi_40_datum'), 
						 'A', to_char(row_pgd.pgd_jubi_40_datum, 'DD.MM.YYYY'), pgd_inhaber, 'N'
			FROM pgd			 
			WHERE (pgd.pgd_austrittsdatum IS NULL OR pgd.pgd_austrittsdatum >= current_date)
				AND pgd_join_id = row_pgd.pgd_join_id
				AND NOT EXISTS (SELECT wvl_pgd_join_id FROM wvl WHERE wvl_tab_spalte = 'pgd_jubi_40_datum' AND wvl_pgd_join_id = row_pgd.pgd_join_id);

			INSERT INTO wvl (wvl_pgd_join_id, wvl_tabellenname, wvl_tab_serial, wvl_tab_spalte, wvl_status,
										 wvl_datum, wvl_termin, wvl_grund,
										 wvl_verarbeitung, wvl_vermerk, wvl_sachbearb, wvl_bearb_status)
			SELECT pgd_join_id, 'pgd', pgd_join_id, 'pgd_jubi_50_datum', 0, 
						current_date, pgd_jubi_50_datum - (((SELECT vorlaufzeit FROM sv_konfig_wvl WHERE feld_name = 'pgd_jubi_50_datum')::text || 'DAY')::interval), (SELECT wvl_grund FROM sv_konfig_wvl WHERE feld_name = 'pgd_jubi_50_datum'), 
						 'A', to_char(row_pgd.pgd_jubi_50_datum, 'DD.MM.YYYY'), pgd_inhaber, 'N'
			FROM pgd			 
			WHERE (pgd.pgd_austrittsdatum IS NULL OR pgd.pgd_austrittsdatum >= current_date)
				AND pgd_join_id = row_pgd.pgd_join_id
				AND NOT EXISTS (SELECT wvl_pgd_join_id FROM wvl WHERE wvl_tab_spalte = 'pgd_jubi_50_datum' AND wvl_pgd_join_id = row_pgd.pgd_join_id);



			--Aktualisierung der Wiedervorlagen:
			UPDATE wvl SET wvl_datum = current_date,
										 wvl_vermerk = to_char(row_pgd.pgd_jubi_25_datum, 'DD.MM.YYYY'),
										 wvl_termin =  row_pgd.pgd_jubi_25_datum - (((SELECT vorlaufzeit FROM sv_konfig_wvl WHERE feld_name = 'pgd_jubi_25_datum')||'DAY')::interval)
			 WHERE wvl_tab_spalte = 'pgd_jubi_25_datum'
				 AND row_pgd.pgd_jubi_25_datum IS NOT NULL
				 AND wvl_pgd_join_id IN
					 (SELECT DISTINCT pgd.pgd_join_id FROM pgd
						 WHERE pgd.pgd_eintrittsdatum <= current_date AND (pgd.pgd_austrittsdatum IS NULL OR pgd.pgd_austrittsdatum >= current_date) AND pgd.pgd_status = 0);
						 
			UPDATE wvl SET wvl_datum = current_date,
										 wvl_vermerk = to_char(row_pgd.pgd_jubi_40_datum, 'DD.MM.YYYY'),
										 wvl_termin =  row_pgd.pgd_jubi_40_datum - (((SELECT vorlaufzeit FROM sv_konfig_wvl WHERE feld_name = 'pgd_jubi_40_datum')||'DAY')::interval)
			 WHERE wvl_tab_spalte = 'pgd_jubi_40_datum'
				 AND row_pgd.pgd_jubi_40_datum IS NOT NULL
				 AND wvl_pgd_join_id IN
					 (SELECT DISTINCT pgd.pgd_join_id FROM pgd
						 WHERE pgd.pgd_eintrittsdatum <= current_date AND (pgd.pgd_austrittsdatum IS NULL OR pgd.pgd_austrittsdatum >= current_date) AND pgd.pgd_status = 0);

			UPDATE wvl SET wvl_datum = current_date,
										 wvl_vermerk = to_char(row_pgd.pgd_jubi_50_datum, 'DD.MM.YYYY'),
										 wvl_termin =  row_pgd.pgd_jubi_50_datum - (((SELECT vorlaufzeit FROM sv_konfig_wvl WHERE feld_name = 'pgd_jubi_50_datum')||'DAY')::interval)
			 WHERE wvl_tab_spalte = 'pgd_jubi_50_datum'
				 AND row_pgd.pgd_jubi_50_datum IS NOT NULL
				 AND wvl_pgd_join_id IN
					 (SELECT DISTINCT pgd.pgd_join_id FROM pgd
						 WHERE pgd.pgd_eintrittsdatum <= current_date AND (pgd.pgd_austrittsdatum IS NULL OR pgd.pgd_austrittsdatum >= current_date) AND pgd.pgd_status = 0);						 


			meldung := 'Erfolgreich berechnet!';

		END IF;
		
    --Rückgabewerte
    RETURN row_pgd;

  END;
$_$;


--
-- Name: jubilaeumsdaten_alter(sva4.pgd, sva4.pgd); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.jubilaeumsdaten_alter(sva4.pgd, sva4.pgd) RETURNS record
    LANGUAGE plpgsql
    AS $_$

DECLARE
		pgd_entry_old ALIAS FOR $1;
		pgd_entry_new ALIAS FOR $2;
		
		p_pgd_join_id INT;
		p_nichtanrechnungsfaehige_tage INT;

    meldung NCHAR(100);

  BEGIN
    SET search_path TO sva4;
		
		-- Nicht anrechnungsfähige Beurlaubungen ermitteln (pbu_jubi_zeit = N):
		p_nichtanrechnungsfaehige_tage := 0;
		p_nichtanrechnungsfaehige_tage := (SELECT COALESCE(SUM(pbu_bis - pbu_von + 1), 0) FROM pbu WHERE pbu_status = 0 AND pbu_jubi_zeit = 'N' AND pbu_pgd_join_id = pgd_entry_new.pgd_join_id);
	
		IF (pgd_entry_new.pgd_jubidtbermod = 'B' AND pgd_entry_new.pgd_jubi_berech IS NOT NULL) THEN			
			pgd_entry_new.pgd_jubi_25_datum := pgd_entry_new.pgd_jubi_berech  + (25||'YEARS')::INTERVAL + (p_nichtanrechnungsfaehige_tage||'DAYS')::INTERVAL;
			pgd_entry_new.pgd_jubi_40_datum := pgd_entry_new.pgd_jubi_berech  + (40||'YEARS')::INTERVAL + (p_nichtanrechnungsfaehige_tage||'DAYS')::INTERVAL;
			pgd_entry_new.pgd_jubi_50_datum := pgd_entry_new.pgd_jubi_berech  + (50||'YEARS')::INTERVAL + (p_nichtanrechnungsfaehige_tage||'DAYS')::INTERVAL;
			
			IF (pgd_entry_old != pgd_entry_new) THEN			

				p_pgd_join_id := pgd_entry_new.pgd_join_id;
				
				--Neue Wiedervorlagen eintragen:
				INSERT INTO wvl (wvl_pgd_join_id, wvl_tabellenname, wvl_tab_serial, wvl_tab_spalte, wvl_status,
											 wvl_datum, wvl_termin, wvl_grund,
											 wvl_verarbeitung, wvl_vermerk, wvl_sachbearb, wvl_bearb_status)
				SELECT pgd_join_id, 'pgd', pgd_join_id, 'pgd_jubi_25_datum', 0, 
							current_date, pgd_jubi_25_datum - (((SELECT vorlaufzeit FROM sv_konfig_wvl WHERE feld_name = 'pgd_jubi_25_datum')::text || 'DAY')::interval), (SELECT wvl_grund FROM sv_konfig_wvl WHERE feld_name = 'pgd_jubi_25_datum'), 
							 'A', to_char(pgd_entry_new.pgd_jubi_25_datum, 'DD.MM.YYYY'), pgd_inhaber, 'N'
				FROM pgd			 
				WHERE (pgd.pgd_austrittsdatum IS NULL OR pgd.pgd_austrittsdatum >= current_date)
					AND pgd_join_id = p_pgd_join_id
					AND NOT EXISTS (SELECT wvl_pgd_join_id FROM wvl WHERE wvl_tab_spalte = 'pgd_jubi_25_datum' AND wvl_pgd_join_id = p_pgd_join_id);
					
				INSERT INTO wvl (wvl_pgd_join_id, wvl_tabellenname, wvl_tab_serial, wvl_tab_spalte, wvl_status,
											 wvl_datum, wvl_termin, wvl_grund,
											 wvl_verarbeitung, wvl_vermerk, wvl_sachbearb, wvl_bearb_status)
				SELECT pgd_join_id, 'pgd', pgd_join_id, 'pgd_jubi_40_datum', 0, 
							current_date, pgd_jubi_40_datum - (((SELECT vorlaufzeit FROM sv_konfig_wvl WHERE feld_name = 'pgd_jubi_40_datum')::text || 'DAY')::interval), (SELECT wvl_grund FROM sv_konfig_wvl WHERE feld_name = 'pgd_jubi_40_datum'), 
							 'A', to_char(pgd_entry_new.pgd_jubi_40_datum, 'DD.MM.YYYY'), pgd_inhaber, 'N'
				FROM pgd			 
				WHERE (pgd.pgd_austrittsdatum IS NULL OR pgd.pgd_austrittsdatum >= current_date)
					AND pgd_join_id = p_pgd_join_id
					AND NOT EXISTS (SELECT wvl_pgd_join_id FROM wvl WHERE wvl_tab_spalte = 'pgd_jubi_40_datum' AND wvl_pgd_join_id = p_pgd_join_id);

				INSERT INTO wvl (wvl_pgd_join_id, wvl_tabellenname, wvl_tab_serial, wvl_tab_spalte, wvl_status,
											 wvl_datum, wvl_termin, wvl_grund,
											 wvl_verarbeitung, wvl_vermerk, wvl_sachbearb, wvl_bearb_status)
				SELECT pgd_join_id, 'pgd', pgd_join_id, 'pgd_jubi_50_datum', 0, 
							current_date, pgd_jubi_50_datum - (((SELECT vorlaufzeit FROM sv_konfig_wvl WHERE feld_name = 'pgd_jubi_50_datum')::text || 'DAY')::interval), (SELECT wvl_grund FROM sv_konfig_wvl WHERE feld_name = 'pgd_jubi_50_datum'), 
							 'A', to_char(pgd_entry_new.pgd_jubi_50_datum, 'DD.MM.YYYY'), pgd_inhaber, 'N'
				FROM pgd			 
				WHERE (pgd.pgd_austrittsdatum IS NULL OR pgd.pgd_austrittsdatum >= current_date)
					AND pgd_join_id = p_pgd_join_id
					AND NOT EXISTS (SELECT wvl_pgd_join_id FROM wvl WHERE wvl_tab_spalte = 'pgd_jubi_50_datum' AND wvl_pgd_join_id = p_pgd_join_id);



				--Aktualisierung der Wiedervorlagen:
				UPDATE wvl SET wvl_datum = current_date,
											 wvl_vermerk = to_char(pgd_entry_new.pgd_jubi_25_datum, 'DD.MM.YYYY'),
											 wvl_termin =  pgd_entry_new.pgd_jubi_25_datum - (((SELECT vorlaufzeit FROM sv_konfig_wvl WHERE feld_name = 'pgd_jubi_25_datum')||'DAY')::interval)
				 WHERE wvl_tab_spalte = 'pgd_jubi_25_datum'
					 AND pgd_entry_new.pgd_jubi_25_datum IS NOT NULL
					 AND wvl_pgd_join_id IN
						 (SELECT DISTINCT pgd.pgd_join_id FROM pgd
							 WHERE pgd.pgd_eintrittsdatum <= current_date AND (pgd.pgd_austrittsdatum IS NULL OR pgd.pgd_austrittsdatum >= current_date) AND pgd.pgd_status = 0 AND pgd.pgd_join_id = p_pgd_join_id);
							 
				UPDATE wvl SET wvl_datum = current_date,
											 wvl_vermerk = to_char(pgd_entry_new.pgd_jubi_40_datum, 'DD.MM.YYYY'),
											 wvl_termin =  pgd_entry_new.pgd_jubi_40_datum - (((SELECT vorlaufzeit FROM sv_konfig_wvl WHERE feld_name = 'pgd_jubi_40_datum')||'DAY')::interval)
				 WHERE wvl_tab_spalte = 'pgd_jubi_40_datum'
					 AND pgd_entry_new.pgd_jubi_40_datum IS NOT NULL
					 AND wvl_pgd_join_id IN
						 (SELECT DISTINCT pgd.pgd_join_id FROM pgd
							 WHERE pgd.pgd_eintrittsdatum <= current_date AND (pgd.pgd_austrittsdatum IS NULL OR pgd.pgd_austrittsdatum >= current_date) AND pgd.pgd_status = 0 AND pgd.pgd_join_id = p_pgd_join_id);

				UPDATE wvl SET wvl_datum = current_date,
											 wvl_vermerk = to_char(pgd_entry_new.pgd_jubi_50_datum, 'DD.MM.YYYY'),
											 wvl_termin =  pgd_entry_new.pgd_jubi_50_datum - (((SELECT vorlaufzeit FROM sv_konfig_wvl WHERE feld_name = 'pgd_jubi_50_datum')||'DAY')::interval)
				 WHERE wvl_tab_spalte = 'pgd_jubi_50_datum'
					 AND pgd_entry_new.pgd_jubi_50_datum IS NOT NULL
					 AND wvl_pgd_join_id IN
						 (SELECT DISTINCT pgd.pgd_join_id FROM pgd
								WHERE pgd.pgd_eintrittsdatum <= current_date AND (pgd.pgd_austrittsdatum IS NULL OR pgd.pgd_austrittsdatum >= current_date) AND pgd.pgd_status = 0 AND pgd.pgd_join_id = p_pgd_join_id);

			END IF;
			
			meldung := 'Erfolgreich berechnet!';

		END IF;
		
    --Rückgabewerte
    RETURN pgd_entry_new;

  END;
$_$;


