-- Name: k_anordnung_del(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.k_anordnung_del(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE sql text; id1 ALIAS FOR $1;  BEGIN sql = 'DELETE FROM k_anordnung WHERE key_ao= ' || quote_literal(id1); return dblink_exec(gc('superx_fsv_90_ap'), sql); END;$_$;


--
-- Name: k_anordnung_ins(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.k_anordnung_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _k_anordnung_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _k_anordnunginst_buffer!'; end if; SELECT * INTO rec FROM _k_anordnung_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO k_anordnung (db_einfuegemarke, key_ao, kurz_ao, druck_ao, text_ao, key_von, key_bis, anzahl_ausdrucke, ao_art) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.key_ao),'NULL') || ' , ' || COALESCE(quote_literal(rec.kurz_ao),'NULL') || ' , ' || COALESCE(quote_literal(rec.druck_ao),'NULL') || ' , ' || COALESCE(quote_literal(rec.text_ao),'NULL') || ' , ' || COALESCE(quote_literal(rec.key_von),'NULL') || ' , ' || COALESCE(quote_literal(rec.key_bis),'NULL') || ' , ' || COALESCE(quote_literal(rec.anzahl_ausdrucke),'NULL') || ' , ' || COALESCE(quote_literal(rec.ao_art),'NULL') || ')'; ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _k_anordnung_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


--
-- Name: k_anordnung_upd(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.k_anordnung_upd(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(key_ao) INTO anz FROM _k_anordnung_buffer WHERE key_ao= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _k_anordnung_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _k_anordnung_buffer WHERE key_ao= id1 ; If FOUND then sql = 'UPDATE k_anordnung SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , key_ao= ' || COALESCE(quote_literal(rec.key_ao),'NULL') || ' , kurz_ao= ' || COALESCE(quote_literal(rec.kurz_ao),'NULL') || ' , druck_ao= ' || COALESCE(quote_literal(rec.druck_ao),'NULL') || ' , text_ao= ' || COALESCE(quote_literal(rec.text_ao),'NULL') || ' , key_von= ' || COALESCE(quote_literal(rec.key_von),'NULL') || ' , key_bis= ' || COALESCE(quote_literal(rec.key_bis),'NULL') || ' , anzahl_ausdrucke= ' || COALESCE(quote_literal(rec.anzahl_ausdrucke),'NULL') || ' , ao_art= ' || COALESCE(quote_literal(rec.ao_art),'NULL') || ' WHERE key_ao=' || quote_literal(rec.key_ao); ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _k_anordnung_buffer WHERE key_ao= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


