--
-- Name: k_anredetiteldi(sva4.k_anredetitel); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.k_anredetiteldi(sva4.k_anredetitel) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
IF EXISTS(SELECT * FROM sva4.pgd pgd WHERE old_row.key_anredetitel = pgd.pgd_titel) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "pgd" verwendet!';
END IF;
 RETURN old_row; END; $_$;


