CREATE FUNCTION sva4.k_bga_del(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE sql text; id1 ALIAS FOR $1;  BEGIN sql = 'DELETE FROM k_bga WHERE key_bga= ' || quote_literal(id1); return dblink_exec(gc('superx_fsv_90_ap'), sql); END;$_$;


--
-- Name: k_bga_ins(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.k_bga_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _k_bga_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _k_bgainst_buffer!'; end if; SELECT * INTO rec FROM _k_bga_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO k_bga (db_einfuegemarke, key_bga, kurz_bga, druck_bga, text_bga, key_von, key_bis, flag_bga) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.key_bga),'NULL') || ' , ' || COALESCE(quote_literal(rec.kurz_bga),'NULL') || ' , ' || COALESCE(quote_literal(rec.druck_bga),'NULL') || ' , ' || COALESCE(quote_literal(rec.text_bga),'NULL') || ' , ' || COALESCE(quote_literal(rec.key_von),'NULL') || ' , ' || COALESCE(quote_literal(rec.key_bis),'NULL') || ' , ' || COALESCE(quote_literal(rec.flag_bga),'NULL') || ')'; ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _k_bga_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


--
-- Name: k_bga_upd(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.k_bga_upd(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(key_bga) INTO anz FROM _k_bga_buffer WHERE key_bga= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _k_bga_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _k_bga_buffer WHERE key_bga= id1 ; If FOUND then sql = 'UPDATE k_bga SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , key_bga= ' || COALESCE(quote_literal(rec.key_bga),'NULL') || ' , kurz_bga= ' || COALESCE(quote_literal(rec.kurz_bga),'NULL') || ' , druck_bga= ' || COALESCE(quote_literal(rec.druck_bga),'NULL') || ' , text_bga= ' || COALESCE(quote_literal(rec.text_bga),'NULL') || ' , key_von= ' || COALESCE(quote_literal(rec.key_von),'NULL') || ' , key_bis= ' || COALESCE(quote_literal(rec.key_bis),'NULL') || ' , flag_bga= ' || COALESCE(quote_literal(rec.flag_bga),'NULL') || ' WHERE key_bga=' || quote_literal(rec.key_bga); ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _k_bga_buffer WHERE key_bga= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


