    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(key_bvlgruppe) INTO anz FROM _k_bvlgruppe_buffer WHERE key_bvlgruppe= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _k_bvlgruppe_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _k_bvlgruppe_buffer WHERE key_bvlgruppe= id1 ; If FOUND then sql = 'UPDATE k_bvlgruppe SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , key_bvlgruppe= ' || COALESCE(quote_literal(rec.key_bvlgruppe),'NULL') || ' , ueberkey= ' || COALESCE(quote_literal(rec.ueberkey),'NULL') || ' , kurz_bvlgruppe= ' || COALESCE(quote_literal(rec.kurz_bvlgruppe),'NULL') || ' , druck_bvlgruppe= ' || COALESCE(quote_literal(rec.druck_bvlgruppe),'NULL') || ' , text_bvlgruppe= ' || COALESCE(quote_literal(rec.text_bvlgruppe),'NULL') || ' , sort_key= ' || COALESCE(quote_literal(rec.sort_key),'NULL') || ' , bund_bvlgruppe= ' || COALESCE(quote_literal(rec.bund_bvlgruppe),'NULL') || ' , bund_dienstverh= ' || COALESCE(quote_literal(rec.bund_dienstverh),'NULL') || ' , land_bvlgruppe= ' || COALESCE(quote_literal(rec.land_bvlgruppe),'NULL') || ' , key_von= ' || COALESCE(quote_literal(rec.key_von),'NULL') || ' , key_bis= ' || COALESCE(quote_literal(rec.key_bis),'NULL') || ' , land_laufbahn= ' || COALESCE(quote_literal(rec.land_laufbahn),'NULL') || ' , key_ms_wert= ' || COALESCE(quote_literal(rec.key_ms_wert),'NULL') || ' , key_kalkulation= ' || COALESCE(quote_literal(rec.key_kalkulation),'NULL') || ' , key_urlaubsgrp= ' || COALESCE(quote_literal(rec.key_urlaubsgrp),'NULL') || ' , hh_bvlgruppe= ' || COALESCE(quote_literal(rec.hh_bvlgruppe),'NULL') || ' , tarifklasse= ' || COALESCE(quote_literal(rec.tarifklasse),'NULL') || ' , art= ' || COALESCE(quote_literal(rec.art),'NULL') || ' , gehalt_bvlgruppe= ' || COALESCE(quote_literal(rec.gehalt_bvlgruppe),'NULL') || ' , gehalt_dienstverh= ' || COALESCE(quote_literal(rec.gehalt_dienstverh),'NULL') || ' , bvlgruppe_paisy= ' || COALESCE(quote_literal(rec.bvlgruppe_paisy),'NULL') || ' , bvlgruppe_paisy_a= ' || COALESCE(quote_literal(rec.bvlgruppe_paisy_a),'NULL') || ' WHERE key_bvlgruppe=' || quote_literal(rec.key_bvlgruppe); ret_dblink = dblink_exec(gc('superx_cob_90_ap'), sql); DELETE FROM _k_bvlgruppe_buffer WHERE key_bvlgruppe= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


