CREATE FUNCTION sva4.k_bvlgruppedi(sva4.__k_bvlgruppe) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM sva4.k_konfig_pko_bvl k_konfig_pko_bvl WHERE old_row.key_bvlgruppe = k_konfig_pko_bvl.bvl_gruppe;
DELETE FROM sva4.k_konfig_sko_bvl k_konfig_sko_bvl WHERE old_row.key_bvlgruppe = k_konfig_sko_bvl.bvl_gruppe;
 RETURN old_row; END; $_$;


