--
-- Name: k_extkotr_del(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.k_extkotr_del(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE sql text; id1 ALIAS FOR $1;  BEGIN sql = 'DELETE FROM k_extkotr WHERE key_extkotr= ' || quote_literal(id1); return dblink_exec(gc('superx_cob_90_ap'), sql); END;$_$;


--
-- Name: k_extkotr_ins(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.k_extkotr_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _k_extkotr_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _k_extkotrinst_buffer!'; end if; SELECT * INTO rec FROM _k_extkotr_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO k_extkotr (db_einfuegemarke, key_extkotr, text_extkotr, kategorie, fins_stugfach) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.key_extkotr),'NULL') || ' , ' || COALESCE(quote_literal(rec.text_extkotr),'NULL') || ' , ' || COALESCE(quote_literal(rec.kategorie),'NULL') || ' , ' || COALESCE(quote_literal(rec.fins_stugfach),'NULL') || ')'; ret_dblink = dblink_exec(gc('superx_cob_90_ap'), sql); DELETE FROM _k_extkotr_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


--
-- Name: k_extkotr_upd(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.k_extkotr_upd(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(key_extkotr) INTO anz FROM _k_extkotr_buffer WHERE key_extkotr= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _k_extkotr_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _k_extkotr_buffer WHERE key_extkotr= id1 ; If FOUND then sql = 'UPDATE k_extkotr SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , key_extkotr= ' || COALESCE(quote_literal(rec.key_extkotr),'NULL') || ' , text_extkotr= ' || COALESCE(quote_literal(rec.text_extkotr),'NULL') || ' , kategorie= ' || COALESCE(quote_literal(rec.kategorie),'NULL') || ' , fins_stugfach= ' || COALESCE(quote_literal(rec.fins_stugfach),'NULL') || ' WHERE key_extkotr=' || quote_literal(rec.key_extkotr); ret_dblink = dblink_exec(gc('superx_cob_90_ap'), sql); DELETE FROM _k_extkotr_buffer WHERE key_extkotr= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


