    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
IF EXISTS(SELECT * FROM sva4.inst_to_ext inst_to_ext WHERE old_row.key_extkotr = inst_to_ext.key_extkotr) THEN
