--
-- Name: k_finanzamt_del(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.k_finanzamt_del(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE sql text; id1 ALIAS FOR $1;  BEGIN sql = 'DELETE FROM k_finanzamt WHERE key_finanzamt= ' || quote_literal(id1); return dblink_exec(gc('superx_fsv_90_ap'), sql); END;$_$;


--
-- Name: k_finanzamt_ins(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.k_finanzamt_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _k_finanzamt_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _k_finanzamtinst_buffer!'; end if; SELECT * INTO rec FROM _k_finanzamt_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO k_finanzamt (db_einfuegemarke, key_finanzamt, ueberkey, name_finanzamt, str_finanzamt, plz_finanzamt, ort_finanzamt, key_von, key_bis) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.key_finanzamt),'NULL') || ' , ' || COALESCE(quote_literal(rec.ueberkey),'NULL') || ' , ' || COALESCE(quote_literal(rec.name_finanzamt),'NULL') || ' , ' || COALESCE(quote_literal(rec.str_finanzamt),'NULL') || ' , ' || COALESCE(quote_literal(rec.plz_finanzamt),'NULL') || ' , ' || COALESCE(quote_literal(rec.ort_finanzamt),'NULL') || ' , ' || COALESCE(quote_literal(rec.key_von),'NULL') || ' , ' || COALESCE(quote_literal(rec.key_bis),'NULL') || ')'; ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _k_finanzamt_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


--
-- Name: k_finanzamt_upd(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.k_finanzamt_upd(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(key_finanzamt) INTO anz FROM _k_finanzamt_buffer WHERE key_finanzamt= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _k_finanzamt_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _k_finanzamt_buffer WHERE key_finanzamt= id1 ; If FOUND then sql = 'UPDATE k_finanzamt SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , key_finanzamt= ' || COALESCE(quote_literal(rec.key_finanzamt),'NULL') || ' , ueberkey= ' || COALESCE(quote_literal(rec.ueberkey),'NULL') || ' , name_finanzamt= ' || COALESCE(quote_literal(rec.name_finanzamt),'NULL') || ' , str_finanzamt= ' || COALESCE(quote_literal(rec.str_finanzamt),'NULL') || ' , plz_finanzamt= ' || COALESCE(quote_literal(rec.plz_finanzamt),'NULL') || ' , ort_finanzamt= ' || COALESCE(quote_literal(rec.ort_finanzamt),'NULL') || ' , key_von= ' || COALESCE(quote_literal(rec.key_von),'NULL') || ' , key_bis= ' || COALESCE(quote_literal(rec.key_bis),'NULL') || ' WHERE key_finanzamt=' || quote_literal(rec.key_finanzamt); ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _k_finanzamt_buffer WHERE key_finanzamt= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


