CREATE FUNCTION sva4.k_hochschule_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _k_hochschule_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _k_hochschuleinst_buffer!'; end if; SELECT * INTO rec FROM _k_hochschule_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO k_hochschule (db_einfuegemarke, key_hochschule, ueberkey, kurz_hochschule, druck_hochschule, text_hochschule, bund_hochschule, key_von, key_bis, habil_recht, land_hochschule) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.key_hochschule),'NULL') || ' , ' || COALESCE(quote_literal(rec.ueberkey),'NULL') || ' , ' || COALESCE(quote_literal(rec.kurz_hochschule),'NULL') || ' , ' || COALESCE(quote_literal(rec.druck_hochschule),'NULL') || ' , ' || COALESCE(quote_literal(rec.text_hochschule),'NULL') || ' , ' || COALESCE(quote_literal(rec.bund_hochschule),'NULL') || ' , ' || COALESCE(quote_literal(rec.key_von),'NULL') || ' , ' || COALESCE(quote_literal(rec.key_bis),'NULL') || ' , ' || COALESCE(quote_literal(rec.habil_recht),'NULL') || ' , ' || COALESCE(quote_literal(rec.land_hochschule),'NULL') || ')'; ret_dblink = dblink_exec(gc('superx_cob_90_ap'), sql); DELETE FROM _k_hochschule_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


