    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(key_hochschule) INTO anz FROM _k_hochschule_buffer WHERE key_hochschule= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _k_hochschule_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _k_hochschule_buffer WHERE key_hochschule= id1 ; If FOUND then sql = 'UPDATE k_hochschule SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , key_hochschule= ' || COALESCE(quote_literal(rec.key_hochschule),'NULL') || ' , ueberkey= ' || COALESCE(quote_literal(rec.ueberkey),'NULL') || ' , kurz_hochschule= ' || COALESCE(quote_literal(rec.kurz_hochschule),'NULL') || ' , druck_hochschule= ' || COALESCE(quote_literal(rec.druck_hochschule),'NULL') || ' , text_hochschule= ' || COALESCE(quote_literal(rec.text_hochschule),'NULL') || ' , bund_hochschule= ' || COALESCE(quote_literal(rec.bund_hochschule),'NULL') || ' , key_von= ' || COALESCE(quote_literal(rec.key_von),'NULL') || ' , key_bis= ' || COALESCE(quote_literal(rec.key_bis),'NULL') || ' , habil_recht= ' || COALESCE(quote_literal(rec.habil_recht),'NULL') || ' , land_hochschule= ' || COALESCE(quote_literal(rec.land_hochschule),'NULL') || ' WHERE key_hochschule=' || quote_literal(rec.key_hochschule); ret_dblink = dblink_exec(gc('superx_cob_90_ap'), sql); DELETE FROM _k_hochschule_buffer WHERE key_hochschule= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


