--
-- Name: k_plz_del(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.k_plz_del(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE sql text; id1 ALIAS FOR $1;  BEGIN sql = 'DELETE FROM k_plz WHERE plz= ' || quote_literal(id1); return dblink_exec(gc('superx_cob_90_ap'), sql); END;$_$;


--
-- Name: k_plz_ins(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.k_plz_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _k_plz_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _k_plzinst_buffer!'; end if; SELECT * INTO rec FROM _k_plz_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO k_plz (db_einfuegemarke, plz, ueberkey, art, aikz, grokz, ort, krskfz, krs_astat, vv_bez) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.plz),'NULL') || ' , ' || COALESCE(quote_literal(rec.ueberkey),'NULL') || ' , ' || COALESCE(quote_literal(rec.art),'NULL') || ' , ' || COALESCE(quote_literal(rec.aikz),'NULL') || ' , ' || COALESCE(quote_literal(rec.grokz),'NULL') || ' , ' || COALESCE(quote_literal(rec.ort),'NULL') || ' , ' || COALESCE(quote_literal(rec.krskfz),'NULL') || ' , ' || COALESCE(quote_literal(rec.krs_astat),'NULL') || ' , ' || COALESCE(quote_literal(rec.vv_bez),'NULL') || ')'; ret_dblink = dblink_exec(gc('superx_cob_90_ap'), sql); DELETE FROM _k_plz_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


--
-- Name: k_plz_upd(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.k_plz_upd(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(plz) INTO anz FROM _k_plz_buffer WHERE plz= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _k_plz_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _k_plz_buffer WHERE plz= id1 ; If FOUND then sql = 'UPDATE k_plz SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , plz= ' || COALESCE(quote_literal(rec.plz),'NULL') || ' , ueberkey= ' || COALESCE(quote_literal(rec.ueberkey),'NULL') || ' , art= ' || COALESCE(quote_literal(rec.art),'NULL') || ' , aikz= ' || COALESCE(quote_literal(rec.aikz),'NULL') || ' , grokz= ' || COALESCE(quote_literal(rec.grokz),'NULL') || ' , ort= ' || COALESCE(quote_literal(rec.ort),'NULL') || ' , krskfz= ' || COALESCE(quote_literal(rec.krskfz),'NULL') || ' , krs_astat= ' || COALESCE(quote_literal(rec.krs_astat),'NULL') || ' , vv_bez= ' || COALESCE(quote_literal(rec.vv_bez),'NULL') || ' WHERE plz=' || quote_literal(rec.plz); ret_dblink = dblink_exec(gc('superx_cob_90_ap'), sql); DELETE FROM _k_plz_buffer WHERE plz= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


