--
-- Name: k_referenz_del(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.k_referenz_del(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE sql text; id1 ALIAS FOR $1;  BEGIN sql = 'DELETE FROM k_referenz WHERE key_ref= ' || quote_literal(id1); return dblink_exec(gc('superx_fsv_90_ap'), sql); END;$_$;


--
-- Name: k_referenz_ins(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.k_referenz_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _k_referenz_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _k_referenzinst_buffer!'; end if; SELECT * INTO rec FROM _k_referenz_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO k_referenz (db_einfuegemarke, key_ref, kurz_ref, druck_ref, text_ref, key_von, key_bis) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.key_ref),'NULL') || ' , ' || COALESCE(quote_literal(rec.kurz_ref),'NULL') || ' , ' || COALESCE(quote_literal(rec.druck_ref),'NULL') || ' , ' || COALESCE(quote_literal(rec.text_ref),'NULL') || ' , ' || COALESCE(quote_literal(rec.key_von),'NULL') || ' , ' || COALESCE(quote_literal(rec.key_bis),'NULL') || ')'; ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _k_referenz_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


