--
-- Name: k_referenz_upd(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.k_referenz_upd(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(key_ref) INTO anz FROM _k_referenz_buffer WHERE key_ref= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _k_referenz_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _k_referenz_buffer WHERE key_ref= id1 ; If FOUND then sql = 'UPDATE k_referenz SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , key_ref= ' || COALESCE(quote_literal(rec.key_ref),'NULL') || ' , kurz_ref= ' || COALESCE(quote_literal(rec.kurz_ref),'NULL') || ' , druck_ref= ' || COALESCE(quote_literal(rec.druck_ref),'NULL') || ' , text_ref= ' || COALESCE(quote_literal(rec.text_ref),'NULL') || ' , key_von= ' || COALESCE(quote_literal(rec.key_von),'NULL') || ' , key_bis= ' || COALESCE(quote_literal(rec.key_bis),'NULL') || ' WHERE key_ref=' || quote_literal(rec.key_ref); ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _k_referenz_buffer WHERE key_ref= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


