    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
IF EXISTS(SELECT * FROM sva4.ansc ansc WHERE old_row.key_staat = ansc.ansc_land) THEN
