--
-- Name: k_urlaubsgruppe_del(character varying, smallint); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.k_urlaubsgruppe_del(character varying, smallint) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE sql text; id1 ALIAS FOR $1;  id2 ALIAS FOR $2;  BEGIN sql = 'DELETE FROM k_urlaubsgruppe WHERE key_urlaubsgrp= ' || quote_literal(id1) ||' AND lebensalter= ' || quote_literal(id2); return dblink_exec(gc('superx_cob_90_ap'), sql); END;$_$;


--
-- Name: k_urlaubsgruppe_ins(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.k_urlaubsgruppe_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _k_urlaubsgruppe_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _k_urlaubsgruppeinst_buffer!'; end if; SELECT * INTO rec FROM _k_urlaubsgruppe_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO k_urlaubsgruppe (db_einfuegemarke, key_urlaubsgrp, ueberkey, lebensalter, kurz_urlaubsgrp, druck_urlaubsgrp, text_urlaubsgrp, anz_urlaub, mindest_urlaub, key_von, key_bis) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.key_urlaubsgrp),'NULL') || ' , ' || COALESCE(quote_literal(rec.ueberkey),'NULL') || ' , ' || COALESCE(quote_literal(rec.lebensalter),'NULL') || ' , ' || COALESCE(quote_literal(rec.kurz_urlaubsgrp),'NULL') || ' , ' || COALESCE(quote_literal(rec.druck_urlaubsgrp),'NULL') || ' , ' || COALESCE(quote_literal(rec.text_urlaubsgrp),'NULL') || ' , ' || COALESCE(quote_literal(rec.anz_urlaub),'NULL') || ' , ' || COALESCE(quote_literal(rec.mindest_urlaub),'NULL') || ' , ' || COALESCE(quote_literal(rec.key_von),'NULL') || ' , ' || COALESCE(quote_literal(rec.key_bis),'NULL') || ')'; ret_dblink = dblink_exec(gc('superx_cob_90_ap'), sql); DELETE FROM _k_urlaubsgruppe_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


--
-- Name: k_urlaubsgruppe_upd(character varying, smallint); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.k_urlaubsgruppe_upd(character varying, smallint) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1;  id2 ALIAS FOR $2; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(key_urlaubsgrp) INTO anz FROM _k_urlaubsgruppe_buffer WHERE key_urlaubsgrp= id1  AND lebensalter= id2; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _k_urlaubsgruppe_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _k_urlaubsgruppe_buffer WHERE key_urlaubsgrp= id1  AND lebensalter= id2; If FOUND then sql = 'UPDATE k_urlaubsgruppe SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , key_urlaubsgrp= ' || COALESCE(quote_literal(rec.key_urlaubsgrp),'NULL') || ' , ueberkey= ' || COALESCE(quote_literal(rec.ueberkey),'NULL') || ' , lebensalter= ' || COALESCE(quote_literal(rec.lebensalter),'NULL') || ' , kurz_urlaubsgrp= ' || COALESCE(quote_literal(rec.kurz_urlaubsgrp),'NULL') || ' , druck_urlaubsgrp= ' || COALESCE(quote_literal(rec.druck_urlaubsgrp),'NULL') || ' , text_urlaubsgrp= ' || COALESCE(quote_literal(rec.text_urlaubsgrp),'NULL') || ' , anz_urlaub= ' || COALESCE(quote_literal(rec.anz_urlaub),'NULL') || ' , mindest_urlaub= ' || COALESCE(quote_literal(rec.mindest_urlaub),'NULL') || ' , key_von= ' || COALESCE(quote_literal(rec.key_von),'NULL') || ' , key_bis= ' || COALESCE(quote_literal(rec.key_bis),'NULL') || ' WHERE key_urlaubsgrp=' || quote_literal(rec.key_urlaubsgrp) || ' AND lebensalter=' || quote_literal(rec.lebensalter) ; ret_dblink = dblink_exec(gc('superx_cob_90_ap'), sql); DELETE FROM _k_urlaubsgruppe_buffer WHERE key_urlaubsgrp= id1  AND lebensalter= id2; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


