--
-- Name: k_verwzweck_del(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.k_verwzweck_del(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE sql text; id1 ALIAS FOR $1;  BEGIN sql = 'DELETE FROM k_verwzweck WHERE key_verwzweck= ' || quote_literal(id1); return dblink_exec(gc('superx_fsv_90_ap'), sql); END;$_$;


--
-- Name: k_verwzweck_ins(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.k_verwzweck_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _k_verwzweck_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _k_verwzweckinst_buffer!'; end if; SELECT * INTO rec FROM _k_verwzweck_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO k_verwzweck (db_einfuegemarke, key_verwzweck, text1, text2) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.key_verwzweck),'NULL') || ' , ' || COALESCE(quote_literal(rec.text1),'NULL') || ' , ' || COALESCE(quote_literal(rec.text2),'NULL') || ')'; ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _k_verwzweck_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


--
-- Name: k_verwzweck_upd(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.k_verwzweck_upd(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(key_verwzweck) INTO anz FROM _k_verwzweck_buffer WHERE key_verwzweck= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _k_verwzweck_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _k_verwzweck_buffer WHERE key_verwzweck= id1 ; If FOUND then sql = 'UPDATE k_verwzweck SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , key_verwzweck= ' || COALESCE(quote_literal(rec.key_verwzweck),'NULL') || ' , text1= ' || COALESCE(quote_literal(rec.text1),'NULL') || ' , text2= ' || COALESCE(quote_literal(rec.text2),'NULL') || ' WHERE key_verwzweck=' || quote_literal(rec.key_verwzweck); ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _k_verwzweck_buffer WHERE key_verwzweck= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


