    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _kap_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _kapinst_buffer!'; end if; SELECT * INTO rec FROM _kap_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO kap (db_einfuegemarke, jahr, kap, kapbez, kz_ueber, art, astnr, kz_vhhf, lkapbez, vwg, hkz, zahlweg_bay, ggnr) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.jahr),'NULL') || ' , ' || COALESCE(quote_literal(rec.kap),'NULL') || ' , ' || COALESCE(quote_literal(rec.kapbez),'NULL') || ' , ' || COALESCE(quote_literal(rec.kz_ueber),'NULL') || ' , ' || COALESCE(quote_literal(rec.art),'NULL') || ' , ' || COALESCE(quote_literal(rec.astnr),'NULL') || ' , ' || COALESCE(quote_literal(rec.kz_vhhf),'NULL') || ' , ' || COALESCE(quote_literal(rec.lkapbez),'NULL') || ' , ' || COALESCE(quote_literal(rec.vwg),'NULL') || ' , ' || COALESCE(quote_literal(rec.hkz),'NULL') || ' , ' || COALESCE(quote_literal(rec.zahlweg_bay),'NULL') || ' , ' || COALESCE(quote_literal(rec.ggnr),'NULL') || ')'; ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _kap_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


--
-- Name: kap_upd(integer); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.kap_upd(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(join_nr) INTO anz FROM _kap_buffer WHERE join_nr= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _kap_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _kap_buffer WHERE join_nr= id1 ; If FOUND then sql = 'UPDATE kap SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , jahr= ' || COALESCE(quote_literal(rec.jahr),'NULL') || ' , kap= ' || COALESCE(quote_literal(rec.kap),'NULL') || ' , kapbez= ' || COALESCE(quote_literal(rec.kapbez),'NULL') || ' , kz_ueber= ' || COALESCE(quote_literal(rec.kz_ueber),'NULL') || ' , art= ' || COALESCE(quote_literal(rec.art),'NULL') || ' , astnr= ' || COALESCE(quote_literal(rec.astnr),'NULL') || ' , kz_vhhf= ' || COALESCE(quote_literal(rec.kz_vhhf),'NULL') || ' , lkapbez= ' || COALESCE(quote_literal(rec.lkapbez),'NULL') || ' , vwg= ' || COALESCE(quote_literal(rec.vwg),'NULL') || ' , hkz= ' || COALESCE(quote_literal(rec.hkz),'NULL') || ' , zahlweg_bay= ' || COALESCE(quote_literal(rec.zahlweg_bay),'NULL') || ' , ggnr= ' || COALESCE(quote_literal(rec.ggnr),'NULL') || ' WHERE join_nr=' || quote_literal(rec.join_nr); ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _kap_buffer WHERE join_nr= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


