CREATE FUNCTION sva4.kollisions_pruefung() RETURNS boolean
    LANGUAGE plpgsql
    AS $$         DECLARE         count_double INTEGER;    meldung text;   BEGIN    SELECT count(*) FROM fikr WHERE REPLACE ( key, 'Z', '' ) IN ( SELECT key FROM fikr ) AND key LIKE '%Z' INTO count_double;    IF count_double <> 0 THEN     meldung := E'Wegen Kollision mit den Kostenarten behalten die Ausgabearten ein Z am Ende!!! Ueberpruefen Sie erneut mit FSV_fikr_umsetz_nach_2.sql Ihre Datenbank!';     RAISE EXCEPTION '%', meldung;     RETURN false;    END IF;    RETURN true;   END;   $$;


