--
-- Name: kto_angaben_aus_mbs(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.kto_angaben_aus_mbs(hhjahr character varying DEFAULT (date_part('year'::text, CURRENT_DATE))::character varying(4)) RETURNS void
    LANGUAGE plpgsql
    AS $$

DECLARE
	p_haushaltsjahr VARCHAR(4);	
	p_hochschule NCHAR(4);

	BEGIN
    SET search_path TO sva4;
		
		p_haushaltsjahr := hhjahr;
		p_hochschule := (SELECT key_hochschule FROM sv_hochschule WHERE key_hochschule IS NOT NULL);

	--tabelle k_kapitel		k_kapitel
	-----------------------------------------
	create temp table t_mehrfach_kap
	(
		join_nr	serial,
		key5		char(5),
		keybez	char(30)
	);
	create temp table t_distinct_kap
	(
		key5		char(5),
		keybez	char(30)
	);

	--die gewünschten Felder werden aus Kontentabelle kap übernommen
	--als Ergebnis können noch doppelte Schluesselwerte vorhanden sein
	insert into t_mehrfach_kap (key5,keybez)
	SELECT DISTINCT kap, kapbez
	FROM kap
	where jahr>=p_haushaltsjahr;

	--wegen insert into t_distinct_kap notwendig
	create temp table tt_mehrfach_kap
	(
		join_nr	serial,
		key5		char(5),
		keybez	char(30)
	);
	insert into tt_mehrfach_kap	(join_nr,key5,keybez)
	select join_nr,key5,keybez
	from t_mehrfach_kap;

	--wegen insert-Befehl notwendig
	create temp table t_k_kapitel
	(
		key_kapitel		char(5),
		druck_kapitel	char(30),
