--
-- Name: ktoj_del(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.ktoj_del(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE sql text; id1 ALIAS FOR $1;  BEGIN sql = 'DELETE FROM ktoj WHERE aost= ' || quote_literal(id1); return dblink_exec(gc('superx_fsv_90_ap'), sql); END;$_$;


--
-- Name: ktoj_ins(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.ktoj_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _ktoj_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _ktojinst_buffer!'; end if; SELECT * INTO rec FROM _ktoj_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO ktoj (db_einfuegemarke, jahr, monat, aost, kap, tit, titzus, betrag, ks_dat, dname) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.jahr),'NULL') || ' , ' || COALESCE(quote_literal(rec.monat),'NULL') || ' , ' || COALESCE(quote_literal(rec.aost),'NULL') || ' , ' || COALESCE(quote_literal(rec.kap),'NULL') || ' , ' || COALESCE(quote_literal(rec.tit),'NULL') || ' , ' || COALESCE(quote_literal(rec.titzus),'NULL') || ' , ' || COALESCE(quote_literal(rec.betrag),'NULL') || ' , ' || COALESCE(quote_literal(rec.ks_dat),'NULL') || ' , ' || COALESCE(quote_literal(rec.dname),'NULL') || ')'; ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _ktoj_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


--
-- Name: ktoj_upd(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.ktoj_upd(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(aost) INTO anz FROM _ktoj_buffer WHERE aost= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _ktoj_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _ktoj_buffer WHERE aost= id1 ; If FOUND then sql = 'UPDATE ktoj SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , jahr= ' || COALESCE(quote_literal(rec.jahr),'NULL') || ' , monat= ' || COALESCE(quote_literal(rec.monat),'NULL') || ' , aost= ' || COALESCE(quote_literal(rec.aost),'NULL') || ' , kap= ' || COALESCE(quote_literal(rec.kap),'NULL') || ' , tit= ' || COALESCE(quote_literal(rec.tit),'NULL') || ' , titzus= ' || COALESCE(quote_literal(rec.titzus),'NULL') || ' , betrag= ' || COALESCE(quote_literal(rec.betrag),'NULL') || ' , ks_dat= ' || COALESCE(quote_literal(rec.ks_dat),'NULL') || ' , dname= ' || COALESCE(quote_literal(rec.dname),'NULL') || ' WHERE aost=' || quote_literal(rec.aost); ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _ktoj_buffer WHERE aost= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


--
-- Name: ktojdb(); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.ktojdb() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
BEGIN
 PERFORM sva4.ktojdi(OLD);
 RETURN OLD; END; $$;


--
-- Name: __ktoj; Type: TABLE; Schema: sva4; Owner: -
--

CREATE TABLE sva4.__ktoj (
    db_einfuegemarke character varying(6),
    jahr character varying(4) NOT NULL,
    monat character varying(2) NOT NULL,
    aost character varying(10),
    kap character varying(5) NOT NULL,
    tit character varying(10) NOT NULL,
    titzus character varying(1),
    betrag numeric(14,2) NOT NULL,
    ks_dat date,
    dname character varying(250),
    join_nr integer NOT NULL,
    aostunr_ihv character varying(7),
    apl_ihv character varying(1)
);


--
-- Name: ktojdi(sva4.__ktoj); Type: FUNCTION; Schema: sva4; Owner: -
