--
-- Name: kurs_ins(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.kurs_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _kurs_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _kursinst_buffer!'; end if; SELECT * INTO rec FROM _kurs_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO kurs (db_einfuegemarke, wbezk, wbezl, kurs, gebuehre, sblae, datlae, u_grenze, o_grenze) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.wbezk),'NULL') || ' , ' || COALESCE(quote_literal(rec.wbezl),'NULL') || ' , ' || COALESCE(quote_literal(rec.kurs),'NULL') || ' , ' || COALESCE(quote_literal(rec.gebuehre),'NULL') || ' , ' || COALESCE(quote_literal(rec.sblae),'NULL') || ' , ' || COALESCE(quote_literal(rec.datlae),'NULL') || ' , ' || COALESCE(quote_literal(rec.u_grenze),'NULL') || ' , ' || COALESCE(quote_literal(rec.o_grenze),'NULL') || ')'; ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _kurs_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


