    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(wbezk) INTO anz FROM _kurs_buffer WHERE wbezk= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _kurs_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _kurs_buffer WHERE wbezk= id1 ; If FOUND then sql = 'UPDATE kurs SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , wbezk= ' || COALESCE(quote_literal(rec.wbezk),'NULL') || ' , wbezl= ' || COALESCE(quote_literal(rec.wbezl),'NULL') || ' , kurs= ' || COALESCE(quote_literal(rec.kurs),'NULL') || ' , gebuehre= ' || COALESCE(quote_literal(rec.gebuehre),'NULL') || ' , sblae= ' || COALESCE(quote_literal(rec.sblae),'NULL') || ' , datlae= ' || COALESCE(quote_literal(rec.datlae),'NULL') || ' , u_grenze= ' || COALESCE(quote_literal(rec.u_grenze),'NULL') || ' , o_grenze= ' || COALESCE(quote_literal(rec.o_grenze),'NULL') || ' WHERE wbezk=' || quote_literal(rec.wbezk); ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _kurs_buffer WHERE wbezk= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


