    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _mbs_import_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _mbs_importinst_buffer!'; end if; SELECT * INTO rec FROM _mbs_import_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO mbs_import (laenge, satzart, quelle, ziel, dname, satz_nr, prot1, prot2, buchart, dienst, jahr, kap, tgr, tit, ut, fb, ins, koa_nr, pknr, huel, u_nr, ref_h, ref_u, a_nr, kassanz, bkz, betrag, dm_kz, grund1, grund2, faell, r_nr, r_dat, z_nr, z_anrede, z_name, z_plz, z_ort, z_str, blz, konto, ge_kz, aufl_kz, ao_kz, ue_kz, zahlweg, zahlschl, mahnschl, zins, feststel, kunden_nr, ggnr, aw, mw_kz, mw_betrag, fw_kz, kurs, gebuehr, ue_nr, b_dat, reserve, db_einfuegemarke, ins2, ins3, kst_nr, ktr_nr, kperanf, kperend, buchungsschluessel, aw2, rmkasse_join_nr, mw_art, pfi_serial, grund3, grund4, grund5, grund6, grund7) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.satzart),'NULL') || ' , ' || COALESCE(quote_literal(rec.quelle),'NULL') || ' , ' || COALESCE(quote_literal(rec.ziel),'NULL') || ' , ' || COALESCE(quote_literal(rec.dname),'NULL') || ' , ' || COALESCE(quote_literal(rec.satz_nr),'NULL') || ' , ' || COALESCE(quote_literal(rec.prot1),'NULL') || ' , ' || COALESCE(quote_literal(rec.prot2),'NULL') || ' , ' || COALESCE(quote_literal(rec.buchart),'NULL') || ' , ' || COALESCE(quote_literal(rec.dienst),'NULL') || ' , ' || COALESCE(quote_literal(rec.jahr),'NULL') || ' , ' || COALESCE(quote_literal(rec.kap),'NULL') || ' , ' || COALESCE(quote_literal(rec.tgr),'NULL') || ' , ' || COALESCE(quote_literal(rec.tit),'NULL') || ' , ' || COALESCE(quote_literal(rec.ut),'NULL') || ' , ' || COALESCE(quote_literal(rec.fb),'NULL') || ' , ' || COALESCE(quote_literal(rec.ins),'NULL') || ' , ' || COALESCE(quote_literal(rec.koa_nr),'NULL') || ' , ' || COALESCE(quote_literal(rec.pknr),'NULL') || ' , ' || COALESCE(quote_literal(rec.huel),'NULL') || ' , ' || COALESCE(quote_literal(rec.u_nr),'NULL') || ' , ' || COALESCE(quote_literal(rec.ref_h),'NULL') || ' , ' || COALESCE(quote_literal(rec.ref_u),'NULL') || ' , ' || COALESCE(quote_literal(rec.a_nr),'NULL') || ' , ' || COALESCE(quote_literal(rec.kassanz),'NULL') || ' , ' || COALESCE(quote_literal(rec.bkz),'NULL') || ' , ' || COALESCE(quote_literal(rec.betrag),'NULL') || ' , ' || COALESCE(quote_literal(rec.dm_kz),'NULL') || ' , ' || COALESCE(quote_literal(rec.grund1),'NULL') || ' , ' || COALESCE(quote_literal(rec.grund2),'NULL') || ' , ' || COALESCE(quote_literal(rec.faell),'NULL') || ' , ' || COALESCE(quote_literal(rec.r_nr),'NULL') || ' , ' || COALESCE(quote_literal(rec.r_dat),'NULL') || ' , ' || COALESCE(quote_literal(rec.z_nr),'NULL') || ' , ' || COALESCE(quote_literal(rec.z_anrede),'NULL') || ' , ' || COALESCE(quote_literal(rec.z_name),'NULL') || ' , ' || COALESCE(quote_literal(rec.z_plz),'NULL') || ' , ' || COALESCE(quote_literal(rec.z_ort),'NULL') || ' , ' || COALESCE(quote_literal(rec.z_str),'NULL') || ' , ' || COALESCE(quote_literal(rec.blz),'NULL') || ' , ' || COALESCE(quote_literal(rec.konto),'NULL') || ' , ' || COALESCE(quote_literal(rec.ge_kz),'NULL') || ' , ' || COALESCE(quote_literal(rec.aufl_kz),'NULL') || ' , ' || COALESCE(quote_literal(rec.ao_kz),'NULL') || ' , ' || COALESCE(quote_literal(rec.ue_kz),'NULL') || ' , ' || COALESCE(quote_literal(rec.zahlweg),'NULL') || ' , ' || COALESCE(quote_literal(rec.zahlschl),'NULL') || ' , ' || COALESCE(quote_literal(rec.mahnschl),'NULL') || ' , ' || COALESCE(quote_literal(rec.zins),'NULL') || ' , ' || COALESCE(quote_literal(rec.feststel),'NULL') || ' , ' || COALESCE(quote_literal(rec.kunden_nr),'NULL') || ' , ' || COALESCE(quote_literal(rec.ggnr),'NULL') || ' , ' || COALESCE(quote_literal(rec.aw),'NULL') || ' , ' || COALESCE(quote_literal(rec.mw_kz),'NULL') || ' , ' || COALESCE(quote_literal(rec.mw_betrag),'NULL') || ' , ' || COALESCE(quote_literal(rec.fw_kz),'NULL') || ' , ' || COALESCE(quote_literal(rec.kurs),'NULL') || ' , ' || COALESCE(quote_literal(rec.gebuehr),'NULL') || ' , ' || COALESCE(quote_literal(rec.ue_nr),'NULL') || ' , ' || COALESCE(quote_literal(rec.b_dat),'NULL') || ' , ' || COALESCE(quote_literal(rec.reserve),'NULL') || ' , ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , ' || COALESCE(quote_literal(rec.ins2),'NULL') || ' , ' || COALESCE(quote_literal(rec.ins3),'NULL') || ' , ' || COALESCE(quote_literal(rec.kst_nr),'NULL') || ' , ' || COALESCE(quote_literal(rec.ktr_nr),'NULL') || ' , ' || COALESCE(quote_literal(rec.kperanf),'NULL') || ' , ' || COALESCE(quote_literal(rec.kperend),'NULL') || ' , ' || COALESCE(quote_literal(rec.buchungsschluessel),'NULL') || ' , ' || COALESCE(quote_literal(rec.aw2),'NULL') || ' , ' || COALESCE(quote_literal(rec.rmkasse_join_nr),'NULL') || ' , ' || COALESCE(quote_literal(rec.mw_art),'NULL') || ' , ' || COALESCE(quote_literal(rec.pfi_serial),'NULL') || ' , ' || COALESCE(quote_literal(rec.grund3),'NULL') || ' , ' || COALESCE(quote_literal(rec.grund4),'NULL') || ' , ' || COALESCE(quote_literal(rec.grund5),'NULL') || ' , ' || COALESCE(quote_literal(rec.grund6),'NULL') || ' , ' || COALESCE(quote_literal(rec.grund7),'NULL') || ')'; ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _mbs_import_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


