te_literal(rec.betrag),'NULL') || ' , dm_kz= ' || COALESCE(quote_literal(rec.dm_kz),'NULL') || ' , grund1= ' || COALESCE(quote_literal(rec.grund1),'NULL') || ' , grund2= ' || COALESCE(quote_literal(rec.grund2),'NULL') || ' , faell= ' || COALESCE(quote_literal(rec.faell),'NULL') || ' , r_nr= ' || COALESCE(quote_literal(rec.r_nr),'NULL') || ' , r_dat= ' || COALESCE(quote_literal(rec.r_dat),'NULL') || ' , z_nr= ' || COALESCE(quote_literal(rec.z_nr),'NULL') || ' , z_anrede= ' || COALESCE(quote_literal(rec.z_anrede),'NULL') || ' , z_name= ' || COALESCE(quote_literal(rec.z_name),'NULL') || ' , z_plz= ' || COALESCE(quote_literal(rec.z_plz),'NULL') || ' , z_ort= ' || COALESCE(quote_literal(rec.z_ort),'NULL') || ' , z_str= ' || COALESCE(quote_literal(rec.z_str),'NULL') || ' , blz= ' || COALESCE(quote_literal(rec.blz),'NULL') || ' , konto= ' || COALESCE(quote_literal(rec.konto),'NULL') || ' , ge_kz= ' || COALESCE(quote_literal(rec.ge_kz),'NULL') || ' , aufl_kz= ' || COALESCE(quote_literal(rec.aufl_kz),'NULL') || ' , ao_kz= ' || COALESCE(quote_literal(rec.ao_kz),'NULL') || ' , ue_kz= ' || COALESCE(quote_literal(rec.ue_kz),'NULL') || ' , zahlweg= ' || COALESCE(quote_literal(rec.zahlweg),'NULL') || ' , zahlschl= ' || COALESCE(quote_literal(rec.zahlschl),'NULL') || ' , mahnschl= ' || COALESCE(quote_literal(rec.mahnschl),'NULL') || ' , zins= ' || COALESCE(quote_literal(rec.zins),'NULL') || ' , feststel= ' || COALESCE(quote_literal(rec.feststel),'NULL') || ' , kunden_nr= ' || COALESCE(quote_literal(rec.kunden_nr),'NULL') || ' , ggnr= ' || COALESCE(quote_literal(rec.ggnr),'NULL') || ' , aw= ' || COALESCE(quote_literal(rec.aw),'NULL') || ' , mw_kz= ' || COALESCE(quote_literal(rec.mw_kz),'NULL') || ' , mw_betrag= ' || COALESCE(quote_literal(rec.mw_betrag),'NULL') || ' , fw_kz= ' || COALESCE(quote_literal(rec.fw_kz),'NULL') || ' , kurs= ' || COALESCE(quote_literal(rec.kurs),'NULL') || ' , gebuehr= ' || COALESCE(quote_literal(rec.gebuehr),'NULL') || ' , ue_nr= ' || COALESCE(quote_literal(rec.ue_nr),'NULL') || ' , b_dat= ' || COALESCE(quote_literal(rec.b_dat),'NULL') || ' , reserve= ' || COALESCE(quote_literal(rec.reserve),'NULL') || ' , db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , ins2= ' || COALESCE(quote_literal(rec.ins2),'NULL') || ' , ins3= ' || COALESCE(quote_literal(rec.ins3),'NULL') || ' , kst_nr= ' || COALESCE(quote_literal(rec.kst_nr),'NULL') || ' , ktr_nr= ' || COALESCE(quote_literal(rec.ktr_nr),'NULL') || ' , kperanf= ' || COALESCE(quote_literal(rec.kperanf),'NULL') || ' , kperend= ' || COALESCE(quote_literal(rec.kperend),'NULL') || ' , buchungsschluessel= ' || COALESCE(quote_literal(rec.buchungsschluessel),'NULL') || ' , aw2= ' || COALESCE(quote_literal(rec.aw2),'NULL') || ' , rmkasse_join_nr= ' || COALESCE(quote_literal(rec.rmkasse_join_nr),'NULL') || ' , mw_art= ' || COALESCE(quote_literal(rec.mw_art),'NULL') || ' , pfi_serial= ' || COALESCE(quote_literal(rec.pfi_serial),'NULL') || ' , grund3= ' || COALESCE(quote_literal(rec.grund3),'NULL') || ' , grund4= ' || COALESCE(quote_literal(rec.grund4),'NULL') || ' , grund5= ' || COALESCE(quote_literal(rec.grund5),'NULL') || ' , grund6= ' || COALESCE(quote_literal(rec.grund6),'NULL') || ' , grund7= ' || COALESCE(quote_literal(rec.grund7),'NULL') || ' WHERE join_nr=' || quote_literal(rec.join_nr); ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _mbs_import_buffer WHERE join_nr= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


--
