--

CREATE FUNCTION sva4.mbs_importdb() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
BEGIN
 PERFORM sva4.mbs_importdi(OLD);
 RETURN OLD; END; $$;


