CREATE FUNCTION sva4.mbs_prot_datei_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _mbs_prot_datei_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _mbs_prot_dateiinst_buffer!'; end if; SELECT * INTO rec FROM _mbs_prot_datei_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO mbs_prot_datei (db_einfuegemarke, dateibezeichner, liefersystem, dienststelle, zielbereich, beendet, quellversion, dateibez_intern) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.dateibezeichner),'NULL') || ' , ' || COALESCE(quote_literal(rec.liefersystem),'NULL') || ' , ' || COALESCE(quote_literal(rec.dienststelle),'NULL') || ' , ' || COALESCE(quote_literal(rec.zielbereich),'NULL') || ' , ' || COALESCE(quote_literal(rec.beendet),'NULL') || ' , ' || COALESCE(quote_literal(rec.quellversion),'NULL') || ' , ' || COALESCE(quote_literal(rec.dateibez_intern),'NULL') || ')'; ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _mbs_prot_datei_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


