--
-- Name: mwst_betraege_del(integer); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.mwst_betraege_del(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE sql text; id1 ALIAS FOR $1;  BEGIN sql = 'DELETE FROM mwst_betraege WHERE join_nr= ' || quote_literal(id1); return dblink_exec(gc('superx_fsv_90_ap'), sql); END;$_$;


--
-- Name: mwst_betraege_ins(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.mwst_betraege_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _mwst_betraege_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _mwst_betraegeinst_buffer!'; end if; SELECT * INTO rec FROM _mwst_betraege_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO mwst_betraege (db_einfuegemarke, bga, mw_kz, mwbetrag_brutto, mwbetrag_steuer, mwbetrag_netto, huel_join_nr) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.bga),'NULL') || ' , ' || COALESCE(quote_literal(rec.mw_kz),'NULL') || ' , ' || COALESCE(quote_literal(rec.mwbetrag_brutto),'NULL') || ' , ' || COALESCE(quote_literal(rec.mwbetrag_steuer),'NULL') || ' , ' || COALESCE(quote_literal(rec.mwbetrag_netto),'NULL') || ' , ' || COALESCE(quote_literal(rec.huel_join_nr),'NULL') || ')'; ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _mwst_betraege_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


--
-- Name: mwst_betraege_upd(integer); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.mwst_betraege_upd(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(join_nr) INTO anz FROM _mwst_betraege_buffer WHERE join_nr= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _mwst_betraege_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _mwst_betraege_buffer WHERE join_nr= id1 ; If FOUND then sql = 'UPDATE mwst_betraege SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , bga= ' || COALESCE(quote_literal(rec.bga),'NULL') || ' , mw_kz= ' || COALESCE(quote_literal(rec.mw_kz),'NULL') || ' , mwbetrag_brutto= ' || COALESCE(quote_literal(rec.mwbetrag_brutto),'NULL') || ' , mwbetrag_steuer= ' || COALESCE(quote_literal(rec.mwbetrag_steuer),'NULL') || ' , mwbetrag_netto= ' || COALESCE(quote_literal(rec.mwbetrag_netto),'NULL') || ' , huel_join_nr= ' || COALESCE(quote_literal(rec.huel_join_nr),'NULL') || ' WHERE join_nr=' || quote_literal(rec.join_nr); ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _mwst_betraege_buffer WHERE join_nr= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


