--
-- Name: pawdi(sva4.paw); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.pawdi(sva4.paw) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM sva4.au_statusmitteilungen au_statusmitteilungen WHERE old_row.paw_serial = au_statusmitteilungen.paw_join_id;
DELETE FROM sva4.pak pak WHERE old_row.paw_serial = pak.pak_ab_paw_serial;
DELETE FROM sva4.pak pak WHERE old_row.paw_serial = pak.pak_zu_paw_serial;
DELETE FROM sva4.ura ura WHERE old_row.paw_serial = ura.ura_paw_serial;
 RETURN old_row; END; $_$;


