--
-- Name: pbvdi(sva4.pbv); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.pbvdi(sva4.pbv) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM sva4.bw_lbv bw_lbv WHERE old_row.pbv_pgd_join_id = bw_lbv.bw_lbv_pgd_join_id AND old_row.pbv_nr = bw_lbv.bw_lbv_pbv_nr;
DELETE FROM sva4.bw_lbv_base bw_lbv_base WHERE old_row.pbv_pgd_join_id = bw_lbv_base.lbv_pgd_join_id AND old_row.pbv_nr = bw_lbv_base.lbv_pbv_nr;
DELETE FROM sva4.gvp_to_pbv gvp_to_pbv WHERE old_row.pbv_serial = gvp_to_pbv.pbv_serial;
DELETE FROM sva4.hla hla WHERE old_row.pbv_pgd_join_id = hla.pgd_join_id AND old_row.pbv_nr = hla.pbv_nr;
DELETE FROM sva4.nrw_a01 nrw_a01 WHERE old_row.pbv_pgd_join_id = nrw_a01.a01_pgd_join_id AND old_row.pbv_nr = nrw_a01.a01_pbv_nr;
DELETE FROM sva4.nrw_a04 nrw_a04 WHERE old_row.pbv_pgd_join_id = nrw_a04.a04_pgd_join_id AND old_row.pbv_nr = nrw_a04.a04_pbv_nr;
DELETE FROM sva4.nrw_a15 nrw_a15 WHERE old_row.pbv_pgd_join_id = nrw_a15.a15_pgd_join_id AND old_row.pbv_nr = nrw_a15.a15_pbv_nr;
DELETE FROM sva4.nrw_a16 nrw_a16 WHERE old_row.pbv_pgd_join_id = nrw_a16.a16_pgd_join_id AND old_row.pbv_nr = nrw_a16.a16_pbv_nr;
DELETE FROM sva4.nrw_a19 nrw_a19 WHERE old_row.pbv_pgd_join_id = nrw_a19.a19_pgd_join_id AND old_row.pbv_nr = nrw_a19.a19_pbv_nr;
DELETE FROM sva4.nrw_a20 nrw_a20 WHERE old_row.pbv_pgd_join_id = nrw_a20.a20_pgd_join_id AND old_row.pbv_nr = nrw_a20.a20_pbv_nr;
DELETE FROM sva4.nrw_a21 nrw_a21 WHERE old_row.pbv_pgd_join_id = nrw_a21.a21_pgd_join_id AND old_row.pbv_nr = nrw_a21.a21_pbv_nr;
DELETE FROM sva4.nrw_a25 nrw_a25 WHERE old_row.pbv_pgd_join_id = nrw_a25.a25_pgd_join_id AND old_row.pbv_nr = nrw_a25.a25_pbv_nr;
DELETE FROM sva4.nrw_b22 nrw_b22 WHERE old_row.pbv_pgd_join_id = nrw_b22.b22_pgd_join_id AND old_row.pbv_nr = nrw_b22.b22_pbv_nr;
DELETE FROM sva4.out_lbv_nrw out_lbv_nrw WHERE old_row.pbv_pgd_join_id = out_lbv_nrw.pgd_join_id AND old_row.pbv_nr = out_lbv_nrw.pbv_nr;
DELETE FROM sva4.out_lbv_nrw_klar out_lbv_nrw_klar WHERE old_row.pbv_pgd_join_id = out_lbv_nrw_klar.pgd_join_id AND old_row.pbv_nr = out_lbv_nrw_klar.pbv_nr;
DELETE FROM sva4.paz paz WHERE old_row.pbv_pgd_join_id = paz.paz_pgd_join_id AND old_row.pbv_nr = paz.paz_pbv_nr;
DELETE FROM sva4.pbl pbl WHERE old_row.pbv_pgd_join_id = pbl.pbl_pgd_join_id AND old_row.pbv_nr = pbl.pbl_pbv_nr;
DELETE FROM sva4.pbu pbu WHERE old_row.pbv_pgd_join_id = pbu.pbu_pgd_join_id AND old_row.pbv_nr = pbu.pbu_pbv_nr;
DELETE FROM sva4.pbv_to_pbz pbv_to_pbz WHERE old_row.pbv_pgd_join_id = pbv_to_pbz.pgd_join_id AND old_row.pbv_nr = pbv_to_pbz.pbv_nr;
DELETE FROM sva4.pbz pbz WHERE old_row.pbv_pgd_join_id = pbz.pbz_pgd_join_id AND old_row.pbv_nr = pbz.pbz_pbv_nr;
DELETE FROM sva4.pdo pdo WHERE old_row.pbv_pgd_join_id = pdo.pdo_pgd_join_id AND old_row.pbv_nr = pdo.pdo_pbv_nr;
DELETE FROM sva4.pdp pdp WHERE old_row.pbv_pgd_join_id = pdp.pdp_pgd_join_id AND old_row.pbv_nr = pdp.pdp_pbv_nr;
DELETE FROM sva4.pfi pfi WHERE old_row.pbv_pgd_join_id = pfi.pfi_pgd_join_id AND old_row.pbv_nr = pfi.pfi_pbv_nr;
DELETE FROM sva4.pgp pgp WHERE old_row.pbv_pgd_join_id = pgp.pgp_pgd_join_id AND old_row.pbv_nr = pgp.pgp_pbv_nr;
DELETE FROM sva4.pko pko WHERE old_row.pbv_pgd_join_id = pko.pko_pgd_join_id AND old_row.pbv_nr = pko.pko_pbv_nr;
DELETE FROM sva4.plv plv WHERE old_row.pbv_pgd_join_id = plv.plv_pgd_join_id AND old_row.pbv_nr = plv.plv_pbv_nr;
IF EXISTS(SELECT * FROM sva4.proj_to_pbv proj_to_pbv WHERE old_row.pbv_pgd_join_id = proj_to_pbv.pbv_pgd_join_id AND old_row.pbv_nr = proj_to_pbv.pbv_nr) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "proj_to_pbv" verwendet!';
END IF;
DELETE FROM sva4.pus pus WHERE old_row.pbv_pgd_join_id = pus.pus_pgd_join_id AND old_row.pbv_nr = pus.pus_pbv_nr;
DELETE FROM sva4.pzu pzu WHERE old_row.pbv_pgd_join_id = pzu.pzu_pgd_join_id AND old_row.pbv_nr = pzu.pzu_pbv_nr;
 RETURN old_row; END; $_$;


