--
-- Name: pbwdi(sva4.pbw); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.pbwdi(sva4.pbw) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM sva4.kpt_to_pbw kpt_to_pbw WHERE old_row.pbw_join_id = kpt_to_pbw.pbw_join_id;
DELETE FROM sva4.pbw_bewertung pbw_bewertung WHERE old_row.pbw_join_id = pbw_bewertung.pbw_bewertung_pbw_join_id;
DELETE FROM sva4.pbw_kommentar pbw_kommentar WHERE old_row.pbw_join_id = pbw_kommentar.pbw_kommentar_pbw_join_id;
DELETE FROM sva4.pbw_status pbw_status WHERE old_row.pbw_join_id = pbw_status.pbw_status_pbw_join_id;
DELETE FROM sva4.r_dokumente r_dokumente WHERE old_row.pbw_join_id = r_dokumente.pbw_join_id;
DELETE FROM sva4.wvl wvl WHERE old_row.pbw_join_id = wvl.wvl_pbw_join_id;
 RETURN old_row; END; $_$;


