--

CREATE FUNCTION sva4.pfidi(sva4.pfi) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM sva4.pfi_festlegung pfi_festlegung WHERE old_row.pfi_serial = pfi_festlegung.pfi_fest_pfi_ser;
 RETURN old_row; END; $_$;


