--
-- Name: pgd_db_sachbearbeiter_migration(); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.pgd_db_sachbearbeiter_migration() RETURNS void
    LANGUAGE plpgsql
    AS $$

DECLARE 
	p_pgd_join_id INT;
	p_db_sachbearbeiter_id INT;
	
	db_sachbearbeiter_entry INT;
	
	db_sachbearbeiter_tab record;
	
	BEGIN
		SET search_path TO sva4;
	
		db_sachbearbeiter_entry := (SELECT COUNT (*) FROM db_sachbearbeiter WHERE pgd_join_id IS NOT NULL);
		
		IF (db_sachbearbeiter_entry > 0) THEN
				
			FOR db_sachbearbeiter_tab IN
				SELECT pgd_join_id, sachbearbeiter_id FROM db_sachbearbeiter WHERE pgd_join_id IS NOT NULL
			LOOP
				p_pgd_join_id := db_sachbearbeiter_tab.pgd_join_id;

				p_db_sachbearbeiter_id := db_sachbearbeiter_tab.sachbearbeiter_id;
				
				INSERT INTO r_pgd_db_sachbearbeiter(pgd_id,sachbearbeiter_id)
				VALUES (p_pgd_join_id,p_db_sachbearbeiter_id);
				
			END LOOP;
		END IF;
	
	END;
$$;


