--
-- Name: pgd_pfa_migration(); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.pgd_pfa_migration() RETURNS void
    LANGUAGE plpgsql
    AS $$

DECLARE 
	p_pgd_join_id INT;
	p_pgd_berufungsjahr NCHAR(4);
	p_pgd_habil_jahr DATE;
	p_pgd_habil_hochsch NCHAR(6);
	p_pgd_habil_fach NCHAR(7);
	p_pgd_eintrittsdatum DATE;
	p_pfa_von DATE;
	p_pfaart_key NCHAR(8);
	exist_habil_entry INT;
	
	pgd_habil_tab record;
	
	BEGIN
		SET search_path TO sva4;
	
		exist_habil_entry := (SELECT COUNT (*) FROM k_pfaart WHERE his_system_key = 'H');
		
		IF (exist_habil_entry > 0) THEN
		
			p_pfaart_key := (SELECT key_pfaart FROM k_pfaart WHERE his_system_key = 'H');
		
			FOR pgd_habil_tab IN
				SELECT pgd_join_id, pgd_habil_hochsch, pgd_habil_fach, pgd_habil_jahr, pgd_berufungsjahr, pgd_eintrittsdatum FROM pgd WHERE pgd_habil_jahr IS NOT NULL
			LOOP
				p_pgd_join_id := pgd_habil_tab.pgd_join_id;
				
				IF(LENGTH(pgd_habil_tab.pgd_habil_jahr) = 4) THEN
					p_pgd_berufungsjahr := pgd_habil_tab.pgd_berufungsjahr;
				ELSE
					p_pgd_berufungsjahr := NULL;
				END IF;
				
				IF(LENGTH(pgd_habil_tab.pgd_habil_jahr) = 4) THEN
					p_pgd_habil_jahr := CONCAT(pgd_habil_tab.pgd_habil_jahr,'-01-01');
				ELSE
					p_pgd_habil_jahr := NULL;
				END IF;
				
				p_pgd_habil_hochsch := pgd_habil_tab.pgd_habil_hochsch;
				p_pgd_habil_fach := pgd_habil_tab.pgd_habil_fach;
				p_pgd_eintrittsdatum := pgd_habil_tab.pgd_eintrittsdatum;
			
				IF(LENGTH(p_pgd_berufungsjahr) = 4) THEN
					p_pfa_von := CONCAT (p_pgd_berufungsjahr, '-01-01');
				ELSE
					p_pfa_von := NULL; 
				END IF;
				
				IF(p_pfa_von IS NOT NULL AND p_pfa_von < p_pgd_eintrittsdatum) THEN
					p_pfa_von := p_pgd_eintrittsdatum;
				END IF;
				
				INSERT INTO pfa (pfa_status, pfa_pgd_join_id, pfa_berufung_lebenszeit, pfa_pruefung_datum, pfa_einrichtungen, pfa_gebiet, pfa_art, pfa_von)
				VALUES (0, p_pgd_join_id, p_pgd_berufungsjahr, p_pgd_habil_jahr, p_pgd_habil_hochsch, p_pgd_habil_fach, p_pfaart_key, p_pfa_von);
				
			END LOOP;
		END IF;
	
	END;
$$;


