--
-- Name: pgddi(sva4.pgd); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.pgddi(sva4.pgd) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM sva4.account_history account_history WHERE old_row.pgd_join_id = account_history.user_id;
DELETE FROM sva4.au_statusmitteilungen au_statusmitteilungen WHERE old_row.pgd_join_id = au_statusmitteilungen.pgd_join_id;
IF EXISTS(SELECT * FROM sva4.bta bta WHERE old_row.pgd_join_id = bta.bta_pgd_join_id) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "bta" verwendet!';
END IF;
DELETE FROM sva4.kpt_to_pgd kpt_to_pgd WHERE old_row.pgd_join_id = kpt_to_pgd.pgd_join_id;
DELETE FROM sva4.pad pad WHERE old_row.pgd_join_id = pad.pad_pgd_join_id;
DELETE FROM sva4.pas pas WHERE old_row.pgd_join_id = pas.pas_pgd_join_id;
DELETE FROM sva4.pat pat WHERE old_row.pgd_join_id = pat.pat_pgd_join_id;
DELETE FROM sva4.pbh pbh WHERE old_row.pgd_join_id = pbh.pbh_pgd_join_id;
DELETE FROM sva4.pbk pbk WHERE old_row.pgd_join_id = pbk.pbk_pgd_join_id;
DELETE FROM sva4.pbv pbv WHERE old_row.pgd_join_id = pbv.pbv_pgd_join_id;
DELETE FROM sva4.pbv_vorzeiten pbv_vorzeiten WHERE old_row.pgd_join_id = pbv_vorzeiten.pbv_vorzeiten_pgd_join_id;
DELETE FROM sva4.pbw_bewertung pbw_bewertung WHERE old_row.pgd_join_id = pbw_bewertung.pbw_bewertung_pgd_join_id;
DELETE FROM sva4.pbw_kommentar pbw_kommentar WHERE old_row.pgd_join_id = pbw_kommentar.pbw_kommentar_pgd_join_id;
DELETE FROM sva4.pfa pfa WHERE old_row.pgd_join_id = pfa.pfa_pgd_join_id;
DELETE FROM sva4.pgd_bearbeiter_berechtigung pgd_bearbeiter_berechtigung WHERE old_row.pgd_join_id = pgd_bearbeiter_berechtigung.bearbeiter_id;
DELETE FROM sva4.pgd_bearbeiter_berechtigung pgd_bearbeiter_berechtigung WHERE old_row.pgd_join_id = pgd_bearbeiter_berechtigung.pgd_join_id;
DELETE FROM sva4.pgd_dgti pgd_dgti WHERE old_row.pgd_join_id = pgd_dgti.pgd_dgti_join_id;
DELETE FROM sva4.pgd_to_bgr pgd_to_bgr WHERE old_row.pgd_join_id = pgd_to_bgr.pgd_join_id;
DELETE FROM sva4.pgd_to_sas pgd_to_sas WHERE old_row.pgd_join_id = pgd_to_sas.pgd_to_sas_pgd_join_id;
DELETE FROM sva4.pgd_ze_chip pgd_ze_chip WHERE old_row.pgd_join_id = pgd_ze_chip.ze_pgd_join_id;
DELETE FROM sva4.pki pki WHERE old_row.pgd_join_id = pki.pki_pgd_join_id;
DELETE FROM sva4.pkr pkr WHERE old_row.pgd_join_id = pkr.pkr_pgd_join_id;
DELETE FROM sva4.pnt pnt WHERE old_row.pgd_join_id = pnt.pnt_pgd_join_id;
DELETE FROM sva4.pvo_vorbelegung pvo_vorbelegung WHERE old_row.pgd_join_id = pvo_vorbelegung.pvo_vorbelegung_bearbeiter_id;
DELETE FROM sva4.pvo_vorbelegung pvo_vorbelegung WHERE old_row.pgd_join_id = pvo_vorbelegung.pvo_vorbelegung_pgd_join_id;
DELETE FROM sva4.pzk pzk WHERE old_row.pgd_join_id = pzk.pzk_pgd_join_id;
DELETE FROM sva4.pzv pzv WHERE old_row.pgd_join_id = pzv.pzv_pgd_join_id;
DELETE FROM sva4.qis_nutzer qis_nutzer WHERE old_row.pgd_join_id = qis_nutzer.pgd_join_id;
DELETE FROM sva4.r_dokumente r_dokumente WHERE old_row.pgd_join_id = r_dokumente.pgd_join_id;
IF EXISTS(SELECT * FROM sva4.rka rka WHERE old_row.pgd_join_id = rka.rka_pgd_join_id) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "rka" verwendet!';
END IF;
IF EXISTS(SELECT * FROM sva4.rka_zusatz rka_zusatz WHERE old_row.pgd_join_id = rka_zusatz.rka_zus_pgd_join_id) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "rka_zusatz" verwendet!';
END IF;
DELETE FROM sva4.sas_kommentar sas_kommentar WHERE old_row.pgd_join_id = sas_kommentar.sas_kommentar_pgd_join_id;
DELETE FROM sva4.sem_to_pgd sem_to_pgd WHERE old_row.pgd_join_id = sem_to_pgd.pgd_join_id;
IF EXISTS(SELECT * FROM sva4.ter ter WHERE old_row.pgd_join_id = ter.ter_pgd_join_id) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "ter" verwendet!';
END IF;
IF EXISTS(SELECT * FROM sva4.ter_verkehrs_rabattkarte ter_verkehrs_rabattkarte WHERE old_row.pgd_join_id = ter_verkehrs_rabattkarte.ter_verkehrs_rabattkarte_pgd_join_id) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "ter_verkehrs_rabattkarte" verwendet!';
END IF;
DELETE FROM sva4.trg trg WHERE old_row.pgd_join_id = trg.trg_pgd_join_id;
DELETE FROM sva4.ura ura WHERE old_row.pgd_join_id = ura.ura_pgd_join_id;
DELETE FROM sva4.vorgangsstornierungen vorgangsstornierungen WHERE old_row.pgd_join_id = vorgangsstornierungen.pgd_join_id;
DELETE FROM sva4.wof_berechtigung wof_berechtigung WHERE old_row.pgd_join_id = wof_berechtigung.wof_berechtigung_pgd_join_id;
DELETE FROM sva4.wof_berechtigung_im_auftrag wof_berechtigung_im_auftrag WHERE old_row.pgd_join_id = wof_berechtigung_im_auftrag.antragsteller_im_auftrag_pgd_join_id;
DELETE FROM sva4.wof_berechtigung_im_auftrag wof_berechtigung_im_auftrag WHERE old_row.pgd_join_id = wof_berechtigung_im_auftrag.antragsteller_pgd_join_id;
DELETE FROM sva4.workflow_next_responsible_person_preallocation workflow_next_responsible_person_preallocation WHERE old_row.pgd_join_id = workflow_next_responsible_person_preallocation.pgd_join_id;
DELETE FROM sva4.workflow_next_responsible_person_preallocation workflow_next_responsible_person_preallocation WHERE old_row.pgd_join_id = workflow_next_responsible_person_preallocation.preallocated_pgd_join_id;
DELETE FROM sva4.wvl wvl WHERE old_row.pgd_join_id = wvl.wvl_pgd_join_id;
 RETURN old_row; END; $_$;


--
-- Name: pgdib(); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.pgdib() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
	DECLARE
  BEGIN
		NEW := sva4.propagate_pgd_change_to_h1_sva_transfer(NEW, NEW, TRUE);
		RETURN NEW;
  END;
$$;


--
-- Name: pgdub(); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.pgdub() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
	DECLARE
  BEGIN
		NEW := sva4.rentendatum_alter(OLD, NEW);
		NEW := sva4.jubilaeumsdaten_alter(OLD, NEW);
		NEW := sva4.propagate_pgd_change_to_h1_sva_transfer(OLD, NEW, FALSE);
		RETURN NEW;
  END;
$$;


