    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _prgs_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _prgsinst_buffer!'; end if; SELECT * INTO rec FROM _prgs_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO prgs (db_einfuegemarke, projnr, ggnr, b_jahr, b_betrag, bkz, b_bwbezk, b_vwbezk, b_vbetrag) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.projnr),'NULL') || ' , ' || COALESCE(quote_literal(rec.ggnr),'NULL') || ' , ' || COALESCE(quote_literal(rec.b_jahr),'NULL') || ' , ' || COALESCE(quote_literal(rec.b_betrag),'NULL') || ' , ' || COALESCE(quote_literal(rec.bkz),'NULL') || ' , ' || COALESCE(quote_literal(rec.b_bwbezk),'NULL') || ' , ' || COALESCE(quote_literal(rec.b_vwbezk),'NULL') || ' , ' || COALESCE(quote_literal(rec.b_vbetrag),'NULL') || ')'; ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _prgs_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


--
-- Name: prgs_upd(integer); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.prgs_upd(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(join_nr) INTO anz FROM _prgs_buffer WHERE join_nr= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _prgs_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _prgs_buffer WHERE join_nr= id1 ; If FOUND then sql = 'UPDATE prgs SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , projnr= ' || COALESCE(quote_literal(rec.projnr),'NULL') || ' , ggnr= ' || COALESCE(quote_literal(rec.ggnr),'NULL') || ' , b_jahr= ' || COALESCE(quote_literal(rec.b_jahr),'NULL') || ' , b_betrag= ' || COALESCE(quote_literal(rec.b_betrag),'NULL') || ' , bkz= ' || COALESCE(quote_literal(rec.bkz),'NULL') || ' , b_bwbezk= ' || COALESCE(quote_literal(rec.b_bwbezk),'NULL') || ' , b_vwbezk= ' || COALESCE(quote_literal(rec.b_vwbezk),'NULL') || ' , b_vbetrag= ' || COALESCE(quote_literal(rec.b_vbetrag),'NULL') || ' WHERE join_nr=' || quote_literal(rec.join_nr); ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _prgs_buffer WHERE join_nr= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


