 RETURN old_row; END; $_$;


--
-- Name: process_entry_h1_sva_transfer(sva4.h1_sva_transfer); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.process_entry_h1_sva_transfer(sva4.h1_sva_transfer) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
	DECLARE
			h1_transfer_entry            ALIAS FOR $1;
			is_h1int_set                 BOOLEAN;
			transfer_entry_new_values_as_json JSON;
			h1_attribute                 TEXT;
			mapped_sva_attribute_name    VARCHAR(255);
			mapped_sva_attribute_names   VARCHAR(255)[];
			mapped_sva_attribute_values  TEXT[];
			is_pgd_entry_present         BOOLEAN;
			array_counter                INTEGER := 0;
			temp_attribute_value         VARCHAR(255);
		transfer_pgd_join_id        INT;
	BEGIN
			-- Nur auslösen, wenn H1-Integration aktiv (H1INT gesetzt),
			-- Eintrag für SVA bestimmt ist und Status noch 0 ("noch nicht verarbeitet").
			EXECUTE 'SELECT true FROM sva4.sys WHERE msnr = $1 AND txt = $2'
			INTO is_h1int_set
			USING 'H1INT', '1';

			-- ---------------------------------------------------
			-- Fall 1: Eintrag noch nicht verarbeitet (Status = 0)
			-- ---------------------------------------------------

			IF is_h1int_set
				 AND (h1_transfer_entry.is_h1_change = 1)
				 AND h1_transfer_entry.entry_status = 0
			THEN
					EXECUTE 'SELECT true FROM sva4.pgd WHERE pgd_join_id = $1'
					INTO is_pgd_entry_present
					USING h1_transfer_entry.pgd_join_id;

					transfer_entry_new_values_as_json := h1_transfer_entry.new_values::json;

					IF is_pgd_entry_present THEN
							FOR h1_attribute IN
									SELECT json_object_keys(transfer_entry_new_values_as_json)
							LOOP
									EXECUTE
											'SELECT sva_attribute
											 FROM sva4.h1_sva_attribute_mapping
											 WHERE h1_attribute = $1 AND h1_entity = $2'
									INTO mapped_sva_attribute_name
									USING h1_attribute, h1_transfer_entry.h1_entity;

									IF mapped_sva_attribute_name IS NOT NULL THEN
											IF transfer_entry_new_values_as_json->>h1_attribute = 'null' THEN
													EXECUTE
															'UPDATE sva4.pgd
															 SET pgd_h1_sva_transfer_block = 1,
																	 ' || mapped_sva_attribute_name || ' = NULL
															 WHERE pgd_join_id = $1'
													USING h1_transfer_entry.pgd_join_id;

											ELSIF mapped_sva_attribute_name = 'pgd_geburtsdatum' THEN
													EXECUTE
															'UPDATE sva4.pgd
															 SET pgd_h1_sva_transfer_block = 1,
																	 ' || mapped_sva_attribute_name || ' = $1::date
															 WHERE pgd_join_id = $2'
													USING transfer_entry_new_values_as_json->>h1_attribute,
																h1_transfer_entry.pgd_join_id;

												ELSIF mapped_sva_attribute_name = 'pgd_matrikelnummer' THEN
													EXECUTE
															'UPDATE sva4.pgd
															 SET pgd_h1_sva_transfer_block = 1,
																	 ' || mapped_sva_attribute_name || ' = $1::int
															 WHERE pgd_join_id = $2'
													USING transfer_entry_new_values_as_json->>h1_attribute,
																h1_transfer_entry.pgd_join_id;   

							ELSIF mapped_sva_attribute_name = 'pgd_h1_person_id' THEN
														EXECUTE
															'UPDATE sva4.pgd
															 SET pgd_h1_sva_transfer_block = 1,
																	 ' || mapped_sva_attribute_name || ' = $1::int
															 WHERE pgd_join_id = $2'
													USING transfer_entry_new_values_as_json->>h1_attribute,
																h1_transfer_entry.pgd_join_id;   	  

											ELSIF mapped_sva_attribute_name = 'pgd_akad_grad' THEN
													EXECUTE
															'SELECT key_akad_grad
															 FROM sva4.k_akad_grad
															 WHERE druck_akad_gradm LIKE $1
															 LIMIT 1'
													INTO temp_attribute_value
													USING transfer_entry_new_values_as_json->>h1_attribute;

													IF temp_attribute_value IS NOT NULL THEN
															EXECUTE
																	'UPDATE sva4.pgd
																	 SET pgd_h1_sva_transfer_block = 1,
																			 ' || mapped_sva_attribute_name || ' = $1
																	 WHERE pgd_join_id = $2'
															USING temp_attribute_value,
																		h1_transfer_entry.pgd_join_id;
													END IF;

											ELSIF mapped_sva_attribute_name = 'pgd_titel' THEN
													EXECUTE
															'SELECT key_anredetitel
															 FROM sva4.k_anredetitel
															 WHERE druck_anredetitelm LIKE $1
															 LIMIT 1'
													INTO temp_attribute_value
													USING transfer_entry_new_values_as_json->>h1_attribute;

													IF temp_attribute_value IS NOT NULL THEN
															EXECUTE
																	'UPDATE sva4.pgd
																	 SET pgd_h1_sva_transfer_block = 1,
																			 ' || mapped_sva_attribute_name || ' = $1
																	 WHERE pgd_join_id = $2'
															USING temp_attribute_value,
																		h1_transfer_entry.pgd_join_id;
													END IF;

											ELSE
													EXECUTE
															'UPDATE sva4.pgd
															 SET pgd_h1_sva_transfer_block = 1,
																	 ' || mapped_sva_attribute_name || ' = $1
															 WHERE pgd_join_id = $2'
													USING transfer_entry_new_values_as_json->>h1_attribute,
																h1_transfer_entry.pgd_join_id;
											END IF;
									END IF;
							END LOOP;

							-- Änderungen übernommen ? als erfolgreich verarbeitet markieren
							UPDATE sva4.h1_sva_transfer
							SET entry_status = 1,
									entry_status_changed_at = NOW()
							WHERE id = h1_transfer_entry.id;

					ELSE
							-- Kein pgd-Datensatz ? Status = 2 ("Person nicht gefunden")
							UPDATE sva4.h1_sva_transfer
							SET entry_status = 2,
									entry_status_changed_at = NOW()
							WHERE id = h1_transfer_entry.id;
					END IF;
			END IF;

			-- ------------------------------------------------------------------------------------------------------------------------------
			-- Fall 2:  HISinOne hat erkannt, dass die Person noch nicht integriert wurde (kein Eintrag in der external_relation).
			--          In diesem Fall wird durch den entry_status = 5 der komplette dump aller Daten über die Transfer Tabelle angestoßen    
			--          Beinhaltet die Tabellen: pgd/pfi/pbv für die pgd_join_id           
			-- ------------------------------------------------------------------------------------------------------------------------------
			IF is_h1int_set
				 AND (h1_transfer_entry.is_h1_change = 1)
				 AND (h1_transfer_entry.entry_status = 4)
			THEN
					transfer_pgd_join_id := h1_transfer_entry.pgd_join_id;
					
					 -- propagate pgd
					RAISE NOTICE 'Starte propagate_pgd_change_to_h1_sva_transfer für pgd_join_id=%', transfer_pgd_join_id;
					PERFORM sva4.propagate_pgd_change_to_h1_sva_transfer(
							NULL,
							pgd,
							TRUE
					)
					FROM sva4.pgd AS pgd
					WHERE pgd.pgd_join_id = transfer_pgd_join_id;

					-- propagate pgd
					RAISE NOTICE 'synchronize_org_unit_change_with_hisinone für pgd_join_id=%',transfer_pgd_join_id;
					PERFORM sva4.synchronize_org_unit_change_with_hisinone(
							NULL,
							pfi
					)
					FROM sva4.pfi AS pfi
					WHERE pfi.pfi_pgd_join_id = transfer_pgd_join_id;

					-- propagate pfi
					RAISE NOTICE 'Starte propagate_pfi_change_to_h1_sva_transfer für pgd_join_id=%', transfer_pgd_join_id;
					PERFORM sva4.propagate_pfi_change_to_h1_sva_transfer(
							NULL,
							pfi
					)
					FROM sva4.pfi AS pfi
					WHERE pfi.pfi_pgd_join_id = transfer_pgd_join_id;

					-- propagate pbv
					RAISE NOTICE 'Starte propagate_pbv_change_to_h1_sva_transfer für pgd_join_id=%', transfer_pgd_join_id;
					PERFORM sva4.propagate_pbv_change_to_h1_sva_transfer(
							NULL,
							pbv
					)
					FROM sva4.pbv AS pbv
					WHERE pbv.pbv_pgd_join_id = transfer_pgd_join_id;
			END IF;

			RETURN h1_transfer_entry;
	END;
$_$;


