--
-- Name: proj_ins(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.proj_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _proj_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _projinst_buffer!'; end if; SELECT * INTO rec FROM _proj_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO proj (db_einfuegemarke, projnr, ueberkey, ktext, ltxt1, ltxt2, az, fb, ins, pjlname1, pjlname2, pjlname3, fins, lehr, spklnr1, spklnr2, bewdat1, bewdat2, bewabl, art1, art2, svarel, mbsrel, ivsrel, baurel, cobrel, besrel, lsfrel, mwpf, laufzeitbeginn, spklnr3, spklnr4, koordination, key_extkotr, key_ext) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.projnr),'NULL') || ' , ' || COALESCE(quote_literal(rec.ueberkey),'NULL') || ' , ' || COALESCE(quote_literal(rec.ktext),'NULL') || ' , ' || COALESCE(quote_literal(rec.ltxt1),'NULL') || ' , ' || COALESCE(quote_literal(rec.ltxt2),'NULL') || ' , ' || COALESCE(quote_literal(rec.az),'NULL') || ' , ' || COALESCE(quote_literal(rec.fb),'NULL') || ' , ' || COALESCE(quote_literal(rec.ins),'NULL') || ' , ' || COALESCE(quote_literal(rec.pjlname1),'NULL') || ' , ' || COALESCE(quote_literal(rec.pjlname2),'NULL') || ' , ' || COALESCE(quote_literal(rec.pjlname3),'NULL') || ' , ' || COALESCE(quote_literal(rec.fins),'NULL') || ' , ' || COALESCE(quote_literal(rec.lehr),'NULL') || ' , ' || COALESCE(quote_literal(rec.spklnr1),'NULL') || ' , ' || COALESCE(quote_literal(rec.spklnr2),'NULL') || ' , ' || COALESCE(quote_literal(rec.bewdat1),'NULL') || ' , ' || COALESCE(quote_literal(rec.bewdat2),'NULL') || ' , ' || COALESCE(quote_literal(rec.bewabl),'NULL') || ' , ' || COALESCE(quote_literal(rec.art1),'NULL') || ' , ' || COALESCE(quote_literal(rec.art2),'NULL') || ' , ' || COALESCE(quote_literal(rec.svarel),'NULL') || ' , ' || COALESCE(quote_literal(rec.mbsrel),'NULL') || ' , ' || COALESCE(quote_literal(rec.ivsrel),'NULL') || ' , ' || COALESCE(quote_literal(rec.baurel),'NULL') || ' , ' || COALESCE(quote_literal(rec.cobrel),'NULL') || ' , ' || COALESCE(quote_literal(rec.besrel),'NULL') || ' , ' || COALESCE(quote_literal(rec.lsfrel),'NULL') || ' , ' || COALESCE(quote_literal(rec.mwpf),'NULL') || ' , ' || COALESCE(quote_literal(rec.laufzeitbeginn),'NULL') || ' , ' || COALESCE(quote_literal(rec.spklnr3),'NULL') || ' , ' || COALESCE(quote_literal(rec.spklnr4),'NULL') || ' , ' || COALESCE(quote_literal(rec.koordination),'NULL') || ' , ' || COALESCE(quote_literal(rec.key_extkotr),'NULL') || ' , ' || COALESCE(quote_literal(rec.key_ext),'NULL') || ')'; ret_dblink = dblink_exec(gc('superx_cob_90_ap'), sql); DELETE FROM _proj_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


