--

CREATE FUNCTION sva4.proj_to_pbv_upd(integer, smallint, character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1;  id2 ALIAS FOR $2;  id3 ALIAS FOR $3; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(pbv_pgd_join_id) INTO anz FROM _proj_to_pbv_buffer WHERE pbv_pgd_join_id= id1  AND pbv_nr= id2 AND projnr= id3; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _proj_to_pbv_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _proj_to_pbv_buffer WHERE pbv_pgd_join_id= id1  AND pbv_nr= id2 AND projnr= id3; If FOUND then sql = 'UPDATE proj_to_pbv SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , projnr= ' || COALESCE(quote_literal(rec.projnr),'NULL') || ' , pbv_pgd_join_id= ' || COALESCE(quote_literal(rec.pbv_pgd_join_id),'NULL') || ' , pbv_nr= ' || COALESCE(quote_literal(rec.pbv_nr),'NULL') || ' , hpers= ' || COALESCE(quote_literal(rec.hpers),'NULL') || ' , proj_pbv_serial= ' || COALESCE(quote_literal(rec.proj_pbv_serial),'NULL') || ' WHERE pbv_pgd_join_id=' || quote_literal(rec.pbv_pgd_join_id) || ' AND pbv_nr=' || quote_literal(rec.pbv_nr)  || ' AND projnr=' || quote_literal(rec.projnr) ; ret_dblink = dblink_exec(gc('superx_cob_90_ap'), sql); DELETE FROM _proj_to_pbv_buffer WHERE pbv_pgd_join_id= id1  AND pbv_nr= id2 AND projnr= id3; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


