    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
 RETURN old_row; END; $_$;


--
-- Name: proj_upd(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.proj_upd(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(projnr) INTO anz FROM _proj_buffer WHERE projnr= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _proj_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _proj_buffer WHERE projnr= id1 ; If FOUND then sql = 'UPDATE proj SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , projnr= ' || COALESCE(quote_literal(rec.projnr),'NULL') || ' , ueberkey= ' || COALESCE(quote_literal(rec.ueberkey),'NULL') || ' , ktext= ' || COALESCE(quote_literal(rec.ktext),'NULL') || ' , ltxt1= ' || COALESCE(quote_literal(rec.ltxt1),'NULL') || ' , ltxt2= ' || COALESCE(quote_literal(rec.ltxt2),'NULL') || ' , az= ' || COALESCE(quote_literal(rec.az),'NULL') || ' , fb= ' || COALESCE(quote_literal(rec.fb),'NULL') || ' , ins= ' || COALESCE(quote_literal(rec.ins),'NULL') || ' , pjlname1= ' || COALESCE(quote_literal(rec.pjlname1),'NULL') || ' , pjlname2= ' || COALESCE(quote_literal(rec.pjlname2),'NULL') || ' , pjlname3= ' || COALESCE(quote_literal(rec.pjlname3),'NULL') || ' , fins= ' || COALESCE(quote_literal(rec.fins),'NULL') || ' , lehr= ' || COALESCE(quote_literal(rec.lehr),'NULL') || ' , spklnr1= ' || COALESCE(quote_literal(rec.spklnr1),'NULL') || ' , spklnr2= ' || COALESCE(quote_literal(rec.spklnr2),'NULL') || ' , bewdat1= ' || COALESCE(quote_literal(rec.bewdat1),'NULL') || ' , bewdat2= ' || COALESCE(quote_literal(rec.bewdat2),'NULL') || ' , bewabl= ' || COALESCE(quote_literal(rec.bewabl),'NULL') || ' , art1= ' || COALESCE(quote_literal(rec.art1),'NULL') || ' , art2= ' || COALESCE(quote_literal(rec.art2),'NULL') || ' , svarel= ' || COALESCE(quote_literal(rec.svarel),'NULL') || ' , mbsrel= ' || COALESCE(quote_literal(rec.mbsrel),'NULL') || ' , ivsrel= ' || COALESCE(quote_literal(rec.ivsrel),'NULL') || ' , baurel= ' || COALESCE(quote_literal(rec.baurel),'NULL') || ' , cobrel= ' || COALESCE(quote_literal(rec.cobrel),'NULL') || ' , besrel= ' || COALESCE(quote_literal(rec.besrel),'NULL') || ' , lsfrel= ' || COALESCE(quote_literal(rec.lsfrel),'NULL') || ' , mwpf= ' || COALESCE(quote_literal(rec.mwpf),'NULL') || ' , laufzeitbeginn= ' || COALESCE(quote_literal(rec.laufzeitbeginn),'NULL') || ' , spklnr3= ' || COALESCE(quote_literal(rec.spklnr3),'NULL') || ' , spklnr4= ' || COALESCE(quote_literal(rec.spklnr4),'NULL') || ' , koordination= ' || COALESCE(quote_literal(rec.koordination),'NULL') || ' , key_extkotr= ' || COALESCE(quote_literal(rec.key_extkotr),'NULL') || ' , key_ext= ' || COALESCE(quote_literal(rec.key_ext),'NULL') || ' WHERE projnr=' || quote_literal(rec.projnr); ret_dblink = dblink_exec(gc('superx_cob_90_ap'), sql); DELETE FROM _proj_buffer WHERE projnr= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


