--
-- Name: projdi(sva4.__proj); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.projdi(sva4.__proj) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM sva4.prbb prbb WHERE old_row.projnr = prbb.projnr;
DELETE FROM sva4.prge prge WHERE old_row.projnr = prge.projnr;
DELETE FROM sva4.prgi prgi WHERE old_row.projnr = prgi.projnr;
DELETE FROM sva4.prgn prgn WHERE old_row.projnr = prgn.projnr;
DELETE FROM sva4.prgs prgs WHERE old_row.projnr = prgs.projnr;
IF EXISTS(SELECT * FROM sva4.proj proj WHERE old_row.projnr = proj.ueberkey) THEN
RAISE EXCEPTION 'Schluessel wird noch in Detailtabelle "proj" verwendet!';
END IF;
DELETE FROM sva4.proj_to_inst proj_to_inst WHERE old_row.projnr = proj_to_inst.projnr;
DELETE FROM sva4.proj_to_pbv proj_to_pbv WHERE old_row.projnr = proj_to_pbv.projnr;
DELETE FROM sva4.r_proj_attribut r_proj_attribut WHERE old_row.projnr = r_proj_attribut.proj_projnr;
 RETURN old_row; END; $_$;


--
-- Name: propagate_paz_change_to_h1_sva_transfer(sva4.paz, sva4.paz); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.propagate_paz_change_to_h1_sva_transfer(sva4.paz, sva4.paz) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$

	DECLARE
		paz_entry_old ALIAS FOR $1;
		paz_entry_new ALIAS FOR $2;
		is_h1int_set CHARACTER VARYING(1);	

	BEGIN
		-- Nur ausloesen, wenn H1-Integration aktiv (H1INT gesetzt)
		EXECUTE 'SELECT txt from sva4.sys WHERE msnr = $1' INTO is_h1int_set USING 'H1INT';			
			
		IF is_h1int_set = '1' THEN			
			INSERT INTO sva4.h1_sva_transfer(pgd_join_id, new_values, h1_entity, created_at,is_h1_change,entry_status,obj_guid, lock_version)
			SELECT
			  sva4.pgd.pgd_join_id AS pgd_join_id
			  , '{'
				   || '"pazSerial":' || sva4.paz.paz_serial
				   || ',"pbvId":' || sva4.pbv.pbv_serial 
				   || ',"pazTzProz": ' || CASE WHEN sva4.paz.paz_tz_proz IS NULL THEN 100 ELSE  sva4.paz.paz_tz_proz  END   
				   || ',"pazVon":' || CASE WHEN sva4.paz.paz_von IS NULL THEN 'null' ELSE '"' || sva4.paz.paz_von ||'"' END  
				   || ',"pazBis":' || CASE WHEN sva4.paz.paz_bis IS NULL THEN 'null' ELSE '"' || sva4.paz.paz_bis ||'"' END
				   || '}' AS new_values			  
			  , 'cs.psv.workingtime.WorkingTime' AS h1_entity
			  , NOW() AS created_at
			  , 0 AS is_h1_change
			  , 0 AS entry_status
			  , 'cs.psv.workingtime.WorkingTime' || sva4.paz.paz_serial AS obj_guid
			  , 0 AS lock_version			     
			FROM sva4.pbv				
			INNER JOIN sva4.pgd ON sva4.pbv.pbv_pgd_join_id = sva4.pgd.pgd_join_id 
			INNER JOIN sva4.paz ON sva4.paz.paz_pgd_join_id = sva4.pbv.pbv_pgd_join_id AND sva4.paz.paz_pbv_nr = sva4.pbv.pbv_nr
			WHERE sva4.paz.paz_serial = paz_entry_new.paz_serial
				AND sva4.paz.paz_status = 0 AND sva4.pbv.pbv_status = 0;				
		END IF;			
			
		RETURN paz_entry_new;
	END;

$_$;


--
-- Name: propagate_pbv_change_to_h1_sva_transfer(sva4.pbv, sva4.pbv); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.propagate_pbv_change_to_h1_sva_transfer(sva4.pbv, sva4.pbv) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$

	DECLARE
		pbv_entry_old ALIAS FOR $1;
		pbv_entry_new ALIAS FOR $2;		
		is_h1int_set CHARACTER VARYING(1);	

	BEGIN
		-- Nur ausloesen, wenn H1-Integration aktiv (H1INT gesetzt)
		EXECUTE 'SELECT txt from sva4.sys WHERE msnr = $1' INTO is_h1int_set USING 'H1INT';			
			
		IF is_h1int_set = '1' THEN
			If pbv_entry_new IS NULL THEN
				INSERT INTO sva4.h1_sva_transfer(pgd_join_id, new_values, h1_entity, created_at,is_h1_change,entry_status,obj_guid, lock_version) 
					VALUES (pbv_entry_old.pbv_pgd_join_id, '{"svaNr":' || pbv_entry_old.pbv_serial || ',"svaTable":"pbv"}', 'cs.psv.employment.DataDeleter', NOW(), 0, 0, 'cs.psv.employment.Employment' || pbv_entry_old.pbv_serial, 0);
			ELSE
				INSERT INTO sva4.h1_sva_transfer(pgd_join_id, new_values, h1_entity, created_at, is_h1_change, entry_status, obj_guid, lock_version)
				SELECT
					sva4.pgd.pgd_join_id AS pgd_join_id	  
					,'{'
						 || '"pbvId":' || sva4.pbv.pbv_serial
						 || ',"pgdId":' || sva4.pgd.pgd_join_id
						 || ',"pbvNr":' || sva4.pbv.pbv_nr
						 || ',"pgdFamilyname": "' || sva4.pgd.pgd_name || '"'
						 || ',"pgdFirstname": "' || sva4.pgd.pgd_vornamen || '"'
						 || ',"pgdGender": "' || COALESCE(sva4.pgd.pgd_geschlecht, '') || '"'
						 || ',"pbvVon":' || CASE WHEN sva4.pbv.pbv_von IS NULL THEN 'null' ELSE '"' || sva4.pbv.pbv_von ||'"' END  
						 || ',"pbvBis":' || CASE WHEN sva4.pbv.pbv_bis IS NULL THEN 'null' ELSE '"' || sva4.pbv.pbv_bis ||'"' END
						 || ',"pbvBefr":' || CASE WHEN sva4.pbv.pbv_befr_bis IS NULL THEN 'null' ELSE '"' || sva4.pbv.pbv_befr_bis ||'"' END
						|| ',"pbvArt": "' || sva4.pbv.pbv_art || '"'
						|| ',"pbvType":' || CASE WHEN sva4.k_vertragsart.his_system_key IS NULL THEN 'null' ELSE '"' || sva4.k_vertragsart.his_system_key ||'"' END 
						|| ',"pbvActivityType":' || CASE WHEN sva4.k_vertragsart.bund_taetigkeit IS NULL THEN 'null' ELSE '"' || sva4.k_vertragsart.bund_taetigkeit ||'"' END 
						|| ',"pbvQualifizierungsverfahren":' || CASE WHEN sva4.pbv.pbv_qualifizierungsverfahren IS NULL THEN 'null' ELSE '"' || sva4.pbv.pbv_qualifizierungsverfahren ||'"' END
						|| '}' AS new_values
						
						,'cs.psv.employment.Employment' AS h1_entity
					,NOW() AS created_at
					, 0 AS is_h1_change
					, 0 AS entry_status
					,'cs.psv.employment.Employment' || sva4.pbv.pbv_serial AS obj_guid
					, 0 AS lock_version
	 
				FROM sva4.pbv
						
				INNER JOIN sva4.pgd ON sva4.pbv.pbv_pgd_join_id = sva4.pgd.pgd_join_id			
				INNER JOIN sva4.k_vertragsart ON sva4.pbv.pbv_art = sva4.k_vertragsart.key_vertragsart
				WHERE sva4.pbv.pbv_serial = pbv_entry_new.pbv_serial
					AND sva4.pgd.pgd_status = 0 AND sva4.pbv.pbv_status = 0;
			
			END IF;
		END IF;			
			
		RETURN pbv_entry_new;
	END;

$_$;


--
-- Name: propagate_pfi_change_to_h1_sva_transfer(sva4.pfi, sva4.pfi); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.propagate_pfi_change_to_h1_sva_transfer(sva4.pfi, sva4.pfi) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$

	DECLARE
		pfi_entry_old ALIAS FOR $1;
		pfi_entry_new ALIAS FOR $2;
		is_h1int_set CHARACTER VARYING(1);

	BEGIN
		-- Nur ausloesen, wenn H1-Integration aktiv (H1INT gesetzt)
		EXECUTE 'SELECT txt from sva4.sys WHERE msnr = $1' INTO is_h1int_set USING 'H1INT';

		IF is_h1int_set = '1' THEN
			INSERT INTO sva4.h1_sva_transfer(pgd_join_id, new_values, h1_entity, created_at,is_h1_change,entry_status,obj_guid, lock_version)
			SELECT
			  sva4.pgd.pgd_join_id AS pgd_join_id
			  ,'{'
			   || '"pfiSerial":' || sva4.pfi.pfi_serial
			   || ',"pbvId":' || sva4.pbv.pbv_serial
			   || ',"pozInstitut": "' || coalesce(sva4.pfi.poz_institut, '') || '"'
			   || ',"pfiArt": "' ||  coalesce(sva4.pfi.pfi_art, '') || '"'
			   || ',"pfiProzent": ' || CASE WHEN sva4.pfi.pfi_prozent IS NULL THEN 100 ELSE  sva4.pfi.pfi_prozent  END
			   || ',"pfiVon":' || CASE WHEN sva4.pfi.pfi_von IS NULL THEN 'null' ELSE '"' || sva4.pfi.pfi_von ||'"' END
			   || ',"pfiBis":' || CASE WHEN sva4.pfi.pfi_bis IS NULL THEN 'null' ELSE '"' || sva4.pfi.pfi_bis ||'"' END
			  || '}' AS new_values
			  ,'cs.psv.personnelcost.Financing' AS h1_entity
			  ,NOW() AS created_at
			  , 0 AS is_h1_change
			  , 0 AS entry_status
			  ,'cs.psv.personnelcost.Financing' || sva4.pfi.pfi_serial AS obj_guid
			  , 0 AS lock_version
			FROM sva4.pbv
			INNER JOIN sva4.pgd ON sva4.pbv.pbv_pgd_join_id = sva4.pgd.pgd_join_id
			INNER JOIN sva4.pfi ON sva4.pfi.pfi_pgd_join_id = sva4.pbv.pbv_pgd_join_id AND sva4.pfi.pfi_pbv_nr = sva4.pbv.pbv_nr
			WHERE sva4.pfi.pfi_serial = pfi_entry_new.pfi_serial
				AND sva4.pfi.pfi_status = 0 AND sva4.pbv.pbv_status = 0;
		END IF;

		RETURN pfi_entry_new;
	END;

$_$;


--
-- Name: propagate_pgd_change_to_h1_sva_transfer(sva4.pgd, sva4.pgd, boolean); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.propagate_pgd_change_to_h1_sva_transfer(sva4.pgd, sva4.pgd, boolean) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
	DECLARE
		pgd_entry_old ALIAS FOR $1;
		pgd_entry_new ALIAS FOR $2;
		is_insert ALIAS FOR $3;
		is_h1int_set CHARACTER VARYING(1);
		all_pgd_column_names CHARACTER VARYING(255)[];
		pgd_column_name CHARACTER VARYING(255);
		pgd_value_old TEXT;
		pgd_value_new TEXT;
		h1_sva_attribute_mapping RECORD;
		key_value_for_transfer TEXT;
		changed_person_values_array TEXT[];
		changed_personinfo_values_array TEXT[];
		changed_postaddress_values_array TEXT[];
		changed_email_values_array TEXT[];
		changed_phone_values_array TEXT[];
		changed_student_values_array TEXT[];
	BEGIN
		-- Nur ausloesen, wenn H1-Integration aktiv (H1INT gesetzt)
		IF (is_insert) OR (pgd_entry_old != pgd_entry_new) THEN
			EXECUTE 'SELECT txt from sva4.sys WHERE msnr = $1' INTO is_h1int_set USING 'H1INT';

			IF is_h1int_set = '1' THEN
				IF is_insert THEN
					-- Wenn der Aufruf der Funktion durch einen INSERT-Trigger durchgefuehrt wurde, setze den pgd-Status des "vorherigen Datensatzes" (was bei
					-- einem INSERT dem neuen Datensatz entspricht) auf ungueltig, so dass spï¿½ter in dieser Funktion alle Merkmale der Person nach HISinOne synchronisiert werden
					pgd_entry_old.pgd_status = 4;
				END IF;

				-- In der Tabelle pgd gibt die Spalte "pgd_h1_sva_transfer_block" an, ob Aenderungen am pgd-Satz auch an die HISInOne h1_sva_transfer-Tabelle uebermittelt werden sollen.
				-- Dies soll z. B. nicht geschehen, wenn Aenderungen bereits aus HISinOne kamen und nun nur noch in der pgd uebernommen werden soll.
				-- Ist pgd_h1_sva_transfer_block gesetzt, soll kein Eintrag in der h1_sva_transfer-Tabelle angelegt werden.
				IF (pgd_entry_old.pgd_h1_sva_transfer_block IS NULL AND pgd_entry_new.pgd_h1_sva_transfer_block IS NULL) THEN
					EXECUTE 'SELECT array(SELECT column_name::CHARACTER VARYING(255) FROM information_schema.columns WHERE table_name=$1 AND table_schema = '|| quote_literal('sva4') ||')'
					INTO all_pgd_column_names
					USING 'pgd';

					FOREACH pgd_column_name IN ARRAY all_pgd_column_names LOOP
						-- Pruefen, ob Spalte sich geaendert hat. Wenn ja, pruefen, ob Spalte nach H1 synchronisiert werden soll (=> in h1_sva_attribute_mapping
						-- vorhanden ist).
						-- Ist dies der Fall, neuen Wert in Uebertragungstabelle schreiben
						EXECUTE 'SELECT ($1).' || pgd_column_name || '::text' INTO pgd_value_old USING pgd_entry_old;
						EXECUTE 'SELECT ($1).' || pgd_column_name || '::text' INTO pgd_value_new USING pgd_entry_new;

						--- Wenn old.pgd_status != 0 und new.pgd_status = 0: Alle pgd-Datensaetze in Transfer-Tabelle schreiben
						--- Datensatz nur uebermitteln, wenn er gueltig ist
						IF (pgd_entry_new.pgd_status = 0) AND ((pgd_value_old != pgd_value_new) OR (pgd_value_old IS NULL AND pgd_value_new IS NOT NULL)
							OR (pgd_value_old IS NOT NULL AND pgd_value_new IS NULL) OR (pgd_entry_old.pgd_status != 0 )) THEN
						
							EXECUTE 'SELECT * FROM sva4.h1_sva_attribute_mapping WHERE sva_attribute = $1'
							INTO h1_sva_attribute_mapping
							USING pgd_column_name;
							IF h1_sva_attribute_mapping.h1_attribute IS NOT NULL THEN
								-- Einige Werte (Schluesselfelder) koennen nicht direkt in die Uebertragungstabelle geschrieben werden, sondern muessen
								-- noch in von HISinOne verwendete Schluessel umgemapped werden
								IF pgd_column_name = 'pgd_akad_grad' THEN
									EXECUTE 'SELECT druck_akad_gradm FROM sva4.k_akad_grad WHERE key_akad_grad = $1'
									INTO key_value_for_transfer
									USING pgd_value_new;
								ELSIF pgd_column_name = 'pgd_titel' THEN
									EXECUTE 'SELECT druck_anredetitelm FROM sva4.k_anredetitel WHERE key_anredetitel = $1'
									INTO key_value_for_transfer
									USING pgd_value_new;
								ELSE
									key_value_for_transfer := pgd_value_new;
								END IF;

								IF key_value_for_transfer IS NULL THEN
									key_value_for_transfer := 'null';
								END IF;

								IF (h1_sva_attribute_mapping.h1_entity = 'psv.Person') THEN
									SELECT array_append(changed_person_values_array, '"' || h1_sva_attribute_mapping.h1_attribute || '":"' || key_value_for_transfer ||'"') INTO changed_person_values_array;
								ELSIF (h1_sva_attribute_mapping.h1_entity = 'psv.Personinfo') THEN
									SELECT array_append(changed_personinfo_values_array, '"' || h1_sva_attribute_mapping.h1_attribute || '":"' || key_value_for_transfer ||'"') INTO changed_personinfo_values_array;
								ELSIF (h1_sva_attribute_mapping.h1_entity = 'psv.Postaddress') THEN
									SELECT array_append(changed_postaddress_values_array, '"' || h1_sva_attribute_mapping.h1_attribute || '":"' || key_value_for_transfer ||'"') INTO changed_postaddress_values_array;
								ELSIF (h1_sva_attribute_mapping.h1_entity = 'psv.EMail') THEN
									SELECT array_append(changed_email_values_array, '"' || h1_sva_attribute_mapping.h1_attribute || '":"' || key_value_for_transfer ||'"') INTO changed_email_values_array;
								ELSIF (h1_sva_attribute_mapping.h1_entity = 'psv.Phone') THEN
									SELECT array_append(changed_phone_values_array, '"' || h1_sva_attribute_mapping.h1_attribute || '":"' || key_value_for_transfer ||'"') INTO changed_phone_values_array;
								ELSIF (h1_sva_attribute_mapping.h1_entity = 'cm.stu.Student') THEN
									SELECT array_append(changed_student_values_array, '"' || h1_sva_attribute_mapping.h1_attribute || '":"' || key_value_for_transfer ||'"') INTO changed_student_values_array;
								END IF;
							END IF;
						END IF;
					END LOOP;

					-- Aenderungen an der "psv.Person" muessen als Erstes in die Transfer-Tabelle eingefuegt werden, damit HISinOne ggf.
					-- die Person mit ihren Stammdaten anlegen kann, falls sie dort noch nicht existiert
					IF (array_length(changed_person_values_array, 1) > 0) THEN
						INSERT INTO sva4.h1_sva_transfer(pgd_join_id, new_values, h1_entity, created_at, is_h1_change, entry_status, obj_guid, lock_version) VALUES (pgd_entry_new.pgd_join_id,
						'{' || array_to_string(changed_person_values_array, ',') || '}', 'psv.Person', NOW(), 0, 0, 'psv.Person' || currval('sva4.h1_sva_transfer_id_seq'), 0);
					END IF;

					IF (array_length(changed_personinfo_values_array, 1) > 0) THEN
						INSERT INTO sva4.h1_sva_transfer(pgd_join_id, new_values, h1_entity, created_at, is_h1_change, entry_status, obj_guid, lock_version) VALUES (pgd_entry_new.pgd_join_id,
						'{' || array_to_string(changed_personinfo_values_array, ',') || '}', 'psv.Personinfo', NOW(), 0, 0, 'psv.Person' || currval('sva4.h1_sva_transfer_id_seq'), 0);
					END IF;

					IF (array_length(changed_postaddress_values_array, 1) > 0) THEN
						INSERT INTO sva4.h1_sva_transfer(pgd_join_id, new_values, h1_entity, created_at, is_h1_change, entry_status, obj_guid, lock_version) VALUES (pgd_entry_new.pgd_join_id,
						'{' || array_to_string(changed_postaddress_values_array, ',') || '}', 'psv.Postaddress', NOW(), 0, 0, 'psv.Person' || currval('sva4.h1_sva_transfer_id_seq'), 0);
					END IF;

					IF (array_length(changed_email_values_array, 1) > 0) THEN
						INSERT INTO sva4.h1_sva_transfer(pgd_join_id, new_values, h1_entity, created_at, is_h1_change, entry_status, obj_guid, lock_version) VALUES (pgd_entry_new.pgd_join_id,
						'{' || array_to_string(changed_email_values_array, ',') || '}', 'psv.EMail', NOW(), 0, 0, 'psv.Person' || currval('sva4.h1_sva_transfer_id_seq'), 0);
					END IF;

					IF (array_length(changed_phone_values_array, 1) > 0) THEN
						INSERT INTO sva4.h1_sva_transfer(pgd_join_id, new_values, h1_entity, created_at, is_h1_change, entry_status, obj_guid, lock_version) VALUES (pgd_entry_new.pgd_join_id,
						'{' || array_to_string(changed_phone_values_array, ',') || '}', 'psv.Phone', NOW(), 0, 0, 'psv.Person' || currval('sva4.h1_sva_transfer_id_seq'), 0);
					END IF;

					IF (array_length(changed_student_values_array, 1) > 0) THEN
						INSERT INTO sva4.h1_sva_transfer(pgd_join_id, new_values, h1_entity, created_at, is_h1_change, entry_status, obj_guid, lock_version) VALUES (pgd_entry_new.pgd_join_id,
						'{' || array_to_string(changed_student_values_array, ',') || '}', 'cm.stu.Student', NOW(), 0, 0, 'psv.Person' || currval('sva4.h1_sva_transfer_id_seq'), 0);
					END IF;					
				ELSIF (pgd_entry_old.pgd_h1_sva_transfer_block IS NOT NULL AND pgd_entry_new.pgd_h1_sva_transfer_block IS NULL) THEN
					-- Nichts zu tun
					RETURN pgd_entry_new;
				ELSE
					-- Aenderung kam durch H1-Transfer-Tabelle => Kein erneutes Schreiben in Transfer-Tabelle, nur den Status
					-- in pgd wieder zuruecksetzen
					pgd_entry_new.pgd_h1_sva_transfer_block = NULL;
				END IF;
			END IF;
		END IF;		

		RETURN pgd_entry_new;
	END;
$_$;


--
-- Name: prti_del(integer); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.prti_del(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE sql text; id1 ALIAS FOR $1;  BEGIN sql = 'DELETE FROM prti WHERE join_nr= ' || quote_literal(id1); return dblink_exec(gc('superx_fsv_90_ap'), sql); END;$_$;


--
-- Name: prti_ins(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.prti_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _prti_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _prtiinst_buffer!'; end if; SELECT * INTO rec FROM _prti_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO prti (db_einfuegemarke, projnr, kap, dr, titel) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.projnr),'NULL') || ' , ' || COALESCE(quote_literal(rec.kap),'NULL') || ' , ' || COALESCE(quote_literal(rec.dr),'NULL') || ' , ' || COALESCE(quote_literal(rec.titel),'NULL') || ')'; ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _prti_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


--
-- Name: prti_upd(integer); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.prti_upd(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(join_nr) INTO anz FROM _prti_buffer WHERE join_nr= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _prti_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _prti_buffer WHERE join_nr= id1 ; If FOUND then sql = 'UPDATE prti SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , projnr= ' || COALESCE(quote_literal(rec.projnr),'NULL') || ' , kap= ' || COALESCE(quote_literal(rec.kap),'NULL') || ' , dr= ' || COALESCE(quote_literal(rec.dr),'NULL') || ' , titel= ' || COALESCE(quote_literal(rec.titel),'NULL') || ' WHERE join_nr=' || quote_literal(rec.join_nr); ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _prti_buffer WHERE join_nr= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


