--
-- Name: pzeda(); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.pzeda() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
   BEGIN
		  UPDATE sva4.pzd_q SET pzd_q_pze_serial = NULL WHERE OLD.pze_serial = pzd_q_pze_serial;
		  UPDATE sva4.pzd SET pzd_pze_serial = NULL WHERE OLD.pze_serial = pzd_pze_serial;
      RETURN OLD;
   END;
$$;


