CREATE FUNCTION sva4.qis_nutzerdi(sva4.qis_nutzer) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM sva4.k_processing_group_in_qis_nutzer k_processing_group_in_qis_nutzer WHERE old_row.nutzer_id = k_processing_group_in_qis_nutzer.nutzer_id;
DELETE FROM sva4.qis_nutzer_inst qis_nutzer_inst WHERE old_row.nutzer_id = qis_nutzer_inst.nutzer_id;
DELETE FROM sva4.r_kollektionnutzer r_kollektionnutzer WHERE old_row.nutzer_id = r_kollektionnutzer.nutzer_id;
 RETURN old_row; END; $_$;


