--
-- Name: rentendatum(); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.rentendatum() RETURNS void
    LANGUAGE plpgsql
    AS $$

   DECLARE
      counter INT;

   BEGIN
	SET search_path TO sva4;
	
	counter := (SELECT SUM(protokollierung) FROM db_tabellen WHERE (name = 'pgd' OR name = 'pbv'));
	IF counter > 0 THEN
		RAISE EXCEPTION 'Protokollierung fuer die HISSVA-GX-Tabellen pgd und pbv ausschalten!!!';
	ELSE
		DROP TRIGGER IF EXISTS pbvua on pbv;
		DROP TRIGGER IF EXISTS pbvia on pbv;
	END IF;
  
   END;

$$;


--
-- Name: rentendatum_alter(sva4.pgd); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.rentendatum_alter(sva4.pgd) RETURNS record
    LANGUAGE plpgsql
    AS $_$

DECLARE
    row_pgd ALIAS FOR $1;

    p_pgd_join_id INT;

    p_bundesland NCHAR(2);
    p_vertragsart NCHAR(2);
    p_alter INT;
    p_monat INT;
		i_monat INT;
    p_alter_alt INT;
    p_monat_alt INT;
    p_datum DATE;
    p_beamte_wie_arbeitnehmer INT;
    p_prof_arbeitnehmer_wie_beamte_prof INT;
    p_wiss_beamte_wie_prof INT;
    p_dienstart INT;	

    p_rentendatum DATE;
    p_rentendatum_tag INT;
    p_rentendatum_monat INT;
    p_rentendatum_jahr INT;

    p_gebdat DATE;
    p_gebdat_tag INT;
    p_gebdat_monat INT;
    p_gebdat_jahr INT;

    p_datum_tag INT;
    p_datum_monat INT;
    
    p_rentdtbermod NCHAR(1);

    pbv_anzahl INT;
    pgd_rentendatum_erreicht INT;
    meldung NCHAR(100);

    ende_ss_monat INT;
    ende_ws_monat INT;

  BEGIN
    SET search_path TO sva4;
    ende_ss_monat := (SELECT txt::int FROM sys WHERE msnr = 'SSENDE');
    ende_ws_monat := (SELECT txt::int FROM sys WHERE msnr = 'WSENDE');

    p_datum := NULL;
    p_alter := 0;
    p_monat := 0;
		i_monat := 0;
    p_beamte_wie_arbeitnehmer := 0;
    p_prof_arbeitnehmer_wie_beamte_prof := 0;
		p_wiss_beamte_wie_prof := 0;
    p_dienstart := 0;	

    p_bundesland := (SELECT key_bundesland FROM sv_hochschule WHERE key_hochschule IS NOT NULL);

	--Länderspezifika:
    ----für Schleswig-Holstein
    IF p_bundesland = '01' THEN
      p_beamte_wie_arbeitnehmer := 1;
    END IF;	
    ----für Hamburg
    IF p_bundesland = '02' THEN
      p_beamte_wie_arbeitnehmer := 1;
    END IF;
    ----für Nordrhein-Westfalen
    IF p_bundesland = '05' THEN
      p_beamte_wie_arbeitnehmer := 1;
    END IF;
	----für Rheinland-Pfalz
	IF p_bundesland = '07' THEN
		p_beamte_wie_arbeitnehmer := 0;
	END IF;
	----für Baden-Württemberg
	IF p_bundesland = '08' THEN
		p_beamte_wie_arbeitnehmer := 1;
	END IF;	
	----für Saarland
    IF p_bundesland = '10' THEN
		p_beamte_wie_arbeitnehmer := 1;
		p_prof_arbeitnehmer_wie_beamte_prof := 1;
    END IF; 	
	----für Berlin					    
	IF p_bundesland = '11' THEN
		p_prof_arbeitnehmer_wie_beamte_prof := 1;
	END IF; 
	----für Brandenburg
    IF p_bundesland = '12' THEN
      p_beamte_wie_arbeitnehmer := 1;
    END IF;   
	----für Mecklenburg-Vorpommern
    IF p_bundesland = '13' THEN
      p_beamte_wie_arbeitnehmer := 1;
    END IF;
	----für Sachsen
    IF p_bundesland = '14' THEN
      p_beamte_wie_arbeitnehmer := 1;
    END IF;     
	----für Thüringen
    IF p_bundesland = '16' THEN
      p_beamte_wie_arbeitnehmer := 1;
    END IF; 
	
    p_pgd_join_id := row_pgd.pgd_join_id;
    p_gebdat := row_pgd.pgd_geburtsdatum;
    p_gebdat_tag := EXTRACT(day FROM p_gebdat);
    p_gebdat_monat := EXTRACT(month FROM p_gebdat);
    p_gebdat_jahr := EXTRACT(year FROM p_gebdat);

    p_rentendatum := row_pgd.pgd_rentendatum;
    p_rentendatum_tag := EXTRACT(day FROM p_rentendatum);
    p_rentendatum_monat := EXTRACT(month FROM p_rentendatum);
    p_rentendatum_jahr := EXTRACT(year FROM p_rentendatum);

    p_alter_alt := row_pgd.pgd_rentenalter;
    p_monat_alt := row_pgd.pgd_rentenmonat;

    p_rentdtbermod := row_pgd.pgd_rentdtbermod;

    pbv_anzahl := (SELECT COUNT(*) FROM pbv, k_vertragsart
                    WHERE pbv_pgd_join_id = p_pgd_join_id 
											AND pbv.pbv_art = k_vertragsart.key_vertragsart
											AND pbv.pbv_von <= current_date
                      AND (pbv.pbv_bis IS NULL OR pbv.pbv_bis >= current_date) AND pbv_status = 0
											AND k_vertragsart.rentenber_relevant = 'J');

    pgd_rentendatum_erreicht := (SELECT COUNT(*) FROM pgd
                                  WHERE pgd_join_id = p_pgd_join_id AND ((pgd_rentendatum < current_date) AND (pgd_austrittsdatum < current_date))
                                    AND pgd_status = 0);


		IF (p_rentdtbermod = 'E') THEN
			----Berechnung des Rentenalters/-monats auf Basis des Geburts- und Rentendatums:
			----Berechnung des Rentenalters und -monats:
			----Berechnung der Monate

			p_datum := p_rentendatum;

			p_monat := (((p_rentendatum_jahr - p_gebdat_jahr)) * 12 + (p_rentendatum_monat - p_gebdat_monat));

			IF p_gebdat_tag = 1 THEN
				p_monat := p_monat + 1;
			END IF;
			
			----Berechnung des Rentenalters
			p_alter := (p_monat - MOD(p_monat,12))/12;

			----Berechnung des Rentenmonats
			p_monat := MOD(p_monat,12);
			
			row_pgd.pgd_rentendatum := p_datum;
			row_pgd.pgd_rentenalter := p_alter;
			row_pgd.pgd_rentenmonat := p_monat;
		ELSE --  Rentenalterberechnung
			-- Prüfung ob gültiges BV vorliegt
			IF pbv_anzahl = 0 THEN
				--RAISE EXCEPTION -746, 0, 'Keine Rentendatenberechnung, da kein aktuelles, gültiges PBV vorliegt!!!';
				--nur wenn Rentendatum oder Austrittsdatum zum Tagesdatum noch nicht erreicht wurden:
				IF pgd_rentendatum_erreicht = 0 THEN
					p_datum := NULL;
					p_alter := 0;
					p_monat := 0;
					meldung = 'Keine Rentendatenberechnung, da kein aktuelles, gültiges Beschäftigungsverhältnis vorliegt!!!';

					row_pgd.pgd_rentendatum := p_datum;
					row_pgd.pgd_rentenalter := p_alter;
					row_pgd.pgd_rentenmonat := p_monat;
				ELSE
					row_pgd.pgd_rentendatum := p_rentendatum;
					row_pgd.pgd_rentenalter := p_alter_alt;
					row_pgd.pgd_rentenmonat := p_monat_alt;
					meldung = 'Keine Rentendatenberechnung, da Person sich bereits im Ruhestand befindet bzw. ausgeschieden ist!!!';
				END IF;
			ELSE
				p_vertragsart := (SELECT MAX(his_system_key) FROM k_vertragsart, pbv
														WHERE pbv.pbv_art = k_vertragsart.key_vertragsart
																		AND pbv_pgd_join_id = p_pgd_join_id AND pbv.pbv_von <= current_date
																		AND (pbv.pbv_bis IS NULL OR pbv.pbv_bis >= current_date) AND pbv_status = 0
																		AND k_vertragsart.rentenber_relevant = 'J');
																		
				-- Spezifika Schleswig-Holstein ## verbeamtete Wissenschaftler werden wie Professoren berechnet
				p_dienstart := (SELECT MIN(bund_dienstart)::INT FROM k_dienstart, pbv 
															WHERE pbv.pbv_dienstart = k_dienstart.key_dienstart
																			AND pbv_pgd_join_id = p_pgd_join_id AND pbv.pbv_von <= current_date
																			AND (pbv.pbv_bis IS NULL OR pbv.pbv_bis >= current_date) AND pbv_status = 0);
				
				-- wenn Person verbeamteter Wissenschaftler, dann Parameter setzen und später wie Prof berechnen
				IF (p_dienstart = 1) AND ((p_bundesland = '01') OR (p_bundesland = '07')) AND (p_vertragsart LIKE 'B%') THEN
					p_wiss_beamte_wie_prof := 1;
				END IF;																		
																		
				IF pgd_rentendatum_erreicht = 1 THEN
					p_datum := p_rentendatum;
					p_alter := p_alter_alt;
					p_monat := p_monat_alt;
					meldung = 'Keine Rentendatenberechnung, da Person sich bereits im Ruhestand befindet bzw. ausgeschieden ist!!!';
				ELSE
					-- Rentenalterberechnung für alle Nicht-Beamten bzw. Bundesländer mit einer
					-- anderen Berechung für die Beamten
					IF (p_vertragsart NOT LIKE 'B%') OR (p_beamte_wie_arbeitnehmer = 1) THEN
							-- Jahrgänge 1945 und älter:
							IF p_gebdat_jahr <= 1945 THEN
								p_alter := 65;
								p_monat := 0;
							END IF;
							-- Jahrgänge 1946 bis 1957:
							IF p_gebdat_jahr >= 1946 AND p_gebdat_jahr <= 1957 THEN
								p_alter := 65;
								p_monat := ((65*12) + (p_gebdat_jahr - 1946));
								p_monat := MOD(p_monat,12);
							END IF;
							-- Jahrgänge 1958 bis 1963:
							IF p_gebdat_jahr >= 1958 AND p_gebdat_jahr <= 1963 THEN
								p_alter := 66;
								p_monat := ((65*12) + (p_gebdat_jahr - 1946) * 2);
								p_monat := MOD(p_monat,12);
							END IF;
							-- Jahrgänge 1964 und jünger:
							IF p_gebdat_jahr >= 1964 THEN
								p_alter := 67;
								p_monat := 0;
							END IF;
					-- Beamte
					ELSE
						p_alter := 65;
						p_monat := 0;

						-- für Rheinland-Pfalz
						IF p_bundesland = '07' THEN
							-- Jahrgänge 1950 und älter:
							IF p_gebdat_jahr <= 1950 THEN
								p_alter := 65;
								p_monat := 0;
							END IF;
							-- Jahrgänge 1951 bis 1954:
							IF p_gebdat_jahr >= 1951 AND p_gebdat_jahr <= 1954 THEN
								p_alter := 65;
								i_monat := ((65*12) + (p_gebdat_jahr - 1951) + 1);
								p_monat := MOD(i_monat, 12);
								p_alter := FLOOR(i_monat/12);
							END IF;
							-- Jahrgänge 1955 bis 1963:
							IF p_gebdat_jahr >= 1955 AND p_gebdat_jahr <= 1963 THEN
								p_alter := 65;
								i_monat := ((65*12) + ((p_gebdat_jahr - 1951) * 2) - 2);
								p_monat := MOD(i_monat, 12); 							
								p_alter := FLOOR(i_monat/12);
							END IF;
							-- Jahrgänge 1964 und jünger:
							IF p_gebdat_jahr >= 1964 THEN
								p_alter := 67;
								p_monat := 0;
							END IF;
						END IF;		
					END IF;
					
					IF (p_prof_arbeitnehmer_wie_beamte_prof = 1 AND (p_vertragsart = 'AP' OR p_vertragsart = 'XP')) THEN
						p_alter := 65;
						p_monat := 0;					
					END IF;

					-- Berechnung der Arbeitnehmer bzw. Beamte, die nach den gleichen Regeln berechnet werden
					IF (p_vertragsart NOT LIKE 'B%') OR (p_beamte_wie_arbeitnehmer = 1) THEN
						p_datum := p_gebdat - (-1 + date_part('day', row_pgd.pgd_geburtsdatum)||'DAY')::interval
																						+ ((1 + p_monat)||'MONTHS')::INTERVAL
																										+ (p_alter||'YEARS')::INTERVAL
																										- INTERVAL '1 DAYS';
					END IF;
										
					--Rentenalterberechnung für Beamten (außer Professoren):
					IF (p_vertragsart LIKE 'B%') AND (p_beamte_wie_arbeitnehmer = 0) THEN
						p_datum := p_gebdat - (-1 + date_part('day', row_pgd.pgd_geburtsdatum)||'DAY')::interval
																										+ INTERVAL '1 MONTHS'
																										+ (p_alter||'YEARS')::INTERVAL
																										- INTERVAL '1 DAYS';
					END IF;

					--Rentenalterberechnung für Beamten (außer Professoren) für Rheinland-Pfalz:
					IF (p_vertragsart LIKE 'B%') AND (p_beamte_wie_arbeitnehmer = 0) AND (p_bundesland = '07') THEN
						p_datum := p_gebdat - (-1 + date_part('day', row_pgd.pgd_geburtsdatum)||'DAY')::interval
																										+ ((1 + p_monat)||'MONTHS')::INTERVAL
																										+ (p_alter||'YEARS')::INTERVAL
																										- INTERVAL '1 DAYS';						
					END IF; 
				
					-- Sonderfall: Am Monats- bzw. Semesterersten Geborene:
					IF p_gebdat_tag = 1 THEN
						p_datum := p_datum + INTERVAL '1 DAYS' - INTERVAL '1 MONTH' - INTERVAL '1 DAYS';
					END IF;

					-- Berechnung für Professoren und verbeamtete Wissenschaftler in Schleswig-Holstein und Rheinland-Pfalz
					IF (p_vertragsart LIKE '%P') OR (p_wiss_beamte_wie_prof = 1) THEN					
						p_datum_monat := EXTRACT(month FROM p_datum);
						p_datum_tag := EXTRACT(day FROM p_datum);

						----Berechnung des Rentendatums (Sommersemester):
						IF p_datum_monat > ende_ws_monat AND p_datum_monat <= ende_ss_monat THEN
							----für Nordrhein-Westfalen
							IF p_bundesland = '05' THEN
								----Berechnung des Rentendatums (vorlesungsfreie Zeit = August):
								IF p_datum_monat = 8 THEN
									p_datum := p_datum - ((p_datum_tag - 1)||'DAY')::interval
													+ ((9 - p_datum_monat)||'MONTH')::interval
													- INTERVAL '1 DAYS';
								ELSE
									p_datum := p_datum - ((p_datum_tag - 1)||'DAY')::interval
													+ ((9 - p_datum_monat - 1)||'MONTH')::interval
													- INTERVAL '1 DAYS';								
								END IF;
							ELSE
								p_datum := p_datum - ((p_datum_tag - 1)||'DAY')::interval
												+ ((ende_ss_monat - p_datum_monat + 1)||'MONTH')::interval
												- INTERVAL '1 DAYS';							
							END IF;
						END IF;

						----Berechnung des Rentendatums (Wintersemester; 2. Semesterhälfte):
						IF p_datum_monat <= ende_ws_monat THEN
							 p_datum := p_datum - ((p_datum_tag - 1)||'DAY')::interval
												+ ((ende_ws_monat - p_datum_monat + 1)||'MONTH')::interval
												- INTERVAL '1 DAYS';
						END IF;

						----Berechnung des Rentendatums (Wintersemester; 1. Semesterhälfte, aber nicht August (vorlesungsfreie Zeit):
						IF p_bundesland = '05' THEN
							IF ((p_datum_monat > ende_ss_monat) AND (p_datum_monat <> 8)) THEN
								p_datum := p_datum - ((p_datum_tag - 1)||'DAY')::interval
													+ ((13 - p_datum_monat + ende_ws_monat)||'MONTH')::interval
													- INTERVAL '1 DAYS';
							END IF;
						ELSE
							IF p_datum_monat > ende_ss_monat THEN
								p_datum := p_datum - ((p_datum_tag - 1)||'DAY')::interval
													+ ((13 - p_datum_monat + ende_ws_monat)||'MONTH')::interval
													- INTERVAL '1 DAYS';
							END IF;						
						END IF;
					END IF;
				END IF;

				row_pgd.pgd_rentendatum := p_datum;
				row_pgd.pgd_rentenalter := p_alter;
				row_pgd.pgd_rentenmonat := p_monat;
			END IF;


			IF pbv_anzahl > 0 THEN
				--Neue Wiedervorlagen eintragen:
				INSERT INTO wvl (wvl_pgd_join_id, wvl_tabellenname, wvl_tab_serial, wvl_tab_spalte, wvl_status,
											 wvl_datum, wvl_termin, wvl_grund,
											 wvl_verarbeitung, wvl_vermerk, wvl_sachbearb, wvl_bearb_status)
				SELECT pgd_join_id, 'pgd', pgd_join_id, 'pgd_rentendatum', 0, 
							current_date, pgd_rentendatum - (((SELECT vorlaufzeit FROM sv_konfig_wvl WHERE feld_name = 'pgd_rentendatum')::text || 'DAY')::interval), (SELECT wvl_grund FROM sv_konfig_wvl WHERE feld_name = 'pgd_rentendatum'), 
							 'A', to_char(p_datum, 'DD.MM.YYYY'), pgd_inhaber, 'N'
				FROM pgd			 
				WHERE (pgd.pgd_austrittsdatum IS NULL OR pgd.pgd_austrittsdatum >= current_date)
					AND pgd_join_id = p_pgd_join_id
					AND NOT EXISTS (SELECT wvl_pgd_join_id FROM wvl WHERE wvl_tab_spalte = 'pgd_rentendatum' AND wvl_pgd_join_id = p_pgd_join_id);
			END IF;

			--Aktualisierung der Wiedervorlagen:
			UPDATE wvl SET wvl_datum = current_date,
										 wvl_vermerk = to_char(p_datum, 'DD.MM.YYYY'),
										 wvl_termin =  p_datum - (((SELECT vorlaufzeit FROM sv_konfig_wvl WHERE feld_name = 'pgd_rentendatum')||'DAY')::interval)
			 WHERE wvl_tab_spalte = 'pgd_rentendatum'
				 AND row_pgd.pgd_rentendatum IS NOT NULL
				 AND wvl_pgd_join_id IN
							 (SELECT DISTINCT pbv.pbv_pgd_join_id FROM pbv, k_vertragsart
								 WHERE pbv.pbv_pgd_join_id = p_pgd_join_id
								 AND pbv.pbv_von <= current_date AND (pbv.pbv_bis IS NULL OR pbv.pbv_bis >= current_date)
 								 AND pbv.pbv_status = 0
								 AND pbv.pbv_art = k_vertragsart.key_vertragsart
								 AND k_vertragsart.rentenber_relevant = 'J')
				 AND wvl_pgd_join_id IN
					 (SELECT DISTINCT pgd.pgd_join_id FROM pgd
						 WHERE pgd.pgd_eintrittsdatum <= current_date AND (pgd.pgd_austrittsdatum IS NULL OR pgd.pgd_austrittsdatum >= current_date) AND pgd.pgd_status = 0);


				meldung := 'Erfolgreich berechnet!';

		END IF;


    --Rückgabewerte
    RETURN row_pgd;

  END;
$_$;


--
-- Name: rentendatum_alter(sva4.pgd, sva4.pgd); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.rentendatum_alter(sva4.pgd, sva4.pgd) RETURNS record
    LANGUAGE plpgsql
    AS $_$

DECLARE
		pgd_entry_old ALIAS FOR $1;
		pgd_entry_new ALIAS FOR $2;		

    p_pgd_join_id INT;

    p_bundesland NCHAR(2);
    p_vertragsart NCHAR(2);
    p_alter INT;
    p_monat INT;
		i_monat INT;
    p_alter_alt INT;
    p_monat_alt INT;
    p_datum DATE;
    p_beamte_wie_arbeitnehmer INT;
    p_prof_arbeitnehmer_wie_beamte_prof INT;
    p_wiss_beamte_wie_prof INT;
		p_semester_key NCHAR(5);
		p_prof_semester_vorlesung NCHAR(1);		
    p_dienstart INT;	

    p_rentendatum DATE;
    p_rentendatum_tag INT;
    p_rentendatum_monat INT;
    p_rentendatum_jahr INT;

    p_gebdat DATE;
    p_gebdat_tag INT;
    p_gebdat_monat INT;
    p_gebdat_jahr INT;

    p_datum_tag INT;
    p_datum_monat INT;
		p_datum_jahr INT;
    
    p_rentdtbermod NCHAR(1);

    pbv_anzahl INT;
		pbv_vertragsart_anzahl INT;
		pbv_vertragsart_anzahl_unbefristet INT;
    pgd_rentendatum_erreicht INT;
    meldung NCHAR(100);

    ende_ss_monat INT;
    ende_ws_monat INT;

    beginn_vl_ss_monat DATE;
    beginn_vl_ws_monat DATE;		
    ende_vl_ss_monat DATE;
    ende_vl_ws_monat DATE;		

  BEGIN
    SET search_path TO sva4;
    ende_ss_monat := (SELECT txt::int FROM sys WHERE msnr = 'SSENDE');
    ende_ws_monat := (SELECT txt::int FROM sys WHERE msnr = 'WSENDE');

		p_prof_semester_vorlesung := (SELECT txt FROM sys WHERE msnr = 'eintritt_ruhestand_profs_semesterende_vorlesungsende');
		
    p_datum := NULL;
    p_alter := 0;
    p_monat := 0;
		i_monat := 0;
    p_beamte_wie_arbeitnehmer := 0;
    p_prof_arbeitnehmer_wie_beamte_prof := 0;
		p_wiss_beamte_wie_prof := 0;
    p_dienstart := 0;	

    p_bundesland := (SELECT key_bundesland FROM sv_hochschule WHERE key_hochschule IS NOT NULL);

	--Laenderspezifika:
    ----fuer Schleswig-Holstein
    IF p_bundesland = '01' THEN
      p_beamte_wie_arbeitnehmer := 1;
    ELSIF p_bundesland = '02' THEN	
    ----fuer Hamburg
      p_beamte_wie_arbeitnehmer := 1;
    ELSIF p_bundesland = '05' THEN
    ----fuer Nordrhein-Westfalen
      p_beamte_wie_arbeitnehmer := 1;
    ELSIF p_bundesland = '07' THEN
		----fuer Rheinland-Pfalz
			p_beamte_wie_arbeitnehmer := 0;
		ELSIF p_bundesland = '08' THEN
		----fuer Baden-Wuerttemberg
			p_beamte_wie_arbeitnehmer := 1;
		ELSIF	p_bundesland = '10' THEN
		----fuer Saarland
			p_beamte_wie_arbeitnehmer := 1;
			p_prof_arbeitnehmer_wie_beamte_prof := 1;
    ELSIF p_bundesland = '11' THEN
		----fuer Berlin					    
			p_prof_arbeitnehmer_wie_beamte_prof := 1;
		ELSIF p_bundesland = '12' THEN
		----fuer Brandenburg
      p_beamte_wie_arbeitnehmer := 1;
    ELSIF p_bundesland = '13' THEN
		----fuer Mecklenburg-Vorpommern
      p_beamte_wie_arbeitnehmer := 1;
    ELSIF p_bundesland = '14' THEN
		----fuer Sachsen
      p_beamte_wie_arbeitnehmer := 1;
    ELSIF p_bundesland = '15' THEN
    ----fuer Sachsen-Anhalt
      p_beamte_wie_arbeitnehmer := 0;
    ELSIF p_bundesland = '16' THEN
		----fuer Thueringen
      p_beamte_wie_arbeitnehmer := 1;
    END IF; 
	
    p_pgd_join_id := pgd_entry_new.pgd_join_id;
    p_gebdat := pgd_entry_new.pgd_geburtsdatum;
    p_gebdat_tag := EXTRACT(day FROM p_gebdat);
    p_gebdat_monat := EXTRACT(month FROM p_gebdat);
    p_gebdat_jahr := EXTRACT(year FROM p_gebdat);

    p_rentendatum := pgd_entry_new.pgd_rentendatum;
    p_rentendatum_tag := EXTRACT(day FROM p_rentendatum);
    p_rentendatum_monat := EXTRACT(month FROM p_rentendatum);
    p_rentendatum_jahr := EXTRACT(year FROM p_rentendatum);

    p_alter_alt := pgd_entry_new.pgd_rentenalter;
    p_monat_alt := pgd_entry_new.pgd_rentenmonat;

    p_rentdtbermod := pgd_entry_new.pgd_rentdtbermod;

    pbv_anzahl := (SELECT COUNT(*) FROM pbv, k_vertragsart
                    WHERE pbv_pgd_join_id = p_pgd_join_id 
											AND pbv.pbv_art = k_vertragsart.key_vertragsart
                      AND (pbv.pbv_bis IS NULL OR pbv.pbv_bis >= current_date) AND pbv_status = 0
											AND k_vertragsart.rentenber_relevant = 'J');

    pgd_rentendatum_erreicht := (SELECT COUNT(*) FROM pgd
                                  WHERE pgd_join_id = p_pgd_join_id AND ((pgd_rentendatum < current_date) AND (pgd_austrittsdatum < current_date))
                                    AND pgd_status = 0);


		IF (p_rentdtbermod = 'E') THEN
			----Berechnung des Rentenalters/-monats auf Basis des Geburts- und Rentendatums:
			----Berechnung des Rentenalters und -monats:
			----Berechnung der Monate

			p_datum := p_rentendatum;

			p_monat := (((p_rentendatum_jahr - p_gebdat_jahr)) * 12 + (p_rentendatum_monat - p_gebdat_monat));

			IF p_gebdat_tag = 1 THEN
				p_monat := p_monat + 1;
			END IF;
			
			----Berechnung des Rentenalters
			p_alter := (p_monat - MOD(p_monat,12))/12;

			----Berechnung des Rentenmonats
			p_monat := MOD(p_monat,12);
			
			pgd_entry_new.pgd_rentendatum := p_datum;
			pgd_entry_new.pgd_rentenalter := p_alter;
			pgd_entry_new.pgd_rentenmonat := p_monat;
		ELSIF (p_rentdtbermod = 'B') THEN	--  Rentenalterberechnung
			-- Pruefung ob gueltiges BV vorliegt
			IF pbv_anzahl = 0 THEN
				--RAISE EXCEPTION -746, 0, 'Keine Rentendatenberechnung, da kein aktuelles, gueltiges PBV vorliegt!!!';
				--nur wenn Rentendatum oder Austrittsdatum zum Tagesdatum noch nicht erreicht wurden:
				IF pgd_rentendatum_erreicht = 0 THEN
					p_datum := NULL;
					p_alter := 0;
					p_monat := 0;
					meldung = 'Keine Rentendatenberechnung, da kein aktuelles, gueltiges Beschaeftigungsverhaeltnis vorliegt!!!';

					pgd_entry_new.pgd_rentendatum := p_datum;
					pgd_entry_new.pgd_rentenalter := p_alter;
					pgd_entry_new.pgd_rentenmonat := p_monat;
				ELSE
					pgd_entry_new.pgd_rentendatum := p_rentendatum;
					pgd_entry_new.pgd_rentenalter := p_alter_alt;
					pgd_entry_new.pgd_rentenmonat := p_monat_alt;
					meldung = 'Keine Rentendatenberechnung, da Person sich bereits im Ruhestand befindet bzw. ausgeschieden ist!!!';
				END IF;
			ELSE
				-- Pruefen, ob mehr als eine BV-Art vorliegt:
				pbv_vertragsart_anzahl := (SELECT COUNT(DISTINCT his_system_key) FROM pbv, k_vertragsart
                    WHERE pbv_pgd_join_id = p_pgd_join_id 
											AND pbv.pbv_art = k_vertragsart.key_vertragsart
                      AND (pbv.pbv_bis IS NULL OR pbv.pbv_bis >= current_date) AND pbv_status = 0
											AND k_vertragsart.rentenber_relevant = 'J');
											
				-- Pruefen, ob ein unbefristetes BV existiert bzw. mehrere BV mit identischer BV-Art
				pbv_vertragsart_anzahl_unbefristet := (SELECT COUNT(DISTINCT his_system_key) FROM pbv, k_vertragsart
									WHERE pbv_pgd_join_id = p_pgd_join_id 
										AND pbv.pbv_art = k_vertragsart.key_vertragsart
										AND (pbv.pbv_bis IS NULL AND pbv.pbv_befr_bis IS NULL) AND pbv_status = 0
										AND k_vertragsart.rentenber_relevant = 'J');											

				IF (pbv_vertragsart_anzahl != 1 AND pbv_vertragsart_anzahl_unbefristet != 1) THEN
					pgd_entry_new.pgd_rentdtbermod := 'E';
					p_datum := NULL;
					p_alter := NULL;
					p_monat := NULL;					
					meldung = 'Keine Rentendatenberechnung, da mehrere Beschaeftigungsverhaeltnisarten vorliegen!!!';
				ELSE
					IF (pbv_vertragsart_anzahl = 1) THEN					
						p_vertragsart := (SELECT DISTINCT k_vertragsart.his_system_key FROM k_vertragsart, pbv
														 WHERE pbv.pbv_art = k_vertragsart.key_vertragsart
															 AND k_vertragsart.rentenber_relevant = 'J'
															 AND pbv.pbv_pgd_join_id = p_pgd_join_id 
															 AND pbv.pbv_status = 0						
															 AND (pbv.pbv_bis IS NULL OR pbv.pbv_bis >= current_date)						
															 AND pbv.pbv_von = 
																(SELECT DISTINCT MAX(pbv.pbv_von) FROM k_vertragsart, pbv
																	WHERE pbv.pbv_art = k_vertragsart.key_vertragsart
																		AND k_vertragsart.rentenber_relevant = 'J'
																		AND pbv.pbv_pgd_join_id = p_pgd_join_id 
																		AND pbv.pbv_status = 0						
																		AND (pbv.pbv_bis IS NULL OR pbv.pbv_bis >= current_date)));
					END IF;
					
					IF (pbv_vertragsart_anzahl_unbefristet = 1) THEN					
						p_vertragsart := (SELECT DISTINCT k_vertragsart.his_system_key FROM k_vertragsart, pbv
														 WHERE pbv.pbv_art = k_vertragsart.key_vertragsart
															 AND k_vertragsart.rentenber_relevant = 'J'
															 AND pbv.pbv_pgd_join_id = p_pgd_join_id 
															 AND pbv.pbv_status = 0						
															 AND (pbv.pbv_bis IS NULL AND pbv.pbv_befr_bis IS NULL)						
															 AND pbv.pbv_von = 
																(SELECT DISTINCT MAX(pbv.pbv_von) FROM k_vertragsart, pbv
																	WHERE pbv.pbv_art = k_vertragsart.key_vertragsart
																		AND k_vertragsart.rentenber_relevant = 'J'
																		AND pbv.pbv_pgd_join_id = p_pgd_join_id 
																		AND pbv.pbv_status = 0						
																		AND (pbv.pbv_bis IS NULL AND pbv.pbv_befr_bis IS NULL)));
					END IF;					
																			
					-- Spezifika Schleswig-Holstein ## verbeamtete Wissenschaftler werden wie Professoren berechnet
					p_dienstart := (SELECT MIN(bund_dienstart)::INT FROM k_dienstart, pbv 
																WHERE pbv.pbv_dienstart = k_dienstart.key_dienstart
																				AND pbv_pgd_join_id = p_pgd_join_id 
																				AND (pbv.pbv_bis IS NULL OR pbv.pbv_bis >= current_date) AND pbv_status = 0);
					
					-- wenn Person verbeamteter Wissenschaftler, dann Parameter setzen und spaeter wie Prof berechnen
					IF (p_dienstart = 1) AND ((p_bundesland = '01') OR (p_bundesland = '07')) AND (p_vertragsart LIKE 'B%') THEN
						p_wiss_beamte_wie_prof := 1;
					END IF;																		
																			
					IF pgd_rentendatum_erreicht = 1 THEN
						p_datum := p_rentendatum;
						p_alter := p_alter_alt;
						p_monat := p_monat_alt;
						meldung = 'Keine Rentendatenberechnung, da Person sich bereits im Ruhestand befindet bzw. ausgeschieden ist!!!';
					ELSE
						-- Rentenalterberechnung fuer alle Nicht-Beamten bzw. Bundeslaender mit einer
						-- anderen Berechung fuer die Beamten
						IF (p_vertragsart NOT LIKE 'B%') OR (p_beamte_wie_arbeitnehmer = 1) THEN
								-- Jahrgaenge 1945 und aelter:
								IF p_gebdat_jahr <= 1945 THEN
									p_alter := 65;
									p_monat := 0;
								END IF;
								-- Jahrgaenge 1946 bis 1957:
								IF p_gebdat_jahr >= 1946 AND p_gebdat_jahr <= 1957 THEN
									p_alter := 65;
									p_monat := ((65*12) + (p_gebdat_jahr - 1946));
									p_monat := MOD(p_monat,12);
								END IF;
								-- Jahrgaenge 1958 bis 1963:
								IF p_gebdat_jahr >= 1958 AND p_gebdat_jahr <= 1963 THEN
									p_alter := 66;
									p_monat := ((65*12) + (p_gebdat_jahr - 1946) * 2);
									p_monat := MOD(p_monat,12);
								END IF;
								-- Jahrgaenge 1964 und juenger:
								IF p_gebdat_jahr >= 1964 THEN
									p_alter := 67;
									p_monat := 0;
								END IF;
						-- Beamte
						ELSE
							p_alter := 65;
							p_monat := 0;

							-- fuer Rheinland-Pfalz
							IF p_bundesland = '07' THEN
								-- Jahrgaenge 1950 und aelter:
								IF p_gebdat_jahr <= 1950 THEN
									p_alter := 65;
									p_monat := 0;
								END IF;
								-- Jahrgaenge 1951 bis 1954:
								IF p_gebdat_jahr >= 1951 AND p_gebdat_jahr <= 1954 THEN
									p_alter := 65;
									i_monat := ((65*12) + (p_gebdat_jahr - 1951) + 1);
									p_monat := MOD(i_monat, 12);
									p_alter := FLOOR(i_monat/12);
								END IF;
								-- Jahrgaenge 1955 bis 1963:
								IF p_gebdat_jahr >= 1955 AND p_gebdat_jahr <= 1963 THEN
									p_alter := 65;
									i_monat := ((65*12) + ((p_gebdat_jahr - 1951) * 2) - 2);
									p_monat := MOD(i_monat, 12); 							
									p_alter := FLOOR(i_monat/12);
								END IF;
								-- Jahrgaenge 1964 und juenger:
								IF p_gebdat_jahr >= 1964 THEN
									p_alter := 67;
									p_monat := 0;
								END IF;
							END IF;
							
							-- fuer Sachsen-Anhalt
							IF p_bundesland = '15' THEN
								-- Jahrgaenge 1953 und aelter:
								IF p_gebdat_jahr <= 1953 THEN
									p_alter := 65;
									p_monat := 0;
								END IF;
								-- Jahrgaenge 1954 bis 1962:
								IF p_gebdat_jahr >= 1954 AND p_gebdat_jahr <= 1962 THEN
									p_alter := 65;
									i_monat := ((65*12) + ((p_gebdat_jahr - 1954) * 2) + 2);
									p_monat := MOD(i_monat, 12); 							
									p_alter := FLOOR(i_monat/12);
								END IF;
								-- Jahrgang 1963:
								IF p_gebdat_jahr = 1963 THEN
									p_alter := 66;
									p_monat := 9;
								END IF;								
								-- Jahrgaenge 1964 und juenger:
								IF p_gebdat_jahr >= 1964 THEN
									p_alter := 67;
									p_monat := 0;
								END IF;
							END IF;							
						END IF;
						
						IF (p_prof_arbeitnehmer_wie_beamte_prof = 1 AND (p_vertragsart = 'AP' OR p_vertragsart = 'XP')) THEN
							p_alter := 65;
							p_monat := 0;					
						END IF;

						-- Berechnung der Arbeitnehmer bzw. Beamte, die nach den gleichen Regeln berechnet werden
						IF (p_vertragsart NOT LIKE 'B%') OR (p_beamte_wie_arbeitnehmer = 1) THEN
							p_datum := p_gebdat - (-1 + date_part('day', pgd_entry_new.pgd_geburtsdatum)||'DAY')::INTERVAL
																							+ ((1 + p_monat)||'MONTHS')::INTERVAL
																											+ (p_alter||'YEARS')::INTERVAL
																											- INTERVAL '1 DAYS';
						END IF;
											
						--Rentenalterberechnung fuer Beamten (ausser Professoren):
						IF (p_vertragsart LIKE 'B%') AND (p_beamte_wie_arbeitnehmer = 0) THEN
							p_datum := p_gebdat - (-1 + date_part('day', pgd_entry_new.pgd_geburtsdatum)||'DAY')::INTERVAL
																											+ INTERVAL '1 MONTHS'
																											+ (p_alter||'YEARS')::INTERVAL
																											- INTERVAL '1 DAYS';
						END IF;

						--Rentenalterberechnung fuer Beamten (ausser Professoren) fuer Rheinland-Pfalz:
						IF (p_vertragsart LIKE 'B%') AND (p_beamte_wie_arbeitnehmer = 0) AND (p_bundesland = '07') THEN
							p_datum := p_gebdat - (-1 + date_part('day', pgd_entry_new.pgd_geburtsdatum)||'DAY')::INTERVAL
																											+ ((1 + p_monat)||'MONTHS')::INTERVAL
																											+ (p_alter||'YEARS')::INTERVAL
																											- INTERVAL '1 DAYS';						
						END IF;
						
						--Rentenalterberechnung fuer Beamten (ausser Professoren) fuer Sachsen-Anhalt:
						IF (p_vertragsart LIKE 'B%') AND (p_beamte_wie_arbeitnehmer = 0) AND (p_bundesland = '15') THEN
							p_datum := p_gebdat - (-1 + date_part('day', pgd_entry_new.pgd_geburtsdatum)||'DAY')::INTERVAL
																											+ ((1 + p_monat)||'MONTHS')::INTERVAL
																											+ (p_alter||'YEARS')::INTERVAL
																											- INTERVAL '1 DAYS';						
						END IF; 						
					
						-- Sonderfall: Am Monats- bzw. Semesterersten Geborene:
						IF p_gebdat_tag = 1 THEN
							p_datum := p_datum + INTERVAL '1 DAYS' - INTERVAL '1 MONTH' - INTERVAL '1 DAYS';
						END IF;

						-- Berechnung fuer Professoren und verbeamtete Wissenschaftler (hier: Schleswig-Holstein u. Rheinland-Pfalz)
						IF (p_vertragsart LIKE '%P') OR (p_wiss_beamte_wie_prof = 1) THEN					
							p_datum_jahr := EXTRACT(year FROM p_datum);
							p_datum_monat := EXTRACT(month FROM p_datum);
							p_datum_tag := EXTRACT(day FROM p_datum);

							IF p_prof_semester_vorlesung = 'V' THEN
								p_semester_key := p_datum_jahr::text||'1';
								beginn_vl_ss_monat := (SELECT vorlesung_von FROM k_semester WHERE his_system_key = p_semester_key AND vorlesung_von IS NOT NULL);
								ende_vl_ss_monat := (SELECT vorlesung_bis FROM k_semester WHERE his_system_key = p_semester_key AND vorlesung_bis IS NOT NULL);
								-- wenn eines der Datumsfelder leer ist, erfolgt Zugriff auf Semesterende
								IF beginn_vl_ss_monat IS NULL OR ende_vl_ss_monat IS NULL THEN
									p_prof_semester_vorlesung := 'S';
								END IF;
								
								-- Unterscheidung, welches Wintersemester zur Prüfung genommen wird
								IF p_datum_monat > 6 THEN 
									p_semester_key := p_datum_jahr::text||'2';
								ELSE 
									p_semester_key := (p_datum_jahr - 1)::text||'2';
								END IF;

								beginn_vl_ws_monat := (SELECT vorlesung_von FROM k_semester WHERE his_system_key = p_semester_key AND vorlesung_von IS NOT NULL);
								ende_vl_ws_monat := (SELECT vorlesung_bis FROM k_semester WHERE his_system_key = p_semester_key AND vorlesung_bis IS NOT NULL);			
								-- wenn eines der Datumsfelder leer ist, erfolgt Zugriff auf Semesterende
								IF beginn_vl_ws_monat IS NULL OR ende_vl_ws_monat IS NULL THEN
									p_prof_semester_vorlesung := 'S';
								END IF;
							END IF;							
						
							----Berechnung des Rentendatums (Sommersemester):
							IF p_datum_monat > ende_ws_monat AND p_datum_monat <= ende_ss_monat THEN
								----fuer Nordrhein-Westfalen und Renteneintrittsdatum während Vorlesungszeit
								---- Renteneintritt am Monatsende des Monats ende_vl_ss_monat, da Vorlesungsende auch im August sein kann						
								IF p_bundesland = '05' AND p_prof_semester_vorlesung = 'V' AND p_datum >= beginn_vl_ss_monat AND p_datum <= ende_vl_ss_monat THEN
									p_datum:= (EXTRACT(YEAR FROM ende_vl_ss_monat)::NCHAR(4)||'-'||(EXTRACT (MONTH FROM ende_vl_ss_monat) + 1)::NCHAR(2)||'-01' )::DATE - INTERVAL '1 DAYS';									
								-- Renteneintritt am Semesterende des Sommersemesters
									ELSE
									p_datum := p_datum - ((p_datum_tag - 1)||'DAY')::INTERVAL
													+ ((ende_ss_monat - p_datum_monat + 1)||'MONTH')::INTERVAL
														- INTERVAL '1 DAYS';										
									END IF;
								ELSE
							----Berechnung des Rentendatums (Wintersemester):	
							-- für Nordrhein-Westfalen und Renteneintritt während der Vorlesungszeit im Wintersemester, dann am Monatsende des Monats ende_vl_ws_monat
								IF p_bundesland = '05' AND p_prof_semester_vorlesung = 'V' AND p_datum >= beginn_vl_ws_monat AND p_datum <= ende_vl_ws_monat THEN

									p_datum := (EXTRACT (YEAR FROM ende_vl_ws_monat)::NCHAR(4)||'-'||(EXTRACT (MONTH FROM ende_vl_ws_monat) + 1)::NCHAR(2)||'-01')::DATE - INTERVAL '1 DAYS';
								-- Renteneintritt am Semesterende des Wintersemesters	
								ELSE
									----Berechnung des Rentendatums (Wintersemester; 2. Semesterhaelfte):
									IF p_datum_monat <= ende_ws_monat THEN
										p_datum := p_datum - ((p_datum_tag - 1)||'DAY')::INTERVAL
														+ ((ende_ws_monat - p_datum_monat + 1)||'MONTH')::INTERVAL
														- INTERVAL '1 DAYS';
									----Berechnung des Rentendatums (Wintersemester; 1. Semesterhaelfte:								
									ELSE								
										p_datum := p_datum - ((p_datum_tag - 1)||'DAY')::INTERVAL
														+ ((13 - p_datum_monat + ende_ws_monat)||'MONTH')::INTERVAL
														- INTERVAL '1 DAYS';
									END IF;						
								END IF;						
							END IF;
						END IF;
					END IF;
				END IF;

				pgd_entry_new.pgd_rentendatum := p_datum;
				pgd_entry_new.pgd_rentenalter := p_alter;
				pgd_entry_new.pgd_rentenmonat := p_monat;				
			END IF;


			IF (pgd_entry_old != pgd_entry_new) THEN
				IF pbv_anzahl > 0 THEN
					--Neue Wiedervorlagen eintragen:
					INSERT INTO wvl (wvl_pgd_join_id, wvl_tabellenname, wvl_tab_serial, wvl_tab_spalte, wvl_status,
												 wvl_datum, wvl_termin, wvl_grund,
												 wvl_verarbeitung, wvl_vermerk, wvl_sachbearb, wvl_bearb_status)
					SELECT pgd_join_id, 'pgd', pgd_join_id, 'pgd_rentendatum', 0, 
								current_date, pgd_rentendatum - (((SELECT vorlaufzeit FROM sv_konfig_wvl WHERE feld_name = 'pgd_rentendatum')::text || 'DAY')::INTERVAL), (SELECT wvl_grund FROM sv_konfig_wvl WHERE feld_name = 'pgd_rentendatum'), 
								 'A', to_char(p_datum, 'DD.MM.YYYY'), pgd_inhaber, 'N'
					FROM pgd			 
					WHERE (pgd.pgd_austrittsdatum IS NULL OR pgd.pgd_austrittsdatum >= current_date)
						AND pgd_join_id = p_pgd_join_id
						AND NOT EXISTS (SELECT wvl_pgd_join_id FROM wvl WHERE wvl_tab_spalte = 'pgd_rentendatum' AND wvl_pgd_join_id = p_pgd_join_id);
				END IF;


				--Aktualisierung der Wiedervorlagen:
				UPDATE wvl SET wvl_datum = current_date,
											 wvl_vermerk = to_char(p_datum, 'DD.MM.YYYY'),
											 wvl_termin =  p_datum - (((SELECT vorlaufzeit FROM sv_konfig_wvl WHERE feld_name = 'pgd_rentendatum')||'DAY')::INTERVAL)
				 WHERE wvl_tab_spalte = 'pgd_rentendatum'
					 AND pgd_entry_new.pgd_rentendatum IS NOT NULL
					 AND wvl_pgd_join_id IN
								 (SELECT DISTINCT pbv.pbv_pgd_join_id FROM pbv, k_vertragsart
									 WHERE pbv.pbv_pgd_join_id = p_pgd_join_id
									 AND (pbv.pbv_bis IS NULL OR pbv.pbv_bis >= current_date)
									 AND pbv.pbv_status = 0
									 AND pbv.pbv_art = k_vertragsart.key_vertragsart
									 AND k_vertragsart.rentenber_relevant = 'J')
					 AND wvl_pgd_join_id IN
						 (SELECT DISTINCT pgd.pgd_join_id FROM pgd
							 WHERE pgd.pgd_eintrittsdatum <= current_date AND (pgd.pgd_austrittsdatum IS NULL OR pgd.pgd_austrittsdatum >= current_date) AND pgd.pgd_status = 0);

				END IF;

				meldung := 'Erfolgreich berechnet!';
		ELSE
		
		END IF;


    --Rueckgabewerte
    RETURN pgd_entry_new;

  END;
$_$;


--
-- Name: rentendatum_alter_pbv(sva4.pbv, sva4.pbv); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.rentendatum_alter_pbv(sva4.pbv, sva4.pbv) RETURNS record
    LANGUAGE plpgsql
    AS $_$

   DECLARE
      row_pbv_old ALIAS FOR $1;
      row_pbv_new ALIAS FOR $2;

   BEGIN
      UPDATE sva4.pgd SET pgd_geburtsdatum = pgd_geburtsdatum WHERE pgd_join_id = row_pbv_new.pbv_pgd_join_id AND pgd_rentdtbermod = 'B';

      RETURN row_pbv_new;

   END;
$_$;


--
-- Name: restkont_berech(); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.restkont_berech() RETURNS void
    LANGUAGE plpgsql
    AS $$

DECLARE
	counter INT;


  BEGIN
    SET search_path TO sva4;

    counter := (SELECT COUNT(*) FROM sgd_prot WHERE proc_esql = 0 AND proc_date::date = current_date);


	BEGIN			
		IF counter < 1 THEN
		
			UPDATE sgd_prot SET (proc_date, proc_esql) = (current_timestamp, 1) WHERE 1 = 1;
			
			CREATE TEMP TABLE tmp_restkont 
			(
			  sgd_join_id integer,
			  ergebnis numeric (10, 6)
			);
			
			INSERT INTO tmp_restkont SELECT sgd_join_id, sgd_ansatz_proz FROM sgd;
			
			CREATE INDEX xtmp_restkont ON tmp_restkont (sgd_join_id);
			ANALYZE tmp_restkont;

			UPDATE tmp_restkont SET ergebnis = tmp_restkont.ergebnis - (
			SELECT SUM (pbe_anteil_prozent) FROM pbe, k_pbeart
			WHERE pbe.pbe_sgd_join_id = tmp_restkont.sgd_join_id AND
			(pbe_von is null or pbe_von <= current_date) AND
			(pbe_bis is null or pbe_bis >= current_date) AND
			(berechnung = 1) AND (key_pbeart = pbe_art) AND
			(pbe_status = 0 ))
			WHERE 1 = 1;

			CREATE TEMP TABLE tmp_proz_sbu 
			(
			  pbe_sgd_join_id integer,
			  pbe_serial integer,
			  sbu_prozent numeric (10, 6)
			);

			INSERT INTO tmp_proz_sbu SELECT pbe_sgd_join_id, pbe_serial, sbu_prozent
			FROM k_pbeart, pbe LEFT OUTER JOIN sbu
			ON pbe.pbe_serial = sbu.sbu_pbe_serial
			AND (pbe_von is null or pbe_von <= current_date)
			AND (pbe_bis is null or pbe_bis >= current_date)
			AND (pbe_status = 0)
			AND (sbu_von is null or sbu_von <= current_date)
			AND (sbu_bis is null or sbu_bis >= current_date)
			AND (sbu_status = 0)
			WHERE (berechnung = 1) AND (key_pbeart = pbe_art);

      UPDATE tmp_proz_sbu SET sbu_prozent = 0 WHERE sbu_prozent IS NULL;

			CREATE INDEX xtmp_proz_sbu ON tmp_proz_sbu (pbe_sgd_join_id);
			ANALYZE tmp_proz_sbu;

			UPDATE tmp_restkont SET ergebnis = ergebnis + (
			SELECT SUM (sbu_prozent) FROM tmp_proz_sbu
			WHERE tmp_proz_sbu.pbe_sgd_join_id = tmp_restkont.sgd_join_id)
			WHERE 1 = 1;

			UPDATE sgd SET sgd_restkont_proz = (
			SELECT ergebnis FROM tmp_restkont
			WHERE tmp_restkont.sgd_join_id = sgd.sgd_join_id)
			WHERE sgd.sgd_join_id IN (
			SELECT tmp_restkont.sgd_join_id FROM tmp_restkont
			WHERE ergebnis IS NOT NULL AND
			ergebnis <> sgd.sgd_restkont_proz);

			UPDATE sgd SET sgd_restkont_proz = sgd.sgd_ansatz_proz
			WHERE sgd.sgd_join_id IN (
			SELECT tmp_restkont.sgd_join_id FROM tmp_restkont
			WHERE ergebnis IS NULL) AND
			sgd.sgd_restkont_proz <> sgd.sgd_ansatz_proz;

			UPDATE sgd SET sgd_restkont_proz = NULL WHERE sgd_bis < current_date;
			
			DROP TABLE tmp_restkont;
			DROP TABLE tmp_proz_sbu;
			
			UPDATE sgd_prot SET (proc_date, proc_esql) = (current_timestamp, 0) WHERE 1 = 1;
			
		END IF;
		

		EXCEPTION
			WHEN OTHERS THEN
				UPDATE sgd_prot SET (proc_date, proc_esql) = (current_timestamp, 99999) WHERE 1 = 1;

	END;

  END;
$$;


