--
-- Name: rkadi(sva4.rka); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.rkadi(sva4.rka) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM sva4.r_dokumente r_dokumente WHERE old_row.rka_serial = r_dokumente.rka_join_id;
DELETE FROM sva4.r_wof r_wof WHERE old_row.rka_serial = r_wof.rka_join_id;
DELETE FROM sva4.rka_anlagen rka_anlagen WHERE old_row.rka_serial = rka_anlagen.rka_anlagen_rka_serial;
DELETE FROM sva4.rka_ausland rka_ausland WHERE old_row.rka_serial = rka_ausland.rka_aus_rka_serial;
DELETE FROM sva4.rka_fahrkosten rka_fahrkosten WHERE old_row.rka_serial = rka_fahrkosten.rka_rka_serial;
DELETE FROM sva4.rka_finanzierung rka_finanzierung WHERE old_row.rka_serial = rka_finanzierung.rka_finanzierung_rka_serial;
DELETE FROM sva4.rka_foerderung rka_foerderung WHERE old_row.rka_serial = rka_foerderung.rka_foerderung_rka_serial;
DELETE FROM sva4.rka_nebenkosten rka_nebenkosten WHERE old_row.rka_serial = rka_nebenkosten.rka_rka_serial;
DELETE FROM sva4.rka_tagesablauf rka_tagesablauf WHERE old_row.rka_serial = rka_tagesablauf.rka_rka_serial;
DELETE FROM sva4.rka_uebernachtung rka_uebernachtung WHERE old_row.rka_serial = rka_uebernachtung.rka_rka_serial;
DELETE FROM sva4.rka_verlauf rka_verlauf WHERE old_row.rka_serial = rka_verlauf.rka_verlauf_rka_serial;
DELETE FROM sva4.rka_wegstrecke rka_wegstrecke WHERE old_row.rka_serial = rka_wegstrecke.rka_rka_serial;
DELETE FROM sva4.rka_zusatz rka_zusatz WHERE old_row.rka_serial = rka_zusatz.rka_zus_rka_serial;
 RETURN old_row; END; $_$;


