    LANGUAGE plpgsql
    AS $_$DECLARE sql text; id1 ALIAS FOR $1;  BEGIN sql = 'DELETE FROM rmkasse WHERE join_nr= ' || quote_literal(id1); return dblink_exec(gc('superx_fsv_90_ap'), sql); END;$_$;


--
-- Name: rmkasse_ins(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.rmkasse_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _rmkasse_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _rmkasseinst_buffer!'; end if; SELECT * INTO rec FROM _rmkasse_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO rmkasse (db_einfuegemarke, kass_dateiname, kass_senddat, imp_join_nr, huel_join_nr, betrag, jahr, kap, tit, ut, objektkonto, kass_perskto, faelligkeit, kass_jahr, kass_aonr, kass_belegnr, kass_zeitbnr, kass_budatum, kass_aostatus, aonr, kass_text, ist_archiviert, kass_banktext, verarbeitstatus, kass_begruendung, kass_belegart, kass_sapbelegart) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.kass_dateiname),'NULL') || ' , ' || COALESCE(quote_literal(rec.kass_senddat),'NULL') || ' , ' || COALESCE(quote_literal(rec.imp_join_nr),'NULL') || ' , ' || COALESCE(quote_literal(rec.huel_join_nr),'NULL') || ' , ' || COALESCE(quote_literal(rec.betrag),'NULL') || ' , ' || COALESCE(quote_literal(rec.jahr),'NULL') || ' , ' || COALESCE(quote_literal(rec.kap),'NULL') || ' , ' || COALESCE(quote_literal(rec.tit),'NULL') || ' , ' || COALESCE(quote_literal(rec.ut),'NULL') || ' , ' || COALESCE(quote_literal(rec.objektkonto),'NULL') || ' , ' || COALESCE(quote_literal(rec.kass_perskto),'NULL') || ' , ' || COALESCE(quote_literal(rec.faelligkeit),'NULL') || ' , ' || COALESCE(quote_literal(rec.kass_jahr),'NULL') || ' , ' || COALESCE(quote_literal(rec.kass_aonr),'NULL') || ' , ' || COALESCE(quote_literal(rec.kass_belegnr),'NULL') || ' , ' || COALESCE(quote_literal(rec.kass_zeitbnr),'NULL') || ' , ' || COALESCE(quote_literal(rec.kass_budatum),'NULL') || ' , ' || COALESCE(quote_literal(rec.kass_aostatus),'NULL') || ' , ' || COALESCE(quote_literal(rec.aonr),'NULL') || ' , ' || COALESCE(quote_literal(rec.kass_text),'NULL') || ' , ' || COALESCE(quote_literal(rec.ist_archiviert),'NULL') || ' , ' || COALESCE(quote_literal(rec.kass_banktext),'NULL') || ' , ' || COALESCE(quote_literal(rec.verarbeitstatus),'NULL') || ' , ' || COALESCE(quote_literal(rec.kass_begruendung),'NULL') || ' , ' || COALESCE(quote_literal(rec.kass_belegart),'NULL') || ' , ' || COALESCE(quote_literal(rec.kass_sapbelegart),'NULL') || ')'; ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _rmkasse_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


