CREATE FUNCTION sva4.rmkasse_upd(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(join_nr) INTO anz FROM _rmkasse_buffer WHERE join_nr= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _rmkasse_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _rmkasse_buffer WHERE join_nr= id1 ; If FOUND then sql = 'UPDATE rmkasse SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , kass_dateiname= ' || COALESCE(quote_literal(rec.kass_dateiname),'NULL') || ' , kass_senddat= ' || COALESCE(quote_literal(rec.kass_senddat),'NULL') || ' , imp_join_nr= ' || COALESCE(quote_literal(rec.imp_join_nr),'NULL') || ' , huel_join_nr= ' || COALESCE(quote_literal(rec.huel_join_nr),'NULL') || ' , betrag= ' || COALESCE(quote_literal(rec.betrag),'NULL') || ' , jahr= ' || COALESCE(quote_literal(rec.jahr),'NULL') || ' , kap= ' || COALESCE(quote_literal(rec.kap),'NULL') || ' , tit= ' || COALESCE(quote_literal(rec.tit),'NULL') || ' , ut= ' || COALESCE(quote_literal(rec.ut),'NULL') || ' , objektkonto= ' || COALESCE(quote_literal(rec.objektkonto),'NULL') || ' , kass_perskto= ' || COALESCE(quote_literal(rec.kass_perskto),'NULL') || ' , faelligkeit= ' || COALESCE(quote_literal(rec.faelligkeit),'NULL') || ' , kass_jahr= ' || COALESCE(quote_literal(rec.kass_jahr),'NULL') || ' , kass_aonr= ' || COALESCE(quote_literal(rec.kass_aonr),'NULL') || ' , kass_belegnr= ' || COALESCE(quote_literal(rec.kass_belegnr),'NULL') || ' , kass_zeitbnr= ' || COALESCE(quote_literal(rec.kass_zeitbnr),'NULL') || ' , kass_budatum= ' || COALESCE(quote_literal(rec.kass_budatum),'NULL') || ' , kass_aostatus= ' || COALESCE(quote_literal(rec.kass_aostatus),'NULL') || ' , aonr= ' || COALESCE(quote_literal(rec.aonr),'NULL') || ' , kass_text= ' || COALESCE(quote_literal(rec.kass_text),'NULL') || ' , ist_archiviert= ' || COALESCE(quote_literal(rec.ist_archiviert),'NULL') || ' , kass_banktext= ' || COALESCE(quote_literal(rec.kass_banktext),'NULL') || ' , verarbeitstatus= ' || COALESCE(quote_literal(rec.verarbeitstatus),'NULL') || ' , kass_begruendung= ' || COALESCE(quote_literal(rec.kass_begruendung),'NULL') || ' , kass_belegart= ' || COALESCE(quote_literal(rec.kass_belegart),'NULL') || ' , kass_sapbelegart= ' || COALESCE(quote_literal(rec.kass_sapbelegart),'NULL') || ' WHERE join_nr=' || quote_literal(rec.join_nr); ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _rmkasse_buffer WHERE join_nr= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


