--
-- Name: sasdi(sva4.sas); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.sasdi(sva4.sas) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM sva4.bgr_to_sas bgr_to_sas WHERE old_row.sas_serial = bgr_to_sas.sas_join_id;
DELETE FROM sva4.kpt_to_sas kpt_to_sas WHERE old_row.sas_serial = kpt_to_sas.sas_serial;
DELETE FROM sva4.pgd_to_sas pgd_to_sas WHERE old_row.sas_serial = pgd_to_sas.pgd_to_sas_sas_serial;
DELETE FROM sva4.r_dokumente r_dokumente WHERE old_row.sas_serial = r_dokumente.sas_join_id;
DELETE FROM sva4.r_wof r_wof WHERE old_row.sas_serial = r_wof.sas_join_id;
DELETE FROM sva4.sas_kommentar sas_kommentar WHERE old_row.sas_serial = sas_kommentar.sas_kommentar_sas_join_id;
DELETE FROM sva4.sas_stand sas_stand WHERE old_row.sas_serial = sas_stand.sas_stand_sas_join_id;
DELETE FROM sva4.sas_to_medienkanal sas_to_medienkanal WHERE old_row.sas_serial = sas_to_medienkanal.sas_to_medienkanal_sas_join_id;
 RETURN old_row; END; $_$;


