--

CREATE FUNCTION sva4.semdi(sva4.sem) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM sva4.fba fba WHERE old_row.sem_id = fba.fba_sem_id;
DELETE FROM sva4.kpt_to_sem kpt_to_sem WHERE old_row.sem_id = kpt_to_sem.sem_id;
DELETE FROM sva4.sem_kosten sem_kosten WHERE old_row.sem_id = sem_kosten.sem_kosten_sem_id;
DELETE FROM sva4.sem_to_pgd sem_to_pgd WHERE old_row.sem_id = sem_to_pgd.sem_id;
 RETURN old_row; END; $_$;


--
-- Name: setze_urlaubsantrag_auf_ungueltig_pg(sva4.paw, sva4.paw); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.setze_urlaubsantrag_auf_ungueltig_pg(sva4.paw, sva4.paw) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
	DECLARE
		paw_entry_old ALIAS FOR $1;
		paw_entry_new ALIAS FOR $2;
		
	BEGIN
		IF (paw_entry_old.paw_von != paw_entry_new.paw_von) OR (paw_entry_old.paw_bis != paw_entry_new.paw_bis) OR (paw_entry_old.paw_art != paw_entry_new.paw_art) THEN
			UPDATE sva4.ura SET ura_status = 4, ura_paw_serial = NULL, ura_fehlermeldung = 'Urlaubsantrag ungültig aufgrund einer Änderung der zugehörigen Abwesenheitsbuchung (paw)' WHERE ura_paw_serial = paw_entry_old.paw_serial;
		END IF;
		
		RETURN paw_entry_new;
	END;
$_$;


--
-- Name: setze_urlaubsantrag_auf_ungueltig_pg(sva4.paw, sva4.paw, boolean); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.setze_urlaubsantrag_auf_ungueltig_pg(sva4.paw, sva4.paw, boolean) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
	DECLARE
		paw_entry_old ALIAS FOR $1;
		paw_entry_new ALIAS FOR $2;
		is_delete ALIAS FOR $3;
		
	BEGIN
		IF (is_delete) OR (paw_entry_old.paw_von != paw_entry_new.paw_von) OR (paw_entry_old.paw_bis != paw_entry_new.paw_bis) OR (paw_entry_old.paw_art != paw_entry_new.paw_art) THEN
			UPDATE sva4.ura SET ura_status = 4, ura_paw_serial = NULL, ura_fehlermeldung = 'Urlaubsantrag ungültig aufgrund einer Änderung der zugehörigen Abwesenheitsbuchung (paw)' WHERE ura_paw_serial = paw_entry_old.paw_serial;
		END IF;
		
		RETURN paw_entry_new;
	END;
$_$;


