--
-- Name: sgddi(sva4.sgd); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.sgddi(sva4.sgd) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM sva4.gvp_to_sgd gvp_to_sgd WHERE old_row.sgd_join_id = gvp_to_sgd.sgd_join_id;
DELETE FROM sva4.pbe pbe WHERE old_row.sgd_join_id = pbe.pbe_sgd_join_id;
DELETE FROM sva4.sas sas WHERE old_row.sgd_join_id = sas.sas_sgd_join_id;
DELETE FROM sva4.sdp sdp WHERE old_row.sgd_join_id = sdp.sdp_sgd_join_id;
DELETE FROM sva4.shv shv WHERE old_row.sgd_join_id = shv.shv_sgd_join_id;
DELETE FROM sva4.sko sko WHERE old_row.sgd_join_id = sko.sko_sgd_join_id;
DELETE FROM sva4.soe soe WHERE old_row.sgd_join_id = soe.soe_sgd_join_id;
DELETE FROM sva4.swe swe WHERE old_row.sgd_join_id = swe.swe_sgd_join_id;
DELETE FROM sva4.wvl wvl WHERE old_row.sgd_join_id = wvl.wvl_sgd_join_id;
 RETURN old_row; END; $_$;


