--
-- Name: stufensteigerung(); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.stufensteigerung() RETURNS void
    LANGUAGE plpgsql
    AS $$

DECLARE
    p_pbl_serial INT;
    p_pbl_tvl_stufe NCHAR(3);
    p_pbl_tvl_stufe_neu NCHAR(3);
    p_pbl_tvl_steig_ab DATE;
    p_pbv_bis DATE;
    p_pbl_bis DATE;
		p_pbl_von_neu DATE;
    p_pbv_befr_bis DATE;
    p_laufzeit SMALLINT;
    p_endstufe NCHAR(3);
		p_stufensteigerung INT;
		p_stufenlaufzeit_verlaengerung INT;
		p_steigerung_erfolgt INT;

    pbl_tab record;

	BEGIN
		SET search_path TO sva4;

		p_steigerung_erfolgt := 0;
		p_stufenlaufzeit_verlaengerung := 0;
		
		p_stufensteigerung := (SELECT txt::int FROM sys WHERE msnr = 'STUSTE');
		
		IF p_stufensteigerung IS NULL THEN
			p_stufensteigerung := 0;
		END IF;

		IF (p_stufensteigerung = 0) THEN    
			FOR pbl_tab IN
				SELECT pbl_serial, pbl_tvl_stufe, pbl_bis, pbv_bis, pbv_befr_bis,
								pbl_tvl_steig_ab, endstufe, pbl_stufenlaufzeit_verlaengerung
					 FROM pbl, pbv, k_bvlgruppe
					WHERE pbl_pgd_join_id = pbv_pgd_join_id AND pbl_pbv_nr = pbv_nr
						AND (pbl_von <= CURRENT_DATE AND (pbl_bis IS NULL OR pbl_bis >= CURRENT_DATE))
						AND (pbv_von <= CURRENT_DATE AND (pbv_bis IS NULL OR pbv_bis >= CURRENT_DATE))
						AND (pbl_tvl_steig_ab IS NOT NULL AND ((pbv_bis IS NULL) OR (pbl_tvl_steig_ab <= pbv.pbv_bis)))
						AND (pbl_status = 0 AND pbv_status = 0)
						AND pbl.pbl_bvl_gruppe = k_bvlgruppe.key_bvlgruppe AND k_bvlgruppe.tvl_bat_mtarb = 'T'
						AND k_bvlgruppe.endstufe <> pbl.pbl_tvl_stufe AND k_bvlgruppe.endstufe IS NOT NULL
						AND 0 = (SELECT COUNT(*) FROM pbl pbl_folge
											WHERE pbl_folge.pbl_von = pbl.pbl_bis + INTERVAL '1 DAYS'
												AND pbl.pbl_bis IS NOT NULL
												AND pbl.pbl_pgd_join_id = pbl_folge.pbl_pgd_join_id
												AND pbl.pbl_pbv_nr = pbl_folge.pbl_pbv_nr
												AND pbl.pbl_serial <> pbl_folge.pbl_serial
												AND pbl_folge.pbl_status = 0)
			LOOP
				p_pbl_serial := pbl_tab.pbl_serial;
				p_pbl_tvl_stufe := pbl_tab.pbl_tvl_stufe;
				p_pbl_tvl_steig_ab := pbl_tab.pbl_tvl_steig_ab;
				p_pbv_bis := pbl_tab.pbv_bis;
				p_pbl_bis := pbl_tab.pbl_bis;
				p_pbv_befr_bis := pbl_tab.pbv_befr_bis;
				p_endstufe := pbl_tab.endstufe;
				p_stufenlaufzeit_verlaengerung := (COALESCE(pbl_tab.pbl_stufenlaufzeit_verlaengerung), 0);
				
				--Folgestufe ermitteln:
				p_pbl_tvl_stufe_neu := (SELECT folge_bvlstufe FROM k_bvlstufe WHERE key_bvlstufe = pbl_tab.pbl_tvl_stufe);

				p_pbl_von_neu := p_pbl_tvl_steig_ab;
				--Laufzeit der Folgestufe:
				p_laufzeit := (SELECT laufzeit FROM k_bvlstufe WHERE key_bvlstufe = p_pbl_tvl_stufe_neu) + p_stufenlaufzeit_verlaengerung;

				IF p_laufzeit IS NULL THEN
					 p_pbl_tvl_steig_ab := NULL;
				ELSE
					 p_pbl_tvl_steig_ab := pbl_tab.pbl_tvl_steig_ab + (p_laufzeit||'MONTH')::interval;
				END IF;

				-- wenn Endstufe erreicht
				IF (p_pbl_tvl_stufe_neu = pbl_tab.endstufe) THEN
					p_pbl_tvl_steig_ab := NULL;
				END IF;

				--Fallunterscheidung fuer Endedatum des neuen PBL-Satzes:
				p_pbl_bis := p_pbv_bis;
				
				IF pbl_tab.pbv_bis IS NULL THEN
					 p_pbl_bis := p_pbv_befr_bis;
				END IF;
				IF (p_pbv_bis IS NOT NULL AND p_pbv_bis > p_pbl_tvl_steig_ab) THEN
					 p_pbl_bis := p_pbl_tvl_steig_ab - INTERVAL '1 DAYS';
				END IF;

				-- Vermeidet zukuenftige PBL-Saetze!
				IF (p_pbl_von_neu IS NOT NULL) THEN
					IF (p_pbl_von_neu <= CURRENT_DATE) THEN
						--Historisierung des alten PBL-Satzes:
						UPDATE pbl SET pbl_bis = pbl_tvl_steig_ab - INTERVAL '1 DAYS' WHERE pbl_serial = pbl_tab.pbl_serial;

						--Kopie des alten PBL-Satzes:
						INSERT INTO pbl
							 SELECT db_einfuegemarke, pbl_pbv_nr, pbl_pgd_join_id, nextval('pbl_pbl_serial_seq'),
									 pbl_status, pbl_bvl_gruppe, pbl_laufbahn, pbl_fallgruppe,
									 pbl_teil, pbl_abschnitt, pbl_unterabsch, pbl_anlage,
									 pbl_bewaehr_ab, pbl_adt_bez, pbl_adt_von, pbl_betrag,
									 pbl_tvl_steig_ab, p_pbl_bis,
									 pbl_aendergrd,
									 pbl_pbv_serial, p_pbl_tvl_stufe_neu, p_pbl_tvl_steig_ab,
									 pbl_diff_betrag,
									 pbl_bat_mtarb, pbl_bat_mtarb_tvl, pbl_tvl_teil, pbl_tvl_abschnitt, 
									 pbl_tvl_fallgruppe, pbl_workflow
							FROM pbl WHERE pbl_serial = pbl_tab.pbl_serial;
							
						p_steigerung_erfolgt := 1;						
					END IF;
				END IF;
			END LOOP;
			
			IF (p_steigerung_erfolgt = 1) AND (p_pbl_tvl_stufe_neu <> pbl_tab.endstufe) THEN
				PERFORM stufensteigerung();
			END IF;
		END IF;	

		IF (p_stufensteigerung = 1) THEN    
			FOR pbl_tab IN
				SELECT pbl_serial, pbl_tvl_stufe, pbl_bis, pbv_bis, pbv_befr_bis,
								pbl_tvl_steig_ab, endstufe, pbl_stufenlaufzeit_verlaengerung
					 FROM pbl, pbv, k_bvlgruppe
					WHERE pbl_pgd_join_id = pbv_pgd_join_id AND pbl_pbv_nr = pbv_nr
						AND (pbl_tvl_steig_ab IS NOT NULL AND ((pbv_bis IS NULL) OR (pbl_tvl_steig_ab <= pbv.pbv_bis)))
						AND (pbl_status = 0 AND pbv_status = 0)
						AND pbl.pbl_bvl_gruppe = k_bvlgruppe.key_bvlgruppe AND k_bvlgruppe.tvl_bat_mtarb = 'T'
						AND k_bvlgruppe.endstufe <> pbl.pbl_tvl_stufe AND k_bvlgruppe.endstufe IS NOT NULL
						AND 0 = (SELECT COUNT(*) FROM pbl pbl_folge
											WHERE pbl_folge.pbl_von = pbl.pbl_bis + INTERVAL '1 DAYS'
												AND pbl.pbl_bis IS NOT NULL
												AND pbl.pbl_pgd_join_id = pbl_folge.pbl_pgd_join_id
												AND pbl.pbl_pbv_nr = pbl_folge.pbl_pbv_nr
												AND pbl.pbl_serial <> pbl_folge.pbl_serial
												AND pbl_folge.pbl_status = 0)
			LOOP
				p_pbl_serial := pbl_tab.pbl_serial;
				p_pbl_tvl_stufe := pbl_tab.pbl_tvl_stufe;
				p_pbl_tvl_steig_ab := pbl_tab.pbl_tvl_steig_ab;
				p_pbv_bis := pbl_tab.pbv_bis;
				p_pbl_bis := pbl_tab.pbl_bis;
				p_pbv_befr_bis := pbl_tab.pbv_befr_bis;
				p_endstufe := pbl_tab.endstufe;
				p_stufenlaufzeit_verlaengerung := (COALESCE(pbl_tab.pbl_stufenlaufzeit_verlaengerung), 0);
				
				--Folgestufe ermitteln:
				p_pbl_tvl_stufe_neu := (SELECT folge_bvlstufe FROM k_bvlstufe WHERE key_bvlstufe = pbl_tab.pbl_tvl_stufe);

				p_pbl_von_neu := p_pbl_tvl_steig_ab;
				--Laufzeit der Folgestufe:
				p_laufzeit := (SELECT laufzeit FROM k_bvlstufe WHERE key_bvlstufe = p_pbl_tvl_stufe_neu) + p_stufenlaufzeit_verlaengerung;

				IF p_laufzeit IS NULL THEN
					 p_pbl_tvl_steig_ab := NULL;
				ELSE
					 p_pbl_tvl_steig_ab := pbl_tab.pbl_tvl_steig_ab + (p_laufzeit||'MONTH')::interval;
				END IF;

				-- wenn Endstufe erreicht
				IF (p_pbl_tvl_stufe_neu = pbl_tab.endstufe) THEN
					p_pbl_tvl_steig_ab := NULL;
				END IF;

				--Fallunterscheidung fuer Endedatum des neuen PBL-Satzes:
				p_pbl_bis := p_pbv_bis;
				
				IF pbl_tab.pbv_bis IS NULL THEN
					 p_pbl_bis := p_pbv_befr_bis;
				END IF;
				IF (p_pbv_bis IS NOT NULL AND p_pbv_bis > p_pbl_tvl_steig_ab) THEN
					 p_pbl_bis := p_pbl_tvl_steig_ab - INTERVAL '1 DAYS';
				END IF;

				--Historisierung des alten PBL-Satzes:
				UPDATE pbl SET pbl_bis = pbl_tvl_steig_ab - INTERVAL '1 DAYS' WHERE pbl_serial = pbl_tab.pbl_serial;

				--Kopie des alten PBL-Satzes:
				INSERT INTO pbl
					 SELECT db_einfuegemarke, pbl_pbv_nr, pbl_pgd_join_id, nextval('pbl_pbl_serial_seq'),
							 pbl_status, pbl_bvl_gruppe, pbl_laufbahn, pbl_fallgruppe,
							 pbl_teil, pbl_abschnitt, pbl_unterabsch, pbl_anlage,
							 pbl_bewaehr_ab, pbl_adt_bez, pbl_adt_von, pbl_betrag,
							 pbl_tvl_steig_ab, p_pbl_bis,
							 pbl_aendergrd,
							 pbl_pbv_serial, p_pbl_tvl_stufe_neu, p_pbl_tvl_steig_ab,
							 pbl_diff_betrag,
							 pbl_bat_mtarb, pbl_bat_mtarb_tvl, pbl_tvl_teil, pbl_tvl_abschnitt, 
							 pbl_tvl_fallgruppe, pbl_workflow
					FROM pbl WHERE pbl_serial = pbl_tab.pbl_serial;
				
				p_steigerung_erfolgt := 1;					
			END LOOP;
			
			IF (p_steigerung_erfolgt = 1) AND (p_pbl_tvl_stufe_neu <> pbl_tab.endstufe) THEN
				PERFORM stufensteigerung();
			END IF;				
		END IF;
		
		-- Nur Stufensteigerungen im nachfolgenden Jahr
		IF (p_stufensteigerung = 2) THEN    
			FOR pbl_tab IN
				SELECT pbl_serial, pbl_tvl_stufe, pbl_bis, pbv_bis, pbv_befr_bis,
								pbl_tvl_steig_ab, endstufe, pbl_stufenlaufzeit_verlaengerung
					 FROM pbl, pbv, k_bvlgruppe
					WHERE pbl_pgd_join_id = pbv_pgd_join_id AND pbl_pbv_nr = pbv_nr
						AND (pbl_tvl_steig_ab IS NOT NULL AND ((pbv_bis IS NULL) OR (pbl_tvl_steig_ab <= pbv.pbv_bis)))
						AND (pbl_tvl_steig_ab < (((EXTRACT(year FROM current_date) + 2)::text || '-01-01')::date))
						AND (pbl_status = 0 AND pbv_status = 0)
						AND pbl.pbl_bvl_gruppe = k_bvlgruppe.key_bvlgruppe AND k_bvlgruppe.tvl_bat_mtarb = 'T'
						AND k_bvlgruppe.endstufe <> pbl.pbl_tvl_stufe AND k_bvlgruppe.endstufe IS NOT NULL
						AND 0 = (SELECT COUNT(*) FROM pbl pbl_folge
											WHERE pbl_folge.pbl_von = pbl.pbl_bis + INTERVAL '1 DAYS'
												AND pbl.pbl_bis IS NOT NULL
												AND pbl.pbl_pgd_join_id = pbl_folge.pbl_pgd_join_id
												AND pbl.pbl_pbv_nr = pbl_folge.pbl_pbv_nr
												AND pbl.pbl_serial <> pbl_folge.pbl_serial
												AND pbl_folge.pbl_status = 0)
												
			LOOP
				p_pbl_serial := pbl_tab.pbl_serial;
				p_pbl_tvl_stufe := pbl_tab.pbl_tvl_stufe;
				p_pbl_tvl_steig_ab := pbl_tab.pbl_tvl_steig_ab;
				p_pbv_bis := pbl_tab.pbv_bis;
				p_pbl_bis := pbl_tab.pbl_bis;
				p_pbv_befr_bis := pbl_tab.pbv_befr_bis;
				p_endstufe := pbl_tab.endstufe;
				p_stufenlaufzeit_verlaengerung := (COALESCE(pbl_tab.pbl_stufenlaufzeit_verlaengerung), 0);
				
				--Folgestufe ermitteln:
				p_pbl_tvl_stufe_neu := (SELECT folge_bvlstufe FROM k_bvlstufe WHERE key_bvlstufe = pbl_tab.pbl_tvl_stufe);

				p_pbl_von_neu := p_pbl_tvl_steig_ab;
				--Laufzeit der Folgestufe:
				p_laufzeit := (SELECT laufzeit FROM k_bvlstufe WHERE key_bvlstufe = p_pbl_tvl_stufe_neu) + p_stufenlaufzeit_verlaengerung;

				IF p_laufzeit IS NULL THEN
					 p_pbl_tvl_steig_ab := NULL;
				ELSE
					 p_pbl_tvl_steig_ab := pbl_tab.pbl_tvl_steig_ab + (p_laufzeit||'MONTH')::interval;
				END IF;

				-- wenn Endstufe erreicht
				IF (p_pbl_tvl_stufe_neu = pbl_tab.endstufe) THEN
					p_pbl_tvl_steig_ab := NULL;
				END IF;

				--Fallunterscheidung fuer Endedatum des neuen PBL-Satzes:
				p_pbl_bis := p_pbv_bis;
				
				IF pbl_tab.pbv_bis IS NULL THEN
					 p_pbl_bis := p_pbv_befr_bis;
				END IF;
				IF (p_pbv_bis IS NOT NULL AND p_pbv_bis > p_pbl_tvl_steig_ab) THEN
					 p_pbl_bis := p_pbl_tvl_steig_ab - INTERVAL '1 DAYS';
				END IF;

				--Historisierung des alten PBL-Satzes:
				UPDATE pbl SET pbl_bis = pbl_tvl_steig_ab - INTERVAL '1 DAYS' WHERE pbl_serial = pbl_tab.pbl_serial;

				--Kopie des alten PBL-Satzes:
				INSERT INTO pbl
					 SELECT db_einfuegemarke, pbl_pbv_nr, pbl_pgd_join_id, nextval('pbl_pbl_serial_seq'),
							 pbl_status, pbl_bvl_gruppe, pbl_laufbahn, pbl_fallgruppe,
							 pbl_teil, pbl_abschnitt, pbl_unterabsch, pbl_anlage,
							 pbl_bewaehr_ab, pbl_adt_bez, pbl_adt_von, pbl_betrag,
							 pbl_tvl_steig_ab, p_pbl_bis,
							 pbl_aendergrd,
							 pbl_pbv_serial, p_pbl_tvl_stufe_neu, p_pbl_tvl_steig_ab,
							 pbl_diff_betrag,
							 pbl_bat_mtarb, pbl_bat_mtarb_tvl, pbl_tvl_teil, pbl_tvl_abschnitt, 
							 pbl_tvl_fallgruppe, pbl_workflow
					FROM pbl WHERE pbl_serial = pbl_tab.pbl_serial;
				
				p_steigerung_erfolgt := 1;
			END LOOP;
			
			IF (p_steigerung_erfolgt = 1) AND (p_pbl_tvl_stufe_neu <> pbl_tab.endstufe) AND (p_pbl_von_neu <= p_pbl_bis) THEN
				PERFORM stufensteigerung();
			END IF;			
		END IF;			
		
	END;
$$;


