--
-- Name: synchronize_org_unit_change_with_hisinone(sva4.pfi, sva4.pfi); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.synchronize_org_unit_change_with_hisinone(sva4.pfi, sva4.pfi) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
	pfi_entry_old ALIAS FOR $1;
	pfi_entry_new ALIAS FOR $2;
	pgd_join_id INTEGER;
	is_h1int_set BOOLEAN;
	pfi_record RECORD;
	instituts_as_json TEXT[];
	institute_as_json TEXT;
	result_json TEXT;

BEGIN
	-- Nur ausloesen, wenn H1-Integration aktiv
	EXECUTE 'SELECT true from sva4.sys WHERE msnr = $1 AND txt = $2'
	INTO is_h1int_set
	USING 'H1INT', '1';

	IF is_h1int_set THEN
		-- Nur Aenderungen beruecksichtigen, die das Institut bzw. den Zeitraum (pfi_von/pfi_bis) und gueltige
		-- Finanzierungen betreffen (pfi_status = 0). Ausserdem bei Neuanlage/Loeschung einer Finanzierung auf die Uebertragungstabelle schreiben,
		-- sofern der geloeschte Satz gueltig war bzw. der neu angelegte Satz gueltig ist.
		-- Wenn der Nutzer einen pfi-Satz von "ungueltig" auf "gueltig" gesetzt hat, sollen die pfi-Saetze ebenso uebertragen werden.
		IF (
			(pfi_entry_new.pfi_serial IS NULL AND pfi_entry_old.pfi_serial IS NOT NULL AND pfi_entry_old.pfi_status = 0)
			OR (pfi_entry_old.pfi_serial IS NULL AND pfi_entry_new.pfi_serial IS NOT NULL AND pfi_entry_new.pfi_status = 0)
			OR (pfi_entry_old.pfi_serial IS NOT NULL AND pfi_entry_old.pfi_status = 4 AND pfi_entry_new.pfi_status IS NOT NULL AND pfi_entry_new.pfi_status = 0)
			OR (pfi_entry_old.pfi_serial IS NOT NULL AND pfi_entry_new.pfi_status = 0
				AND
					((pfi_entry_old.pfi_von IS DISTINCT FROM pfi_entry_new.pfi_von)
					OR (pfi_entry_old.pfi_bis IS DISTINCT FROM pfi_entry_new.pfi_bis)
					OR (pfi_entry_old.poz_institut IS DISTINCT FROM pfi_entry_new.poz_institut))))
		THEN
			DROP TABLE IF EXISTS pfi_records;
			CREATE TEMPORARY TABLE pfi_records (poz_institut CHARACTER VARYING(10), pfi_von TEXT, pfi_bis TEXT);

			IF pfi_entry_new.pfi_pgd_join_id IS NOT NULL THEN
				pgd_join_id := pfi_entry_new.pfi_pgd_join_id;
			ELSIF pfi_entry_old.pfi_pgd_join_id IS NOT NULL THEN
				pgd_join_id := pfi_entry_old.pfi_pgd_join_id;
			ELSE
				RETURN pfi_entry_new;
			END IF;

			EXECUTE 'INSERT INTO pfi_records (poz_institut, pfi_von, pfi_bis) SELECT poz_institut, MIN(pfi_von) AS pfi_von, NULLIF(MAX(COALESCE(pfi_bis, ''infinity''::date)), ''infinity''::date) AS pfi_bis FROM sva4.pfi 
			WHERE pfi_pgd_join_id = $1 AND pfi_status = 0 AND poz_institut IS NOT NULL GROUP BY poz_institut ORDER BY poz_institut'
			USING pgd_join_id;

			FOR pfi_record IN SELECT * FROM pfi_records
			LOOP
				SELECT array_append(instituts_as_json,
				'"' || pfi_record.poz_institut || '":{"valid_from":"' || pfi_record.pfi_von || '","valid_to":"'
				|| (CASE WHEN pfi_record.pfi_bis IS NULL THEN '' ELSE pfi_record.pfi_bis END) || '"}') INTO instituts_as_json;

			END LOOP;

			-- Wenn die Person noch weiteren Instituten zugeordnet ist, uebermittle alle Institute an die Transfertabelle. Wenn ein pfi-Datensatz geloescht wurde, uebermittle eine leere Insititutsliste.
			IF (array_length(instituts_as_json, 1) > 0) THEN
				result_json := '{' || array_to_string(instituts_as_json, ',') || '}';
			ELSE
				result_json := '{}';
			END IF;
			
			INSERT INTO sva4.h1_sva_transfer(pgd_join_id, new_values, h1_entity, created_at,is_h1_change,entry_status,obj_guid, lock_version) VALUES
				(pgd_join_id, result_json, 'psv.Orgrole', NOW(), 0, 0, 'psv.Orgrole' || currval('sva4.h1_sva_transfer_id_seq'), 0);

			DROP TABLE IF EXISTS pfi_records;
		END IF;
	END IF;

	RETURN pfi_entry_new;
END;

$_$;


