--
-- Name: taetigkeitsschluessel(integer, integer); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.taetigkeitsschluessel(p_paz_pgd_join_id integer, p_paz_pbv_nr integer) RETURNS text
    LANGUAGE plpgsql
    AS $$

DECLARE
		p_pbv_befr_bis DATE;
		p_paz_anteil FLOAT;

    p_vertragsart NCHAR(2);

		p_PAZTaetigkeit NCHAR(9);		
		p_taetigkeit_1_5 NCHAR(5);		
		p_taetigkeit_6 NCHAR(1);
		p_taetigkeit_7 NCHAR(1);		
		p_taetigkeit_8 NCHAR(1);		
		p_taetigkeit_9 NCHAR(1);

    meldung NCHAR(100);


  BEGIN
    SET search_path TO sva4;

		p_vertragsart := (SELECT k_vertragsart.his_system_key FROM k_vertragsart, pbv, paz
											 WHERE pbv.pbv_art = k_vertragsart.key_vertragsart
												 AND k_vertragsart.rentenber_relevant = 'J'
												 AND pbv.pbv_pgd_join_id = paz.paz_pgd_join_id
												 AND pbv.pbv_nr = paz.paz_pbv_nr
												 AND paz.paz_pgd_join_id = p_paz_pgd_join_id 
												 AND paz.paz_pbv_nr = p_paz_pbv_nr 
												 AND pbv.pbv_status = 0);

		-- nur ausfuehren, wenn kein Beamter
		IF (p_vertragsart LIKE 'A%') OR (p_vertragsart LIKE 'S%') OR (p_vertragsart LIKE '%S') OR (p_vertragsart LIKE '%W') OR (p_vertragsart LIKE '%U') THEN

			p_taetigkeit_1_5 := (SELECT LEFT(astat, 5) FROM pbv, k_astat_occupation
																	WHERE pbv_pgd_join_id = p_paz_pgd_join_id 
																	  AND pbv_nr = p_paz_pbv_nr
																		AND pbv_status = 0
																		AND k_astat_occupation_id = id);
																		
			IF p_taetigkeit_1_5 IS NULL THEN
				p_taetigkeit_1_5 := '?????';
			END IF;

			-- Hoechster allgemeinbildender Schulabschluss (Stelle 6)
			p_taetigkeit_6 := (SELECT LEFT(astat, 1) FROM pgd, k_astat_graduation
																	WHERE pgd_join_id = p_paz_pgd_join_id 
																		AND pgd_status = 0
																		AND k_astat_graduation_id = id);																		

			IF p_taetigkeit_6 IS NULL THEN
				p_taetigkeit_6 := '?';
			END IF;
			
			-- Hoechster beruflicher Ausbildungsabschluss (Stelle 7)
			p_taetigkeit_7 := (SELECT Left(astat, 1) FROM pgd, k_astat_job_graduation
																	WHERE pgd_join_id = p_paz_pgd_join_id 
																		AND pgd_status = 0
																		AND k_astat_job_graduation_id = id);

			IF p_taetigkeit_7 IS NULL THEN
				p_taetigkeit_7 := '?';
			END IF;
			
			-- Arbeitnehmerueberlassung  (Stelle 8)
			p_taetigkeit_8 := (SELECT temporary_provision_of_labour FROM pgd
																	WHERE pgd_join_id = p_paz_pgd_join_id 
																		AND pgd_status = 0);			

			IF p_taetigkeit_8 IS NULL THEN
				p_taetigkeit_8 := '?';
			END IF;
			
			IF (p_taetigkeit_8 = '1') THEN
				p_taetigkeit_8 := '2';
			ELSE
				p_taetigkeit_8 := '1';
			END IF;
		
			-- Vertragsform (Stelle 9)			
			p_pbv_befr_bis := (SELECT pbv_befr_bis FROM pbv
																	WHERE pbv_pgd_join_id = p_paz_pgd_join_id 
																	  AND pbv_nr = p_paz_pbv_nr
																		AND pbv_status = 0);
																		
			p_paz_anteil := (SELECT paz_tz_proz FROM paz
																	WHERE paz_pgd_join_id = p_paz_pgd_join_id 
																	  AND paz_pbv_nr = p_paz_pbv_nr 
																		AND paz_status = 0);

			IF p_paz_anteil = 100 THEN	-- Vollzeit
				IF p_pbv_befr_bis IS NULL THEN
					p_taetigkeit_9 := '1';
				ELSE
					p_taetigkeit_9 := '3';
				END IF;
			ELSE												-- Teilzeit
				IF p_pbv_befr_bis IS NULL THEN
					p_taetigkeit_9 := '2';
				ELSE
					p_taetigkeit_9 := '4';
				END IF;
			END IF;
			
			p_PAZTaetigkeit := CONCAT(p_taetigkeit_1_5, p_taetigkeit_6, p_taetigkeit_7, p_taetigkeit_8, p_taetigkeit_9);

			meldung := 'Erfolgreich ermittelt!';

		END IF;


    --Rueckgabewerte
    RETURN p_PAZTaetigkeit;
		
  END;
$$;


