CREATE FUNCTION sva4.terdi(sva4.ter) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM sva4.r_dokumente r_dokumente WHERE old_row.ter_serial = r_dokumente.ter_join_id;
DELETE FROM sva4.r_wof r_wof WHERE old_row.ter_serial = r_wof.ter_join_id;
DELETE FROM sva4.ter_finanzierung ter_finanzierung WHERE old_row.ter_serial = ter_finanzierung.ter_finanzierung_ter_serial;
DELETE FROM sva4.ter_foerderung ter_foerderung WHERE old_row.ter_serial = ter_foerderung.ter_foerderung_ter_serial;
DELETE FROM sva4.ter_verlauf ter_verlauf WHERE old_row.ter_serial = ter_verlauf.ter_verlauf_ter_serial;
DELETE FROM sva4.ter_wegstrecke ter_wegstrecke WHERE old_row.ter_serial = ter_wegstrecke.ter_wegstrecke_ter_serial;
 RETURN old_row; END; $_$;


