ALESCE(quote_literal(rec.ein),'NULL') || ' , ' || COALESCE(quote_literal(rec.verfkor),'NULL') || ' , ' || COALESCE(quote_literal(rec.vojs),'NULL') || ' , ' || COALESCE(quote_literal(rec.pruef),'NULL') || ' , ' || COALESCE(quote_literal(rec.art),'NULL') || ' , ' || COALESCE(quote_literal(rec.kz_ueber),'NULL') || ' , ' || COALESCE(quote_literal(rec.sperrkz),'NULL') || ' , ' || COALESCE(quote_literal(rec.soll_kontr),'NULL') || ' , ' || COALESCE(quote_literal(rec.o_nr),'NULL') || ' , ' || COALESCE(quote_literal(rec.finz_stat),'NULL') || ' , ' || COALESCE(quote_literal(rec.sblae),'NULL') || ' , ' || COALESCE(quote_literal(rec.datlae),'NULL') || ' , ' || COALESCE(quote_literal(rec.korrkz),'NULL') || ' , ' || COALESCE(quote_literal(rec.hhansa),'NULL') || ' , ' || COALESCE(quote_literal(rec.aktsf),'NULL') || ' , ' || COALESCE(quote_literal(rec.restev),'NULL') || ' , ' || COALESCE(quote_literal(rec.ltitbez),'NULL') || ' , ' || COALESCE(quote_literal(rec.kennzahl),'NULL') || ' , ' || COALESCE(quote_literal(rec.mwpf),'NULL') || ' , ' || COALESCE(quote_literal(rec.dtgr),'NULL') || ' , ' || COALESCE(quote_literal(rec.vwg),'NULL') || ' , ' || COALESCE(quote_literal(rec.kz_vhhf),'NULL') || ' , ' || COALESCE(quote_literal(rec.ea),'NULL') || ')'; ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _tit_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


