CREATE FUNCTION sva4.trg_monatdi(sva4.trg_monat) RETURNS record
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
DECLARE
old_row ALIAS FOR $1;
BEGIN
DELETE FROM sva4.trg_tage trg_tage WHERE old_row.trg_monat_serial = trg_tage.trg_tage_monat_serial;
DELETE FROM sva4.trg_tage_roh trg_tage_roh WHERE old_row.trg_monat_serial = trg_tage_roh.trg_tage_roh_monat_serial;
 RETURN old_row; END; $_$;


