--
-- Name: ut_ins(character varying); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.ut_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _ut_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _utinst_buffer!'; end if; SELECT * INTO rec FROM _ut_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO ut (db_einfuegemarke, jahr, kap, tit, ut, utbez, dr, dr2, hhans, akts, sperr, reste, zvert, fest, ausz, soll, ein, verfkor, vojs, kz_ueber, sperrkz, art, soll_kontr, o_nr, finz_stat, mwpf, titkor, drkor, korrkz, dtgr, vwg, utkor) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.jahr),'NULL') || ' , ' || COALESCE(quote_literal(rec.kap),'NULL') || ' , ' || COALESCE(quote_literal(rec.tit),'NULL') || ' , ' || COALESCE(quote_literal(rec.ut),'NULL') || ' , ' || COALESCE(quote_literal(rec.utbez),'NULL') || ' , ' || COALESCE(quote_literal(rec.dr),'NULL') || ' , ' || COALESCE(quote_literal(rec.dr2),'NULL') || ' , ' || COALESCE(quote_literal(rec.hhans),'NULL') || ' , ' || COALESCE(quote_literal(rec.akts),'NULL') || ' , ' || COALESCE(quote_literal(rec.sperr),'NULL') || ' , ' || COALESCE(quote_literal(rec.reste),'NULL') || ' , ' || COALESCE(quote_literal(rec.zvert),'NULL') || ' , ' || COALESCE(quote_literal(rec.fest),'NULL') || ' , ' || COALESCE(quote_literal(rec.ausz),'NULL') || ' , ' || COALESCE(quote_literal(rec.soll),'NULL') || ' , ' || COALESCE(quote_literal(rec.ein),'NULL') || ' , ' || COALESCE(quote_literal(rec.verfkor),'NULL') || ' , ' || COALESCE(quote_literal(rec.vojs),'NULL') || ' , ' || COALESCE(quote_literal(rec.kz_ueber),'NULL') || ' , ' || COALESCE(quote_literal(rec.sperrkz),'NULL') || ' , ' || COALESCE(quote_literal(rec.art),'NULL') || ' , ' || COALESCE(quote_literal(rec.soll_kontr),'NULL') || ' , ' || COALESCE(quote_literal(rec.o_nr),'NULL') || ' , ' || COALESCE(quote_literal(rec.finz_stat),'NULL') || ' , ' || COALESCE(quote_literal(rec.mwpf),'NULL') || ' , ' || COALESCE(quote_literal(rec.titkor),'NULL') || ' , ' || COALESCE(quote_literal(rec.drkor),'NULL') || ' , ' || COALESCE(quote_literal(rec.korrkz),'NULL') || ' , ' || COALESCE(quote_literal(rec.dtgr),'NULL') || ' , ' || COALESCE(quote_literal(rec.vwg),'NULL') || ' , ' || COALESCE(quote_literal(rec.utkor),'NULL') || ')'; ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _ut_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


