CREATE FUNCTION sva4.ut_upd(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE  id1 ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(join_nr) INTO anz FROM _ut_buffer WHERE join_nr= id1 ; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _ut_buffer! Wahrscheinlich wird er gerade bearbeitet'; end if; SELECT * INTO rec FROM _ut_buffer WHERE join_nr= id1 ; If FOUND then sql = 'UPDATE ut SET db_einfuegemarke= ' || COALESCE(quote_literal(rec.db_einfuegemarke),'NULL') || ' , jahr= ' || COALESCE(quote_literal(rec.jahr),'NULL') || ' , kap= ' || COALESCE(quote_literal(rec.kap),'NULL') || ' , tit= ' || COALESCE(quote_literal(rec.tit),'NULL') || ' , ut= ' || COALESCE(quote_literal(rec.ut),'NULL') || ' , utbez= ' || COALESCE(quote_literal(rec.utbez),'NULL') || ' , dr= ' || COALESCE(quote_literal(rec.dr),'NULL') || ' , dr2= ' || COALESCE(quote_literal(rec.dr2),'NULL') || ' , hhans= ' || COALESCE(quote_literal(rec.hhans),'NULL') || ' , akts= ' || COALESCE(quote_literal(rec.akts),'NULL') || ' , sperr= ' || COALESCE(quote_literal(rec.sperr),'NULL') || ' , reste= ' || COALESCE(quote_literal(rec.reste),'NULL') || ' , zvert= ' || COALESCE(quote_literal(rec.zvert),'NULL') || ' , fest= ' || COALESCE(quote_literal(rec.fest),'NULL') || ' , ausz= ' || COALESCE(quote_literal(rec.ausz),'NULL') || ' , soll= ' || COALESCE(quote_literal(rec.soll),'NULL') || ' , ein= ' || COALESCE(quote_literal(rec.ein),'NULL') || ' , verfkor= ' || COALESCE(quote_literal(rec.verfkor),'NULL') || ' , vojs= ' || COALESCE(quote_literal(rec.vojs),'NULL') || ' , kz_ueber= ' || COALESCE(quote_literal(rec.kz_ueber),'NULL') || ' , sperrkz= ' || COALESCE(quote_literal(rec.sperrkz),'NULL') || ' , art= ' || COALESCE(quote_literal(rec.art),'NULL') || ' , soll_kontr= ' || COALESCE(quote_literal(rec.soll_kontr),'NULL') || ' , o_nr= ' || COALESCE(quote_literal(rec.o_nr),'NULL') || ' , finz_stat= ' || COALESCE(quote_literal(rec.finz_stat),'NULL') || ' , mwpf= ' || COALESCE(quote_literal(rec.mwpf),'NULL') || ' , titkor= ' || COALESCE(quote_literal(rec.titkor),'NULL') || ' , drkor= ' || COALESCE(quote_literal(rec.drkor),'NULL') || ' , korrkz= ' || COALESCE(quote_literal(rec.korrkz),'NULL') || ' , dtgr= ' || COALESCE(quote_literal(rec.dtgr),'NULL') || ' , vwg= ' || COALESCE(quote_literal(rec.vwg),'NULL') || ' , utkor= ' || COALESCE(quote_literal(rec.utkor),'NULL') || ' WHERE join_nr=' || quote_literal(rec.join_nr); ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _ut_buffer WHERE join_nr= id1 ; else RETURN '-3'; END IF;
 return ret_dblink;  END;$_$;


