    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _zawe_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _zaweinst_buffer!'; end if; SELECT * INTO rec FROM _zawe_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO zawe (db_einfuegemarke, zw_nr, blz, konto, bname, bstr, bplz, bort, kz_uebern, uet_nr, art, waehrung, stap_nr, e_ist, a_ist, e_soll, a_soll, zbu_nr, euro_eist, euro_aist, euro_esoll, euro_asoll, kz_dta, sperre, kz_scheck, be_ist, ba_ist, be_soll, ba_soll) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.zw_nr),'NULL') || ' , ' || COALESCE(quote_literal(rec.blz),'NULL') || ' , ' || COALESCE(quote_literal(rec.konto),'NULL') || ' , ' || COALESCE(quote_literal(rec.bname),'NULL') || ' , ' || COALESCE(quote_literal(rec.bstr),'NULL') || ' , ' || COALESCE(quote_literal(rec.bplz),'NULL') || ' , ' || COALESCE(quote_literal(rec.bort),'NULL') || ' , ' || COALESCE(quote_literal(rec.kz_uebern),'NULL') || ' , ' || COALESCE(quote_literal(rec.uet_nr),'NULL') || ' , ' || COALESCE(quote_literal(rec.art),'NULL') || ' , ' || COALESCE(quote_literal(rec.waehrung),'NULL') || ' , ' || COALESCE(quote_literal(rec.stap_nr),'NULL') || ' , ' || COALESCE(quote_literal(rec.e_ist),'NULL') || ' , ' || COALESCE(quote_literal(rec.a_ist),'NULL') || ' , ' || COALESCE(quote_literal(rec.e_soll),'NULL') || ' , ' || COALESCE(quote_literal(rec.a_soll),'NULL') || ' , ' || COALESCE(quote_literal(rec.zbu_nr),'NULL') || ' , ' || COALESCE(quote_literal(rec.euro_eist),'NULL') || ' , ' || COALESCE(quote_literal(rec.euro_aist),'NULL') || ' , ' || COALESCE(quote_literal(rec.euro_esoll),'NULL') || ' , ' || COALESCE(quote_literal(rec.euro_asoll),'NULL') || ' , ' || COALESCE(quote_literal(rec.kz_dta),'NULL') || ' , ' || COALESCE(quote_literal(rec.sperre),'NULL') || ' , ' || COALESCE(quote_literal(rec.kz_scheck),'NULL') || ' , ' || COALESCE(quote_literal(rec.be_ist),'NULL') || ' , ' || COALESCE(quote_literal(rec.ba_ist),'NULL') || ' , ' || COALESCE(quote_literal(rec.be_soll),'NULL') || ' , ' || COALESCE(quote_literal(rec.ba_soll),'NULL') || ')'; ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _zawe_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


