OALESCE(quote_literal(rec.be_ist),'NULL') || ' , ba_ist= ' || COALESCE(quote_literal(rec.ba_ist),'NULL') || ' , be_soll= ' || COALESCE(quote_literal(rec.be_soll),'NULL') || ' , ba_soll= ' || COALESCE(quote_literal(rec.ba_soll),'NULL') || ' WHERE zw_nr=' || quote_literal(rec.zw_nr); ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _zawe_buffer WHERE zw_nr= id1 ; else RETURN '-3'; END IF;
