--
-- Name: zetpaw_into_k_abwesnheitsart(); Type: FUNCTION; Schema: sva4; Owner: -
--

CREATE FUNCTION sva4.zetpaw_into_k_abwesnheitsart() RETURNS void
    LANGUAGE plpgsql
    AS $$

DECLARE
	p_abwesenheitsart VARCHAR;
	counter INT := 1;
	
	BEGIN
		LOOP 
			p_abwesenheitsart := (SELECT split_part(txt,';',counter) FROM sva4.sys WHERE msnr = 'ZETPAW');
			EXIT WHEN p_abwesenheitsart = ''; 
			counter := counter + 1 ; 
			UPDATE sva4.k_abwesenheitsart SET zeb_autostorno = 'J' WHERE his_system_key = p_abwesenheitsart;
		END LOOP ; 
	END;
	
$$;


