CREATE FUNCTION sva4.zpa_ins(character varying) RETURNS text
    LANGUAGE plpgsql
    AS $_$DECLARE efm ALIAS FOR $1; rec RECORD; sql text; ret_dblink text; anz int8; BEGIN SELECT COUNT(db_einfuegemarke) INTO anz FROM _zpa_buffer WHERE db_einfuegemarke = efm; if anz > 1 then RAISE EXCEPTION 'Doppelte Datensätze in Tabelle _zpainst_buffer!'; end if; SELECT * INTO rec FROM _zpa_buffer WHERE db_einfuegemarke = efm; If FOUND then sql = 'INSERT INTO zpa (db_einfuegemarke, zp_key, zp_name1, zp_name2, plz, ort, str, land, landbez, bname1, bname2, bort1, bort2, konto, blz, wbezk, landkz, bankschl, bankkz, bic, blz_inland) VALUES (' || quote_literal(efm) || ' , ' || COALESCE(quote_literal(rec.zp_key),'NULL') || ' , ' || COALESCE(quote_literal(rec.zp_name1),'NULL') || ' , ' || COALESCE(quote_literal(rec.zp_name2),'NULL') || ' , ' || COALESCE(quote_literal(rec.plz),'NULL') || ' , ' || COALESCE(quote_literal(rec.ort),'NULL') || ' , ' || COALESCE(quote_literal(rec.str),'NULL') || ' , ' || COALESCE(quote_literal(rec.land),'NULL') || ' , ' || COALESCE(quote_literal(rec.landbez),'NULL') || ' , ' || COALESCE(quote_literal(rec.bname1),'NULL') || ' , ' || COALESCE(quote_literal(rec.bname2),'NULL') || ' , ' || COALESCE(quote_literal(rec.bort1),'NULL') || ' , ' || COALESCE(quote_literal(rec.bort2),'NULL') || ' , ' || COALESCE(quote_literal(rec.konto),'NULL') || ' , ' || COALESCE(quote_literal(rec.blz),'NULL') || ' , ' || COALESCE(quote_literal(rec.wbezk),'NULL') || ' , ' || COALESCE(quote_literal(rec.landkz),'NULL') || ' , ' || COALESCE(quote_literal(rec.bankschl),'NULL') || ' , ' || COALESCE(quote_literal(rec.bankkz),'NULL') || ' , ' || COALESCE(quote_literal(rec.bic),'NULL') || ' , ' || COALESCE(quote_literal(rec.blz_inland),'NULL') || ')'; ret_dblink = dblink_exec(gc('superx_fsv_90_ap'), sql); DELETE FROM _zpa_buffer WHERE db_einfuegemarke = efm; else RETURN '-3'; END IF; return ret_dblink;  END;$_$;


