--
-- Name: imp_busa_monate; Type: VIEW; Schema: cob; Owner: -
--

CREATE VIEW cob.imp_busa_monate AS
 SELECT db_einfuegemarke,
    busa_id,
    busa_quellsys,
    busa_quelldatnr,
    busa_quellidnr,
    busa_status,
    busa_hinweis,
    busa_jahr,
    busa_monat,
    busa_korepvon,
    busa_korepbis,
    busa_instnr,
    busa_projnr,
    busa_fikrkey,
    busa_kapitel,
    busa_titel,
    busa_betrag,
    busa_verwzweck1,
    busa_verwzweck2,
    busa_stornokz,
    (((date_part('year'::text, busa_korepbis) * (12)::double precision) + date_part('month'::text, busa_korepbis)) - ((date_part('year'::text, busa_korepvon) * (12)::double precision) + date_part('month'::text, busa_korepvon))) AS ausdr1,
    date_part('month'::text, busa_korepvon) AS ausdr2
   FROM cob.imp_busa x0
  WHERE (((busa_korepvon IS NULL) AND (busa_korepbis IS NULL)) OR ((((date_part('year'::text, busa_korepbis) * (12)::double precision) + date_part('month'::text, busa_korepbis)) - ((date_part('year'::text, busa_korepvon) * (12)::double precision) + date_part('month'::text, busa_korepvon))) = ((0)::numeric)::double precision));


--
-- Name: imp_busa_perioden; Type: VIEW; Schema: cob; Owner: -
--

CREATE VIEW cob.imp_busa_perioden AS
 SELECT db_einfuegemarke,
    busa_id,
    busa_quellsys,
    busa_quelldatnr,
    busa_quellidnr,
    busa_status,
    busa_hinweis,
    busa_jahr,
    busa_monat,
    busa_korepvon,
    busa_korepbis,
    busa_instnr,
    busa_projnr,
    busa_fikrkey,
    busa_kapitel,
    busa_titel,
    busa_betrag,
    busa_verwzweck1,
    busa_verwzweck2,
    busa_stornokz,
    (((date_part('year'::text, busa_korepbis) * (12)::double precision) + date_part('month'::text, busa_korepbis)) - ((date_part('year'::text, busa_korepvon) * (12)::double precision) + date_part('month'::text, busa_korepvon))) AS anzahlmonate
   FROM cob.imp_busa x0
  WHERE ((busa_korepvon IS NOT NULL) AND (busa_korepbis IS NOT NULL) AND (((((date_part('year'::text, busa_korepbis) * (12)::double precision) + date_part('month'::text, busa_korepbis)) - ((date_part('year'::text, busa_korepvon) * (12)::double precision) + date_part('month'::text, busa_korepvon))) + ((1)::numeric)::double precision) > ((1)::numeric)::double precision));


