--
-- Name: su_ffabschluss; Type: VIEW; Schema: cob; Owner: -
--

CREATE VIEW cob.su_ffabschluss AS
 SELECT DISTINCT abslkey,
    abslkeydbez
   FROM cob.su_imp_stud_view
  ORDER BY abslkey, abslkeydbez;


--
-- Name: su_fffach; Type: VIEW; Schema: cob; Owner: -
--

CREATE VIEW cob.su_fffach AS
 SELECT DISTINCT fachkey,
    min((fachkeydbez)::text) AS fachkeydbez
   FROM cob.su_imp_stud_view
  GROUP BY fachkey
  ORDER BY fachkey, (min((fachkeydbez)::text));


--
-- Name: su_ffsem; Type: VIEW; Schema: cob; Owner: -
--

CREATE VIEW cob.su_ffsem AS
 SELECT DISTINCT imp_stud.a_semester AS sem,
    k_sem.dbez AS dtxt
   FROM cob.k_sem,
    cob.imp_stud
  WHERE (k_sem.sem_key = mod((imp_stud.a_semester)::integer, 10))
  ORDER BY imp_stud.a_semester, k_sem.dbez;


--
-- Name: su_ffstgnr; Type: VIEW; Schema: cob; Owner: -
--

CREATE VIEW cob.su_ffstgnr AS
 SELECT stgnr,
    '*'::text AS dummy
   FROM cob.su_imp_stud_view
  GROUP BY stgnr;


--
-- Name: su_stud_semester; Type: VIEW; Schema: cob; Owner: -
--

CREATE VIEW cob.su_stud_semester AS
 SELECT DISTINCT stud.stud_sem AS sem,
    k_sem.dbez AS dtxt
   FROM cob.stud,
    cob.k_sem
  WHERE (mod((stud.stud_sem)::integer, 10) = k_sem.sem_key)
  ORDER BY stud.stud_sem, k_sem.dbez;


--
-- Name: su_view_sem; Type: VIEW; Schema: cob; Owner: -
--

CREATE VIEW cob.su_view_sem AS
 SELECT DISTINCT su_imp_stud_view.sem,
    k_sem.dbez
   FROM cob.k_sem,
    cob.su_imp_stud_view
  WHERE (k_sem.sem_key = mod(su_imp_stud_view.sem, 10))
  ORDER BY su_imp_stud_view.sem, k_sem.dbez;


