--

CREATE VIEW cob.tit_imp_sva_pbv AS
 SELECT pbv_titel AS key,
    pbv_titel AS text
   FROM cob.imp_sva_pbv
  GROUP BY pbv_titel;


--
-- Name: titel_in_busa; Type: VIEW; Schema: cob; Owner: -
--

CREATE VIEW cob.titel_in_busa AS
 SELECT DISTINCT "substring"((busa_titel)::text, 4, 2) AS key,
    "substring"((busa_titel)::text, 4, 2) AS text,
    busa_kapitel AS kapitel
   FROM cob.busa
  WHERE ((busa_titel IS NOT NULL) AND (busa_kapitel IS NOT NULL))
  ORDER BY ("substring"((busa_titel)::text, 4, 2)), busa_kapitel;


