--
-- Name: bau_stat; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.bau_stat AS
 SELECT stamm.geb_nr,
    stamm.ges_nr,
    stamm.raumid,
    stamm.nutzer_nr,
    ((((((((((((date_part('year'::text, ('now'::text)::date))::character varying(4))::text || (sv_hochschule.key_bundesland)::text) || (geb.hs_nr)::text) || (("substring"(((stamm.geb_nr)::text || '0000'::text), 1, 4))::character varying(4))::text) || (("substring"(((stamm.ges_nr)::text || '00'::text), 1, 2))::character varying(2))::text) || (("substring"(((stamm.raumid)::text || '0000'::text), 1, 4))::character varying(4))::text) || (("substring"(btrim(to_char((stamm.flaeche + (100000)::numeric), '999999'::text)), 2, 5))::character varying(5))::text) || (stamm.rna_nr)::text) || (nutzer.ore_nr)::text) || (nutzer.lfb_nr)::text) || (nutzer.fgb_nr)::text) AS statistik
   FROM ((((mbs.stamm
     JOIN mbs.geb ON (((stamm.geb_nr)::text = (geb.geb_nr)::text)))
     JOIN mbs.k_hochschule ON (((geb.hs_nr)::text = (k_hochschule.bund_hochschule)::text)))
     JOIN mbs.nutzer ON (((stamm.nutzer_nr)::text = (nutzer.nutzer_nr)::text)))
     JOIN mbs.sv_hochschule ON ((1 = 1)));


--
-- Name: fakt_stud; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.fakt_stud AS
 SELECT 'Detail'::text AS bezug,
    ein_studfakt.hs_nr,
    ein_studfakt.fgr_nr,
    fgr.stb_nr,
    ein_zeitansatz.studg_nr,
    ein_studfakt.vl_fakt,
    ein_studfakt.vl_zeit,
    ein_studfakt.vl_platz,
    ein_studfakt.sem_fakt,
    ein_studfakt.sem_zeit,
    ein_studfakt.sem_platz,
    ein_studfakt.pra_fakt,
    ein_studfakt.pra_zeit,
    ein_studfakt.pra_platz,
    ein_studfakt.gr_fakt,
    ein_studfakt.gr_zeit,
    ein_studfakt.gr_platz,
    ein_studfakt.lese_fakt,
    ein_studfakt.lese_zeit,
    ein_studfakt.lese_platz,
    ein_studfakt.theo_fakt,
    ein_studfakt.theo_platz,
    ein_studfakt.exp_fakt,
    ein_studfakt.exp_platz,
    ein_studfakt.dv_fakt,
    ein_studfakt.dv_platz
   FROM ((mbs.ein_studfakt
     JOIN mbs.ein_zeitansatz ON ((((ein_zeitansatz.hs_nr)::text || (ein_zeitansatz.fgr_nr)::text) = ((ein_studfakt.hs_nr)::text || (ein_studfakt.fgr_nr)::text))))
     JOIN mbs.fgr ON (((ein_zeitansatz.fgr_nr)::text = (fgr.fgr_nr)::text)))
UNION
 SELECT 'STB Bezug'::text AS bezug,
    ein_zeitansatz.hs_nr,
    ein_zeitansatz.fgr_nr,
    fgr.stb_nr,
    ein_zeitansatz.studg_nr,
    ein_studfakt.vl_fakt,
    ein_studfakt.vl_zeit,
    ein_studfakt.vl_platz,
    ein_studfakt.sem_fakt,
    ein_studfakt.sem_zeit,
    ein_studfakt.sem_platz,
    ein_studfakt.pra_fakt,
    ein_studfakt.pra_zeit,
    ein_studfakt.pra_platz,
    ein_studfakt.gr_fakt,
    ein_studfakt.gr_zeit,
    ein_studfakt.gr_platz,
    ein_studfakt.lese_fakt,
    ein_studfakt.lese_zeit,
    ein_studfakt.lese_platz,
    ein_studfakt.theo_fakt,
    ein_studfakt.theo_platz,
    ein_studfakt.exp_fakt,
    ein_studfakt.exp_platz,
    ein_studfakt.dv_fakt,
    ein_studfakt.dv_platz
   FROM ((mbs.ein_zeitansatz
     JOIN mbs.ein_studfakt ON ((('0000'::text || (substr((ein_zeitansatz.fgr_nr)::text, 1, 1) || '00'::text)) = ((ein_studfakt.hs_nr)::text || (ein_studfakt.fgr_nr)::text))))
     JOIN mbs.fgr ON (((ein_zeitansatz.fgr_nr)::text = (fgr.fgr_nr)::text)))
  WHERE (NOT (EXISTS ( SELECT einstudfakt.hs_nr,
            einstudfakt.fgr_nr,
            einstudfakt.vl_fakt,
            einstudfakt.vl_zeit,
            einstudfakt.vl_platz,
            einstudfakt.sem_fakt,
            einstudfakt.sem_zeit,
            einstudfakt.sem_platz,
            einstudfakt.pra_fakt,
            einstudfakt.pra_zeit,
            einstudfakt.pra_platz,
            einstudfakt.gr_fakt,
            einstudfakt.gr_zeit,
            einstudfakt.gr_platz,
            einstudfakt.lese_fakt,
            einstudfakt.lese_zeit,
            einstudfakt.lese_platz,
            einstudfakt.theo_fakt,
            einstudfakt.theo_platz,
            einstudfakt.exp_fakt,
            einstudfakt.exp_platz,
            einstudfakt.dv_fakt,
            einstudfakt.dv_platz
           FROM mbs.ein_studfakt einstudfakt
          WHERE (((ein_zeitansatz.hs_nr)::text = (einstudfakt.hs_nr)::text) AND ((ein_zeitansatz.fgr_nr)::text = (einstudfakt.fgr_nr)::text)))))
UNION
 SELECT 'Standard'::text AS bezug,
    ein_zeitansatz.hs_nr,
    ein_zeitansatz.fgr_nr,
    fgr.stb_nr,
    ein_zeitansatz.studg_nr,
    ein_studfakt.vl_fakt,
    ein_studfakt.vl_zeit,
    ein_studfakt.vl_platz,
    ein_studfakt.sem_fakt,
    ein_studfakt.sem_zeit,
    ein_studfakt.sem_platz,
    ein_studfakt.pra_fakt,
    ein_studfakt.pra_zeit,
    ein_studfakt.pra_platz,
    ein_studfakt.gr_fakt,
    ein_studfakt.gr_zeit,
    ein_studfakt.gr_platz,
    ein_studfakt.lese_fakt,
    ein_studfakt.lese_zeit,
    ein_studfakt.lese_platz,
    ein_studfakt.theo_fakt,
    ein_studfakt.theo_platz,
    ein_studfakt.exp_fakt,
    ein_studfakt.exp_platz,
    ein_studfakt.dv_fakt,
    ein_studfakt.dv_platz
   FROM ((mbs.ein_zeitansatz
     JOIN mbs.ein_studfakt ON ((((ein_studfakt.hs_nr)::text = '0000'::text) AND ((ein_studfakt.fgr_nr)::text = '000'::text))))
     JOIN mbs.fgr ON (((ein_zeitansatz.fgr_nr)::text = (fgr.fgr_nr)::text)))
  WHERE (NOT (EXISTS ( SELECT einstudfakt.db_einfuegemarke,
            einstudfakt.hs_nr,
            einstudfakt.fgr_nr,
            einstudfakt.vl_fakt,
            einstudfakt.vl_zeit,
            einstudfakt.vl_platz,
            einstudfakt.sem_fakt,
            einstudfakt.sem_zeit,
            einstudfakt.sem_platz,
            einstudfakt.pra_fakt,
            einstudfakt.pra_zeit,
            einstudfakt.pra_platz,
            einstudfakt.gr_fakt,
            einstudfakt.gr_zeit,
            einstudfakt.gr_platz,
            einstudfakt.lese_fakt,
            einstudfakt.lese_zeit,
            einstudfakt.lese_platz,
            einstudfakt.theo_fakt,
            einstudfakt.theo_platz,
            einstudfakt.exp_fakt,
            einstudfakt.exp_platz,
            einstudfakt.dv_fakt,
            einstudfakt.dv_platz
           FROM mbs.ein_studfakt einstudfakt
          WHERE ((((ein_zeitansatz.hs_nr)::text = (einstudfakt.hs_nr)::text) AND ((ein_zeitansatz.fgr_nr)::text = (einstudfakt.fgr_nr)::text)) OR ((substr((ein_zeitansatz.fgr_nr)::text, 1, 1) || '00'::text) = (einstudfakt.fgr_nr)::text)))));


--
-- Name: esum_nb08; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.esum_nb08 AS
 SELECT hsfgr.hs_nr,
    hsfgr.fgr_nr,
    ein_zeitansatz.studg_nr,
    (((ein_student.studzahl * ein_zeitansatz.teilnahme) * fakt_stud.exp_platz) * fakt_stud.exp_fakt) AS sum08
   FROM (((mbs.ein_zeitansatz
     JOIN mbs.hsfgr ON ((((ein_zeitansatz.hs_nr)::text = (hsfgr.hs_nr)::text) AND ((ein_zeitansatz.fgr_nr)::text = (hsfgr.fgr_nr)::text))))
     JOIN mbs.ein_student ON ((((ein_student.studg_nr)::text = (ein_zeitansatz.studg_nr)::text) AND ((ein_student.hs_nr)::text = (ein_zeitansatz.hs_nr)::text))))
     JOIN mbs.fakt_stud ON ((((ein_zeitansatz.fgr_nr)::text = (fakt_stud.fgr_nr)::text) AND ((ein_zeitansatz.hs_nr)::text = (fakt_stud.hs_nr)::text) AND ((ein_zeitansatz.studg_nr)::text = (fakt_stud.studg_nr)::text))))
  WHERE ((ein_zeitansatz.teilnahme = (1)::numeric) AND ((((ein_student.studzahl * ein_zeitansatz.teilnahme) * fakt_stud.exp_platz) * fakt_stud.exp_fakt) > (0)::numeric))
  GROUP BY hsfgr.hs_nr, hsfgr.fgr_nr, ein_zeitansatz.studg_nr, ein_student.studzahl, ein_zeitansatz.teilnahme, fakt_stud.exp_platz, fakt_stud.exp_fakt;


