   FROM (mbs.ein_personal
     JOIN mbs.ein_persfakt ON ((((ein_persfakt.hs_nr)::text = '0000'::text) AND ((ein_persfakt.fgr_nr)::text = '000'::text) AND ((ein_personal.pers_gr)::text = (ein_persfakt.pers_gr)::text))))
  WHERE (NOT (EXISTS ( SELECT einpersfakt.db_einfuegemarke,
            einpersfakt.hs_nr,
            einpersfakt.fgr_nr,
            einpersfakt.pers_pf,
            einpersfakt.pers_ff,
