          WHERE (((ein_personal.hs_nr)::text = (einpersfakt.hs_nr)::text) AND ((ein_personal.fgr_nr)::text = (einpersfakt.fgr_nr)::text) AND ((ein_personal.pers_gr)::text = (einpersfakt.pers_gr)::text)))));


--
-- Name: esum_nb10; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.esum_nb10 AS
 SELECT ein_personal.hs_nr,
    ein_personal.fgr_nr,
    sum((((ein_personal.stellen * ein_personal.pers_stell) * fakt_pers.pers_pf_ex) * fakt_pers.pers_ff_ex)) AS sum10
   FROM (mbs.ein_personal
     JOIN mbs.fakt_pers ON ((((ein_personal.hs_nr)::text = (fakt_pers.hs_nr)::text) AND ((ein_personal.fgr_nr)::text = (fakt_pers.fgr_nr)::text) AND ((ein_personal.pers_gr)::text = (fakt_pers.pers_gr)::text))))
  WHERE ((((ein_personal.stellen * ein_personal.pers_stell) * fakt_pers.pers_pf_ex) * fakt_pers.pers_ff_ex) > (0)::numeric)
  GROUP BY ein_personal.hs_nr, ein_personal.fgr_nr;


--
-- Name: esum_nb21; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.esum_nb21 AS
 SELECT hs_nr,
    fgr_nr,
    sum((
        CASE
            WHEN (ff = (0)::numeric) THEN anz
            ELSE (0)::numeric
        END + ((anz * pf) * ff))) AS sum21
   FROM mbs.ein_detail
  WHERE (((nb_nr)::text = '21'::text) AND (((anz * pf) * ff) > (0)::numeric))
  GROUP BY hs_nr, fgr_nr;


--
-- Name: esum_nb0810; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.esum_nb0810 AS
 SELECT hsfgr.hs_nr,
    hsfgr.fgr_nr,
    ((
        CASE
            WHEN (esum_nb08.sum08 IS NULL) THEN (0)::numeric
            ELSE esum_nb08.sum08
        END +
        CASE
            WHEN (esum_nb10.sum10 IS NULL) THEN (0)::numeric
            ELSE esum_nb10.sum10
        END) +
        CASE
            WHEN (esum_nb21.sum21 IS NULL) THEN (0)::numeric
            ELSE esum_nb21.sum21
        END) AS sumb
   FROM (((mbs.hsfgr
     LEFT JOIN mbs.esum_nb08 ON ((((hsfgr.hs_nr)::text = (esum_nb08.hs_nr)::text) AND ((hsfgr.fgr_nr)::text = (esum_nb08.fgr_nr)::text))))
     LEFT JOIN mbs.esum_nb10 ON ((((hsfgr.hs_nr)::text = (esum_nb10.hs_nr)::text) AND ((hsfgr.fgr_nr)::text = (esum_nb10.fgr_nr)::text))))
     LEFT JOIN mbs.esum_nb21 ON ((((hsfgr.hs_nr)::text = (esum_nb21.hs_nr)::text) AND ((hsfgr.fgr_nr)::text = (esum_nb21.fgr_nr)::text))));


--
-- Name: esum_nb081012; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.esum_nb081012 AS
 SELECT hsfgr.hs_nr,
    hsfgr.fgr_nr,
        CASE
            WHEN (esum_nb0810.sumb IS NULL) THEN (0)::numeric
            ELSE (esum_nb0810.sumb + (esum_nb0810.sumb * ein_detail.pf))
        END AS sumb
   FROM ((mbs.hsfgr
     JOIN mbs.esum_nb0810 ON ((((hsfgr.hs_nr)::text = (esum_nb0810.hs_nr)::text) AND ((hsfgr.fgr_nr)::text = (esum_nb0810.fgr_nr)::text))))
     JOIN mbs.ein_detail ON ((((hsfgr.hs_nr)::text = (ein_detail.hs_nr)::text) AND ((hsfgr.fgr_nr)::text = (ein_detail.fgr_nr)::text))))
  WHERE ((ein_detail.pf > (0)::numeric) AND ((ein_detail.bezug)::text = 'Zuschlag Labor'::text));


--
-- Name: esum_nb09; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.esum_nb09 AS
 SELECT ein_personal.hs_nr,
    ein_personal.fgr_nr,
    sum((((ein_personal.stellen * ein_personal.pers_stell) * fakt_pers.pers_pf) * fakt_pers.pers_ff)) AS sumb
   FROM (mbs.ein_personal
     JOIN mbs.fakt_pers ON ((((ein_personal.hs_nr)::text = (fakt_pers.hs_nr)::text) AND ((ein_personal.fgr_nr)::text = (fakt_pers.fgr_nr)::text) AND ((ein_personal.pers_gr)::text = (fakt_pers.pers_gr)::text))))
  GROUP BY ein_personal.hs_nr, ein_personal.fgr_nr;


--
-- Name: esum_nb14; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.esum_nb14 AS
 SELECT hs_nr,
    fgr_nr,
    sum((
        CASE
            WHEN (ff = (0)::numeric) THEN anz
            ELSE (0)::numeric
        END + ((anz * pf) * ff))) AS sumb
   FROM mbs.ein_detail
  WHERE ((nb_nr)::text = '14'::text)
  GROUP BY hs_nr, fgr_nr;


--
-- Name: esum_pers; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.esum_pers AS
 SELECT hs_nr,
    fgr_nr,
    sum((stellen * pers_stell)) AS spers
   FROM mbs.ein_personal
  GROUP BY hs_nr, fgr_nr
  ORDER BY hs_nr, fgr_nr;


--
-- Name: fakt_bib; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.fakt_bib AS
 SELECT 'Detail'::text AS bezug,
    ein_biblfakt.hs_nr,
    ein_biblfakt.fgr_nr,
    fgr.stb_nr,
    ein_biblfakt.buch_ff,
    ein_biblfakt.mbuch_ff,
    ein_biblfakt.zeit_ff
   FROM ((mbs.ein_biblfakt
     JOIN mbs.ein_bibliothek ON ((((ein_bibliothek.hs_nr)::text = (ein_biblfakt.hs_nr)::text) AND ((ein_bibliothek.fgr_nr)::text = (ein_biblfakt.fgr_nr)::text))))
     JOIN mbs.fgr ON (((ein_bibliothek.fgr_nr)::text = (fgr.fgr_nr)::text)))
UNION
 SELECT 'STB Bezug'::text AS bezug,
    ein_bibliothek.hs_nr,
    ein_bibliothek.fgr_nr,
    fgr.stb_nr,
    ein_biblfakt.buch_ff,
    ein_biblfakt.mbuch_ff,
    ein_biblfakt.zeit_ff
   FROM ((mbs.ein_bibliothek
     JOIN mbs.ein_biblfakt ON ((((ein_bibliothek.hs_nr)::text = (ein_biblfakt.hs_nr)::text) AND ((substr((ein_bibliothek.fgr_nr)::text, 1, 1) || '00'::text) = (ein_biblfakt.fgr_nr)::text))))
     JOIN mbs.fgr ON (((ein_bibliothek.fgr_nr)::text = (fgr.fgr_nr)::text)))
  WHERE (NOT (EXISTS ( SELECT einbiblfakt.db_einfuegemarke,
            einbiblfakt.hs_nr,
            einbiblfakt.fgr_nr,
            einbiblfakt.buch_ff,
            einbiblfakt.mbuch_ff,
            einbiblfakt.zeit_ff
           FROM mbs.ein_biblfakt einbiblfakt
          WHERE (((ein_bibliothek.hs_nr)::text = (einbiblfakt.hs_nr)::text) AND ((ein_bibliothek.fgr_nr)::text = (einbiblfakt.fgr_nr)::text)))))
UNION
 SELECT 'Standard'::text AS bezug,
    ein_biblfakt.hs_nr,
    ein_bibliothek.fgr_nr,
    fgr.stb_nr,
    ein_biblfakt.buch_ff,
    ein_biblfakt.mbuch_ff,
    ein_biblfakt.zeit_ff
   FROM ((mbs.ein_bibliothek
     JOIN mbs.ein_biblfakt ON ((((ein_biblfakt.hs_nr)::text = '0000'::text) AND ((ein_biblfakt.fgr_nr)::text = '000'::text))))
     JOIN mbs.fgr ON (((ein_bibliothek.fgr_nr)::text = (fgr.fgr_nr)::text)))
  WHERE (NOT (EXISTS ( SELECT einbiblfakt.db_einfuegemarke,
            einbiblfakt.hs_nr,
            einbiblfakt.fgr_nr,
            einbiblfakt.buch_ff,
            einbiblfakt.mbuch_ff,
            einbiblfakt.zeit_ff
           FROM mbs.ein_biblfakt einbiblfakt
          WHERE (((ein_bibliothek.hs_nr)::text = (einbiblfakt.hs_nr)::text) AND (((ein_bibliothek.fgr_nr)::text = (einbiblfakt.fgr_nr)::text) OR ((substr((ein_bibliothek.fgr_nr)::text, 1, 1) || '00'::text) = (einbiblfakt.fgr_nr)::text))))));


--
-- Name: bedarf_view; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.bedarf_view AS
 SELECT 'SWS Vorlesen'::text AS bezug,
    ein_zeitansatz.hs_nr,
    ein_zeitansatz.fgr_nr,
    fgr.stb_nr,
    nb.nb_nr,
    nb.nbgr_nr,
    ein_student.studg_nr,
    NULL::text AS pers_gr,
    ein_student.studg AS gru,
    ein_student.studzahl AS ebezug,
    ein_zeitansatz.vorles AS esws,
    fakt_stud.vl_zeit AS enz,
    fakt_stud.vl_platz AS epf,
    0 AS epl,
    fakt_stud.vl_fakt AS eff,
    ein_zeitansatz.teilnahme,
    0 AS persanz,
    round(((((ein_zeitansatz.vorles / (fakt_stud.vl_zeit * fakt_stud.vl_platz)) * ein_student.studzahl) * fakt_stud.vl_fakt) * ein_zeitansatz.teilnahme), 6) AS bedarf
   FROM mbs.nb,
    (((mbs.ein_student
     JOIN mbs.ein_zeitansatz ON ((((ein_student.hs_nr)::text = (ein_zeitansatz.hs_nr)::text) AND ((ein_student.studg_nr)::text = (ein_zeitansatz.studg_nr)::text))))
     JOIN mbs.fakt_stud ON ((((ein_zeitansatz.studg_nr)::text = (fakt_stud.studg_nr)::text) AND ((ein_zeitansatz.hs_nr)::text = (fakt_stud.hs_nr)::text) AND ((ein_zeitansatz.fgr_nr)::text = (fakt_stud.fgr_nr)::text))))
     JOIN mbs.fgr ON (((ein_zeitansatz.fgr_nr)::text = (fgr.fgr_nr)::text)))
  WHERE (((nb.nb_nr)::text = '01'::text) AND (ein_student.studzahl > (0)::numeric) AND (ein_zeitansatz.vorles > (0)::numeric))
