   FROM mbs.nb,
    (((mbs.ein_student
     JOIN mbs.ein_zeitansatz ON ((((ein_student.hs_nr)::text = (ein_zeitansatz.hs_nr)::text) AND ((ein_student.studg_nr)::text = (ein_zeitansatz.studg_nr)::text))))
     JOIN mbs.fakt_stud ON ((((ein_zeitansatz.studg_nr)::text = (fakt_stud.studg_nr)::text) AND ((ein_zeitansatz.hs_nr)::text = (fakt_stud.hs_nr)::text) AND ((ein_zeitansatz.fgr_nr)::text = (fakt_stud.fgr_nr)::text))))
