     JOIN mbs.fakt_stud ON ((((ein_zeitansatz.studg_nr)::text = (fakt_stud.studg_nr)::text) AND ((ein_zeitansatz.fgr_nr)::text = (fakt_stud.fgr_nr)::text) AND ((ein_zeitansatz.hs_nr)::text = (fakt_stud.hs_nr)::text))))
