--
-- Name: beleg_anz; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.beleg_anz AS
 SELECT geb_nr,
    ges_nr,
    raumid,
    count(0) AS anz
   FROM mbs.beleg
  GROUP BY geb_nr, ges_nr, raumid
  ORDER BY geb_nr, ges_nr, raumid, (count(0));


--
-- Name: beleg_anz_dat; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.beleg_anz_dat AS
 SELECT geb_nr,
    ges_nr,
    raumid,
    count(*) AS anz
   FROM mbs.beleg
  WHERE (((bel_bis >= ('now'::text)::date) OR (bel_bis IS NULL)) AND ((bel_von <= ('now'::text)::date) OR (bel_von IS NULL)))
  GROUP BY geb_nr, ges_nr, raumid
  ORDER BY geb_nr, ges_nr, raumid;


