--

CREATE VIEW mbs.db_spaltplaus_view AS
 SELECT DISTINCT db_tabellen.tabellen_id,
    db_tabellen.name AS tabellen_name,
    db_spalten.spalten_id,
    db_spalten.name AS spalten_name
   FROM mbs.db_spaltenplausis,
    mbs.db_tabellen,
    mbs.db_spalten
  WHERE ((db_spaltenplausis.spalten_id = db_spalten.spalten_id) AND (db_tabellen.tabellen_id = db_spalten.tabellen_id))
  ORDER BY db_tabellen.tabellen_id, db_tabellen.name, db_spalten.spalten_id, db_spalten.name;


