--
-- Name: esum_nb12; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.esum_nb12 AS
 SELECT ein_detail.hs_nr,
    ein_detail.fgr_nr,
    ((esum_nb08.sum08 + esum_nb10.sum10) * ein_detail.pf) AS sum12
   FROM ((mbs.ein_detail
     JOIN mbs.esum_nb08 ON ((((ein_detail.fgr_nr)::text = (esum_nb08.fgr_nr)::text) AND ((ein_detail.hs_nr)::text = (esum_nb08.hs_nr)::text))))
     JOIN mbs.esum_nb10 ON ((((ein_detail.fgr_nr)::text = (esum_nb10.fgr_nr)::text) AND ((ein_detail.hs_nr)::text = (esum_nb10.hs_nr)::text))))
  WHERE ((ein_detail.nb_nr)::text = '12'::text);


