--
-- Name: hs_view; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.hs_view AS
 SELECT DISTINCT geb.hs_nr,
    k_hochschule.druck_hochschule AS hs,
    sv_hochschule.key_bundesland,
    'RP'::character varying(2) AS bw_rp,
    '0'::character varying(1) AS bw_merk,
    (date_part('year'::text, ('now'::text)::date))::character varying(4) AS mjahr
   FROM mbs.geb,
    mbs.k_hochschule,
    mbs.sv_hochschule
  WHERE ((geb.hs_nr)::text = (k_hochschule.bund_hochschule)::text);


--
-- Name: hsfgr_view; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.hsfgr_view AS
 SELECT DISTINCT hsfgr.hs_nr,
    k_hochschule.druck_hochschule AS hs
   FROM mbs.hsfgr,
    mbs.k_hochschule
  WHERE ((hsfgr.hs_nr)::text = (k_hochschule.bund_hochschule)::text)
  ORDER BY hsfgr.hs_nr, k_hochschule.druck_hochschule;


--
-- Name: hsstb_view; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.hsstb_view AS
 SELECT DISTINCT hsfgr.hs_nr,
    k_hochschule.druck_hochschule AS hs,
    stb.stb_nr,
    stb.stb
   FROM (((mbs.hsfgr
     JOIN mbs.fgr ON (((hsfgr.fgr_nr)::text = (fgr.fgr_nr)::text)))
     JOIN mbs.stb ON (((fgr.stb_nr)::text = (stb.stb_nr)::text)))
     JOIN mbs.k_hochschule ON (((hsfgr.hs_nr)::text = (k_hochschule.bund_hochschule)::text)))
  ORDER BY hsfgr.hs_nr, stb.stb_nr, stb.stb, k_hochschule.druck_hochschule;


