--
-- Name: ivst_ges; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.ivst_ges AS
 SELECT ges.db_einfuegemarke,
    ges.geb_nr,
    ges.ges_nr,
    ges.ges
   FROM mbs.ges
UNION
 SELECT geb.db_einfuegemarke,
    geb.geb_nr,
    '-'::character varying(2) AS ges_nr,
    '-'::character varying(25) AS ges
   FROM mbs.geb;


