--
-- Name: ivst_stamm; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.ivst_stamm AS
 SELECT stamm.db_einfuegemarke,
    stamm.geb_nr,
    stamm.ges_nr,
    stamm.raumid,
    stamm.raumnr,
    stamm.bez,
    stamm.kost_nr,
    stamm.rna_nr
   FROM mbs.stamm
UNION
 SELECT ges.db_einfuegemarke,
    ges.geb_nr,
    ges.ges_nr,
    '-'::character varying(4) AS raumid,
    '-'::character varying(8) AS raumnr,
    '-'::character varying(25) AS bez,
    '-'::character varying(10) AS kost_nr,
    '-'::character varying(10) AS rna_nr
   FROM mbs.ges
UNION
 SELECT geb.db_einfuegemarke,
    geb.geb_nr,
    '-'::character varying(2) AS ges_nr,
    '-'::character varying(4) AS raumid,
    '-'::character varying(8) AS raumnr,
    '-'::character varying(25) AS bez,
    '-'::character varying(10) AS kost_nr,
    '-'::character varying(10) AS rna_nr
   FROM mbs.geb;


