--
-- Name: nbstamm; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.nbstamm AS
 SELECT nb.nbgr_nr,
    stamm.geb_nr,
    stamm.ges_nr,
    stamm.raumid,
    stamm.flaeche,
    stamm.rna_nr,
    stamm.nutzer_nr,
    stamm.kost_nr,
    stamm.traeger_nr,
    stamm.kfa_nr,
    nutzer.fgr_nr,
    nutzer.stb_nr,
    geb.gebber_nr,
    geb.hs_nr
   FROM (mbs.geb
     JOIN (((mbs.stamm
     JOIN mbs.rna ON (((stamm.rna_nr)::text = (rna.rna_nr)::text)))
     JOIN mbs.nb ON (((rna.rnaber_nr)::text = (nb.rnaber_nr)::text)))
     JOIN mbs.nutzer ON (((stamm.nutzer_nr)::text = (nutzer.nutzer_nr)::text))) ON (((geb.geb_nr)::text = (stamm.geb_nr)::text)))
  GROUP BY nb.nbgr_nr, stamm.geb_nr, stamm.ges_nr, stamm.raumid, stamm.flaeche, stamm.rna_nr, stamm.nutzer_nr, stamm.kost_nr, stamm.traeger_nr, stamm.kfa_nr, nutzer.fgr_nr, nutzer.stb_nr, geb.gebber_nr, geb.hs_nr;


--
-- Name: nutzer_bw; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.nutzer_bw AS
 SELECT DISTINCT sv_hochschule.key_hochschule,
    nutzer.nutzer_nr,
    nutzer.nutzer,
    nutzer.ore_nr,
    nutzer.lfb_nr,
    nutzer.fgb_nr
   FROM mbs.nutzer,
    mbs.sv_hochschule;


