--
-- Name: pgd_bau; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.pgd_bau AS
 SELECT DISTINCT pgd_join_id,
    pgd_status,
    pgd_vornamen,
    pgd_name,
        CASE
            WHEN (pgd_vornamen IS NULL) THEN ((pgd_name)::text || ', -'::text)
            ELSE (((pgd_name)::text || ', '::text) || (pgd_vornamen)::text)
        END AS bau_name,
    pgd_titel,
    pgd_namenbestand,
    pgd_eintrittsdatum,
    pgd_austrittsdatum
   FROM mbs.pgd
  ORDER BY pgd_join_id, pgd_status, pgd_vornamen, pgd_name,
        CASE
            WHEN (pgd_vornamen IS NULL) THEN ((pgd_name)::text || ', -'::text)
            ELSE (((pgd_name)::text || ', '::text) || (pgd_vornamen)::text)
        END, pgd_titel, pgd_namenbestand, pgd_eintrittsdatum, pgd_austrittsdatum;


