--
-- Name: rnakfa_view; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.rnakfa_view AS
 SELECT DISTINCT kfa.kfa_nr,
    kfa.kfa,
    rna.rna_nr,
    rna.rna,
    rnakfa.rnakfa,
    rnakfa.bem
   FROM ((mbs.kfa
     JOIN mbs.rnakfa ON (((kfa.kfa_nr)::text = (rnakfa.kfa_nr)::text)))
     JOIN mbs.rna ON (((rna.rna_nr)::text = (rnakfa.rna_nr)::text)));


--
-- Name: rp_stamm; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.rp_stamm AS
 SELECT geb_nr,
    ges_nr,
    raumid,
    rna_nr,
    flaeche,
    nutzer_nr
   FROM mbs.stamm
  WHERE ((((rna_nr)::text >= '01*'::text) AND ((rna_nr)::text < '07*'::text)) OR (((rna_nr)::text >= '1*'::text) AND ((rna_nr)::text < '700'::text)));


--
-- Name: rp_umleg0; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.rp_umleg0 AS
 SELECT ab_nutzer,
    ((100)::double precision - sum(anteil)) AS rest
   FROM mbs.umleg
  GROUP BY ab_nutzer
  ORDER BY ab_nutzer;


--
-- Name: rp_umleg; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.rp_umleg AS
 SELECT 'Auf Prozent'::text AS bezug,
    umleg.ab_nutzer,
    umleg.auf_nutzer,
    (umleg.anteil / (100)::double precision) AS anteil
   FROM mbs.umleg
UNION
 SELECT 'Rest Prozent'::text AS bezug,
    rp_umleg0.ab_nutzer,
    rp_umleg0.ab_nutzer AS auf_nutzer,
    (rp_umleg0.rest / (100)::double precision) AS anteil
   FROM mbs.rp_umleg0
UNION
 SELECT 'Dummy'::text AS bezug,
    'Dummy'::character varying AS ab_nutzer,
    'Dummy'::character varying AS auf_nutzer,
    0 AS anteil;


--
-- Name: rp_bestand; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.rp_bestand AS
 SELECT 'Anteil'::text AS bezug,
    rp_stamm.geb_nr,
    rp_stamm.ges_nr,
    rp_stamm.raumid,
    rp_stamm.rna_nr,
    (0)::numeric(14,2) AS flaeche,
    rp_umleg.auf_nutzer AS nutzer_nr,
    (rp_umleg.anteil * (rp_stamm.flaeche)::double precision) AS fla_ist
   FROM mbs.rp_stamm,
    mbs.rp_umleg
  WHERE (((rp_umleg.ab_nutzer)::text = (rp_stamm.nutzer_nr)::text) AND (rp_umleg.bezug = 'Auf Prozent'::text))
UNION
 SELECT 'Rest'::text AS bezug,
    rp_stamm.geb_nr,
    rp_stamm.ges_nr,
    rp_stamm.raumid,
    rp_stamm.rna_nr,
    rp_stamm.flaeche,
    rp_umleg.auf_nutzer AS nutzer_nr,
    (rp_umleg.anteil * (rp_stamm.flaeche)::double precision) AS fla_ist
   FROM mbs.rp_stamm,
    mbs.rp_umleg
  WHERE (((rp_umleg.ab_nutzer)::text = (rp_stamm.nutzer_nr)::text) AND (rp_umleg.bezug = 'Rest Prozent'::text))
UNION
 SELECT 'Ist'::text AS bezug,
    rp_stamm.geb_nr,
    rp_stamm.ges_nr,
    rp_stamm.raumid,
    rp_stamm.rna_nr,
    rp_stamm.flaeche,
    rp_stamm.nutzer_nr,
    rp_stamm.flaeche AS fla_ist
   FROM (mbs.rp_stamm
     LEFT JOIN mbs.rp_umleg ON (((rp_stamm.nutzer_nr)::text = (rp_umleg.ab_nutzer)::text)))
  WHERE (rp_umleg.ab_nutzer IS NULL);


--
-- Name: rp_bewgeb; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.rp_bewgeb AS
 SELECT stamm.geb_nr,
    stamm.nutzer_nr,
    nutzer.fgr_nr,
    geb.baujahr,
    geb.art,
        CASE
            WHEN (((nutzer.fgr_nr)::text = '300'::text) OR (((nutzer.fgr_nr)::text > '301'::text) AND ((nutzer.fgr_nr)::text < '700'::text))) THEN 1
            ELSE 0
        END AS gexp,
        CASE
            WHEN ((((nutzer.fgr_nr)::text = '300'::text) OR (((nutzer.fgr_nr)::text > '301'::text) AND ((nutzer.fgr_nr)::text < '700'::text))) AND ((bewgrund.artexp)::text = (geb.art)::text)) THEN bewgrund.abmindexp
            WHEN ((((nutzer.fgr_nr)::text < '300'::text) OR ((nutzer.fgr_nr)::text = '301'::text) OR ((nutzer.fgr_nr)::text >= '700'::text)) AND ((bewgrund.artnexp)::text = (geb.art)::text)) THEN bewgrund.abmindnexp
            ELSE 0
        END AS abmind
   FROM (((mbs.stamm
     JOIN mbs.geb ON (((stamm.geb_nr)::text = (geb.geb_nr)::text)))
     JOIN mbs.nutzer ON (((stamm.nutzer_nr)::text = (nutzer.nutzer_nr)::text)))
     JOIN mbs.bewgrund ON ((((geb.baujahr)::text >= (bewgrund.abbaujahr)::text) AND ((geb.baujahr)::text <= (bewgrund.bisbaujahr)::text) AND (((geb.art)::text = (bewgrund.artexp)::text) OR ((geb.art)::text = (bewgrund.artnexp)::text)))))
  GROUP BY stamm.geb_nr, stamm.nutzer_nr, nutzer.fgr_nr, geb.baujahr, geb.art, bewgrund.abmind, bewgrund.artexp, bewgrund.artnexp, bewgrund.abmindexp, bewgrund.abmindnexp
  ORDER BY stamm.geb_nr, stamm.nutzer_nr, nutzer.fgr_nr, geb.baujahr;


--
-- Name: rp_bewnut; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.rp_bewnut AS
 SELECT nutzer_nr,
    sum(abmind) AS abmind
   FROM mbs.bewnut
  GROUP BY nutzer_nr
  ORDER BY nutzer_nr;


--
-- Name: rp_bwert1; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.rp_bwert1 AS
 SELECT DISTINCT rp_bestand.geb_nr,
    rp_bestand.ges_nr,
    rp_bestand.raumid,
    rp_bestand.rna_nr,
    rp_bestand.flaeche,
    rp_bestand.nutzer_nr,
    rp_bestand.fla_ist,
        CASE
            WHEN (rp_bewnut.abmind IS NULL) THEN (0)::double precision
            ELSE ((rp_bestand.fla_ist * rp_bewnut.abmind) / (100)::double precision)
        END AS abzug_1
   FROM (mbs.rp_bestand
     LEFT JOIN mbs.rp_bewnut ON (((rp_bestand.nutzer_nr)::text = (rp_bewnut.nutzer_nr)::text)))
  ORDER BY rp_bestand.geb_nr, rp_bestand.ges_nr, rp_bestand.raumid, rp_bestand.rna_nr, rp_bestand.flaeche, rp_bestand.nutzer_nr, rp_bestand.fla_ist,
        CASE
            WHEN (rp_bewnut.abmind IS NULL) THEN (0)::double precision
            ELSE ((rp_bestand.fla_ist * rp_bewnut.abmind) / (100)::double precision)
        END;


--
-- Name: rp_bwert2; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.rp_bwert2 AS
 SELECT DISTINCT rp_bwert1.geb_nr,
    rp_bwert1.ges_nr,
    rp_bwert1.raumid,
    rp_bwert1.rna_nr,
    rp_bwert1.flaeche,
    rp_bwert1.nutzer_nr,
    rp_bwert1.fla_ist,
    rp_bwert1.abzug_1,
        CASE
            WHEN (bewrna.abmind IS NULL) THEN (0)::double precision
            ELSE (((rp_bwert1.fla_ist - rp_bwert1.abzug_1) * bewrna.abmind) / (100)::double precision)
        END AS abzug_2
   FROM (mbs.rp_bwert1
     LEFT JOIN mbs.bewrna ON (((rp_bwert1.rna_nr)::text = (bewrna.rna_nr)::text)))
  ORDER BY rp_bwert1.geb_nr, rp_bwert1.ges_nr, rp_bwert1.raumid, rp_bwert1.rna_nr, rp_bwert1.flaeche, rp_bwert1.nutzer_nr, rp_bwert1.fla_ist, rp_bwert1.abzug_1,
        CASE
            WHEN (bewrna.abmind IS NULL) THEN (0)::double precision
            ELSE (((rp_bwert1.fla_ist - rp_bwert1.abzug_1) * bewrna.abmind) / (100)::double precision)
        END;


--
-- Name: rp_bwert3; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.rp_bwert3 AS
 SELECT DISTINCT rp_bwert2.geb_nr,
    rp_bwert2.ges_nr,
    rp_bwert2.raumid,
    rp_bwert2.rna_nr,
    rp_bwert2.flaeche,
    rp_bwert2.nutzer_nr,
    rp_bwert2.fla_ist,
    rp_bwert2.abzug_1,
    rp_bwert2.abzug_2,
        CASE
            WHEN (bewrau.abmind IS NULL) THEN (0)::double precision
            ELSE ((((rp_bwert2.fla_ist - rp_bwert2.abzug_1) - rp_bwert2.abzug_2) * bewrau.abmind) / (100)::double precision)
        END AS abzug_3
   FROM (mbs.rp_bwert2
     LEFT JOIN mbs.bewrau ON ((((rp_bwert2.geb_nr)::text = (bewrau.geb_nr)::text) AND ((rp_bwert2.ges_nr)::text = (bewrau.ges_nr)::text) AND ((rp_bwert2.raumid)::text = (bewrau.raumid)::text) AND ((rp_bwert2.rna_nr)::text = (bewrau.rna_nr)::text) AND ((rp_bwert2.nutzer_nr)::text = (bewrau.nutzer_nr)::text))))
  ORDER BY rp_bwert2.geb_nr, rp_bwert2.ges_nr, rp_bwert2.raumid, rp_bwert2.rna_nr, rp_bwert2.nutzer_nr,
        CASE
            WHEN (bewrau.abmind IS NULL) THEN (0)::double precision
            ELSE ((((rp_bwert2.fla_ist - rp_bwert2.abzug_1) - rp_bwert2.abzug_2) * bewrau.abmind) / (100)::double precision)
        END, rp_bwert2.flaeche, rp_bwert2.fla_ist, rp_bwert2.abzug_1, rp_bwert2.abzug_2;


--
-- Name: rp_bwert4; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.rp_bwert4 AS
 SELECT DISTINCT rp_bwert3.geb_nr,
    rp_bwert3.ges_nr,
    rp_bwert3.raumid,
    rp_bwert3.rna_nr,
    rp_bwert3.flaeche,
    rp_bwert3.nutzer_nr,
    rp_bwert3.fla_ist,
    rp_bwert3.abzug_1,
    rp_bwert3.abzug_2,
    rp_bwert3.abzug_3,
        CASE
            WHEN (rp_bewgeb.abmind IS NULL) THEN (0)::double precision
            ELSE (((((rp_bwert3.fla_ist - rp_bwert3.abzug_1) - rp_bwert3.abzug_2) - rp_bwert3.abzug_3) * (rp_bewgeb.abmind)::double precision) / (100)::double precision)
        END AS abzug_4
   FROM (mbs.rp_bwert3
     LEFT JOIN mbs.rp_bewgeb ON ((((rp_bwert3.geb_nr)::text = (rp_bewgeb.geb_nr)::text) AND ((rp_bwert3.nutzer_nr)::text = (rp_bewgeb.nutzer_nr)::text))))
  ORDER BY rp_bwert3.geb_nr, rp_bwert3.ges_nr, rp_bwert3.raumid, rp_bwert3.rna_nr, rp_bwert3.nutzer_nr,
        CASE
            WHEN (rp_bewgeb.abmind IS NULL) THEN (0)::double precision
            ELSE (((((rp_bwert3.fla_ist - rp_bwert3.abzug_1) - rp_bwert3.abzug_2) - rp_bwert3.abzug_3) * (rp_bewgeb.abmind)::double precision) / (100)::double precision)
        END, rp_bwert3.flaeche, rp_bwert3.fla_ist, rp_bwert3.abzug_1, rp_bwert3.abzug_2, rp_bwert3.abzug_3;


--
-- Name: rp_peranz; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.rp_peranz AS
 SELECT DISTINCT rp_bwert4.nutzer_nr,
    sum(((((rp_bwert4.fla_ist - rp_bwert4.abzug_1) - rp_bwert4.abzug_2) - rp_bwert4.abzug_3) - rp_bwert4.abzug_4)) AS fla_p,
    bewper.persanz,
    bewper.persabzug
   FROM (mbs.rp_bwert4
     JOIN mbs.bewper ON (((rp_bwert4.nutzer_nr)::text = (bewper.nutzer_nr)::text)))
  GROUP BY rp_bwert4.nutzer_nr, bewper.persanz, bewper.persabzug
  ORDER BY rp_bwert4.nutzer_nr, (sum(((((rp_bwert4.fla_ist - rp_bwert4.abzug_1) - rp_bwert4.abzug_2) - rp_bwert4.abzug_3) - rp_bwert4.abzug_4))), bewper.persanz, bewper.persabzug;


--
-- Name: rp_bwert5; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.rp_bwert5 AS
 SELECT DISTINCT rp_bwert4.geb_nr,
    rp_bwert4.ges_nr,
    rp_bwert4.raumid,
    rp_bwert4.rna_nr,
    rp_bwert4.flaeche,
    rp_bwert4.nutzer_nr,
    rp_bwert4.fla_ist,
    rp_bwert4.abzug_1,
    rp_bwert4.abzug_2,
    rp_bwert4.abzug_3,
    rp_bwert4.abzug_4,
        CASE
            WHEN (rp_peranz.persanz IS NULL) THEN (0)::double precision
            ELSE (((((((rp_bwert4.fla_ist - rp_bwert4.abzug_1) - rp_bwert4.abzug_2) - rp_bwert4.abzug_3) - rp_bwert4.abzug_4) * rp_peranz.persanz) * rp_peranz.persabzug) / rp_peranz.fla_p)
        END AS abzug_5
   FROM (mbs.rp_bwert4
     LEFT JOIN mbs.rp_peranz ON (((rp_bwert4.nutzer_nr)::text = (rp_peranz.nutzer_nr)::text)))
  ORDER BY rp_bwert4.geb_nr, rp_bwert4.ges_nr, rp_bwert4.raumid, rp_bwert4.rna_nr, rp_bwert4.nutzer_nr,
        CASE
            WHEN (rp_peranz.persanz IS NULL) THEN (0)::double precision
            ELSE (((((((rp_bwert4.fla_ist - rp_bwert4.abzug_1) - rp_bwert4.abzug_2) - rp_bwert4.abzug_3) - rp_bwert4.abzug_4) * rp_peranz.persanz) * rp_peranz.persabzug) / rp_peranz.fla_p)
        END, rp_bwert4.flaeche, rp_bwert4.fla_ist, rp_bwert4.abzug_1, rp_bwert4.abzug_2, rp_bwert4.abzug_3, rp_bwert4.abzug_4;


--
-- Name: rp_bwert; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.rp_bwert AS
 SELECT DISTINCT rp_bestand.bezug,
    rp_bwert5.geb_nr,
    rp_bwert5.ges_nr,
    rp_bwert5.raumid,
    rp_bwert5.rna_nr,
    rp_bwert5.flaeche,
    rp_bwert5.nutzer_nr,
    rp_bwert5.fla_ist,
    rp_bwert5.abzug_1,
    rp_bwert5.abzug_2,
    rp_bwert5.abzug_3,
    rp_bwert5.abzug_4,
    rp_bwert5.abzug_5,
    ((((rp_bwert5.abzug_1 + rp_bwert5.abzug_2) + rp_bwert5.abzug_3) + rp_bwert5.abzug_4) + rp_bwert5.abzug_5) AS abzug,
    (((((rp_bwert5.fla_ist - rp_bwert5.abzug_1) - rp_bwert5.abzug_2) - rp_bwert5.abzug_3) - rp_bwert5.abzug_4) - rp_bwert5.abzug_5) AS bwfla,
    stb.frw,
    stb.bfrw,
        CASE
            WHEN (stb.frw > (0)::double precision) THEN ((((((rp_bwert5.fla_ist - rp_bwert5.abzug_1) - rp_bwert5.abzug_2) - rp_bwert5.abzug_3) - rp_bwert5.abzug_4) - rp_bwert5.abzug_5) / stb.frw)
            ELSE (0)::double precision
        END AS studpl,
        CASE
            WHEN (stb.bfrw > (0)::double precision) THEN ((((((rp_bwert5.fla_ist - rp_bwert5.abzug_1) - rp_bwert5.abzug_2) - rp_bwert5.abzug_3) - rp_bwert5.abzug_4) - rp_bwert5.abzug_5) / stb.bfrw)
            ELSE (0)::double precision
        END AS bstudpl
   FROM ((((mbs.rp_bwert5
     JOIN mbs.nutzer ON (((rp_bwert5.nutzer_nr)::text = (nutzer.nutzer_nr)::text)))
     JOIN mbs.fgr ON (((nutzer.fgr_nr)::text = (fgr.fgr_nr)::text)))
     JOIN mbs.stb ON (((fgr.stb_nr)::text = (stb.stb_nr)::text)))
     JOIN mbs.rp_bestand ON ((((rp_bwert5.geb_nr)::text = (rp_bestand.geb_nr)::text) AND ((rp_bwert5.ges_nr)::text = (rp_bestand.ges_nr)::text) AND ((rp_bwert5.raumid)::text = (rp_bestand.raumid)::text) AND ((rp_bwert5.nutzer_nr)::text = (rp_bestand.nutzer_nr)::text))))
  ORDER BY rp_bwert5.geb_nr, rp_bwert5.ges_nr, rp_bwert5.raumid, rp_bwert5.rna_nr, rp_bwert5.flaeche, rp_bwert5.nutzer_nr, rp_bwert5.fla_ist, rp_bwert5.abzug_1, rp_bwert5.abzug_2, rp_bwert5.abzug_3, rp_bwert5.abzug_4, rp_bwert5.abzug_5, (((((rp_bwert5.fla_ist - rp_bwert5.abzug_1) - rp_bwert5.abzug_2) - rp_bwert5.abzug_3) - rp_bwert5.abzug_4) - rp_bwert5.abzug_5), stb.frw, stb.bfrw,
        CASE
            WHEN (stb.frw > (0)::double precision) THEN ((((((rp_bwert5.fla_ist - rp_bwert5.abzug_1) - rp_bwert5.abzug_2) - rp_bwert5.abzug_3) - rp_bwert5.abzug_4) - rp_bwert5.abzug_5) / stb.frw)
            ELSE (0)::double precision
        END,
        CASE
            WHEN (stb.bfrw > (0)::double precision) THEN ((((((rp_bwert5.fla_ist - rp_bwert5.abzug_1) - rp_bwert5.abzug_2) - rp_bwert5.abzug_3) - rp_bwert5.abzug_4) - rp_bwert5.abzug_5) / stb.bfrw)
            ELSE (0)::double precision
        END, ((((rp_bwert5.abzug_1 + rp_bwert5.abzug_2) + rp_bwert5.abzug_3) + rp_bwert5.abzug_4) + rp_bwert5.abzug_5);


