CREATE VIEW mbs.stamm_cob AS
 SELECT stamm.geb_nr,
    stamm.ges_nr,
    stamm.raumid,
    stamm.raumnr,
    stamm.flaeche,
    stamm.rna_nr,
    stamm.bez,
    stamm.nutzer_nr,
    stamm.kost_nr,
    stamm.traeger_nr,
    stamm.fkt_nr,
    stamm.kfa_nr,
    geb.hs_nr,
    geb.qkz,
    '0'::character varying(1) AS f1,
    '0'::character varying(1) AS f2,
    (to_char((CURRENT_DATE)::timestamp with time zone, 'DD.MM.YYYY'::text))::character varying(19) AS mdat,
        CASE
            WHEN ((stamm.kost_nr)::text = '-'::text) THEN ''::character varying
            ELSE stamm.kost_nr
        END AS cob_kost,
        CASE
            WHEN ((stamm.traeger_nr)::text = '-'::text) THEN ''::character varying
            ELSE stamm.traeger_nr
        END AS cob_traeger
   FROM (mbs.stamm
     JOIN mbs.geb ON (((stamm.geb_nr)::text = (geb.geb_nr)::text)));


--
-- Name: stamm_view; Type: VIEW; Schema: mbs; Owner: -
--

CREATE VIEW mbs.stamm_view AS
 SELECT
        CASE
            WHEN ((anteil_sum.ab_sum IS NULL) AND (beleg_anz_dat.anz IS NULL)) THEN 'Raum Ist'::character varying(15)
            WHEN ((anteil_sum.ab_sum IS NOT NULL) AND (beleg_anz_dat.anz IS NULL)) THEN 'Raum Rest'::character varying(15)
            ELSE 'Raum Satz'::character varying(15)
        END AS ur,
    stamm.geb_nr,
    stamm.ges_nr,
    stamm.raumid,
    stamm.raumnr,
    '-'::character varying(4) AS belegid,
        CASE
            WHEN ((anteil_sum.ab_sum IS NULL) AND (beleg_anz_dat.anz IS NULL)) THEN (stamm.flaeche)::double precision
            WHEN ((anteil_sum.ab_sum IS NOT NULL) AND (beleg_anz_dat.anz IS NULL)) THEN ((stamm.flaeche)::double precision - (((stamm.flaeche)::double precision * anteil_sum.ab_sum) / ((100)::numeric)::double precision))
            ELSE ((0)::numeric)::double precision
        END AS flaeche,
    stamm.rna_nr,
    stamm.bez,
    stamm.nutzer_nr,
    stamm.kost_nr,
    stamm.traeger_nr,
    stamm.fkt_nr,
    stamm.kfa_nr,
    geb.hs_nr,
    geb.qkz,
    '0'::character varying(1) AS f1,
    '0'::character varying(1) AS f2,
    (( SELECT to_char((CURRENT_DATE)::timestamp with time zone, 'DD.MM.YYYY'::text) AS to_char))::character varying(19) AS mdat,
        CASE
            WHEN ((stamm.kost_nr)::text = '-'::text) THEN ''::character varying
            ELSE stamm.kost_nr
        END AS cob_kost,
        CASE
            WHEN ((stamm.traeger_nr)::text = '-'::text) THEN ''::character varying
            ELSE stamm.traeger_nr
        END AS cob_traeger
   FROM ((mbs.anteil_sum anteil_sum
     RIGHT JOIN (mbs.stamm
     LEFT JOIN mbs.beleg_anz_dat ON ((((stamm.geb_nr)::text = (beleg_anz_dat.geb_nr)::text) AND ((stamm.ges_nr)::text = (beleg_anz_dat.ges_nr)::text) AND ((stamm.raumid)::text = (beleg_anz_dat.raumid)::text)))) ON (((anteil_sum.ab_kost)::text = (stamm.kost_nr)::text)))
     JOIN mbs.geb ON (((stamm.geb_nr)::text = (geb.geb_nr)::text)))
  WHERE (((beleg_anz_dat.anz IS NULL) AND (anteil_sum.ab_sum IS NULL)) OR ((anteil_sum.ab_sum > ((0)::numeric)::double precision) AND (anteil_sum.ab_sum < ((100)::numeric)::double precision)))
UNION
 SELECT
        CASE
            WHEN (anteil_sum.ab_sum IS NULL) THEN 'Beleg'::character varying(15)
            WHEN ((((stamm.flaeche / (beleg_anz_dat.anz)::numeric))::double precision - ((((stamm.flaeche / (beleg_anz_dat.anz)::numeric))::double precision * anteil_sum.ab_sum) / ((100)::numeric)::double precision)) = ((0)::numeric)::double precision) THEN 'Beleg Ist'::character varying(15)
            ELSE 'Beleg Anteil'::character varying(15)
        END AS ur,
    stamm.geb_nr,
    stamm.ges_nr,
    stamm.raumid,
    stamm.raumnr,
    beleg.belegid,
        CASE
            WHEN (anteil_sum.ab_sum IS NULL) THEN ((stamm.flaeche / (beleg_anz_dat.anz)::numeric))::double precision
            ELSE (((stamm.flaeche / (beleg_anz_dat.anz)::numeric))::double precision - ((((stamm.flaeche / (beleg_anz_dat.anz)::numeric))::double precision * anteil_sum.ab_sum) / ((100)::numeric)::double precision))
        END AS flaeche,
    stamm.rna_nr,
    stamm.bez,
    stamm.nutzer_nr,
    beleg.kost_nr,
    beleg.traeger_nr,
    stamm.fkt_nr,
    stamm.kfa_nr,
    geb.hs_nr,
    geb.qkz,
    '0'::character varying(1) AS f1,
    '0'::character varying(1) AS f2,
    (( SELECT to_char((CURRENT_DATE)::timestamp with time zone, 'DD.MM.YYYY'::text) AS to_char))::character varying(19) AS mdat,
        CASE
            WHEN ((beleg.kost_nr)::text = '-'::text) THEN ''::character varying
            ELSE beleg.kost_nr
        END AS cob_kost,
        CASE
            WHEN ((beleg.traeger_nr)::text = '-'::text) THEN ''::character varying
            ELSE beleg.traeger_nr
        END AS cob_traeger
   FROM ((mbs.beleg_anz_dat
     JOIN ((mbs.stamm
     JOIN mbs.beleg ON ((((stamm.raumid)::text = (beleg.raumid)::text) AND ((stamm.ges_nr)::text = (beleg.ges_nr)::text) AND ((stamm.geb_nr)::text = (beleg.geb_nr)::text))))
     LEFT JOIN mbs.anteil_sum anteil_sum ON (((beleg.kost_nr)::text = (anteil_sum.ab_kost)::text))) ON ((((beleg_anz_dat.geb_nr)::text = (stamm.geb_nr)::text) AND ((beleg_anz_dat.ges_nr)::text = (stamm.ges_nr)::text) AND ((beleg_anz_dat.raumid)::text = (stamm.raumid)::text))))
     JOIN mbs.geb ON (((stamm.geb_nr)::text = (geb.geb_nr)::text)))
  WHERE ((beleg.bel_bis > CURRENT_DATE) OR ((beleg.bel_bis IS NULL) AND (beleg.bel_von < CURRENT_DATE)) OR (beleg.bel_von IS NULL))
UNION
 SELECT 'Anteil'::character varying(15) AS ur,
    stamm.geb_nr,
    stamm.ges_nr,
    stamm.raumid,
    stamm.raumnr,
    '-'::character varying(4) AS belegid,
    (((stamm.flaeche)::double precision * anteil.anteil) / (100)::double precision) AS flaeche,
    stamm.rna_nr,
    stamm.bez,
    stamm.nutzer_nr,
    anteil.auf_kost AS kost_nr,
    stamm.traeger_nr,
    stamm.fkt_nr,
    stamm.kfa_nr,
    geb.hs_nr,
    geb.qkz,
    '0'::character varying(1) AS f1,
    '0'::character varying(1) AS f2,
    (( SELECT to_char((CURRENT_DATE)::timestamp with time zone, 'DD.MM.YYYY'::text) AS to_char))::character varying(19) AS mdat,
        CASE
            WHEN ((anteil.auf_kost)::text = '-'::text) THEN ''::character varying
            ELSE anteil.auf_kost
        END AS cob_kost,
        CASE
            WHEN ((stamm.traeger_nr)::text = '-'::text) THEN ''::character varying
            ELSE stamm.traeger_nr
        END AS cob_traeger
   FROM ((mbs.anteil
     JOIN (mbs.stamm
     LEFT JOIN mbs.beleg ON ((((stamm.raumid)::text = (beleg.raumid)::text) AND ((stamm.ges_nr)::text = (beleg.ges_nr)::text) AND ((stamm.geb_nr)::text = (beleg.geb_nr)::text)))) ON (((anteil.ab_kost)::text = (stamm.kost_nr)::text)))
     JOIN mbs.geb ON (((stamm.geb_nr)::text = (geb.geb_nr)::text)))
  WHERE (beleg.belegid IS NULL)
UNION
 SELECT 'Anteil Beleg'::character varying(15) AS ur,
    beleg.geb_nr,
    beleg.ges_nr,
    beleg.raumid,
    stamm.raumnr,
    '-'::character varying(4) AS belegid,
    ((((stamm.flaeche / (beleg_anz_dat.anz)::numeric))::double precision * anteil.anteil) / ((100)::numeric)::double precision) AS flaeche,
    stamm.rna_nr,
    stamm.bez,
    stamm.nutzer_nr,
    anteil.auf_kost AS kost_nr,
    stamm.traeger_nr,
    stamm.fkt_nr,
    stamm.kfa_nr,
    geb.hs_nr,
    geb.qkz,
    '0'::character varying(1) AS f1,
    '0'::character varying(1) AS f2,
    (( SELECT to_char((CURRENT_DATE)::timestamp with time zone, 'DD.MM.YYYY'::text) AS to_char))::character varying(19) AS mdat,
        CASE
            WHEN ((anteil.auf_kost)::text = '-'::text) THEN ''::character varying
            ELSE anteil.auf_kost
        END AS cob_kost,
        CASE
            WHEN ((stamm.traeger_nr)::text = '-'::text) THEN ''::character varying
            ELSE stamm.traeger_nr
        END AS cob_traeger
   FROM (((mbs.anteil
     JOIN (mbs.stamm
     JOIN mbs.beleg ON ((((stamm.raumid)::text = (beleg.raumid)::text) AND ((stamm.ges_nr)::text = (beleg.ges_nr)::text) AND ((stamm.geb_nr)::text = (beleg.geb_nr)::text)))) ON (((anteil.ab_kost)::text = (beleg.kost_nr)::text)))
     JOIN mbs.beleg_anz_dat ON ((((stamm.raumid)::text = (beleg_anz_dat.raumid)::text) AND ((stamm.ges_nr)::text = (beleg_anz_dat.ges_nr)::text) AND ((stamm.geb_nr)::text = (beleg_anz_dat.geb_nr)::text))))
     JOIN mbs.geb ON (((stamm.geb_nr)::text = (geb.geb_nr)::text)));


