-- Name: bgr_to_sas_view; Type: VIEW; Schema: sva4; Owner: -
--

CREATE VIEW sva4.bgr_to_sas_view AS
 SELECT bgr_to_sas.bgr_to_sas_serial,
    ((((((bgr.bgr_name)::text || ' : '::text) || (sas.sas_kurzbeschreibung)::text) || '('::text) || (sas.sas_kennziffer)::text) || ')'::text) AS gremien_ausschreibung
   FROM ((sva4.bgr_to_sas
     LEFT JOIN sva4.sas ON ((bgr_to_sas.sas_join_id = sas.sas_serial)))
     LEFT JOIN sva4.bgr ON ((bgr_to_sas.bgr_join_id = bgr.bgr_serial)));


