--
-- Name: bw_lbv_uebersicht_view; Type: VIEW; Schema: sva4; Owner: -
--

CREATE VIEW sva4.bw_lbv_uebersicht_view AS
 SELECT bw_lbv.bw_lbv_pgd_join_id,
    bw_lbv.bw_lbv_serial,
    bw_lbv.bw_lbv_besold_nr,
    bw_lbv.bw_lbv_pbv_nr,
    bw_lbv.user_email,
    bw_lbv.bw_lbv_status,
    bw_lbv.dienststelle,
    bw_lbv.user_kennung,
    bw_lbv.user_name,
    bw_lbv.user_tel,
    bw_lbv.absend_zeit,
    bw_lbv.lbv_version,
    bw_lbv.rc,
    bw_lbv.rc_text,
    bw_lbv.service_nr,
    bw_lbv.bw_lbv_sva_status,
    bw_lbv.bw_anwendung_kommentar
   FROM sva4.bw_lbv
  WHERE ((bw_lbv.service_nr)::text <> ALL (ARRAY[('HIS0016'::character varying)::text, ('HISAUAN'::character varying)::text, ('HISEAUM'::character varying)::text]))
UNION
 SELECT bw_lbv_base.lbv_pgd_join_id AS bw_lbv_pgd_join_id,
    bw_lbv_base.id AS bw_lbv_serial,
    bw_lbv_base.besold_nr AS bw_lbv_besold_nr,
    bw_lbv_base.lbv_pbv_nr AS bw_lbv_pbv_nr,
    bw_lbv_base.user_email,
    bw_lbv_base.lbv_status AS bw_lbv_status,
    bw_lbv_base.dienststelle,
    bw_lbv_base.user_kennung,
    bw_lbv_base.user_name,
    bw_lbv_base.user_tel,
    bw_lbv_base.absend_zeit,
    bw_lbv_base.lbv_version,
    bw_lbv_base.rc,
    bw_lbv_base.rc_text,
    bw_lbv_base.service_nr,
    bw_lbv_base.lbv_sva_status AS bw_lbv_sva_status,
    bw_lbv_base.anwendung_kommentar AS bw_anwendung_kommentar
   FROM sva4.bw_lbv_base
  WHERE ((bw_lbv_base.service_nr)::text = ANY (ARRAY[('HIS0016'::character varying)::text, ('HISAUAN'::character varying)::text, ('HISEAUM'::character varying)::text]));


