--
-- Name: pbz_sum; Type: VIEW; Schema: sva4; Owner: -
--

CREATE VIEW sva4.pbz_sum AS
 SELECT pbz_pgd_join_id,
    pbz_pbv_nr,
    sum(pbz_gesamtbetrag) AS pbz_sumbetrag,
    pbz_von,
    pbz_bis
   FROM sva4.pbz
  WHERE ((pbz_pgd_join_id = pbz_pgd_join_id) AND (pbz_pbv_nr = pbz_pbv_nr) AND (pbz_status = 0) AND (date_part('year'::text, pbz_von) = date_part('year'::text, pbz_von)) AND (date_part('month'::text, pbz_von) = date_part('month'::text, pbz_von)))
  GROUP BY pbz_pgd_join_id, pbz_pbv_nr, pbz_von, pbz_bis;


--
-- Name: pko_pbz; Type: VIEW; Schema: sva4; Owner: -
--

CREATE VIEW sva4.pko_pbz AS
 SELECT pko.pko_pgd_join_id,
    pko.pko_pbv_nr,
    pko.pko_jahr,
    pko.pko_monat,
    pbz_sum.pbz_sumbetrag AS pbz_gesamtbetrag,
    pko.pko_gesamtbetrag,
    pbz_sum.pbz_von,
    pbz_sum.pbz_bis,
    ((pko.pko_jahr * 12) + pko.pko_monat) AS pko_datum,
    pko.pko_festleg_art,
    pbz_sum.pbz_pgd_join_id,
    pbz_sum.pbz_pbv_nr,
    date_part('year'::text, pbz_sum.pbz_von) AS pbz_jahr,
    date_part('month'::text, pbz_sum.pbz_von) AS pbz_monat,
    ((date_part('year'::text, pbz_sum.pbz_von) * (12)::double precision) + date_part('month'::text, pbz_sum.pbz_von)) AS pbz_datum,
    pko.pko_simul_modus,
    pko.pko_kalk_modus
   FROM (sva4.pbz_sum
     LEFT JOIN sva4.pko ON (((pbz_sum.pbz_pgd_join_id = pko.pko_pgd_join_id) AND (pbz_sum.pbz_pbv_nr = pko.pko_pbv_nr) AND (date_part('year'::text, pbz_sum.pbz_von) = (pko.pko_jahr)::double precision) AND (date_part('month'::text, pbz_sum.pbz_von) = (pko.pko_monat)::double precision))));


--
-- Name: fachbereich_proj; Type: VIEW; Schema: sva4; Owner: -
--

CREATE VIEW sva4.fachbereich_proj AS
 SELECT pfi.pfi_pgd_join_id,
    pfi.pfi_pbv_nr,
    pfi.pfi_fb_projekt,
    pfi.pfi_prozent,
    pko_pbz.pko_jahr,
    pko_pbz.pko_monat,
    ((pko_pbz.pbz_gesamtbetrag * pfi.pfi_prozent) / (100)::double precision) AS ist_kosten,
    ((pko_pbz.pko_gesamtbetrag * pfi.pfi_prozent) / (100)::double precision) AS kalk_kosten,
    pfi.pfi_serial,
    pko_pbz.pko_simul_modus
   FROM (sva4.pfi
     LEFT JOIN sva4.pko_pbz ON (((pfi.pfi_pgd_join_id = pko_pbz.pko_pgd_join_id) AND (pfi.pfi_pbv_nr = pko_pbz.pko_pbv_nr) AND (pfi.pfi_status = 0) AND ((((pfi.pfi_von IS NULL) OR (pfi.pfi_von < pko_pbz.pbz_von)) AND ((pfi.pfi_bis IS NULL) OR (pfi.pfi_bis > pko_pbz.pbz_von))) OR (pko_pbz.pbz_von IS NULL)) AND ((((pfi.pfi_von IS NULL) OR (((date_part('year'::text, pfi.pfi_von) * (12)::double precision) + date_part('month'::text, pfi.pfi_von)) < (pko_pbz.pko_datum)::double precision)) AND ((pfi.pfi_bis IS NULL) OR (((date_part('year'::text, pfi.pfi_bis) * (12)::double precision) + date_part('month'::text, pfi.pfi_bis)) > (pko_pbz.pko_datum)::double precision))) OR (pko_pbz.pko_datum IS NULL)))));


