--
-- Name: k_aufgabengebiet; Type: VIEW; Schema: sva4; Owner: -
--

CREATE VIEW sva4.k_aufgabengebiet AS
 SELECT pbv_aufgabengebiet,
    db_einfuegemarke
   FROM ( SELECT DISTINCT pbv.pbv_aufgabengebiet,
            pbv.db_einfuegemarke
           FROM sva4.pbv
          WHERE (pbv.pbv_aufgabengebiet IS NOT NULL)) ag
  ORDER BY ((pbv_aufgabengebiet)::text = 'Wissenschaftliche Dienstleistungen'::text) DESC, ((pbv_aufgabengebiet)::text = 'Dienstaufgabenbeschreibung'::text) DESC, ((pbv_aufgabengebiet)::text = 'Weiterqualifikation'::text) DESC, pbv_aufgabengebiet;


