--
-- Name: k_institut; Type: VIEW; Schema: sva4; Owner: -
--

CREATE VIEW sva4.k_institut AS
 SELECT inst.db_einfuegemarke,
    inst.inst_nr AS key_institut,
    inst.kname AS kurz_institut,
    inst.dname AS druck_institut,
    inst.lname1 AS text_institut,
    ansc.ansc_strasse AS text_inst_adresse,
    inst.gebname AS text_inst_adresse2,
    ansc.ansc_plz,
    ansc.ansc_ort AS text_inst_adresse3,
    inst.key_von,
    inst.key_bis,
    inst.bund_kategorie,
    inst.bund_lehr_forsch,
    inst.bund_fachgebiet,
    inst.land_fachgebiet,
    inst.land_institut,
    inst.art,
    inst.sis_lehr
   FROM (sva4.inst
     LEFT JOIN sva4.ansc ON ((inst.anscid = ansc.ansc_id)))
  WHERE ((inst.svarel)::text = '1'::text);


