--
-- Name: kosten_stelle; Type: VIEW; Schema: sva4; Owner: -
--

CREATE VIEW sva4.kosten_stelle AS
 SELECT pfi.pfi_pgd_join_id,
    pfi.pfi_pbv_nr,
    pfi.pfi_kostenstelle,
    pfi.pfi_prozent,
    pko_pbz.pko_jahr,
    pko_pbz.pko_monat,
    ((pko_pbz.pbz_gesamtbetrag * pfi.pfi_prozent) / (100)::double precision) AS ist_kosten,
    ((pko_pbz.pko_gesamtbetrag * pfi.pfi_prozent) / (100)::double precision) AS kalk_kosten,
    pfi.pfi_serial,
    pko_pbz.pbz_monat,
    pko_pbz.pbz_jahr,
    pko_pbz.pbz_datum,
    pko_pbz.pko_datum,
    pko_pbz.pko_simul_modus
   FROM (sva4.pfi
     LEFT JOIN sva4.pko_pbz ON (((pfi.pfi_pgd_join_id = pko_pbz.pbz_pgd_join_id) AND (pfi.pfi_pbv_nr = pko_pbz.pbz_pbv_nr) AND (pfi.pfi_status = 0) AND ((((pfi.pfi_von IS NULL) OR (date_part('year'::text, pfi.pfi_von) < date_part('year'::text, pko_pbz.pbz_von))) AND ((pfi.pfi_bis IS NULL) OR (date_part('year'::text, pfi.pfi_bis) > date_part('year'::text, pko_pbz.pbz_von)))) OR (pko_pbz.pbz_von IS NULL)))));


