--
-- Name: pak_paw; Type: VIEW; Schema: sva4; Owner: -
--

CREATE VIEW sva4.pak_paw AS
 SELECT paw.paw_pgd_join_id,
    paw.paw_pas_jahr,
    pak.pak_ab_paw_serial,
    pak.pak_zu_paw_serial,
    pak.pak_tage_abbuchung
   FROM (sva4.paw paw
     LEFT JOIN sva4.pak pak ON ((paw.paw_serial = pak.pak_ab_paw_serial)))
  WHERE ((pak.pak_tage_abbuchung IS NOT NULL) AND (pak.pak_tage_abbuchung > (0)::double precision) AND (pak.pak_status = 0) AND (paw.paw_status = 0));


--
-- Name: pak_urlaub; Type: VIEW; Schema: sva4; Owner: -
--

CREATE VIEW sva4.pak_urlaub AS
 SELECT paw.paw_pgd_join_id,
    paw.paw_pas_jahr,
    paw.paw_serial,
    paw.paw_tage,
    k_abwesenheitsart.his_system_key,
    k_abwesenheitsart.druck_abwesenheit,
    paw.paw_von,
    paw.paw_bis,
    paw.paw_verfallsdatum,
        CASE
            WHEN (sum(pak.pak_tage_abbuchung) IS NOT NULL) THEN sum(pak.pak_tage_abbuchung)
            ELSE (0)::double precision
        END AS abgebuchte_tage,
        CASE
            WHEN ((paw.paw_tage - sum(pak.pak_tage_abbuchung)) IS NULL) THEN
            CASE
                WHEN ((k_abwesenheitsart.his_system_key)::text <> 'AE'::text) THEN paw.paw_tage
                ELSE (0)::double precision
            END
            ELSE (paw.paw_tage - sum(pak.pak_tage_abbuchung))
        END AS verbleibende_tage,
        CASE
            WHEN (EXTRACT(year FROM paw.paw_verfallsdatum) < (paw.paw_pas_jahr)::numeric) THEN (paw.paw_tage - sum(pak.pak_tage_abbuchung))
            ELSE (0)::double precision
        END AS gekappt_akt,
        CASE
            WHEN (paw.paw_verfallsdatum < (((paw.paw_pas_jahr)::text || '-12-31'::text))::date) THEN
            CASE
                WHEN ((paw.paw_tage - sum(pak.pak_tage_abbuchung)) IS NOT NULL) THEN (paw.paw_tage - sum(pak.pak_tage_abbuchung))
                ELSE (0)::double precision
            END
            ELSE (0)::double precision
        END AS gekappt_jahr,
        CASE
            WHEN (EXTRACT(year FROM paw.paw_verfallsdatum) >= (paw.paw_pas_jahr)::numeric) THEN
            CASE
                WHEN (sum(pak.pak_tage_abbuchung) > (0)::double precision) THEN (paw.paw_tage - sum(pak.pak_tage_abbuchung))
                ELSE paw.paw_tage
            END
            ELSE (0)::double precision
        END AS rest_akt,
        CASE
            WHEN (paw.paw_verfallsdatum >= (((paw.paw_pas_jahr)::text || '-12-31'::text))::date) THEN
            CASE
                WHEN (sum(pak.pak_tage_abbuchung) > (0)::double precision) THEN (paw.paw_tage - sum(pak.pak_tage_abbuchung))
                ELSE paw.paw_tage
            END
            ELSE (0)::double precision
        END AS rest_jahr
   FROM (((sva4.pas pas
     LEFT JOIN sva4.paw paw ON ((pas.pas_serial = paw.paw_pas_serial)))
     LEFT JOIN sva4.pak pak ON ((paw.paw_serial = pak.pak_zu_paw_serial)))
     LEFT JOIN sva4.k_abwesenheitsart k_abwesenheitsart ON (((paw.paw_art)::text = (k_abwesenheitsart.key_abwesenheit)::text)))
  WHERE (((paw.paw_pas_jahr >= 2015) OR ((paw.paw_verfallsdatum IS NOT NULL) AND (EXTRACT(year FROM paw.paw_verfallsdatum) >= (paw.paw_pas_jahr)::numeric))) AND ((pas.pas_pawneu)::text = 'J'::text) AND ((k_abwesenheitsart.his_system_key)::text = ANY (ARRAY[('TJ'::character varying)::text, ('GJ'::character varying)::text, ('IJ'::character varying)::text, ('BJ'::character varying)::text, ('BR'::character varying)::text, ('BB'::character varying)::text, ('BS'::character varying)::text, ('XB'::character varying)::text, ('XG'::character varying)::text, ('XI'::character varying)::text, ('XR'::character varying)::text, ('XS'::character varying)::text, ('XT'::character varying)::text, ('XX'::character varying)::text, ('KJ'::character varying)::text, ('SO'::character varying)::text, ('BI'::character varying)::text, ('BA'::character varying)::text, ('AE'::character varying)::text, ('AR'::character varying)::text, ('AB'::character varying)::text, ('AU'::character varying)::text, ('AG'::character varying)::text, ('AA'::character varying)::text])) AND (pas.pas_status = 0) AND (paw.paw_status = 0))
  GROUP BY paw.paw_pas_jahr, paw.paw_verfallsdatum, paw.paw_pgd_join_id, paw.paw_serial, paw.paw_tage, k_abwesenheitsart.his_system_key, k_abwesenheitsart.druck_abwesenheit, paw.paw_von, paw.paw_bis;


