--
-- Name: pbv_dokumente; Type: VIEW; Schema: sva4; Owner: -
--

CREATE VIEW sva4.pbv_dokumente AS
 SELECT pbv_pgd_join_id,
    pbv_nr,
    ( SELECT count(*) AS count
           FROM sva4.pdo,
            sva4.k_dokumente_kategorie
          WHERE ((pdo.pdo_pgd_join_id = pbv.pbv_pgd_join_id) AND (pdo.pdo_pbv_nr = pbv.pbv_nr) AND ((pdo.pdo_art)::text = (k_dokumente_kategorie.key_dokument)::text) AND ((k_dokumente_kategorie.his_system_key)::text = 'PB'::text))) AS pb,
    ( SELECT count(*) AS count
           FROM sva4.pdo,
            sva4.k_dokumente_kategorie
          WHERE ((pdo.pdo_pgd_join_id = pbv.pbv_pgd_join_id) AND (pdo.pdo_pbv_nr = pbv.pbv_nr) AND ((pdo.pdo_art)::text = (k_dokumente_kategorie.key_dokument)::text) AND ((k_dokumente_kategorie.his_system_key)::text = 'ER'::text))) AS er,
    ( SELECT count(*) AS count
           FROM sva4.pdo,
            sva4.k_dokumente_kategorie
          WHERE ((pdo.pdo_pgd_join_id = pbv.pbv_pgd_join_id) AND (pdo.pdo_pbv_nr = pbv.pbv_nr) AND ((pdo.pdo_art)::text = (k_dokumente_kategorie.key_dokument)::text) AND ((k_dokumente_kategorie.his_system_key)::text = 'HA'::text))) AS ha,
    ( SELECT count(*) AS count
           FROM sva4.pdo,
            sva4.k_dokumente_kategorie
          WHERE ((pdo.pdo_pgd_join_id = pbv.pbv_pgd_join_id) AND (pdo.pdo_pbv_nr = pbv.pbv_nr) AND ((pdo.pdo_art)::text = (k_dokumente_kategorie.key_dokument)::text) AND ((k_dokumente_kategorie.his_system_key)::text = 'RS'::text))) AS rs,
    ( SELECT count(*) AS count
           FROM sva4.pdo,
            sva4.k_dokumente_kategorie
          WHERE ((pdo.pdo_pgd_join_id = pbv.pbv_pgd_join_id) AND (pdo.pdo_pbv_nr = pbv.pbv_nr) AND ((pdo.pdo_art)::text = (k_dokumente_kategorie.key_dokument)::text) AND ((k_dokumente_kategorie.his_system_key)::text = 'KV'::text))) AS kv,
    ( SELECT count(*) AS count
           FROM sva4.pdo,
            sva4.k_dokumente_kategorie
          WHERE ((pdo.pdo_pgd_join_id = pbv.pbv_pgd_join_id) AND (pdo.pdo_pbv_nr = pbv.pbv_nr) AND ((pdo.pdo_art)::text = (k_dokumente_kategorie.key_dokument)::text) AND ((k_dokumente_kategorie.his_system_key)::text = 'IM'::text))) AS im,
    ( SELECT count(*) AS count
           FROM sva4.pdo,
            sva4.k_dokumente_kategorie
          WHERE ((pdo.pdo_pgd_join_id = pbv.pbv_pgd_join_id) AND (pdo.pdo_pbv_nr = pbv.pbv_nr) AND ((pdo.pdo_art)::text = (k_dokumente_kategorie.key_dokument)::text) AND ((k_dokumente_kategorie.his_system_key)::text = 'LK'::text))) AS lk,
    ( SELECT count(*) AS count
           FROM sva4.pdo,
            sva4.k_dokumente_kategorie
          WHERE ((pdo.pdo_pgd_join_id = pbv.pbv_pgd_join_id) AND (pdo.pdo_pbv_nr = pbv.pbv_nr) AND ((pdo.pdo_art)::text = (k_dokumente_kategorie.key_dokument)::text) AND ((k_dokumente_kategorie.his_system_key)::text = 'LL'::text))) AS ll,
    ( SELECT count(*) AS count
           FROM sva4.pdo,
            sva4.k_dokumente_kategorie
          WHERE ((pdo.pdo_pgd_join_id = pbv.pbv_pgd_join_id) AND (pdo.pdo_pbv_nr = pbv.pbv_nr) AND ((pdo.pdo_art)::text = (k_dokumente_kategorie.key_dokument)::text) AND ((k_dokumente_kategorie.his_system_key)::text = 'GL'::text))) AS gl,
    ( SELECT count(*) AS count
           FROM sva4.pdo,
            sva4.k_dokumente_kategorie
          WHERE ((pdo.pdo_pgd_join_id = pbv.pbv_pgd_join_id) AND (pdo.pdo_pbv_nr = pbv.pbv_nr) AND ((pdo.pdo_art)::text = (k_dokumente_kategorie.key_dokument)::text) AND ((k_dokumente_kategorie.his_system_key)::text = 'GH'::text))) AS gh
   FROM sva4.pbv
  ORDER BY pbv_pgd_join_id, pbv_nr;


