    pgd_join_id AS id,
    pgd_status AS status,
    pgd_name AS surname,
    pgd_vornamen AS firstname,
    pgd_alle_vornamen AS allfirstnames,
    pgd_titel AS title_id,
    pgd_geschlecht AS gender,
    pgd_geburtsdatum AS birthdate,
    pgd_email AS emailaddress,
    obj_guid,
    lock_version
   FROM sva4.pgd
  WHERE (1 = 1);


