CREATE VIEW sva4.pmi_in_plv AS
 SELECT pmi.pmi_serial,
    pmi.pmi_von,
    pmi.pmi_bis,
    pmi.pmi_minderungsgrd,
    k_minderungsgrd.druck_mind_grund,
    pmi.pmi_minderungsstd,
    pgd.pgd_join_id,
    pgd.pgd_name,
    pgd.pgd_vornamen
   FROM (((sva4.pmi
     LEFT JOIN sva4.k_minderungsgrd ON (((pmi.pmi_minderungsgrd)::text = (k_minderungsgrd.key_mind_grund)::text)))
     LEFT JOIN sva4.pdp ON ((pdp.pdp_serial = pmi.pmi_pdp_serial)))
     LEFT JOIN sva4.pgd ON ((pdp.pdp_pgd_join_id = pgd.pgd_join_id)));


