--
-- Name: geb geb_del; Type: RULE; Schema: cob; Owner: -
--

CREATE RULE geb_del AS
    ON DELETE TO cob.geb DO INSTEAD  DELETE FROM mbs.geb geb1
  WHERE ((geb1.geb_nr)::text = (old.geb_nr)::text);


--
-- Name: geb geb_ins; Type: RULE; Schema: cob; Owner: -
--

CREATE RULE geb_ins AS
    ON INSERT TO cob.geb DO INSTEAD  INSERT INTO mbs.geb (db_einfuegemarke, geb_nr, geb, geb2, baujahr, besitz, art, gebber_nr, hs_nr, qkz, fnw, pers_nr, denkmal_nr, ort_nr, stra_nr, haus_nr, gemark_nr, flur_nr, flurst_nr, miete, bauwerk, b_grad, l_grad, bem, text_geb, kurz_geb)
  VALUES (new.db_einfuegemarke, new.geb_nr, new.geb, new.geb2, new.baujahr, new.besitz, new.art, new.gebber_nr, new.hs_nr, new.qkz, new.fnw, new.pers_nr, new.denkmal_nr, new.ort_nr, new.stra_nr, new.haus_nr, new.gemark_nr, new.flur_nr, new.flurst_nr, new.miete, new.bauwerk, new.b_grad, new.l_grad, new.bem, new.text_geb, new.kurz_geb);


--
-- Name: geb geb_upd; Type: RULE; Schema: cob; Owner: -
--

CREATE RULE geb_upd AS
    ON UPDATE TO cob.geb DO INSTEAD  UPDATE mbs.geb geb1 SET db_einfuegemarke = new.db_einfuegemarke, geb_nr = new.geb_nr, geb = new.geb, geb2 = new.geb2, baujahr = new.baujahr, besitz = new.besitz, art = new.art, gebber_nr = new.gebber_nr, hs_nr = new.hs_nr, qkz = new.qkz, fnw = new.fnw, pers_nr = new.pers_nr, denkmal_nr = new.denkmal_nr, ort_nr = new.ort_nr, stra_nr = new.stra_nr, haus_nr = new.haus_nr, gemark_nr = new.gemark_nr, flur_nr = new.flur_nr, flurst_nr = new.flurst_nr, miete = new.miete, bauwerk = new.bauwerk, b_grad = new.b_grad, l_grad = new.l_grad, bem = new.bem, text_geb = new.text_geb, kurz_geb = new.kurz_geb
  WHERE ((geb1.geb_nr)::text = (old.geb_nr)::text);


--
-- Name: ges ges_del; Type: RULE; Schema: cob; Owner: -
--

CREATE RULE ges_del AS
    ON DELETE TO cob.ges DO INSTEAD  DELETE FROM mbs.ges ges1
  WHERE (((ges1.geb_nr)::text = (old.geb_nr)::text) AND ((ges1.ges_nr)::text = (old.ges_nr)::text));


--
-- Name: ges ges_ins; Type: RULE; Schema: cob; Owner: -
--

CREATE RULE ges_ins AS
    ON INSERT TO cob.ges DO INSTEAD  INSERT INTO mbs.ges (db_einfuegemarke, geb_nr, ges_nr, ges, text_ges, kurz_ges)
  VALUES (new.db_einfuegemarke, new.geb_nr, new.ges_nr, new.ges, new.text_ges, new.kurz_ges);


--
-- Name: ges ges_upd; Type: RULE; Schema: cob; Owner: -
--

CREATE RULE ges_upd AS
    ON UPDATE TO cob.ges DO INSTEAD  UPDATE mbs.ges ges1 SET db_einfuegemarke = new.db_einfuegemarke, geb_nr = new.geb_nr, ges_nr = new.ges_nr, ges = new.ges, text_ges = new.text_ges, kurz_ges = new.kurz_ges
  WHERE (((ges1.geb_nr)::text = (old.geb_nr)::text) AND ((ges1.ges_nr)::text = (old.ges_nr)::text));


